                {
                    Id = -1012100,
                    StorageType = StorageType.Integer,
                    Value = 99,
                },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
                Faces =
                [
                    Face([[0, -0.5, 0], [4, -0.5, 0], [4, 0.5, 0], [0, 0.5, 0]]),
                    Face([[0, -0.5, 3], [0, 0.5, 3], [4, 0.5, 3], [4, -0.5, 3]]),
                    Face([[0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3], [4, -0.5, 0]]),
                    Face([[4, -0.5, 0], [4, -0.5, 3], [4, 0.5, 3], [4, 0.5, 0]]),
                    Face([[4, 0.5, 0], [4, 0.5, 3], [0, 0.5, 3], [0, 0.5, 0]]),
