    [Fact]
    public void StandardCaseWithoutPhasePayload_UsesRotatedAxisSweptSolid()
    {
        const double offset = 0.3535533905932738;
        double[][] bottom =
        [
            [-offset, offset, 0],
            [4 - offset, 4 + offset, 0],
            [4 + offset, 4 - offset, 0],
            [offset, -offset, 0],
        ];
        double[][] top = bottom
            .Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var wall = new Element
        {
            Id = 4300,
            TypeId = 4301,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Rotated compound wall",
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                    MaterialId = 10,
                },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1013201,
                    StorageType = StorageType.ElementId,
                    Value = 999,
                },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 4, 0],
            },
            BoundingBox = [-offset, -offset, 0, 4 + offset, 4 + offset, 3],
            Geometry = new GeometryData
            {
                BoundingBox = [-offset, -offset, 0, 4 + offset, 4 + offset, 3],
                Faces =
                [
                    Face(bottom),
                    Face(top.AsEnumerable().Reverse().ToArray()),
                    Face([bottom[0], top[0], top[1], bottom[1]]),
                    Face([bottom[1], top[1], top[2], bottom[2]]),
                    Face([bottom[2], top[2], top[3], bottom[3]]),
                    Face([bottom[3], top[3], top[0], bottom[0]]),
                ],
            },
        };
        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        info.Elements.Add(new Element
        {
            Id = 4302,
            TypeId = 4303,
            CategoryId = -2000170,
            Category = "OST_CurtainWallPanels",
            References = [wall.Id],
        });
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-rotated-standardcase-{Guid.NewGuid():N}.ifc");

        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'4300'", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCEXTRUDEDAREASOLID(", ifc);
            Assert.Contains("=IFCARBITRARYCLOSEDPROFILEDEF(", ifc);
            Assert.DoesNotContain("=IFCRECTANGLEPROFILEDEF(", ifc);
            Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void RawRevitPropertySets_AreOptInForViewerCompatibleIfc()
    {
        var wall = new Element
        {
            Id = 420,
            TypeId = -1,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Property export wall",
            References = [99],
            Parameters =
            [
                new Parameter
                {
                    Id = 9001,
                    Definition = new Definition { Id = 9001, Name = "CustomCode" },
                    StorageType = StorageType.String,
                    Value = "ABC-123",
                },
                new Parameter { Id = -1012100, StorageType = StorageType.Integer, Value = 99 },
                new Parameter { Id = -1001000, StorageType = StorageType.Double, Value = 1.0 },
                new Parameter { Id = -1001105, StorageType = StorageType.Double, Value = 3.0 },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
                Faces =
                [
                    Face([[0, -0.5, 0], [4, -0.5, 0], [4, 0.5, 0], [0, 0.5, 0]]),
                    Face([[0, -0.5, 3], [0, 0.5, 3], [4, 0.5, 3], [4, -0.5, 3]]),
                    Face([[0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3], [4, -0.5, 0]]),
                    Face([[4, -0.5, 0], [4, -0.5, 3], [4, 0.5, 3], [4, 0.5, 0]]),
                    Face([[4, 0.5, 0], [4, 0.5, 3], [0, 0.5, 3], [0, 0.5, 0]]),
                    Face([[0, 0.5, 0], [0, 0.5, 3], [0, -0.5, 3], [0, -0.5, 0]]),
                ],
            },
        };
        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string compactPath = Path.Combine(Path.GetTempPath(), $"revitreader-compact-{Guid.NewGuid():N}.ifc");
        string verbosePath = Path.Combine(Path.GetTempPath(), $"revitreader-verbose-{Guid.NewGuid():N}.ifc");

        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, compactPath);
            new IfcExporter(includeRevitPropertySets: true) { Profile = IfcProfile.Legacy }.Export(info, verbosePath);

            string compactIfc = File.ReadAllText(compactPath);
            string verboseIfc = File.ReadAllText(verbosePath);
            // The default (compact) path carries the Pset_QuantityTakeOff slice but never the raw
            // per-parameter dump ("RevitParameters", arbitrary names like "CustomCode"): that stays
            // opt-in behind --ifc-revit-parameters.
            Assert.DoesNotContain("CustomCode", compactIfc);
            Assert.DoesNotContain("'RevitParameters'", compactIfc);
            Assert.Contains("'Pset_QuantityTakeOff'", compactIfc);
            // Exactly three property-value entities: the pooled Reference shared by
            // Pset_QuantityTakeOff and Pset_WallCommon, the unpooled Reference of
            // Pset_ReinforcementBarPitchOfWall, and Pset_BuildingCommon.NumberOfStoreys.
            Assert.Equal(3, System.Text.RegularExpressions.Regex.Matches(
                compactIfc, "=IFCPROPERTYSINGLEVALUE\\(").Count);
            Assert.Contains("=IFCPROPERTYSINGLEVALUE(", verboseIfc);
            Assert.Contains("CustomCode", verboseIfc);
            Assert.Contains("ABC-123", verboseIfc);
            Assert.Contains("'RevitParameters'", verboseIfc);
        }
        finally
        {
            if (File.Exists(compactPath)) File.Delete(compactPath);
            if (File.Exists(verbosePath)) File.Delete(verbosePath);
        }
    }

    [Fact]
    public void StandardCaseWall_UsesSerializedAxisWidthAndHeightInsteadOfJoinedFaceBounds()
    {
        var wall = new Element
        {
            Id = 43,
            TypeId = 44,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Axis wall",
            References = [99],
            Parameters =
            [
                new Parameter { Id = -1012100, StorageType = StorageType.Integer, Value = 99 },
                new Parameter { Id = -1001000, StorageType = StorageType.Double, Value = 1.0 },
                new Parameter { Id = -1001105, StorageType = StorageType.Double, Value = 3.0 },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [10, 20, 5],
                EndPoint = [14, 20, 5],
            },
            // These bounds deliberately describe unrelated joined geometry. They remain a
            // fallback for missing data, but must not replace the authored wall definition.
            BoundingBox = [8, 17, 6, 19, 25, 8],
            Geometry = new GeometryData
            {
                Faces = [Face([[8, 17, 6], [19, 17, 6], [19, 25, 8]])],
            },
        };
        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string path = Path.Combine(Path.GetTempPath(), $"revitreader-axis-wall-{Guid.NewGuid():N}.ifc");

        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains(",1219.2,304.8);", ifc);
            Assert.Contains(",914.4);", ifc);
            Assert.Contains("=IFCCARTESIANPOINT((3657.6,6096.,1524.));", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void StandardCaseFootprint_UsesTheExactWidthMatchedExteriorProfilePair()
    {
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Geometry = new GeometryData
            {
                Faces =
                [
                    Face([[0.25, -0.5, 0], [3.75, -0.5, 0], [3.75, -0.5, 3], [0.25, -0.5, 3]]),
                    Face([[0.25, 0.5, 0], [3.75, 0.5, 0], [3.75, 0.5, 3], [0.25, 0.5, 3]]),
                    // A disconnected neighbouring face has no opposite profile one wall
                    // width away and therefore cannot expand the wall section.
                    Face([[0, 5, 0], [10, 5, 0], [10, 5, 3], [0, 5, 3]]),
                ],
            },
        };

        Assert.True(IfcExporter.TryGetAuthoredStraightWallFootprint(
            wall, 1.0, out double length, out double centreX, out double centreY));
        Assert.Equal(3.5, length, 12);
        Assert.Equal(2.0, centreX, 12);
        Assert.Equal(0.0, centreY, 12);
    }

