    [Fact]
    public void StandardCaseFootprint_UsesAlternativeSerializedFaceLoops()
    {
        var negative = Face([[1, -0.5, 0], [2, -0.5, 0], [2, -0.5, 1], [1, -0.5, 1]]);
        negative.AlternativeOuterVertices =
            [[0, -0.5, 0], [4, -0.5, 0], [4, -0.5, 4], [0, -0.5, 4]];
        var positive = Face([[1, 0.5, 0], [2, 0.5, 0], [2, 0.5, 1], [1, 0.5, 1]]);
        positive.AlternativeOuterVertices =
            [[0, 0.5, 0], [4, 0.5, 0], [4, 0.5, 4], [0, 0.5, 4]];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Geometry = new GeometryData { Faces = [negative, positive] },
        };

        Assert.True(IfcExporter.TryGetAuthoredStraightWallFootprint(
            wall, 1.0, out double length, out double centreX, out double centreY));
        Assert.Equal(4.0, length, 12);
        Assert.Equal(2.0, centreX, 12);
        Assert.Equal(0.0, centreY, 12);
    }

    [Fact]
    public void StandardCaseFootprint_PreservesStaggeredJoinedSideEnds()
    {
        var wall = new Element
        {
