    [Fact]
    public void StandardCasePlan_UsesAuthoredEndConnectorsWhenOpeningsSplitSideFaces()
    {
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 9.7, 0.5, 3],
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 9.7, 0.5, 3],
                Faces =
                [
                    // Only short side cells survive around a full-height hosted opening.
                    Face([[4, -0.5, 0], [6, -0.5, 0], [6, -0.5, 3], [4, -0.5, 3]]),
                    Face([[4, 0.5, 0], [6, 0.5, 0], [6, 0.5, 3], [4, 0.5, 3]]),
                    // Authored exterior ends, with the second one trimmed by a join.
                    Face([[0, -0.5, 0], [0, 0.5, 0], [0, 0.5, 3], [0, -0.5, 3]]),
                    Face([[9.7, -0.5, 0], [9.7, 0.5, 0], [9.7, 0.5, 3], [9.7, -0.5, 3]]),
                    // Partial-height reveal faces are not gross-body end connectors.
                    Face([[4, -0.5, 0.5], [4, 0.5, 0.5], [4, 0.5, 2.5], [4, -0.5, 2.5]]),
                    Face([[6, -0.5, 0.5], [6, 0.5, 0.5], [6, 0.5, 2.5], [6, -0.5, 2.5]]),
                ],
            },
        };

        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(wall, 1, out var plan));
        Assert.Equal(new double[] { 0, -0.5 }, plan[0]);
        Assert.Equal(new double[] { 9.7, -0.5 }, plan[1]);
        Assert.Equal(new double[] { 9.7, 0.5 }, plan[2]);
        Assert.Equal(new double[] { 0, 0.5 }, plan[3]);
    }

