    [Fact]
    public void StandardCaseSweptSolidGate_RejectsRotatedAabbAmbiguity()
    {
        double axis = Math.Sqrt(0.5);
        double nominalLength = Math.Sqrt(2);
        const double nominalWidth = 0.1;
        const double actualLength = 0.9;
        double actualWidth = nominalLength + nominalWidth - actualLength;
        double[] Point(double along, double across, double z) =>
        [
            0.5 + along * axis - across * axis,
            0.5 + along * axis + across * axis,
            z,
        ];
        double[][] bottom =
        [
            Point(-actualLength / 2, -actualWidth / 2, 0),
            Point(actualLength / 2, -actualWidth / 2, 0),
            Point(actualLength / 2, actualWidth / 2, 0),
            Point(-actualLength / 2, actualWidth / 2, 0),
        ];
        double[][] top = bottom.Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var boundary = new GeometryData
        {
            Faces =
            [
                Face(bottom), Face(top.AsEnumerable().Reverse().ToArray()),
                Face([bottom[0], top[0], top[1], bottom[1]]),
                Face([bottom[1], top[1], top[2], bottom[2]]),
                Face([bottom[2], top[2], top[3], bottom[3]]),
                Face([bottom[3], top[3], top[0], bottom[0]]),
            ],
        };
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [1, 1, 0],
            },
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0, ThicknessMm = nominalWidth * 304.8,
                },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105, StorageType = StorageType.Double, Value = 3.0,
                },
            ],
            Geometry = boundary,
        };
        double extent = 1 + nominalWidth * axis / 2;
        double[] bounds = [-nominalWidth * axis / 2, -nominalWidth * axis / 2, 0,
            extent, extent, 3];

        Assert.True(IfcExporter.IsExactVerticalExtrusionBoundary(boundary));
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_AllowsExactOpenFragmentedAuthoredPlanOnlyWhenOptedIn()
    {
        double axis = Math.Sqrt(0.5);
        double length = 4 / axis;
        double[] Point(double along, double across, double z) =>
        [
            along * axis - across * axis,
            along * axis + across * axis,
            z,
        ];
        List<double[]> lowSide =
        [
            Point(0, -0.5, 0),
            Point(length, -0.5, 0),
            Point(length, -0.5, 1),
            Point(1, -0.5, 1),
            Point(1, -0.5, 3),
            Point(0, -0.5, 3),
        ];
        List<double[]> highSide =
        [
            Point(0, 0.5, 3),
            Point(2, 0.5, 3),
            Point(2, 0.5, 1),
            Point(length, 0.5, 1),
            Point(length, 0.5, 0),
            Point(0, 0.5, 0),
        ];
        var fragmented = new GeometryData
        {
            Faces = [Face(lowSide), Face(highSide)],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = false,
                    FaceIndices = [0, 1],
                },
            ],
        };
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 4, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Geometry = fragmented,
        };
        double halfProjection = axis / 2;
        double[] bounds =
        [
            -halfProjection, -halfProjection, 0,
            4 + halfProjection, 4 + halfProjection, 3,
        ];

        Assert.False(IfcExporter.IsExactVerticalExtrusionBoundary(fragmented));
        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(
            wall, 1, out var authoredPlan));
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            authoredPlan, bounds));
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, fragmented));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, fragmented,
            allowOpenFragmentedAuthoredPlan: true));

        wall.CuttingElementIds = [1];
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, fragmented,
            allowOpenFragmentedAuthoredPlan: true));
        wall.CuttingElementIds = [];

        fragmented.BrepSolids![0].IsClosed = true;
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, fragmented,
            allowOpenFragmentedAuthoredPlan: true));
        fragmented.BrepSolids[0].IsClosed = false;

        fragmented.Faces![0].AlternativeOuterVertices =
        [
            Point(0, -0.5, 0),
            Point(1, -0.5, 0),
            Point(1, -0.5, 1),
        ];
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, fragmented,
            allowOpenFragmentedAuthoredPlan: true));
        fragmented.Faces[0].AlternativeOuterVertices = null;

        fragmented.Faces[0].InnerVertices =
        [
            [
                Point(1.5, -0.5, 1),
                Point(2.5, -0.5, 1),
                Point(2.5, -0.5, 2),
                Point(1.5, -0.5, 2),
            ],
        ];
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, fragmented,
            allowOpenFragmentedAuthoredPlan: true));
        fragmented.Faces[0].InnerVertices = null;

        var interiorTopNotch = new GeometryData
        {
            Faces =
            [
                Face(
                [
                    Point(0, -0.5, 0),
                    Point(length, -0.5, 0),
                    Point(length, -0.5, 3),
                    Point(3, -0.5, 3),
                    Point(3, -0.5, 1),
                    Point(2, -0.5, 1),
                    Point(2, -0.5, 3),
                    Point(0, -0.5, 3),
                ]),
                Face(highSide),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = false,
                    FaceIndices = [0, 1],
                },
            ],
        };
        wall.Geometry = interiorTopNotch;
        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(
            wall, 1, out var interiorTopNotchPlan));
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            interiorTopNotchPlan, bounds));
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, interiorTopNotch,
            allowOpenFragmentedAuthoredPlan: true));

        var lowerTrimmed = new GeometryData
        {
            Faces =
            [
                Face(
                [
                    Point(0, -0.5, 0),
                    Point(length - 1, -0.5, 0),
                    Point(length - 1, -0.5, 1),
                    Point(length, -0.5, 1),
                    Point(length, -0.5, 3),
                    Point(0, -0.5, 3),
                ]),
                Face(
                [
                    Point(0, 0.5, 3),
                    Point(length, 0.5, 3),
                    Point(length, 0.5, 1),
                    Point(length - 0.5, 0.5, 1),
                    Point(length - 0.5, 0.5, 0),
                    Point(0, 0.5, 0),
                ]),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = false,
                    FaceIndices = [0, 1],
                },
            ],
        };
        wall.Geometry = lowerTrimmed;
        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(
            wall, 1, out var lowerTrimmedPlan));
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            lowerTrimmedPlan, bounds));
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, lowerTrimmed,
            allowOpenFragmentedAuthoredPlan: true));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactJoinedBoundarySpanOnlyWhenOptedIn()
    {
        double[][] bottom =
        [
            [0, -0.5, 1], [4, -0.5, 1],
            [4.5, 0.5, 1], [-0.5, 0.5, 1],
        ];
        double[][] top = bottom
            .Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var faces = new List<GeoFace>
        {
            Face(bottom), Face(top.AsEnumerable().Reverse().ToArray()),
            Face([bottom[0], top[0], top[1], bottom[1]]),
            Face([bottom[1], top[1], top[2], bottom[2]]),
            Face([bottom[2], top[2], top[3], bottom[3]]),
            Face([bottom[3], top[3], top[0], bottom[0]]),
        };
        var boundary = new GeometryData
        {
            BoundingBox = [-0.5, -0.5, 1, 4.5, 0.5, 3],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = true,
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                },
            ],
        };
        var wall = new Element
        {
            Id = 4350,
            TypeId = 4351,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Boundary-owned joined wall",
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105, StorageType = StorageType.Double, Value = 3.0,
                },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            BoundingBox = [-0.5, -0.5, 1, 4.5, 0.5, 3],
            Geometry = boundary,
        };
        double[] bounds = [-0.5, -0.5, 1, 4.5, 0.5, 3];

        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            boundary, wall.Location!, 1, bounds,
            out var plan, out double baseZFt, out double heightFt));
        Assert.Equal(4, plan.Count);
        Assert.Equal(1, baseZFt, 12);
        Assert.Equal(2, heightFt, 12);
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            boundary, wall.Location!, 0.9, bounds, out _, out _, out _));
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary, allowBoundaryOwnedVerticalDefinition: true));

        wall.Parameters.Clear();
        wall.Parameters.Add(new Parameter
        {
            Id = -1001111, StorageType = StorageType.Double, Value = 1.0,
        });
        wall.Parameters.Add(new Parameter
        {
            Id = -1001105, StorageType = StorageType.Double, Value = 2.0,
        });
        wall.Geometry = new GeometryData();
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary, allowBoundaryOwnedVerticalDefinition: true));
        wall.Geometry = boundary;
        wall.Parameters.Clear();
        wall.Parameters.Add(new Parameter
        {
            Id = -1001105, StorageType = StorageType.Double, Value = 3.0,
        });

        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        info.Elements.Add(new Element
        {
            Id = 4352,
            TypeId = 4353,
            CategoryId = -2000170,
            Category = "OST_CurtainWallPanels",
            References = [wall.Id],
        });
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-boundary-owned-wall-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCARBITRARYCLOSEDPROFILEDEF(", ifc);
            Assert.Contains(",609.6);", ifc);
            Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

    }

    [Fact]
    public void ExactWallDefinition_RejectsOverlappingOrIncompleteRedundantBoundaryFaces()
    {
        var location = new LocationCurve
        {
            CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
        };
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var redundant = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        redundant.Faces.Add(Face(
        [
            [1, -0.5, 0], [3, -0.5, 0], [3, 0.5, 0], [1, 0.5, 0],
        ]));

        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            redundant, location, 1, bounds, out _, out _, out _));

        var exterior = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        exterior.Faces.Add(Face(
        [
            [3.5, -0.5, 0], [4.5, -0.5, 0], [4.5, 0.5, 0], [3.5, 0.5, 0],
        ]));
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            exterior, location, 1, bounds, out _, out _, out _));

        var incomplete = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        incomplete.Faces.RemoveAt(1);
        incomplete.Faces.Add(Face(
        [
            [1, -0.5, 3], [3, -0.5, 3], [3, 0.5, 3], [1, 0.5, 3],
        ]));
        incomplete.Faces.Add(Face(
        [
            [1, -0.5, 0], [3, -0.5, 0], [3, 0.5, 0], [1, 0.5, 0],
        ]));
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            incomplete, location, 1, bounds, out _, out _, out _));
    }

    [Fact]
    public void ExactWallDefinition_AllowsCompleteCoplanarSideSubdivisionFallback()
    {
        var location = new LocationCurve
        {
            CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
        };
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var splitSide = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        splitSide.Faces.RemoveAt(2);
        splitSide.Faces.Add(Face(
        [
            [0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3],
        ]));
        splitSide.Faces.Add(Face(
        [
            [0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0],
        ]));
        splitSide.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, splitSide.Faces.Count).ToList();

        Assert.False(IfcExporter.IsExactVerticalExtrusionBoundary(splitSide));
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            splitSide, location, 1, bounds,
            out var plan, out double baseZFt, out double heightFt,
            out string rejectionReason), rejectionReason);
        Assert.Equal("exact-redundant-boundary-faces", rejectionReason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(0, baseZFt, 12);
        Assert.Equal(3, heightFt, 12);

        var wall = new Element
        {
            Id = 17915,
            Location = location,
            BoundingBox = bounds,
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105, StorageType = StorageType.Double, Value = 3.0,
                },
            ],
            Geometry = splitSide,
        };
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, splitSide));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, splitSide,
            allowBoundaryOwnedVerticalDefinition: true));

        splitSide.Faces.RemoveAt(splitSide.Faces.Count - 1);
        splitSide.BrepSolids[0].FaceIndices =
            Enumerable.Range(0, splitSide.Faces.Count).ToList();
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            splitSide, location, 1, bounds, out _, out _, out _));
        Assert.False(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, splitSide,
            allowBoundaryOwnedVerticalDefinition: true));
    }

    [Fact]
    public void ExactWallDefinition_AllowsAxisAlignedRedundantBoundaryOnWriterLattice()
    {
        var location = new LocationCurve
        {
            CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
        };
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var splitSide = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        splitSide.Faces.RemoveAt(2);
        splitSide.Faces.Add(Face(
        [
            [0, -0.5, 0], [0, -0.5, 3], [4, -0.5 + 1.0e-8, 3],
        ]));
        splitSide.Faces.Add(Face(
        [
            [0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0],
        ]));
        splitSide.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, splitSide.Faces.Count).ToList();

        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            splitSide, location, 1, bounds,
            out var plan, out double baseZFt, out double heightFt,
            out string rejectionReason), rejectionReason);
        Assert.Equal(
            "exact-writer-lattice-redundant-boundary-faces",
            rejectionReason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(0, baseZFt, 12);
        Assert.Equal(3, heightFt, 12);

        splitSide.Faces[^2].OuterVertices![2][1] = -0.5 + 2.0e-5;
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            splitSide, location, 1, bounds, out _, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesWriterLatticeRedundantWallWithUnconfirmedRotatedOpening()
    {
        const int phaseId = 99;
        var (wall, cutter, boundary) = ExactWallWithOneThroughOpening();
        boundary.Faces.RemoveAt(2);
        boundary.Faces.Add(Face(
        [
            [0, -0.5, 0], [0, -0.5, 3],
            [4, -0.5 + 1.0e-8, 3],
        ]));
        boundary.Faces.Add(Face(
        [
            [0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0],
        ]));
        boundary.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, boundary.Faces.Count).ToList();
        wall.Geometry = boundary;
        wall.IsDiscovered = true;
        wall.Name = "Exact redundant wall";
        cutter.IsDiscovered = true;
        cutter.HostId = wall.Id;
        cutter.References = [wall.Id, phaseId];
        cutter.Parameters =
        [
            new Parameter
            {
                Id = -1012100,
                StorageType = StorageType.ElementId,
                Value = phaseId,
            },
            new Parameter
            {
                Id = -1013201,
                StorageType = StorageType.Integer,
                Value = -4,
            },
        ];
        double cosine = Math.Cos(0.1);
        double sine = Math.Sin(0.1);
        cutter.Transform = new InstanceTransform
        {
            Origin = [1.5, 0, 1],
            BasisX = [cosine, sine, 0],
            BasisY = [-sine, cosine, 0],
            BasisZ = [0, 0, 1],
        };
        cutter.Geometry = BoxGeometry(1, -0.5, 1, 2, 0.5, 2);

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, cutter]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-redundant-wall-opening-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void ExactWallDefinition_AllowsBoundaryOwnedJoinedSpanWithRedundantEndSubdivision()
    {
        var location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0.25, 0, 0],
            EndPoint = [3.75, 0, 0],
        };
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        GeometryData Boundary() => new()
        {
            BoundingBox = bounds,
            Faces =
            [
                Face(
                [
                    [0, -0.5, 0], [4, -0.5, 0], [4, -0.5, 1.5],
                    [4, -0.5, 3], [0, -0.5, 3],
                ]),
                Face(
                [
                    [0, 0.5, 3], [4, 0.5, 3], [4, 0.5, 1.5],
                    [4, 0.5, 0], [0, 0.5, 0],
                ]),
                Face(
                [
                    [0, -0.5, 0], [0, 0.5, 0],
                    [4, 0.5, 0], [4, -0.5, 0],
                ]),
                Face(
                [
                    [4, -0.5, 0], [4, 0.5, 0],
                    [4, 0.5, 1.5], [4, -0.5, 1.5],
                ]),
                Face(
                [
                    [4, -0.5, 1.5], [4, 0.5, 1.5],
                    [4, 0.5, 3], [4, -0.5, 3],
                ]),
                Face(
                [
                    [4, -0.5, 3], [4, 0.5, 3],
                    [0, 0.5, 3], [0, -0.5, 3],
                ]),
                Face(
                [
                    [0, -0.5, 3], [0, 0.5, 3],
                    [0, 0.5, 0], [0, -0.5, 0],
                ]),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 7).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var boundary = Boundary();

        Assert.False(IfcExporter.TryResolveStraightWallPlanCentre(
            location, 1, bounds, out _, out _));
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            boundary, location, 1, bounds,
            out var plan, out double baseZFt, out double heightFt,
            out string rejectionReason), rejectionReason);
        Assert.Equal(
            "exact-boundary-owned-redundant-faces", rejectionReason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(0, baseZFt, 12);
        Assert.Equal(3, heightFt, 12);

        var wall = new Element
        {
            Location = location,
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            Geometry = boundary,
        };
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary,
            allowBoundaryOwnedVerticalDefinition: true));
        const int CapCutterId = 17916;
        var exactCapCut = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 0, CentreYFt: 0, AxisX: 0, AxisY: 0,
            WidthFt: 0, DepthFt: 0, BaseZFt: 0, HeightFt: 0,
            ExactDepth: true,
            Boundary: BoxGeometry(1.5, -1, 0, 2.5, 1, 1),
            IsExactConcordantFamilyCut: true);
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [CapCutterId],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(CapCutterId, exactCapCut)],
        };
        Assert.True(IfcExporter
            .TryGetVerifiedBoundaryOwnedRedundantWallFromSingleExactCapCoincidentWriterOperand(
                wall, bounds, boundary, emittedCutters, emittedOperands,
                new Dictionary<int, List<int>>(), out var verifiedGross,
                out var verifiedCutterIds));
        Assert.Same(boundary, verifiedGross);
        Assert.Equal([CapCutterId], verifiedCutterIds);
        emittedOperands[wall.Id] =
        [
            (CapCutterId, exactCapCut with
            {
                IsExactConcordantFamilyCut = false,
            }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedBoundaryOwnedRedundantWallFromSingleExactCapCoincidentWriterOperand(
                wall, bounds, boundary, emittedCutters, emittedOperands,
                new Dictionary<int, List<int>>(), out _, out _));

        var minimumEnd = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 0.5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 1,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        var maximumEnd = minimumEnd with { CentreXFt = 3.5 };
        Assert.True(
            IfcExporter.HostedOpeningWriterOperandsAnchorBothEndsOfExactWall(
                wall, bounds, boundary, [minimumEnd, maximumEnd]));
        Assert.False(
            IfcExporter.HostedOpeningWriterOperandsAnchorBothEndsOfExactWall(
                wall, bounds, boundary, [minimumEnd]));
        Assert.False(
            IfcExporter.HostedOpeningWriterOperandsAnchorBothEndsOfExactWall(
                wall, bounds, boundary,
                [minimumEnd, minimumEnd with { WidthFt = 0.5 }]));

        wall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [-0.25, 0, 0],
            EndPoint = [4, 0, 0],
        };
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandAnchorsSoleInwardShiftedEndOfExactWall(
                wall, bounds, boundary, minimumEnd));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandAnchorsSoleInwardShiftedEndOfExactWall(
                wall, bounds, boundary, maximumEnd));

        wall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0, 0],
            EndPoint = [4, 0, 0],
        };
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandAnchorsSoleInwardShiftedEndOfExactWall(
                wall, bounds, boundary, minimumEnd));

        wall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [-0.25, 0, 0],
            EndPoint = [4.25, 0, 0],
        };
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandAnchorsSoleInwardShiftedEndOfExactWall(
                wall, bounds, boundary, minimumEnd));

        wall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0.25, 0, 0],
            EndPoint = [4, 0, 0],
        };
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandAnchorsSoleInwardShiftedEndOfExactWall(
                wall, bounds, boundary, minimumEnd));

        var offBoundary = Boundary();
        offBoundary.Faces[3].OuterVertices![2][0] = 3.9;
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            offBoundary, location, 1, bounds, out _, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactUncutSourceOwnedJoinedSpan()
    {
        var location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0.25, 0, 0],
            EndPoint = [3.75, 0, 0],
        };
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var boundary = new GeometryData
        {
            BoundingBox = bounds,
            Faces =
            [
                Face(
                [
                    [0, -0.5, 0], [4, -0.5, 0], [4, -0.5, 1.5],
                    [4, -0.5, 3], [0, -0.5, 3],
                ]),
                Face(
                [
                    [0, 0.5, 3], [4, 0.5, 3], [4, 0.5, 1.5],
                    [4, 0.5, 0], [0, 0.5, 0],
                ]),
                Face(
                [
                    [0, -0.5, 0], [0, 0.5, 0],
                    [4, 0.5, 0], [4, -0.5, 0],
                ]),
                Face(
                [
                    [4, -0.5, 0], [4, 0.5, 0],
                    [4, 0.5, 1.5], [4, -0.5, 1.5],
                ]),
                Face(
                [
                    [4, -0.5, 1.5], [4, 0.5, 1.5],
                    [4, 0.5, 3], [4, -0.5, 3],
                ]),
                Face(
                [
                    [4, -0.5, 3], [4, 0.5, 3],
                    [0, 0.5, 3], [0, -0.5, 3],
                ]),
                Face(
                [
                    [0, -0.5, 3], [0, 0.5, 3],
                    [0, 0.5, 0], [0, -0.5, 0],
                ]),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 7).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var sourceFaces = boundary.Faces.Select(face =>
            Face(face.OuterVertices!
                .Select(point => (double[])point.Clone()).ToList())).ToList();
        sourceFaces[0].OuterVertices =
        [
            [1, -0.5, 0], [2, -0.5, 0],
            [2, -0.5, 3], [1, -0.5, 3],
        ];
        sourceFaces[0].AlternativeOuterVertices = boundary.Faces[0]
            .OuterVertices!.Select(point => (double[])point.Clone()).ToList();
        var source = new GeometryData
        {
            BoundingBox = bounds,
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, sourceFaces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = 746,
            TypeId = 716,
            IsDiscovered = true,
            Name = "Uncut joined-span wall",
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = bounds,
            Geometry = source,
            CuttingElementIds = [],
            Location = location,
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
        };

        Assert.True(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, boundary, hasAnyEmittedWallOpening: false));
        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuilt));
        Assert.True(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, rebuilt, hasAnyEmittedWallOpening: false));

        var endSubdividedBoundary = new GeometryData
        {
            BoundingBox = bounds,
            Faces =
            [
                Face(
                [
                    [0, -0.5, 0], [4, -0.5, 0],
                    [4, -0.5, 3], [0, -0.5, 3],
                ]),
                Face(
                [
                    [0, 0.5, 3], [4, 0.5, 3],
                    [4, 0.5, 0], [0, 0.5, 0],
                ]),
                Face(
                [
                    [0, -0.5, 0], [0, 0.5, 0], [4, 0.5, 0],
                    [4, 0, 0], [4, -0.5, 0],
                ]),
                Face(
                [
                    [4, -0.5, 3], [4, 0.5, 3],
                    [0, 0.5, 3], [0, -0.5, 3],
                ]),
                Face(
                [
                    [4, -0.5, 0], [4, 0, 0], [4, 0.5, 0],
                    [4, 0.5, 3], [4, -0.5, 3],
                ]),
                Face(
                [
                    [0, -0.5, 3], [0, 0.5, 3],
                    [0, 0.5, 0], [0, -0.5, 0],
                ]),
            ],
        };
        sourceFaces[0].AlternativeOuterVertices =
            endSubdividedBoundary.Faces[4].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.True(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, endSubdividedBoundary,
            hasAnyEmittedWallOpening: false));
        var doublySubdividedBoundary = new GeometryData
        {
            BoundingBox = bounds,
            Faces = boundary.Faces.Select(face =>
                Face(face.OuterVertices!
                    .Select(point => (double[])point.Clone()).ToList()))
                .ToList(),
        };
        doublySubdividedBoundary.Faces[0].OuterVertices!.Insert(
            1, [2, -0.5, 0]);
        doublySubdividedBoundary.Faces[2].OuterVertices!.Add(
            [2, -0.5, 0]);
        sourceFaces[0].AlternativeOuterVertices =
            doublySubdividedBoundary.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.True(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, doublySubdividedBoundary,
            hasAnyEmittedWallOpening: false));

        var filledInnerBoundary = new GeometryData
        {
            BoundingBox = bounds,
            Faces = boundary.Faces.Select(face =>
                Face(face.OuterVertices!
                    .Select(point => (double[])point.Clone()).ToList()))
                .ToList(),
        };
        filledInnerBoundary.Faces[0].OuterVertices!.Insert(
            1, [2, -0.5, 0]);
        filledInnerBoundary.Faces[0].OuterVertices!.Insert(
            4, [4, -0.5, 2.25]);
        filledInnerBoundary.Faces[0].OuterVertices!.Insert(
            6, [2, -0.5, 3]);
        filledInnerBoundary.Faces[2].OuterVertices!.Add(
            [2, -0.5, 0]);
        filledInnerBoundary.Faces[4].OuterVertices!.Add(
            [4, -0.5, 2.25]);
        filledInnerBoundary.Faces[5].OuterVertices!.Add(
            [2, -0.5, 3]);
        List<double[]> filledInner =
        [
            [1, -0.5, 1], [3, -0.5, 1],
            [3, -0.5, 2], [1, -0.5, 2],
        ];
        sourceFaces[0].OuterVertices =
        [
            [0, -0.5, 0], [4, -0.5, 0],
            [4, -0.5, 3], [0, -0.5, 3],
        ];
        sourceFaces[0].AlternativeOuterVertices =
            filledInnerBoundary.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        sourceFaces[0].InnerVertices =
        [
            filledInner.Select(point =>
                (double[])point.Clone()).ToList(),
        ];
        sourceFaces.Add(Face(filledInner.Select(point =>
            (double[])point.Clone()).AsEnumerable().Reverse().ToList()));
        source.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, sourceFaces.Count).ToList();
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                filledInnerBoundary, location, 1, bounds,
                out _, out _, out _, out string filledInnerReason),
            filledInnerReason);
        Assert.Equal(
            "exact-boundary-owned-redundant-faces", filledInnerReason);
        Assert.True(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, filledInnerBoundary,
            hasAnyEmittedWallOpening: false));
        sourceFaces[^1].OuterVertices![0][2] = 2.125;
        Assert.False(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, filledInnerBoundary,
            hasAnyEmittedWallOpening: false));
        sourceFaces.RemoveAt(sourceFaces.Count - 1);
        sourceFaces[0].InnerVertices = null;
        sourceFaces[0].OuterVertices =
        [
            [1, -0.5, 0], [2, -0.5, 0],
            [2, -0.5, 3], [1, -0.5, 3],
        ];
        source.BrepSolids[0].FaceIndices =
            Enumerable.Range(0, sourceFaces.Count).ToList();
        sourceFaces[0].AlternativeOuterVertices = boundary.Faces[0]
            .OuterVertices!.Select(point => (double[])point.Clone()).ToList();

        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-uncut-joined-span-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCARBITRARYCLOSEDPROFILEDEF(", ifc);
            Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
            Assert.DoesNotContain("=IFCOPENINGELEMENT(", ifc);
            Assert.Contains("=IFCCARTESIANPOINT((-609.6,0.));", ifc);
            Assert.Contains("=IFCCARTESIANPOINT((609.6,0.));", ifc);
            Assert.DoesNotContain("=IFCCARTESIANPOINT((-533.4,0.));", ifc);
            Assert.DoesNotContain("=IFCCARTESIANPOINT((533.4,0.));", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        wall.CuttingElementIds = [9001];
        Assert.False(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, boundary, hasAnyEmittedWallOpening: false));
        wall.CuttingElementIds = [];
        source.Faces[2].AlternativeOuterVertices =
            boundary.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.False(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, boundary, hasAnyEmittedWallOpening: false));
        source.Faces[2].AlternativeOuterVertices = null;
        source.Faces[1].OuterVertices =
        [
            [0, 0.5, 3], [4, 0.5, 3],
            [4, 0.5, 0], [0, 0.5, 0],
        ];
        Assert.False(IfcExporter.TryGetExactUncutSourceOwnedJoinedSpan(
            wall, bounds, boundary, hasAnyEmittedWallOpening: false));
    }

    [Fact]
    public void ExactWallDefinition_AllowsOnlyCompleteCollinearBoundarySubdivision()
    {
        var location = new LocationCurve
        {
            CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
        };
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        double[][] low =
        [
            [0, -0.5, 0], [2, -0.5, 0], [4, -0.5, 0],
            [4, 0.5, 0], [2, 0.5, 0], [0, 0.5, 0],
        ];
        double[][] high = low.Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var faces = new List<GeoFace>
        {
            Face(low), Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < low.Length; index++)
            faces.Add(Face(
            [
                low[index], high[index], high[(index + 1) % high.Length],
                low[(index + 1) % low.Length],
            ]));
        GeometryData Geometry(List<GeoFace> geometryFaces) => new()
        {
            BoundingBox = bounds,
            Faces = geometryFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, geometryFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var subdivided = Geometry(faces);

        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            subdivided, location, 1, bounds,
            out var plan, out double baseZFt, out double heightFt,
            out string rejectionReason), rejectionReason);
        Assert.Equal("exact-collinear-boundary-subdivision", rejectionReason);
        Assert.Equal(6, plan.Count);
        Assert.Equal(0, baseZFt, 12);
        Assert.Equal(3, heightFt, 12);

        var missingSide = Geometry(faces.Take(faces.Count - 1).ToList());
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            missingSide, location, 1, bounds, out _, out _, out _));

        var internalFace = Geometry([.. faces]);
        internalFace.Faces.Add(Face(
        [
            [2, -0.5, 0], [2, -0.5, 3], [2, 0.5, 3], [2, 0.5, 0],
        ]));
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            internalFace, location, 1, bounds, out _, out _, out _));

        var offBoundaryFaces = faces.Select(face => Face(face.OuterVertices!)).ToList();
        offBoundaryFaces[0].OuterVertices![1][1] = -0.4;
        var offBoundary = Geometry(offBoundaryFaces);
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            offBoundary, location, 1, bounds, out _, out _, out _));
    }

    [Fact]
    public void ExactWallDefinition_AllowsOnlyMatchedVerticalProfileEdgeSubdivision()
    {
        var location = new LocationCurve
        {
            CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
        };
        double[] bounds = [0, -0.5, -0.15, 4.25, 0.5, 3.7];
        double[][] low =
        [
            [0, -0.5, 0], [0, -0.5, 3.696], [0, -0.5, 3.7],
            [4, -0.5, 3.7], [4, -0.5, -0.15], [0, -0.5, -0.15],
        ];
        double[][] high =
        [
            [0.25, 0.5, -0.15], [4.25, 0.5, -0.15],
            [4.25, 0.5, 3.7], [0.25, 0.5, 3.7],
            [0.25, 0.5, 3.696], [0.25, 0.5, 0],
        ];
        GeometryData Geometry(
            IReadOnlyList<double[]> lowProfile,
            IReadOnlyList<double[]> highProfile)
        {
            var geometryFaces =
                new List<GeoFace> { Face(lowProfile), Face(highProfile) };
            for (int index = 0; index < lowProfile.Count; index++)
            {
                int highIndex = highProfile.Count - 1 - index;
                int highNext = (highIndex + highProfile.Count - 1)
                    % highProfile.Count;
                geometryFaces.Add(Face(
                [
                    lowProfile[index], highProfile[highIndex],
                    highProfile[highNext],
                    lowProfile[(index + 1) % lowProfile.Count],
                ]));
            }
            return GeometryFromFaces(geometryFaces);
        }
        GeometryData GeometryFromFaces(IEnumerable<GeoFace> sourceFaces)
        {
            var geometryFaces = sourceFaces.ToList();
            return new GeometryData
            {
                BoundingBox = bounds,
                Faces = geometryFaces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(0, geometryFaces.Count)
                            .ToList(),
                        IsClosed = true,
                    },
                ],
            };
        }
        var subdivided = Geometry(low, high);

        Assert.False(IfcExporter.IsExactVerticalExtrusionBoundary(subdivided));
        Assert.True(IfcExporter.IsExactFacetedShell(
            subdivided.Faces, subdivided.BrepSolids![0].FaceIndices));
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            subdivided, location, 1, bounds,
            out var plan, out double baseZFt, out double heightFt,
            out string rejectionReason), rejectionReason);
        Assert.Equal(
            "exact-subdivided-vertical-profile-edge", rejectionReason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(-0.15, baseZFt, 5);
        Assert.Equal(3.85, heightFt, 5);

        double[][] singleLow =
        [
            low[0], low[2], low[3], low[4], low[5],
        ];
        double[][] singleHigh =
        [
            high[0], high[1], high[2], high[3], high[5],
        ];
        var singleSubdivision = Geometry(singleLow, singleHigh);
        Assert.False(IfcExporter.IsExactVerticalExtrusionBoundary(
            singleSubdivision));
        Assert.True(IfcExporter.IsExactFacetedShell(
            singleSubdivision.Faces,
            singleSubdivision.BrepSolids![0].FaceIndices));
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            singleSubdivision, location, 1, bounds,
            out plan, out baseZFt, out heightFt, out rejectionReason),
            rejectionReason);
        Assert.Equal(
            "exact-subdivided-vertical-profile-edge", rejectionReason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(-0.15, baseZFt, 5);
        Assert.Equal(3.85, heightFt, 5);
        var singleSubdivisionWall = new Element
        {
            Location = location,
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Geometry = singleSubdivision,
            BoundingBox = bounds,
        };
        var exactInteriorCut = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 1, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                singleSubdivisionWall, bounds, singleSubdivision,
                exactInteriorCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                singleSubdivisionWall, bounds, singleSubdivision,
                exactInteriorCut with { DepthFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                singleSubdivisionWall, bounds, singleSubdivision,
                exactInteriorCut with { CentreXFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                singleSubdivisionWall, bounds, singleSubdivision,
                exactInteriorCut with { BaseZFt = -0.15 }));

        double[][] mismatchedSingleHigh = singleHigh
            .Select(point => point.ToArray()).ToArray();
        mismatchedSingleHigh[^1][2] = 0.1;
        var mismatchedSingleSubdivision =
            Geometry(singleLow, mismatchedSingleHigh);
        Assert.True(IfcExporter.IsExactFacetedShell(
            mismatchedSingleSubdivision.Faces,
            mismatchedSingleSubdivision.BrepSolids![0].FaceIndices));
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            mismatchedSingleSubdivision, location, 1, bounds,
            out _, out _, out _));

        var missingConnector = GeometryFromFaces(
            subdivided.Faces.Take(subdivided.Faces.Count - 1));
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            missingConnector, location, 1, bounds, out _, out _, out _));

        double[][] horizontalLow =
        [
            [1, -0.5, -0.15], [2, -0.5, -0.15], [4, -0.5, -0.15],
            [4, -0.5, 3.7], [0, -0.5, 3.7], [0, -0.5, -0.15],
        ];
        double[][] horizontalHigh =
        [
            [0.25, 0.5, -0.15], [0.25, 0.5, 3.7],
            [4.25, 0.5, 3.7], [4.25, 0.5, -0.15],
            [2.25, 0.5, -0.15], [1.25, 0.5, -0.15],
        ];
        var horizontalSubdivision = Geometry(horizontalLow, horizontalHigh);
        Assert.True(IfcExporter.IsExactFacetedShell(
            horizontalSubdivision.Faces,
            horizontalSubdivision.BrepSolids![0].FaceIndices));
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            horizontalSubdivision, location, 1, bounds, out _, out _, out _));

        double[][] overlappingLow =
        [
            [0, -0.5, 2.1], [4, -0.5, 2.1], [4, -0.5, -0.15],
            [4, -0.5, 3.7], [0, -0.5, 3.7], [0, -0.5, -0.15],
        ];
        double[][] overlappingHigh =
        [
            [0.25, 0.5, -0.15], [0.25, 0.5, 3.7],
            [4.25, 0.5, 3.7], [4.25, 0.5, -0.15],
            [4.25, 0.5, 2.1], [0.25, 0.5, 2.1],
        ];
        var overlappingProfile = Geometry(overlappingLow, overlappingHigh);
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            overlappingProfile, location, 1, bounds, out _, out _, out _));
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_RequiresRobustExactSeparation()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = boundary,
            BoundingBox = bounds,
        };

        var separatedBox = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2, BaseZFt: 4, HeightFt: 1,
            ExactDepth: true);
        var touchingBox = separatedBox with { BaseZFt = 3 };
        var overlappingBox = separatedBox with { BaseZFt = 2 };
        var separatedBoundary = separatedBox with
        {
            Boundary = BoxGeometry(1, -1, 4, 3, 1, 5),
        };
        var touchingBoundary = separatedBox with
        {
            Boundary = BoxGeometry(1, -1, 3, 3, 1, 4),
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, boundary, separatedBox));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, boundary, touchingBox));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, boundary, overlappingBox));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, boundary, separatedBoundary));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, boundary, touchingBoundary));

        // The world AABBs overlap at the upper-right wall corner, but the two exact
        // convex plans have a separating axis with a gap well above IFC precision.
        var diagonalBoundary = BoxGeometry(-0.4, -0.4, 1, 0.4, 0.4, 2);
        double cosine = Math.Sqrt(0.5), sine = cosine;
        foreach (double[] point in diagonalBoundary.Faces!
                     .SelectMany(face => face.OuterVertices!))
        {
            double x = point[0], y = point[1];
            point[0] = 4.5 + x * cosine - y * sine;
            point[1] = 1 + x * sine + y * cosine;
        }
        var diagonallySeparatedBoundary = separatedBox with
        {
            Boundary = diagonalBoundary,
        };
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, boundary, diagonallySeparatedBoundary));
    }

    [Fact]
    public void HostedOpeningWriterOperandValidations_AllowMixedStableKinds()
    {
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20], [10], [20]));
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20], [10, 20], []));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20], [10], []));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 10], [10], []));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10], [10], [20]));
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30], [10], [20], [30]));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30], [10], [20], []));
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30, 40], [10], [20], [30], [40]));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30, 40], [10], [20], [30], []));
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30, 40, 50], [10], [20], [30], [40], [50]));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30, 40, 50], [10], [20], [30], [40], []));
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30, 40, 50, 60],
            [10], [20], [30], [40], [50], [60]));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20, 30, 40, 50, 60],
            [10], [20], [30], [40], [50], []));
        Assert.True(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20], [10], [], [], [], [], [20], [], [], []));
        Assert.False(IfcExporter.HostedOpeningWriterOperandValidationsCoverAllCutters(
            [10, 20], [10], [], [], [], [], [], [], [], []));
    }

