    [Fact]
    public void BoundaryOwnedJoinedSpanValidation_RequiresCompleteForwardPrimaryHostEndSidePartition()
    {
        var wall = new Element
        {
            Id = 1,
            References = [10, 20],
        };
        var firstCutter = new Element
        {
            Id = 10,
            HostId = wall.Id,
            SerializedHostId = wall.Id,
        };
        var secondCutter = new Element
        {
            Id = 20,
            HostId = wall.Id,
            SerializedHostId = wall.Id,
        };
        var elemById = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [firstCutter.Id] = firstCutter,
            [secondCutter.Id] = secondCutter,
        };
        var operands = new List<(
            int CutterId, IfcExporter.HostedOpeningGeometry Operand)>
        {
            (firstCutter.Id, default),
            (secondCutter.Id, default),
        };

        Assert.True(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
                [firstCutter.Id, secondCutter.Id],
                [firstCutter.Id], [secondCutter.Id]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
                [firstCutter.Id, secondCutter.Id],
                [firstCutter.Id], [firstCutter.Id]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
                [firstCutter.Id, secondCutter.Id],
                [firstCutter.Id], []));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
                [firstCutter.Id, secondCutter.Id],
                [], [secondCutter.Id]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
                [firstCutter.Id, firstCutter.Id],
                [firstCutter.Id], [secondCutter.Id]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
                [firstCutter.Id, secondCutter.Id, 30],
                [firstCutter.Id], [secondCutter.Id]));

        wall.CuttingElementIds = [];
        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands));
        wall.CuttingElementIds = null;

        wall.References = [firstCutter.Id, firstCutter.Id, secondCutter.Id];
        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands));
        wall.References = [firstCutter.Id, secondCutter.Id];

        firstCutter.ExtraHostIds = [wall.Id];
        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands));
        firstCutter.ExtraHostIds = null;

        secondCutter.SerializedHostId = 2;
        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands));
        secondCutter.SerializedHostId = wall.Id;

        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands.Take(1).ToList()));
        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, firstCutter.Id],
                operands));

        var omittedCutter = new Element
        {
            Id = 30,
            HostId = wall.Id,
            SerializedHostId = wall.Id,
        };
        elemById[omittedCutter.Id] = omittedCutter;
        wall.References.Add(omittedCutter.Id);
        Assert.False(IfcExporter
            .ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
                wall, elemById, [firstCutter.Id, secondCutter.Id],
                operands));
    }

