    [Fact]
    public void BoundaryOwnedSingleInteriorBrepValidation_RequiresExactHalfWidthEndShift()
    {
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleInteriorBrepJoinedSpan(
                [10], [], [10]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleInteriorBrepJoinedSpan(
                [10, 20], [], [10, 20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleInteriorBrepJoinedSpan(
                [10], [10], [10]));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentBrepJoinedSpan(
                [10], [], [], [10]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentBrepJoinedSpan(
                [10], [], [10], [10]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentBrepJoinedSpan(
                [10, 20], [], [], [10, 20]));

        var boundary = BoxGeometry(0, -0.5, 0, 6, 0.5, 3);
        var oneEndShifted = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [-0.5, 0, 0],
            EndPoint = [6, 0, 0],
        };
        Assert.True(IfcExporter
            .ExactStraightWallPlanEndpointsUseHalfWidthLattice(
                oneEndShifted, 1, boundary));

        var sourceAuthoredEndOffset = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0, 0],
            EndPoint = [6.75, 0, 0],
        };
        Assert.False(IfcExporter
            .ExactStraightWallPlanEndpointsUseHalfWidthLattice(
                sourceAuthoredEndOffset, 1, boundary));

        var unchanged = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0, 0],
            EndPoint = [6, 0, 0],
        };
        Assert.False(IfcExporter
            .ExactStraightWallPlanEndpointsUseHalfWidthLattice(
                unchanged, 1, boundary));
    }

    [Fact]
    public void BoundaryOwnedCapBrepValidation_RequiresUniqueReciprocalPathSideEndTrim()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 6, 0.5, 3);
        var wall = new Element
        {
            Id = 10,
            CategoryId = -2000011,
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6.5, 0, 0],
            },
            Parameters = [WallWidthParameter(1)],
            References = [20],
        };
        var neighbour = new Element
        {
            Id = 20,
            CategoryId = -2000011,
            BoundingBox = [6, -5, -1, 7, 5, 4],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [6.5, -5, 0],
                EndPoint = [6.5, 5, 0],
            },
            Parameters = [WallWidthParameter(1)],
            References = [wall.Id],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [neighbour.Id] = neighbour,
        };

        Assert.True(IfcExporter
            .ExactStraightWallPlanHasSingleInwardEndTrimByReciprocalPathNeighbourSideLattice(
                wall, elements, boundary));

        neighbour.References = [];
        Assert.False(IfcExporter
            .ExactStraightWallPlanHasSingleInwardEndTrimByReciprocalPathNeighbourSideLattice(
                wall, elements, boundary));
        neighbour.References = [wall.Id];

        var outwardBoundary = BoxGeometry(
            0, -0.5, 0, 7, 0.5, 3);
        Assert.False(IfcExporter
            .ExactStraightWallPlanHasSingleInwardEndTrimByReciprocalPathNeighbourSideLattice(
                wall, elements, outwardBoundary));

        var connectedLocation = neighbour.Location;
        neighbour.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [6.5, 1, 0],
            EndPoint = [6.5, 5, 0],
        };
        Assert.False(IfcExporter
            .ExactStraightWallPlanHasSingleInwardEndTrimByReciprocalPathNeighbourSideLattice(
                wall, elements, boundary));
        neighbour.Location = connectedLocation;

        var duplicateNeighbour = new Element
        {
            Id = 30,
            CategoryId = neighbour.CategoryId,
            BoundingBox = (double[])neighbour.BoundingBox!.Clone(),
            Location = neighbour.Location,
            Parameters = neighbour.Parameters,
            References = [wall.Id],
        };
        elements[duplicateNeighbour.Id] = duplicateNeighbour;
        wall.References = [neighbour.Id, duplicateNeighbour.Id];
        Assert.False(IfcExporter
            .ExactStraightWallPlanHasSingleInwardEndTrimByReciprocalPathNeighbourSideLattice(
                wall, elements, boundary));
    }

