    [Fact]
    public void BoundaryOwnedJoinedSpanPathEndLattice_ConfirmsTwoInwardEndsFromBidirectionalGraph()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 10, 0.5, 3);
        var wall = new Element
        {
            Id = 10,
            CategoryId = -2000011,
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [-1, 0, 0],
                EndPoint = [11, 0, 0],
            },
            Parameters = [WallWidthParameter(1)],
            References = [30],
        };
        Element Neighbour(int id, double x, List<int> references) => new()
        {
            Id = id,
            CategoryId = -2000011,
            BoundingBox = [x - 1, -5, -1, x + 1, 5, 4],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [x, -5, 0],
                EndPoint = [x, 5, 0],
            },
            Parameters = [WallWidthParameter(2)],
            References = references,
            Geometry = BoxGeometry(x - 1, -5, -1, x + 1, 5, 4),
        };
        var startNeighbour = Neighbour(20, -1, [wall.Id]);
        var endNeighbour = Neighbour(30, 11, []);
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [startNeighbour.Id] = startNeighbour,
            [endNeighbour.Id] = endNeighbour,
        };
        int[] bidirectionalNeighbours =
            [startNeighbour.Id, endNeighbour.Id];

        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            boundary, wall.Location, 1, wall.BoundingBox!,
            out _, out _, out _, out string definitionReason), definitionReason);
        Assert.True(IfcExporter
            .ExactStraightWallPlanEndpointsUseExplicitPathNeighbourLattice(
                wall, elements, boundary, bidirectionalNeighbours,
                requireBothEndsInwardTrim: true));
        Assert.False(IfcExporter
            .ExactStraightWallPlanEndpointsUseExplicitPathNeighbourLattice(
                wall, elements, boundary,
                requireBothEndsInwardTrim: true));

        startNeighbour.References = [];
        Assert.False(IfcExporter
            .ExactStraightWallPlanEndpointsUseExplicitPathNeighbourLattice(
                wall, elements, boundary, bidirectionalNeighbours,
                requireBothEndsInwardTrim: true));
        startNeighbour.References = [wall.Id];

        Assert.False(IfcExporter
            .ExactStraightWallPlanEndpointsUseExplicitPathNeighbourLattice(
                wall, elements, BoxGeometry(-1, -0.5, 0, 10, 0.5, 3),
                bidirectionalNeighbours,
                requireBothEndsInwardTrim: true));

        var duplicateStartNeighbour = Neighbour(40, -1, [wall.Id]);
        elements[duplicateStartNeighbour.Id] = duplicateStartNeighbour;
        Assert.False(IfcExporter
            .ExactStraightWallPlanEndpointsUseExplicitPathNeighbourLattice(
                wall, elements, boundary,
                [.. bidirectionalNeighbours, duplicateStartNeighbour.Id],
                requireBothEndsInwardTrim: true));
    }

    [Fact]
    public void BoundaryOwnedSingleCapCoincidentSweptValidation_RequiresExactSinglePartition()
    {
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmCapCoincidentSweptWithDisjointJoinedSpan(
                [10, 20], [10], [20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmCapCoincidentSweptWithDisjointJoinedSpan(
                [10, 20], [], [20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmCapCoincidentSweptWithDisjointJoinedSpan(
                [10, 20], [10], [10]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmCapCoincidentSweptWithDisjointJoinedSpan(
                [10, 10], [10], [20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmCapCoincidentSweptWithDisjointJoinedSpan(
                [10, 20, 30], [10], [20]));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandFullHeightCapCrossingBrepWithDisjointJoinedSpan(
                [10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 50], [60]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandFullHeightCapCrossingBrepWithDisjointJoinedSpan(
                [10, 20, 30, 40, 50, 60], [10, 20, 30, 40], [60]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandFullHeightCapCrossingBrepWithDisjointJoinedSpan(
                [10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 60], [60]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandFullHeightCapCrossingBrepWithDisjointJoinedSpan(
                [10, 20, 30, 40, 50, 50], [10, 20, 30, 40, 50], [60]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandFullHeightCapCrossingBrepWithDisjointJoinedSpan(
                [10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 50], [70]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandFullHeightCapCrossingBrepWithDisjointJoinedSpan(
                [10, 20, 30, 40, 50, 60, 70],
                [10, 20, 30, 40, 50, 60], [70]));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentSweptJoinedSpan(
                [10], [], [10]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentSweptJoinedSpan(
                [10], [10], [10]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentSweptJoinedSpan(
                [10], [], []));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentSweptJoinedSpan(
                [10, 20], [], [10, 20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleCapCoincidentSweptJoinedSpan(
                [10, 10], [], [10]));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmInteriorAndWriterPrecisionCapSweptJoinedSpan(
                [10, 20], [10], [20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmInteriorAndWriterPrecisionCapSweptJoinedSpan(
                [10, 20], [], [10, 20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmInteriorAndWriterPrecisionCapSweptJoinedSpan(
                [10, 20], [10, 20], []));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmInteriorAndWriterPrecisionCapSweptJoinedSpan(
                [10, 20], [10], [10, 20]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmInteriorAndWriterPrecisionCapSweptJoinedSpan(
                [10, 10], [10], [20]));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSixOperandPanelJoinedSpan(
                [10, 20, 30, 40, 50, 60],
                [10], [20], [30], [40], [50], [60]));
        Assert.False(IfcExporter
