        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmBidirectionalSixOperandPanelWithSingleEndCrossingJoinedSpan(
                [10, 20, 30, 40, 50, 60],
                [10], [20], [30], [40], [50], [50]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmBidirectionalSixOperandPanelWithSingleEndCrossingJoinedSpan(
                [10, 20, 30, 40, 50, 50],
