    [Fact]
    public void WriterLatticeWallPlan_SnapsEveryCoordinateToFacetedBrepGrid()
    {
        var snapped = IfcExporter.SnapPlanToIfcWriterLattice(
        [
            [1.000001, 2.000019],
            [-3.000011, 4.000029],
        ]);

        Assert.Equal(0.3048, snapped[0][0] * 0.3048, 5);
        Assert.Equal(0.60961, snapped[0][1] * 0.3048, 5);
