    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_RequiresRobustRectangularBoundaryCut()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = boundary,
            BoundingBox = bounds,
        };

        var endCut = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 0, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 2, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        var interiorCut = endCut with { CentreXFt = 2, WidthFt = 1 };
        var touchingCut = endCut with { CentreXFt = 0.5, WidthFt = 1 };
        var shallowCut = endCut with { DepthFt = 0.5 };
        var endBoundaryCut = endCut with
        {
            Boundary = BoxGeometry(-1, -1, 1, 1, 1, 2),
        };
        var interiorBoundaryCut = endCut with
        {
            Boundary = BoxGeometry(1, -1, 1, 2, 1, 2),
        };
        var rotatedBoundary = BoxGeometry(-1.5, -1.5, 1, 1.5, 1.5, 2);
        const double rotation = 0.3;
        double cosine = Math.Cos(rotation), sine = Math.Sin(rotation);
        foreach (double[] point in rotatedBoundary.Faces!
                     .SelectMany(face => face.OuterVertices!))
        {
            double x = point[0], y = point[1];
            point[0] = x * cosine - y * sine;
            point[1] = x * sine + y * cosine;
        }
        var rotatedBoundaryCut = endCut with { Boundary = rotatedBoundary };
        double[][] miterBottom =
        [
            [0, -0.5, 0], [4, -0.5, 0], [4.5, 0.5, 0], [-0.5, 0.5, 0],
        ];
        double[][] miterTop = miterBottom
            .Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var miterFaces = new List<GeoFace>
        {
            Face(miterBottom), Face(miterTop.AsEnumerable().Reverse().ToArray()),
            Face([miterBottom[0], miterTop[0], miterTop[1], miterBottom[1]]),
            Face([miterBottom[1], miterTop[1], miterTop[2], miterBottom[2]]),
            Face([miterBottom[2], miterTop[2], miterTop[3], miterBottom[3]]),
            Face([miterBottom[3], miterTop[3], miterTop[0], miterBottom[0]]),
        };
        var miterBoundary = new GeometryData
        {
            BoundingBox = [-0.5, -0.5, 0, 4.5, 0.5, 3],
            Faces = miterFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = true,
                    FaceIndices = Enumerable.Range(0, miterFaces.Count).ToList(),
                },
            ],
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, endCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, interiorCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, touchingCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, shallowCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, endBoundaryCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, rotatedBoundaryCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, [-0.5, -0.5, 0, 4.5, 0.5, 3],
                miterBoundary, endBoundaryCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
                wall, bounds, boundary, interiorBoundaryCut));
    }

