        };

        IfcExporter.HostedOpeningGeometry Stepped(
            double centreX, double width, double baseZ, double height)
        {
            var definition = new IfcExporter.HostedOpeningGeometry(
                CentreXFt: centreX, CentreYFt: 0,
                AxisX: 1, AxisY: 0,
                WidthFt: width, DepthFt: 2,
                BaseZFt: baseZ, HeightFt: height,
                ExactDepth: true,
                IsExactParameterizedReveal: true);
            double innerWidth = width * 0.75;
            double innerHeight = height * 0.75;
            Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
                definition, innerWidth, innerHeight,
                breakpointNormalFt: 0, innerAtMinimum: false,
                out var steppedBoundary));
            return definition with
            {
                Boundary = steppedBoundary,
                SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                    innerWidth, innerHeight, 0, false),
            };
        }

        var exactInteriorCut = Stepped(2, 1, 1, 1);
        var missingProvenance = exactInteriorCut with
        {
            IsExactParameterizedReveal = false,
        };
        var mismatchedDefinition = exactInteriorCut with
        {
            SteppedProfile = exactInteriorCut.SteppedProfile!.Value with
            {
                BreakpointNormalFt = 0.125,
            },
        };
        var endTouching = Stepped(0.5, 1, 1, 1);
        var capTouching = Stepped(2, 1, 0, 1);
        var minimumCapCrossing = Stepped(2, 1, -1, 2);
        var bothCapsCrossing = Stepped(2, 1, -1, 5);

        Assert.True(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, exactInteriorCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, minimumCapCrossing));
        Assert.False(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, boundary, exactInteriorCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, missingProvenance));
        Assert.False(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, mismatchedDefinition));
        Assert.False(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, endTouching));
        Assert.False(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, capTouching));
        Assert.False(IfcExporter
            .HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCapsCrossing));

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleExactSteppedJoinedSpan(
                [2055104], [2055104]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleExactSteppedJoinedSpan(
                [2055104], []));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleExactSteppedJoinedSpan(
                [2055104, 2055104], [2055104]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleExactSteppedJoinedSpan(
                [2055104], [2055104, 2055104]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmSingleExactSteppedJoinedSpan(
                [2055104], [2722170]));
    }

    [Fact]
    public void JoinedWallEndProfileOpening_RequiresExactProfileDisjointPartition()
    {
        var profile = new IfcExporter.ProfileWallThroughOpening(
            1, 0,
            [
                (2, 1), (2, 4), (5, 4),
                (5, 3), (4, 3), (4, 1),
            ],
            -1, 1);

        Assert.True(IfcExporter.TryBuildExactVerticalProfileOpeningBoundary(
            profile, out var boundary));
        Assert.Equal(8, boundary.Faces.Count);
        Assert.NotNull(boundary.BrepSolids);
        Assert.Single(boundary.BrepSolids!);
        Assert.True(boundary.BrepSolids![0].IsClosed);
        Assert.Equal(12, boundary.Faces
            .SelectMany(face => face.OuterVertices!)
            .Select(Key).Distinct().Count());
        Assert.NotNull(boundary.BoundingBox);
        Assert.Equal([2, -1, 1, 5, 1, 4], boundary.BoundingBox!);

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmJoinedWallEndProfileWithDisjointJoinedSpan(
                [1487082, 1605546], [1605546], [1487082]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmJoinedWallEndProfileWithDisjointJoinedSpan(
                [1487082], [], [1487082]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmJoinedWallEndProfileWithDisjointJoinedSpan(
                [1487082, 1605546], [1487082], [1487082]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmJoinedWallEndProfileWithDisjointJoinedSpan(
                [1487082, 1605546], [1605546, 1605546], [1487082]));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandValidationsConfirmJoinedWallEndProfileWithDisjointJoinedSpan(
                [1487082, 1487082], [1605546], [1487082]));
    }

    [Fact]
    public void JoinedWallEndProfileOpening_RequiresExactOpenShellAuthority()
    {
        static GeoFace HorizontalPolygon(
            int vertexCount, double centreX, double centreY, double z)
        {
            var vertices = Enumerable.Range(0, vertexCount)
                .Select(index => new[]
                {
                    centreX + 0.05 * Math.Cos(
                        2 * Math.PI * index / vertexCount),
                    centreY + 0.05 * Math.Sin(
                        2 * Math.PI * index / vertexCount),
                    z,
                }).ToList();
            return new GeoFace { OuterVertices = vertices };
        }

        static List<GeoFace> SymbolicFaces(
            IReadOnlyList<int[]> cycles,
            IReadOnlyDictionary<int, double[]> fixedPoints,
            double minimumX, double z)
        {
            var points = fixedPoints.ToDictionary(
                item => item.Key, item => (double[])item.Value.Clone());
            int generatedPointCount = 0;
            double[] Point(int id)
            {
                if (points.TryGetValue(id, out var point)) return point;
                double ordinal = ++generatedPointCount;
                point =
                [
                    minimumX + 0.02 * ordinal,
                    -0.4 + 0.0002 * ordinal * ordinal,
                    z,
                ];
                points[id] = point;
                return point;
            }
            return cycles.Select(cycle =>
                Face(cycle.Select(Point))).ToList();
        }

        static GeometryData TargetSource()
        {
            int[][] cycles =
            [
                [0, 1, 4, 3], [1, 2, 5, 4],
                [2, 0, 3, 5], [3, 4, 7, 6],
                [4, 5, 8, 7], [5, 3, 6, 8],
                [0, 3, 10, 9], [9, 10, 11],
                [20, 21, 22, 23], [21, 20, 24, 25],
                [30, 31, 32, 34, 33],
                [100, 103, 102, 101], [101, 102, 106, 105],
                [102, 103, 107, 106], [103, 100, 104, 107],
                [100, 104, 107, 103], [103, 107, 106, 102],
                [102, 106, 105, 101], [101, 105, 104, 100],
            ];
            var faces = SymbolicFaces(cycles,
                new Dictionary<int, double[]>
                {
                    [20] = [1, -0.5, 0], [21] = [3, -0.5, 0],
                    [22] = [3, -0.5, 3], [23] = [1, -0.5, 3],
                    [30] = [1, 0.5, 3], [31] = [3, 0.5, 3],
                    [32] = [3, 0.5, 0], [33] = [1, 0.5, 0],
                    [34] = [3, 0.5, 0.00000001],
                }, minimumX: 0.1, z: 1.5);
            faces[2].AlternativeOuterVertices =
                HorizontalPolygon(6, 2, 0, 1.5).OuterVertices;
            return new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
                Faces = faces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(0, 11).ToList(),
                    },
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(11, 4).ToList(),
                    },
                    new GeoBrepSolid
                    {
                        FaceIndices = [11, 15, 16, 17, 18],
                    },
                ],
            };
        }

        static GeometryData CutterSource()
        {
            int[][] cycles =
            [
                [200, 205, 204, 203, 202, 201],
                [210, 211, 212, 213, 214, 215],
                [201, 202, 212, 211], [202, 203, 213, 212],
                [203, 204, 214, 213], [204, 205, 215, 214],
                [205, 200, 210, 215], [200, 201, 220, 221],
                [230, 231, 232, 233],
                [300, 302, 301], [310, 311, 312],
                [301, 302, 312, 311], [302, 300, 310, 312],
            ];
            var faces = SymbolicFaces(cycles,
                new Dictionary<int, double[]>
                {
                    [200] = [3, -0.5, 1], [201] = [5, -0.5, 1],
                    [220] = [5, -0.5, 4], [221] = [3, -0.5, 4],
                    [230] = [3, 0.5, 4], [231] = [5, 0.5, 4],
                    [232] = [5, 0.5, 1], [233] = [3, 0.5, 1],
                }, minimumX: 3.1, z: 2.5);
            return new GeometryData
            {
                BoundingBox = [3, -0.5, 1, 5, 0.5, 4],
                Faces = faces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(0, 9).ToList(),
                    },
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(9, 4).ToList(),
                    },
                ],
            };
        }

        Assert.True(IfcExporter
            .HasExactJoinedWallEndTargetSourceAuthority(TargetSource()));
        Assert.True(IfcExporter
            .HasExactJoinedWallEndCutterSourceAuthority(CutterSource()));

        var overlappingTargetSolids = TargetSource();
        overlappingTargetSolids.BrepSolids![1].FaceIndices.Add(0);
        Assert.False(IfcExporter
            .HasExactJoinedWallEndTargetSourceAuthority(
                overlappingTargetSolids));

        var wrongTargetAlternative = TargetSource();
        wrongTargetAlternative.Faces[0].AlternativeOuterVertices =
            HorizontalPolygon(4, 2, 0, 1.5).OuterVertices;
        Assert.False(IfcExporter
            .HasExactJoinedWallEndTargetSourceAuthority(
                wrongTargetAlternative));

        var wrongTargetEdges = TargetSource();
        wrongTargetEdges.Faces[0].OuterVertices![0][0] += 0.01;
        Assert.False(IfcExporter
            .HasExactJoinedWallEndTargetSourceAuthority(wrongTargetEdges));

        var outOfRangeTarget = TargetSource();
        outOfRangeTarget.Faces[0].OuterVertices![0][0] = double.MaxValue;
        Assert.False(IfcExporter
            .HasExactJoinedWallEndTargetSourceAuthority(outOfRangeTarget));

        var outOfRangeAlternative = TargetSource();
        outOfRangeAlternative.Faces[2]
            .AlternativeOuterVertices![0][0] = double.MaxValue;
        Assert.False(IfcExporter
            .HasExactJoinedWallEndTargetSourceAuthority(
                outOfRangeAlternative));

        var closedCutterShell = CutterSource();
        closedCutterShell.BrepSolids![0].IsClosed = true;
        Assert.False(IfcExporter
            .HasExactJoinedWallEndCutterSourceAuthority(closedCutterShell));

        var malformedWall = new Element
        {
            Id = 1,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0],
                EndPoint = [1, 0, 0],
            },
        };
        Assert.False(IfcExporter.TryBuildExactJoinedWallEndProfileOpening(
            malformedWall, [0, 0, 0, 1, 1, 1], new GeometryData(),
            new Dictionary<int, Element>(),
            new Dictionary<int, HashSet<int>>(),
            null, null, null, out _, out _, out _));

        double[] targetBounds = [0, -0.5, 0, 4, 0.5, 3];
        var rebuiltBoundary = new GeometryData
        {
            BoundingBox = targetBounds,
            Faces =
            [
                Face([[0, -0.5, 0], [4, -0.5, 0],
                    [4, -0.5, 1.5], [4, -0.5, 3], [0, -0.5, 3]]),
                Face([[0, 0.5, 3], [4, 0.5, 3],
                    [4, 0.5, 1.5], [4, 0.5, 0], [0, 0.5, 0]]),
                Face([[0, -0.5, 0], [0, 0.5, 0],
                    [4, 0.5, 0], [4, -0.5, 0]]),
                Face([[4, -0.5, 0], [4, 0.5, 0],
                    [4, 0.5, 1.5], [4, -0.5, 1.5]]),
                Face([[4, -0.5, 1.5], [4, 0.5, 1.5],
                    [4, 0.5, 3], [4, -0.5, 3]]),
                Face([[4, -0.5, 3], [4, 0.5, 3],
                    [0, 0.5, 3], [0, -0.5, 3]]),
                Face([[0, -0.5, 3], [0, 0.5, 3],
                    [0, 0.5, 0], [0, -0.5, 0]]),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 7).ToList(),
                    IsClosed = true,
                },
            ],
        };
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                rebuiltBoundary,
                new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [0.5, 0, 0],
                    EndPoint = [3.5, 0, 0],
                },
                1, targetBounds, out var rebuiltPlan, out _, out _,
                out string rebuiltReason), rebuiltReason);
        Assert.Equal("exact-boundary-owned-redundant-faces", rebuiltReason);
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            rebuiltPlan, targetBounds));

        var targetWall = new Element
        {
            Id = 1485448,
            CategoryId = -2000011,
            BoundingBox = targetBounds,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0.5, 0, 0],
                EndPoint = [3.5, 0, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            Geometry = TargetSource(),
            CuttingElementIds = [1487082, 1605546],
            References = [1487082],
        };
        var cutterWall = new Element
        {
            Id = 1487082,
            CategoryId = -2000011,
            BoundingBox = [3, -0.5, 1, 5, 0.5, 4],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [3.9, 0, 1],
                EndPoint = [4.9, 0, 1],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            Geometry = CutterSource(),
            References = [1485448],
        };
        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(
            targetWall, 1, out var truncatedTargetPlan));
        Assert.False(IfcExporter.WallPlanMatchesSerializedBounds(
            truncatedTargetPlan, targetBounds));
        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(
            cutterWall, 1, out var cutterPlan));
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            cutterPlan, cutterWall.BoundingBox!));

        var existingOperand = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 6.5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2,
            BaseZFt: 0, HeightFt: 1,
            ExactDepth: true,
            Boundary: BoxGeometry(6, -1, 0, 7, 1, 1));
        var existingCutter = new Element
        {
            Id = 1605546,
            CategoryId = -2000014,
        };
        var elements = new Dictionary<int, Element>
        {
            [targetWall.Id] = targetWall,
            [cutterWall.Id] = cutterWall,
            [existingCutter.Id] = existingCutter,
        };
        var emittedIds = new Dictionary<int, List<int>>
        {
            [targetWall.Id] = [existingCutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [targetWall.Id] = [(existingCutter.Id, existingOperand)],
        };

        bool TryBuild(
            out IfcExporter.ProfileWallThroughOpening candidateOpening,
            out IfcExporter.HostedOpeningGeometry candidateOperand,
            out int candidateCutterWallId) =>
            IfcExporter.TryBuildExactJoinedWallEndProfileOpening(
                targetWall, targetBounds, rebuiltBoundary, elements,
                new Dictionary<int, HashSet<int>>
                {
                    [targetWall.Id] = [cutterWall.Id],
                },
                emittedIds, emittedOperands,
                new Dictionary<int, List<int>>(),
                out candidateOpening, out candidateOperand,
                out candidateCutterWallId);

        var targetSourceBounds = targetWall.Geometry!.BoundingBox!;
        targetSourceBounds[0] += 0.01;
        Assert.False(TryBuild(out _, out _, out _));
        targetSourceBounds[0] -= 0.01;

        var cutterSourceBounds = cutterWall.Geometry!.BoundingBox!;
        cutterSourceBounds[3] -= 0.01;
        Assert.False(TryBuild(out _, out _, out _));
        cutterSourceBounds[3] += 0.01;

        Assert.True(TryBuild(
            out var exactOpening, out var exactOperand,
            out int cutterWallId));
        Assert.Equal(cutterWall.Id, cutterWallId);
        Assert.Equal(
            new (double AlongFt, double ZFt)[]
            {
                (3, 1), (3, 4), (5, 4),
                (5, 3), (4, 3), (4, 1),
            },
            exactOpening.Profile);
        Assert.Equal(-1, exactOpening.NormalMinimumFt, 12);
        Assert.Equal(1, exactOpening.NormalMaximumFt, 12);
        Assert.True(exactOperand.IsExactJoinedWallEndProfile);
        Assert.NotNull(exactOperand.Boundary);
        Assert.Equal([3, -1, 1, 5, 1, 4],
            exactOperand.Boundary!.BoundingBox!);
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_AllowsOnlySerializedBrepCapCoincidentThroughCut()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        var redundantBoundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        redundantBoundary.Faces!.RemoveAt(2);
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3]]));
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0]]));
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = redundantBoundary,
            BoundingBox = bounds,
        };
        var minimumCapCut = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 0, CentreYFt: 0, AxisX: 0, AxisY: 0,
            WidthFt: 0, DepthFt: 0, BaseZFt: 0, HeightFt: 0,
            ExactDepth: false,
            Boundary: BoxGeometry(1.5, -1, 0, 2.5, 1, 1));
        var maximumCapCut = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, 2, 2.5, 1, 3),
        };
        var bothCaps = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, 0, 2.5, 1, 3),
        };
        var interior = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, 1, 2.5, 1, 2),
        };
        var crossingCap = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, -0.001, 2.5, 1, 1),
        };
        var minimumCapFullHeightCrossing = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, 0, 2.5, 1, 4),
        };
        var maximumCapFullHeightCrossing = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, -1, 2.5, 1, 3),
        };
        var bothCapsCrossing = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, -1, 2.5, 1, 4),
        };
        var shallow = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -0.25, 0, 2.5, 0.25, 1),
        };
        var endCrossing = minimumCapCut with
        {
            Boundary = BoxGeometry(-1, -1, 0, 1, 1, 1),
        };
        var swept = minimumCapCut with { Boundary = null };

        Assert.True(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, minimumCapCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, maximumCapCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCaps));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, interior));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, crossingCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, shallow));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, endCrossing));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, boundary, minimumCapCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, swept));

        Assert.True(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                minimumCapFullHeightCrossing));
        Assert.True(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                maximumCapFullHeightCrossing));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCapsCrossing));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCaps));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, interior));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, shallow));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, endCrossing));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, boundary, minimumCapFullHeightCrossing));
        Assert.False(IfcExporter
            .HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, swept));
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_AllowsOnlySerializedHorizontalCapCoincidentThroughCut()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = boundary,
            BoundingBox = bounds,
        };
        var minimumCapCut = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2, BaseZFt: 0, HeightFt: 1,
            ExactDepth: true);
        var maximumCapCut = minimumCapCut with { BaseZFt = 2 };
        var bothCapsCut = minimumCapCut with { HeightFt = 3 };
        var perpendicularCut = minimumCapCut with
        {
            AxisX = 0, AxisY = 1, WidthFt = 2, DepthFt = 1,
        };
        var insideCaps = minimumCapCut with { BaseZFt = 1 };
        var crossingCap = minimumCapCut with { BaseZFt = -0.001 };
        var shallow = minimumCapCut with { DepthFt = 0.5 };
        var endTouching = minimumCapCut with { CentreXFt = 0.5 };
        var rotated = minimumCapCut with
        {
            AxisX = Math.Cos(0.001), AxisY = Math.Sin(0.001),
        };
        var inexactDepth = minimumCapCut with { ExactDepth = false };
        var brep = minimumCapCut with
        {
            Boundary = BoxGeometry(1.5, -1, 0, 2.5, 1, 1),
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, minimumCapCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, maximumCapCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, bothCapsCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, perpendicularCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, insideCaps));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, crossingCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, shallow));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, endTouching));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, rotated));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, inexactDepth));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, boundary, brep));
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_AllowsOnlyWriterPrecisionComplementaryCapThroughCut()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        var redundantBoundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        redundantBoundary.Faces!.RemoveAt(2);
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3]]));
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0]]));
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = redundantBoundary,
            BoundingBox = bounds,
        };
        var nearMaximumCap = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2, BaseZFt: 0, HeightFt: 2.99999,
            ExactDepth: true);
        var nearMinimumCap = nearMaximumCap with
        {
            BaseZFt = 0.00001,
            HeightFt = 2.99999,
        };
        var bothCapsExact = nearMaximumCap with { HeightFt = 3 };
        var onlyOneCap = nearMaximumCap with { HeightFt = 1 };
        var beyondDeclaredPrecision = nearMaximumCap with { HeightFt = 2.9999 };
        var crossingCap = nearMaximumCap with { HeightFt = 3.00001 };
        var endTouching = nearMaximumCap with { CentreXFt = 0.5 };
        var shallow = nearMaximumCap with { DepthFt = 0.5 };
        var brep = nearMaximumCap with
        {
            Boundary = BoxGeometry(1.5, -1, 0, 2.5, 1, 2.99999),
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, nearMaximumCap));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, nearMinimumCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCapsExact));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, onlyOneCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, beyondDeclaredPrecision));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, crossingCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, endTouching));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, shallow));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, brep));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, boundary, nearMaximumCap));

        var nearSingleMaximumCap = nearMaximumCap with
        {
            BaseZFt = 1,
            HeightFt = 1.99999,
        };
        var nearSingleMinimumCap = nearMaximumCap with
        {
            BaseZFt = 0.00001,
            HeightFt = 1,
        };
        var bothCapsNear = nearMaximumCap with
        {
            BaseZFt = 0.00001,
            HeightFt = 2.99998,
        };
        var exactSingleMaximumCap = nearSingleMaximumCap with
        {
            HeightFt = 2,
        };
        var beyondSingleMaximumCap = nearSingleMaximumCap with
        {
            HeightFt = 1.9999,
        };
        var crossingSingleMaximumCap = nearSingleMaximumCap with
        {
            HeightFt = 2.00001,
        };
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, nearSingleMaximumCap));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, nearSingleMinimumCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCapsNear));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, exactSingleMaximumCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, beyondSingleMaximumCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, crossingSingleMaximumCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearSingleMaximumCap with { CentreXFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearSingleMaximumCap with { DepthFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearSingleMaximumCap with
                {
                    Boundary = BoxGeometry(
                        1.5, -1, 1, 2.5, 1, 2.99999),
                }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
                wall, bounds, boundary, nearSingleMaximumCap));
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_AllowsOnlyWriterPrecisionEndSideCapNotch()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        var redundantBoundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        redundantBoundary.Faces!.RemoveAt(2);
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3]]));
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0]]));
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = redundantBoundary,
            BoundingBox = bounds,
        };
        var maximumCapNotch = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 3.5, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 1, BaseZFt: 1, HeightFt: 2.00001,
            ExactDepth: true);
        var maximumCapInside = maximumCapNotch with { HeightFt = 1.99999 };
        var minimumCapNotch = maximumCapNotch with
        {
            BaseZFt = -0.00001,
            HeightFt = 1,
        };
        var exactCap = maximumCapNotch with { HeightFt = 2 };
        var bothCapsNear = maximumCapNotch with
        {
            BaseZFt = 0.00001,
            HeightFt = 2.99998,
        };
        var outsideCapPrecision = maximumCapNotch with { HeightFt = 2.0001 };
        var capInterior = maximumCapNotch with { HeightFt = 1 };
        var endInterior = maximumCapNotch with { CentreXFt = 2.5 };
        var bothEnds = maximumCapNotch with { CentreXFt = 2, WidthFt = 4 };
        var sideOutsidePrecision = maximumCapNotch with { DepthFt = 0.9999 };
        var rotated = maximumCapNotch with
        {
            AxisX = Math.Cos(0.001), AxisY = Math.Sin(0.001),
        };
        var brep = maximumCapNotch with
        {
            Boundary = BoxGeometry(3, -0.5, 1, 4, 0.5, 3.00001),
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, maximumCapNotch));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, maximumCapInside));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, minimumCapNotch));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, exactCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothCapsNear));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, outsideCapPrecision));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, capInterior));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, endInterior));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, bothEnds));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, sideOutsidePrecision));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, rotated));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, brep));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
                wall, bounds, boundary, maximumCapNotch));
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_AllowsOnlyRobustInteriorCut()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = boundary,
            BoundingBox = bounds,
        };
        var interiorCut = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 0.5, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        var perpendicularCut = interiorCut with
        {
            AxisX = 0, AxisY = 1, WidthFt = 0.5, DepthFt = 1,
        };
        var throughThickness = interiorCut with { DepthFt = 2 };
        var touchesEnd = interiorCut with { CentreXFt = 0.5 };
        var touchesCap = interiorCut with { BaseZFt = 0 };
        var rotated = interiorCut with
        {
            AxisX = Math.Cos(0.001), AxisY = Math.Sin(0.001),
        };
        var inexactDepth = interiorCut with { ExactDepth = false };
        var brep = interiorCut with
        {
            Boundary = BoxGeometry(1.5, -0.25, 1, 2.5, 0.25, 2),
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, interiorCut));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, perpendicularCut));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, throughThickness));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, touchesEnd));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, touchesCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, rotated));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, inexactDepth));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, boundary, brep));
    }

    [Fact]
    public void BoundaryOwnedWallOpeningGate_AllowsOnlySidePlaneCoextensiveInteriorCut()
    {
        var boundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        var redundantBoundary = BoxGeometry(0, -0.5, 0, 4, 0.5, 3);
        redundantBoundary.Faces!.RemoveAt(2);
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [0, -0.5, 3], [4, -0.5, 3]]));
        redundantBoundary.Faces.Add(
            Face([[0, -0.5, 0], [4, -0.5, 3], [4, -0.5, 0]]));
        double[] bounds = [0, -0.5, 0, 4, 0.5, 3];
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers = [new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 }],
            Geometry = redundantBoundary,
            BoundingBox = bounds,
        };
        var coextensive = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 1, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        var withinDeclaredPrecision = coextensive with { CentreYFt = 0.000005 };
        var outsideDeclaredPrecision = coextensive with { CentreYFt = 0.0001 };
        var shallow = coextensive with { DepthFt = 0.5 };
        var overdeep = coextensive with { DepthFt = 2 };
        var endTouching = coextensive with { CentreXFt = 0.5 };
        var capTouching = coextensive with { BaseZFt = 0 };
        var rotated = coextensive with
        {
            AxisX = Math.Cos(0.001), AxisY = Math.Sin(0.001),
        };
        var inexactDepth = coextensive with { ExactDepth = false };
        var brep = coextensive with
        {
            Boundary = BoxGeometry(1.5, -0.5, 1, 2.5, 0.5, 2),
        };

        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, coextensive));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, withinDeclaredPrecision));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, outsideDeclaredPrecision));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, shallow));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, overdeep));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, endTouching));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, capTouching));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, rotated));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, inexactDepth));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, brep));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, boundary, coextensive));

        var crossesMinimumEnd = coextensive with
        {
            CentreXFt = 0.4,
        };
        var crossesMaximumEnd = coextensive with
        {
            CentreXFt = 3.6,
        };
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, crossesMinimumEnd));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, crossesMaximumEnd));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, coextensive));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                coextensive with { CentreXFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                coextensive with { WidthFt = 5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                crossesMinimumEnd with { DepthFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                crossesMinimumEnd with { BaseZFt = 0 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                crossesMinimumEnd with
                {
                    AxisX = Math.Cos(0.001), AxisY = Math.Sin(0.001),
                }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                crossesMinimumEnd with
                {
                    Boundary = BoxGeometry(-0.1, -0.5, 1, 0.9, 0.5, 2),
                }));

        wall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [-0.5, 0, 0],
            EndPoint = [4, 0, 0],
        };
        var fullPlanInterior = coextensive with { WidthFt = 4 };
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionFullPlanCoextensiveInteriorCutOfExactBoundaryOwnedWall(
                wall, bounds, redundantBoundary, fullPlanInterior));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionFullPlanCoextensiveInteriorCutOfExactBoundaryOwnedWall(
                wall, bounds, redundantBoundary,
                fullPlanInterior with { WidthFt = 3 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionFullPlanCoextensiveInteriorCutOfExactBoundaryOwnedWall(
                wall, bounds, redundantBoundary,
                fullPlanInterior with { BaseZFt = 0 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionFullPlanCoextensiveInteriorCutOfExactBoundaryOwnedWall(
                wall, bounds, redundantBoundary,
                fullPlanInterior with { DepthFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionFullPlanCoextensiveInteriorCutOfExactBoundaryOwnedWall(
                wall, bounds, redundantBoundary,
                fullPlanInterior with
                {
                    Boundary = BoxGeometry(0, -0.5, 1, 4, 0.5, 2),
                }));

        var nearMaximumCap = coextensive with
        {
            BaseZFt = 2,
            HeightFt = 0.99999,
        };
        var nearMinimumCap = coextensive with
        {
            BaseZFt = 0.00001,
            HeightFt = 1,
        };
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, nearMaximumCap));
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, nearMinimumCap));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary, coextensive));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearMaximumCap with { HeightFt = 1 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearMaximumCap with { CentreXFt = 0.5 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearMaximumCap with { CentreYFt = 0.001 }));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, bounds, redundantBoundary,
                nearMaximumCap with
                {
                    Boundary = BoxGeometry(
                        1.5, -0.5, 2, 2.5, 0.5, 2.99999),
                }));

        double narrowHalfWidthFt = 120.0 / 304.8 / 2;
        var narrowRedundantBoundary = BoxGeometry(
            0, -narrowHalfWidthFt, 0, 4, narrowHalfWidthFt, 3);
        narrowRedundantBoundary.Faces!.RemoveAt(2);
        narrowRedundantBoundary.Faces.Add(
            Face([[0, -narrowHalfWidthFt, 0],
                  [0, -narrowHalfWidthFt, 3],
                  [4, -narrowHalfWidthFt, 3]]));
        narrowRedundantBoundary.Faces.Add(
            Face([[0, -narrowHalfWidthFt, 0],
                  [4, -narrowHalfWidthFt, 3],
                  [4, -narrowHalfWidthFt, 0]]));
        double[] narrowBounds =
            [0, -narrowHalfWidthFt, 0, 4, narrowHalfWidthFt, 3];
        wall.Layers =
            [new MaterialLayer { LayerIndex = 0, ThicknessMm = 120 }];
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
                wall, narrowBounds, narrowRedundantBoundary,
                nearMaximumCap with { DepthFt = 2 * narrowHalfWidthFt }));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactJoinedRectangleBeyondLocationEnds()
    {
        double[][] bottom =
        [
            [-0.5, -0.5, 0], [4.5, -0.5, 0],
            [4.5, 0.5, 0], [-0.5, 0.5, 0],
        ];
        double[][] top = bottom
            .Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var boundary = new GeometryData
        {
            Faces =
            [
                Face(bottom), Face(top.AsEnumerable().Reverse().ToArray()),
                Face([bottom[0], top[0], top[1], bottom[1]]),
                Face([bottom[1], top[1], top[2], bottom[2]]),
                Face([bottom[2], top[2], top[3], bottom[3]]),
                Face([bottom[3], top[3], top[0], bottom[0]]),
            ],
        };
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [4, 0, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105, StorageType = StorageType.Double, Value = 3.0,
                },
            ],
            // The raw side cells retain the shorter pre-join location span. Only the
            // independently rebuilt boundary confirms the final extended rectangle.
            Geometry = new GeometryData
            {
                Faces =
                [
                    Face([[0, -0.5, 0], [4, -0.5, 0], [4, -0.5, 3], [0, -0.5, 3]]),
                    Face([[0, 0.5, 0], [4, 0.5, 0], [4, 0.5, 3], [0, 0.5, 3]]),
                ],
            },
        };
        double[] bounds = [-0.5, -0.5, 0, 4.5, 0.5, 3];

        Assert.True(IfcExporter.TryGetExactVerticalRectangularWallPlan(
            boundary, wall.Location, 1, bounds, out var plan));
        Assert.Equal(-0.5, plan.Min(point => point[0]), 12);
        Assert.Equal(4.5, plan.Max(point => point[0]), 12);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, boundary));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesGrossRectangleWhenExactOpeningRecreatesHole()
    {
        var (wall, cutter, boundary) = ExactWallWithOneThroughOpening();
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };

        Assert.True(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            boundary, wall.Location!, 1, wall.BoundingBox!,
            out var gross, out var opening));
        Assert.Equal(6, gross.Faces.Count);
        Assert.All(gross.Faces, face => Assert.Null(face.InnerVertices));
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(1, opening.WidthFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(1, opening.HeightFt, 12);

        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundary(
            wall, wall.BoundingBox!, boundary, elements,
            new HashSet<int> { wall.Id },
            new Dictionary<int, List<int>> { [cutter.Id] = [wall.Id] },
            out gross, out int cutterId));
        Assert.Equal(cutter.Id, cutterId);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_PreservesExactSourceOwnedHoleWithoutCutter()
    {
        var (wall, _, boundary) = ExactWallWithOneThroughOpening();
        wall.IsDiscovered = true;
        wall.Name = "Source-owned opening wall";
        wall.CuttingElementIds = [];

        Assert.True(IfcExporter.TryGetExactSourceOwnedWallGrossBoundaryAndOpenings(
            wall, wall.BoundingBox!, boundary, hasAnyEmittedWallOpening: false,
            out var gross, out var openings));
        Assert.Equal(6, gross.Faces.Count);
        Assert.Single(openings);
        Assert.False(IfcExporter.TryGetExactSourceOwnedWallGrossBoundaryAndOpenings(
            wall, wall.BoundingBox!, boundary, hasAnyEmittedWallOpening: true,
            out _, out _));

        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-source-owned-opening-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
            Assert.Contains("=IFCRECTANGLEPROFILEDEF(", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

    }

