    [Theory]
    [InlineData("missing-owner-type")]
    [InlineData("missing-tag-type")]
    [InlineData("wrong-role-topology")]
    [InlineData("missing-line")]
    [InlineData("ambiguous-line")]
    [InlineData("duplicate-contour")]
    [InlineData("duplicate-opening")]
    [InlineData("axis-mismatch")]
    [InlineData("nonmatching-rectangle")]
    [InlineData("nonfinite")]
    [InlineData("overflow")]
    [InlineData("branch")]
    public void SourceOwnedWallOpeningTagSelector_TopNotchFailsClosed(
        string brokenValidation)
    {
        var wall = new Element
        {
            Id = 1201,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
        };
        var opening = ExactSourceOwnedRectangularOpening();
        var (owner, lines) = ExactSourceOwnedTopNotchOpeningSketch(
            wall, opening);
        var elements = new[] { wall, owner }.Concat(lines)
            .ToDictionary(element => element.Id);
        IReadOnlyList<IfcExporter.RectangularWallThroughOpening> openings =
            [opening];

        switch (brokenValidation)
        {
            case "missing-owner-type":
                owner.TypeId = 0;
                break;
            case "missing-tag-type":
                lines[4].TypeId = 0;
                break;
            case "wrong-role-topology":
                LocationCurve seed = Assert.IsType<LocationCurve>(
                    lines[0].Location);
                (seed.StartPoint, seed.EndPoint) =
                    (seed.EndPoint, seed.StartPoint);
                break;
            case "missing-line":
                elements.Remove(lines[7].Id);
                break;
            case "ambiguous-line":
                var duplicateLine = new Element
                {
                    Id = 9290,
                    CategoryId = -2000045,
                    Category = "OST_SketchLines",
                    HostId = owner.Id,
                    References = [wall.Id],
                    Location = new LocationCurve
                    {
                        CurveType = "Line",
                        StartPoint = (double[])lines[7].Location!
                            .StartPoint.Clone(),
                        EndPoint = (double[])lines[7].Location!
                            .EndPoint.Clone(),
                    },
                };
                owner.References!.Add(duplicateLine.Id);
                elements.Add(duplicateLine.Id, duplicateLine);
                break;
            case "duplicate-contour":
                var (duplicateOwner, duplicateLines) =
                    ExactSourceOwnedTopNotchOpeningSketch(
                        wall, opening, idOffset: 1000);
                elements.Add(duplicateOwner.Id, duplicateOwner);
                foreach (Element line in duplicateLines)
                    elements.Add(line.Id, line);
                break;
            case "duplicate-opening":
                openings = [opening, opening];
                break;
            case "axis-mismatch":
                openings = [opening with
                {
                    AxisX = Math.BitIncrement(opening.AxisX),
                }];
                break;
            case "nonmatching-rectangle":
                openings = [opening with { CentreXFt = 1.75 }];
                break;
            case "nonfinite":
                owner.SketchLoops![0][0][0] = double.NaN;
                break;
            case "overflow":
                owner.SketchLoops![0][0][0] = double.MaxValue;
                break;
            case "branch":
                var branch = new Element
                {
                    Id = 9290,
                    CategoryId = -2000045,
                    Category = "OST_SketchLines",
                    HostId = owner.Id,
                    References = [wall.Id],
                    Location = new LocationCurve
                    {
                        CurveType = "Line",
                        StartPoint = [2, 0, 2],
                        EndPoint = [2, 0, 1.5],
                    },
                };
                owner.References!.Add(branch.Id);
                elements.Add(branch.Id, branch);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(brokenValidation));
        }

        var tags = IfcExporter.SelectExactSourceOwnedWallOpeningTags(
            wall, openings, elements, fallbackTagId: wall.Id);

        Assert.All(tags, tag => Assert.Equal(wall.Id, tag));
    }

    [Theory]
    [InlineData("missing")]
    [InlineData("ambiguous")]
    [InlineData("open")]
    [InlineData("branched")]
    [InlineData("degenerate")]
    [InlineData("overflow")]
    [InlineData("top-open")]
    [InlineData("duplicate-opening")]
    public void SourceOwnedWallOpeningTagSelector_FailsClosedWithoutUniqueExactContour(
        string brokenValidation)
    {
        var wall = new Element
        {
            Id = 1201,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
        };
        var opening = ExactSourceOwnedRectangularOpening();
        var (owner, lines) = ExactSourceOwnedRectangularOpeningSketch(wall);
        var elements = new[] { wall, owner }.Concat(lines)
            .ToDictionary(element => element.Id);
        IReadOnlyList<IfcExporter.RectangularWallThroughOpening> openings =
            [opening];

        switch (brokenValidation)
        {
            case "missing":
                elements.Remove(lines[3].Id);
                break;
            case "ambiguous":
                var (duplicateOwner, duplicateLines) =
                    ExactSourceOwnedRectangularOpeningSketch(
                        wall, idOffset: 1000);
                elements.Add(duplicateOwner.Id, duplicateOwner);
                foreach (Element line in duplicateLines)
                    elements.Add(line.Id, line);
                break;
            case "open":
                lines[3].Location!.EndPoint = [1, 0, 1.25];
                break;
            case "branched":
                var branch = new Element
                {
                    Id = 9150,
                    CategoryId = -2000045,
                    HostId = owner.Id,
                    References = [wall.Id],
                    Location = new LocationCurve
                    {
                        CurveType = "Line",
                        StartPoint = [1, 0, 1],
                        EndPoint = [2, 0, 1],
                    },
                };
                owner.References!.Add(branch.Id);
                elements.Add(branch.Id, branch);
                break;
            case "degenerate":
                LocationCurve location = Assert.IsType<LocationCurve>(
                    lines[0].Location);
                location.EndPoint = (double[])location.StartPoint.Clone();
                break;
            case "overflow":
                lines[0].Location!.EndPoint = [double.MaxValue, 0, 1];
                break;
            case "top-open":
                owner.SketchLoops =
                [
                    new List<double[]>
                    {
                        new[] { 0.0, 0.0, 0.0 },
                        new[] { 4.0, 0.0, 0.0 },
                        new[] { 4.0, 0.0, 1.0 },
                        new[] { 2.0, 0.0, 1.0 },
                        new[] { 2.0, 0.0, 2.0 },
                        new[] { 1.0, 0.0, 2.0 },
                        new[] { 1.0, 0.0, 1.0 },
                        new[] { 0.0, 0.0, 1.0 },
                        new[] { 0.0, 0.0, 0.0 },
                    },
                ];
                break;
            case "duplicate-opening":
                openings = [opening, opening];
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(brokenValidation));
        }

        var tags = IfcExporter.SelectExactSourceOwnedWallOpeningTags(
            wall, openings, elements, fallbackTagId: wall.Id);

        Assert.All(tags, tag => Assert.Equal(wall.Id, tag));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactSourceSketchTagAndWallReference()
    {
        var (wall, _, _) = ExactWallWithOneThroughOpening();
        wall.IsDiscovered = true;
        wall.Name = "Source-owned opening wall";
        wall.CuttingElementIds = [];
        var (owner, lines) = ExactSourceOwnedRectangularOpeningSketch(wall);
        var info = new RevitFileInfo();
        info.Elements.AddRange(new[] { wall, owner }.Concat(lines));
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-source-sketch-tag-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);
            string openingLine = Assert.Single(ifc.Split('\n'),
                line => line.Contains("=IFCOPENINGELEMENT("));
            Assert.Contains(",'9100');", openingLine);
            int equals = openingLine.IndexOf('=');
            int openingId = int.Parse(openingLine[1..equals]);
            string[] openingPropertyRelations = ifc.Split('\n')
                .Where(line => line.Contains("=IFCRELDEFINESBYPROPERTIES(")
                    && line.Contains($",(#{openingId}),"))
                .ToArray();

            Assert.Equal(2, openingPropertyRelations.Length);
            Assert.Contains("'Pset_OpeningElementCommon'", ifc);
            Assert.Contains("'Pset_QuantityTakeOff'", ifc);
            Assert.Contains(
                "IFCPROPERTYSINGLEVALUE('Reference',$,"
                + "IFCIDENTIFIER('Source-owned opening wall'),$)", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    private static IfcExporter.RectangularWallThroughOpening
        ExactSourceOwnedRectangularOpening() => new(
            CentreXFt: 1.5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 1, BaseZFt: 1, HeightFt: 1,
            NormalMinimumFt: -0.5, NormalMaximumFt: 0.5);

    private static (Element Owner, List<Element> Lines)
        ExactSourceOwnedRectangularOpeningSketch(
            Element wall, bool reverseSeed = false, int idOffset = 0,
            IfcExporter.RectangularWallThroughOpening? openingOverride = null)
    {
        int ownerId = 9000 + idOffset;
        var opening = openingOverride ?? ExactSourceOwnedRectangularOpening();
        double halfWidth = opening.WidthFt / 2;
        double[] Corner(double alongSign, double z) =>
        [
            opening.CentreXFt + opening.AxisX * halfWidth * alongSign,
            opening.CentreYFt + opening.AxisY * halfWidth * alongSign,
            z,
        ];
        double[] minimumBottom = Corner(-1, opening.BaseZFt);
        double[] maximumBottom = Corner(1, opening.BaseZFt);
        double[] maximumTop = Corner(1, opening.BaseZFt + opening.HeightFt);
        double[] minimumTop = Corner(-1, opening.BaseZFt + opening.HeightFt);
        static Element Line(int id, int ownerId, int wallId,
            double[] start, double[] end) => new()
        {
            Id = id,
            CategoryId = -2000045,
            Category = "OST_SketchLines",
            HostId = ownerId,
            References = [wallId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = start,
                EndPoint = end,
            },
        };
        var lines = new List<Element>
        {
            Line(9100 + idOffset, ownerId, wall.Id,
                (double[])(reverseSeed ? maximumBottom : minimumBottom).Clone(),
                (double[])(reverseSeed ? minimumBottom : maximumBottom).Clone()),
            Line(9130 + idOffset, ownerId, wall.Id,
                (double[])maximumTop.Clone(), (double[])maximumBottom.Clone()),
            Line(9120 + idOffset, ownerId, wall.Id,
                (double[])maximumTop.Clone(), (double[])minimumTop.Clone()),
            Line(9140 + idOffset, ownerId, wall.Id,
                (double[])minimumBottom.Clone(), (double[])minimumTop.Clone()),
        };
        var owner = new Element
        {
            Id = ownerId,
            TypeId = wall.Id,
            References = new List<int> { wall.Id }
                .Concat(lines.Select(line => line.Id)).ToList(),
            SketchLoops =
            [
                new List<double[]>
                {
                    (double[])minimumBottom.Clone(),
                    (double[])maximumBottom.Clone(),
                    (double[])maximumTop.Clone(),
                    (double[])minimumTop.Clone(),
                    (double[])minimumBottom.Clone(),
                },
            ],
        };
        return (owner, lines);
    }

    private static (Element Owner, List<Element> Lines)
        ExactSourceOwnedTopNotchOpeningSketch(
            Element wall,
            IfcExporter.RectangularWallThroughOpening opening,
            int idOffset = 0,
            bool reverseTagDirection = false)
    {
        int ownerId = 9050 + idOffset;
        double[] Point(double alongOffset, double z) =>
        [
            opening.CentreXFt + opening.AxisX * alongOffset,
            opening.CentreYFt + opening.AxisY * alongOffset,
            z,
        ];
        var vertices = new List<double[]>
        {
            Point(-1.5, 2), Point(-1.5, 0),
            Point(1.5, 0), Point(1.5, 2),
            Point(0.5, 2), Point(0.5, 1),
            Point(-0.5, 1), Point(-0.5, 2),
        };
        static Element Line(int id, int ownerId, int wallId,
            double[] start, double[] end) => new()
        {
            Id = id,
            CategoryId = -2000045,
            Category = "OST_SketchLines",
            HostId = ownerId,
            References = [wallId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = start,
                EndPoint = end,
            },
        };
        var lines = Enumerable.Range(0, vertices.Count)
            .Select(index => Line(
                9200 + idOffset + index * 10,
                ownerId, wall.Id,
                (double[])vertices[index].Clone(),
                (double[])vertices[(index + 1) % vertices.Count].Clone()))
            .ToList();
        lines[4].TypeId = lines[3].Id;
        if (reverseTagDirection)
        {
            LocationCurve tagLocation = Assert.IsType<LocationCurve>(
                lines[4].Location);
            (tagLocation.StartPoint, tagLocation.EndPoint) =
                (tagLocation.EndPoint, tagLocation.StartPoint);
        }
        var owner = new Element
        {
            Id = ownerId,
            TypeId = wall.Id,
            References = new List<int> { wall.Id }
                .Concat(lines.Select(line => line.Id)).ToList(),
            SketchLoops =
            [
                vertices.Select(point => (double[])point.Clone())
                    .Append((double[])vertices[0].Clone()).ToList(),
            ],
        };
        return (owner, lines);
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RecreatesExactSourceOwnedBlindRecessWithWallTag()
    {
        static double[][] Rectangle(double minimumAlong, double maximumAlong,
            double plane, double minimumZ, double maximumZ) =>
        [
            [minimumAlong, plane, minimumZ],
            [maximumAlong, plane, minimumZ],
            [maximumAlong, plane, maximumZ],
            [minimumAlong, plane, maximumZ],
        ];
        static void AddConnectors(List<GeoFace> faces,
            IReadOnlyList<double[]> first, IReadOnlyList<double[]> second)
        {
            for (int index = 0; index < 4; index++)
            {
                int next = (index + 1) % 4;
                faces.Add(Face(
                [
                    first[index], first[next],
                    second[next], second[index],
                ]));
            }
        }

        double[][] lowOuter = Rectangle(0, 4, -0.5, 0, 3);
        double[][] highOuter = Rectangle(0, 4, 0.5, 0, 3);
        double[][] blindMouth = Rectangle(0.5, 3.5, -0.5, 0.25, 2.75);
        double[][] blindBack = Rectangle(0.5, 3.5, -0.49, 0.25, 2.75);
        double[][] filledRing = Rectangle(0.4, 3.4, 0.5, 0.25, 2.75);
        var lowSide = Face(lowOuter);
        lowSide.InnerVertices = [blindMouth.ToList()];
        var highSide = Face(highOuter.AsEnumerable().Reverse().ToArray());
        highSide.InnerVertices = [filledRing.AsEnumerable().Reverse().ToList()];
        var faces = new List<GeoFace>
        {
            lowSide,
            highSide,
        };
        AddConnectors(faces, lowOuter, highOuter);
        faces.Add(Face(filledRing));
        int blindBackFaceIndex = faces.Count;
        faces.Add(Face(blindBack));
        AddConnectors(faces, blindMouth, blindBack);
        // A disconnected, exterior parallel remnant is not a recess back face.
        faces.Add(Face(Rectangle(0.5, 3.5, -0.52, 0.25, 2.75)));

        var wall = new Element
        {
            Id = 1201,
            TypeId = 1202,
            IsDiscovered = true,
            Name = "Blind recess wall",
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.52, 0, 4, 0.5, 3],
                Faces = faces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices =
                            Enumerable.Range(0, faces.Count).ToList(),
                        IsClosed = false,
                    },
                ],
            },
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
        };

        Assert.True(IfcExporter.TryGetExactSourceOwnedBlindWallRecess(
            wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
            out var gross, out var openings));
        Assert.Equal(6, gross.Faces.Count);
        var opening = Assert.Single(openings);
        Assert.Equal(2, opening.CentreXFt, 12);
        Assert.Equal(-0.495, opening.CentreYFt, 12);
        Assert.Equal(3, opening.WidthFt, 12);
        Assert.Equal(0.25, opening.BaseZFt, 12);
        Assert.Equal(2.5, opening.HeightFt, 12);
        Assert.Equal(-0.5, opening.NormalMinimumFt, 12);
        Assert.Equal(-0.49, opening.NormalMaximumFt, 12);
        Assert.False(IfcExporter.TryGetExactSourceOwnedBlindWallRecess(
            wall, wall.BoundingBox!, hasAnyEmittedWallOpening: true,
            out _, out _));

        Assert.False(IfcExporter.TryGetExactSourceOwnedWallGrossBoundaryAndOpenings(
            wall, wall.BoundingBox!, gross,
            hasAnyEmittedWallOpening: false, out _, out _));

        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-source-owned-blind-recess-{Guid.NewGuid():N}.ifc");
        try
        {
            var info = new RevitFileInfo();
            info.Elements.Add(wall);
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
            Assert.Matches(
                @"IFCOPENINGELEMENT\([^;]*,'1201'\);", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        faces[blindBackFaceIndex].OuterVertices![0][0] += 0.05;
        Assert.False(IfcExporter.TryGetExactSourceOwnedBlindWallRecess(
            wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
            out _, out _));
        faces[blindBackFaceIndex].OuterVertices![0][0] -= 0.05;

        faces[6].OuterVertices![0][1] -= 0.01;
        Assert.False(IfcExporter.TryGetExactSourceOwnedBlindWallRecess(
            wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
            out _, out _));
        faces[6].OuterVertices![0][1] += 0.01;

        lowSide.AlternativeOuterVertices =
            lowOuter.Select(point => point.ToArray()).ToList();
        Assert.False(IfcExporter.TryGetExactSourceOwnedBlindWallRecess(
            wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
            out _, out _));
        lowSide.AlternativeOuterVertices = null;
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RecreatesExactEditedProfileOpeningsWithSketchLineTags()
    {
        const int wallId = 700;
        const int ownerId = 900;
        const int firstTagId = 901;
        const int secondTagId = 902;
        static List<double[]> Profile(double normal,
            double firstMinimum, double firstMaximum,
            double secondMinimum, double secondMaximum) =>
        [
            [0, normal, 3], [0, normal, 0],
            [10, normal, 0], [10, normal, 3],
            [secondMaximum, normal, 3],
            [secondMaximum, normal, 1.5],
            [secondMinimum, normal, 1.5],
            [secondMinimum, normal, 3],
            [firstMaximum, normal, 3],
            [firstMaximum, normal, 1],
            [firstMinimum, normal, 1],
            [firstMinimum, normal, 3],
        ];

        var lowSide = Profile(-0.5, 2.1, 2.9, 6.2, 7.8);
        var highSide = Profile(0.5, 2.1, 2.9, 6.2, 7.8);
        var rebuilt = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Faces =
            [
                Face(lowSide),
                Face(highSide.AsEnumerable().Reverse()),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = [0, 1],
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = wallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Geometry = rebuilt,
            CuttingElementIds = [],
            References = [ownerId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
            },
            Parameters = [WallWidthParameter(1)],
        };
        var owner = new Element
        {
            Id = ownerId,
            TypeId = wallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            References = [wallId, firstTagId, secondTagId],
            SketchLoops =
            [
                Profile(0, 2, 3, 6, 8)
                    .Append(new[] { 0.0, 0.0, 3.0 }).ToList(),
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1002050,
                    Definition = new Definition { Name = "ELEM_TYPE_PARAM" },
                    StorageType = StorageType.ElementId,
                    Value = wallId,
                },
            ],
        };
        static Element SketchLine(int id, int hostId, int wallId,
            double along, double lowZ, double highZ) => new()
        {
            Id = id,
            CategoryId = -2000045,
            Category = "OST_SketchLines",
            HostId = hostId,
            References = [wallId, hostId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [along, 0, highZ],
                EndPoint = [along, 0, lowZ],
            },
        };
        var firstLine = SketchLine(firstTagId, ownerId, wallId, 8, 1.5, 3);
        var secondLine = SketchLine(secondTagId, ownerId, wallId, 3, 1, 3);
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [owner.Id] = owner,
            [firstLine.Id] = firstLine,
            [secondLine.Id] = secondLine,
        };

        Assert.Equal(wallId, owner.FamilyTypeId);
        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(
            wall, 1, out var authoredPlan));
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            authoredPlan, wall.BoundingBox!));
        Assert.True(IfcExporter
            .TryGetExactEditedWallSketchProfileGrossBoundaryAndOpenings(
                wall, wall.BoundingBox!, rebuilt, elements,
                out var gross, out var openings));
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(gross.BrepSolids!.Single().IsClosed);
        Assert.Equal([secondTagId, firstTagId],
            openings.Select(item => item.TagId).ToArray());
        Assert.Equal([1.0, 2.0],
            openings.Select(item => item.Opening.WidthFt).ToArray());
        Assert.Equal([1.0, 1.5],
            openings.Select(item => item.Opening.BaseZFt).ToArray());
        Assert.Equal([2.0, 1.5],
            openings.Select(item => item.Opening.HeightFt).ToArray());
        Assert.All(openings, item =>
        {
            Assert.Equal(-0.5, item.Opening.NormalMinimumFt, 12);
            Assert.Equal(0.5, item.Opening.NormalMaximumFt, 12);
        });

        owner.References.Remove(secondTagId);
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchProfileGrossBoundaryAndOpenings(
                wall, wall.BoundingBox!, rebuilt, elements,
                out _, out _));
        owner.References.Add(secondTagId);
        rebuilt.Faces[0].InnerVertices =
        [
            [[4, -0.5, 1], [5, -0.5, 1],
                [5, -0.5, 2], [4, -0.5, 2]],
        ];
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchProfileGrossBoundaryAndOpenings(
                wall, wall.BoundingBox!, rebuilt, elements,
            out _, out _));
    }

