    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactEditedInverseStepOwnerAsGrossBodyAndOpening()
    {
        const int wallId = 712;
        const int ownerId = 912;
        const int tagId = 913;
        var source = VerticalStepWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            stepAlong: 1, stepZ: 1);
        foreach (var point in source.Faces!
                     .SelectMany(face => face.OuterVertices!)
                     .Distinct<double[]>(ReferenceEqualityComparer.Instance))
        {
            point[0] = 6 - point[0];
            point[2] = 3 - point[2];
        }
        source.Faces.Add(Face(
        [
            [5.1, -0.5, 0], [5.1, 0.5, 0],
            [5.1, 0.5, 2], [5.1, -0.5, 2],
        ]));
        source.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, source.Faces.Count).ToList();
        source.BrepSolids[0].IsClosed = true;
        var wall = new Element
        {
            Id = wallId,
            TypeId = 713,
            IsDiscovered = true,
            Name = "Edited inverse-step wall",
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = source,
            CuttingElementIds = [],
            References = [ownerId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
        };
        var ownerLoop = source.Faces[0].OuterVertices!
            .Select(point => new[] { point[0], 0.0, point[2] })
            .ToList();
        foreach (double[] point in ownerLoop)
            if (Math.Abs(point[0] - 5) < 1e-12)
                point[0] = 5.1;
        ownerLoop.Add((double[])ownerLoop[0].Clone());
        var owner = new Element
        {
            Id = ownerId,
            TypeId = wallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            References = [wallId, tagId],
            SketchLoops = [ownerLoop],
        };
        var tagLine = new Element
        {
            Id = tagId,
            TypeId = 914,
            CategoryId = -2000045,
            Category = "OST_SketchLines",
            HostId = ownerId,
            References = [wallId, ownerId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 2],
                EndPoint = [5.1, 0, 2],
            },
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [owner.Id] = owner,
            [tagLine.Id] = tagLine,
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuilt));
        Assert.Equal(8, rebuilt.Faces.Count);
        Assert.True(IfcExporter
            .TryGetExactRectangularWallGrossBoundaryFromInverseVerticalStep(
                rebuilt, wall.Location!, 1, wall.BoundingBox!,
                out var inverseGross, out string rejectionReason),
            rejectionReason);
        Assert.Equal(6, inverseGross.Faces.Count);
        Assert.True(IfcExporter
            .TryGetExactEditedWallSketchInverseStepGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                emittedCutterIds, standaloneOpeningIds,
                out var gross, out var openings));
        Assert.Equal(6, gross.Faces.Count);
        var opening = Assert.Single(openings);
        Assert.Equal(tagId, opening.TagId);
        Assert.Equal(5.1, opening.Opening.WidthFt, 12);
        Assert.Equal(0, opening.Opening.BaseZFt, 12);
        Assert.Equal(2, opening.Opening.HeightFt, 12);
        Assert.Equal(-0.5, opening.Opening.NormalMinimumFt, 12);
        Assert.Equal(0.5, opening.Opening.NormalMaximumFt, 12);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, owner, tagLine]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-edited-inverse-step-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
            Assert.Contains(",'913');", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        owner.References.Remove(tagId);
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchInverseStepGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                emittedCutterIds, standaloneOpeningIds, out _, out _));
    }

