            },
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [owner.Id] = owner,
            [tagLine.Id] = tagLine,
        };

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuilt));
        Assert.Equal(8, rebuilt.Faces.Count);
        Assert.True(IfcExporter
            .TryGetExactEditedWallSketchSlopedTopGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                out var gross, out var opening, out int openingTagId));
        Assert.Equal(6, gross.Faces.Count);
        Assert.Equal(tagId, openingTagId);
        Assert.Equal(4, opening.Profile.Count);
        Assert.Equal(1, opening.Profile.Min(point => point.ZFt), 12);
        Assert.Equal(3, opening.Profile.Max(point => point.ZFt), 12);
        Assert.Equal(4, opening.Profile.Min(point => point.AlongFt), 12);
        Assert.Equal(10, opening.Profile.Max(point => point.AlongFt), 12);
        Assert.Equal(-0.5, opening.NormalMinimumFt, 12);
        Assert.Equal(0.5, opening.NormalMaximumFt, 12);

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, owner, tagLine]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-edited-sloped-top-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(
                2, Count(ifc, "=IFCARBITRARYCLOSEDPROFILEDEF("));
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
            Assert.Contains(",'918');", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        owner.References.Remove(tagId);
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchSlopedTopGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                out _, out _, out _));
        owner.References.Add(tagId);

        tagLine.Location.EndPoint[2] = 1.25;
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchSlopedTopGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                out _, out _, out _));
        tagLine.Location.EndPoint[2] = 1;

        source.Faces![0].AlternativeOuterVertices =
            source.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchSlopedTopGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                out _, out _, out _));
        source.Faces[0].AlternativeOuterVertices = null;

        var duplicateTag = new Element
        {
            Id = tagId + 1,
            TypeId = tagLine.TypeId,
            CategoryId = tagLine.CategoryId,
            Category = tagLine.Category,
            HostId = ownerId,
            References = [wallId, ownerId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [7, 0, 1],
                EndPoint = [4, 0, 3],
            },
        };
        owner.References.Add(duplicateTag.Id);
        elements[duplicateTag.Id] = duplicateTag;
        Assert.False(IfcExporter
            .TryGetExactEditedWallSketchSlopedTopGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                out _, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RecreatesExactEditedBottomStairProfileOpening()
    {
        const int wallId = 714;
        const int ownerId = 914;
        const int tagId = 915;
        List<(double Along, double Z)> materialProfile =
        [
            (0, 3), (0, 0), (4, 0), (4, 0.5),
            (5, 0.5), (5, 1), (6, 1), (6, 1.5),
            (7, 1.5), (7, 2), (10, 2), (10, 3),
        ];
        var faces = new List<GeoFace>
        {
            Face(materialProfile.Select(point =>
                new[] { point.Along, -0.5, point.Z }).ToList()),
            Face(materialProfile.AsEnumerable().Reverse().Select(point =>
                new[] { point.Along, 0.5, point.Z }).ToList()),
        };
        for (int index = 0; index < materialProfile.Count; index++)
        {
            var first = materialProfile[index];
            var second = materialProfile[
                (index + 1) % materialProfile.Count];
            faces.Add(Face(
            [
                [first.Along, -0.5, first.Z],
                [second.Along, -0.5, second.Z],
                [second.Along, 0.5, second.Z],
                [first.Along, 0.5, first.Z],
            ]));
        }
        faces.Add(Face(
        [
            [4.5, -0.5, 0.1],
            [6.5, -0.5, 0.1],
            [6.5, 0.5, 0.1],
            [4.5, 0.5, 0.1],
