            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, materialProfile.Count + 2).ToList(),
                    IsClosed = true,
                },
                new GeoBrepSolid
                {
                    FaceIndices = [materialProfile.Count + 2],
                    IsClosed = false,
                },
