            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
        };
        var owner = new Element
        {
            Id = ownerId,
            TypeId = wallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            References = [wallId, tagId],
            SketchLoops =
            [
                materialProfile.Select(point =>
                        new[] { point.Along, 0.0, point.Z })
                    .Append(new[] { 0.0, 0.0, 3.0 }).ToList(),
            ],
        };
        var tagLine = new Element
        {
            Id = tagId,
            TypeId = 916,
            CategoryId = -2000045,
            Category = "OST_SketchLines",
            HostId = ownerId,
            References = [wallId, ownerId],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [4, 0, 0],
                EndPoint = [4, 0, 0.5],
            },
