            .TryGetExactEditedWallSketchBottomStairGrossBoundaryAndOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                out _, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RecreatesExactSourceOwnedFullSectionGap()
    {
        const int wallId = 731;
        static double[] Point(double x, double y, double z) => [x, y, z];
        static GeoFace Face(params double[][] points) => new()
        {
            OuterVertices = points.Select(point =>
                (double[])point.Clone()).ToList(),
        };

        double[][] plan =
        [
            Point(0, -0.5, 0),
            Point(10, -0.5, 0),
            Point(10, 0.5, 0),
            Point(0, 0.5, 0),
        ];
        double[][] AtZ(double z) => plan.Select(point =>
            Point(point[0], point[1], z)).ToArray();
        var lowGap = AtZ(2);
        var highGap = AtZ(2.5);
        var openingFaces = new List<GeoFace>
        {
            Face(lowGap),
            Face(highGap.AsEnumerable().Reverse().ToArray()),
        };
        for (int index = 0; index < plan.Length; index++)
        {
            int next = (index + 1) % plan.Length;
            openingFaces.Add(Face(
                lowGap[index], lowGap[next],
                highGap[next], highGap[index]));
        }
        openingFaces[2].AlternativeOuterVertices =
        [
            Point(0, -0.5, 0),
            Point(10, -0.5, 0),
            Point(10, -0.5, 5),
            Point(7, -0.5, 5),
            Point(7, -0.5, 2),
            Point(3, -0.5, 2),
            Point(3, -0.5, 5),
            Point(0, -0.5, 5),
        ];
        var bottom = AtZ(0);
        var top = AtZ(5);
        var supportFaces = new List<GeoFace>
        {
            Face(bottom),
            Face(top.AsEnumerable().Reverse().ToArray()),
        };
        for (int index = 0; index < plan.Length; index++)
        {
            int next = (index + 1) % plan.Length;
            supportFaces.Add(Face(
                bottom[index], bottom[next], top[next], top[index]));
        }
        supportFaces.Add(Face(
            bottom[0], bottom[1], top[1], top[0]));
        supportFaces.Add(Face(
            bottom[2], bottom[3], top[3], top[2]));
        var sourceFaces = openingFaces.Concat(supportFaces).ToList();
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 10, 0.5, 5],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, sourceFaces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = wallId,
            TypeId = 716,
            IsDiscovered = true,
            Name = "Full-section-gap wall",
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 10, 0.5, 5],
            Geometry = source,
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
            },
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 5.0,
                },
            ],
        };

        Assert.True(IfcExporter
            .TryGetExactSourceOwnedFullSectionHorizontalGap(
                wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
                out var gross, out var openings));
        Assert.Equal(6, gross.Faces.Count);
        var opening = Assert.Single(openings);
        Assert.Equal(10, opening.WidthFt, 12);
        Assert.Equal(2, opening.BaseZFt, 12);
        Assert.Equal(0.5, opening.HeightFt, 12);
        Assert.Equal(-0.5, opening.NormalMinimumFt, 12);
        Assert.Equal(0.5, opening.NormalMaximumFt, 12);

        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-full-section-gap-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
            string openingLine = ifc.Split('\n').Single(line =>
                line.Contains("=IFCOPENINGELEMENT("));
            Assert.EndsWith(",'731');", openingLine.Trim());
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        wall.CuttingElementIds = [9001];
        Assert.False(IfcExporter
            .TryGetExactSourceOwnedFullSectionHorizontalGap(
                wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
                out _, out _));
        wall.CuttingElementIds = [];
        source.Faces[1].OuterVertices![0][2] = 2.6;
        Assert.False(IfcExporter
            .TryGetExactSourceOwnedFullSectionHorizontalGap(
                wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
                out _, out _));
        source.Faces[1].OuterVertices![0][2] = 2.5;
        source.Faces[6].OuterVertices =
        [
            Point(2, -0.5, 2),
            Point(3, -0.5, 2),
            Point(3, -0.5, 2.5),
            Point(2, -0.5, 2.5),
        ];
        Assert.False(IfcExporter
            .TryGetExactSourceOwnedFullSectionHorizontalGap(
                wall, wall.BoundingBox!, hasAnyEmittedWallOpening: false,
                out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RecreatesExactSourceOwnedFullHeightVerticalGap()
    {
        const int wallId = 476474;
        static double[] Point(double x, double y, double z) => [x, y, z];
        static GeoFace LocalFace(params double[][] points) => new()
        {
            OuterVertices = points.Select(point =>
                (double[])point.Clone()).ToList(),
        };
        double[][] GrossSide(double normal) =>
        [
            Point(0, normal, 0), Point(10, normal, 0),
            Point(10, normal, 5), Point(4.2, normal, 5),
            Point(0, normal, 5),
        ];
        GeoFace CrossSection(double along) => LocalFace(
            Point(along, -0.5, 0), Point(along, 0.5, 0),
            Point(along, 0.5, 5), Point(along, -0.5, 5));

        var openingMinimumAlong = CrossSection(4);
        var openingMaximumAlong = CrossSection(4.2);
        var openingMinimumNormal = LocalFace(
            Point(4, -0.5, 0), Point(4.2, -0.5, 0),
            Point(4.2, -0.5, 5), Point(4, -0.5, 5));
        openingMinimumNormal.AlternativeOuterVertices = GrossSide(-0.5).ToList();
        var openingMaximumNormal = LocalFace(
            Point(4, 0.5, 5), Point(4.2, 0.5, 5),
            Point(4.2, 0.5, 0), Point(4, 0.5, 0));
        var openingBottom = LocalFace(
            Point(4, -0.5, 0), Point(4, 0.5, 0),
            Point(4.2, 0.5, 0), Point(4.2, -0.5, 0));
        var openingTop = LocalFace(
            Point(4, -0.5, 5), Point(4.2, -0.5, 5),
            Point(4.2, 0.5, 5), Point(4, 0.5, 5));
        var sourceFaces = new List<GeoFace>
        {
            openingMinimumAlong,
            openingMaximumAlong,
            openingMinimumNormal,
            openingMaximumNormal,
            openingBottom,
            openingTop,
            CrossSection(0),
            CrossSection(0.1),
            CrossSection(10),
        };
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 10, 0.5, 5],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, sourceFaces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = wallId,
            TypeId = 716,
            IsDiscovered = true,
            Name = "Full-height vertical-gap wall",
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 10, 0.5, 5],
            Geometry = source,
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [9.5, 0, 0],
            },
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 5.0,
                },
            ],
        };
        var rebuiltFaces = new List<GeoFace>
        {
            LocalFace(GrossSide(-0.5)),
            LocalFace(GrossSide(0.5).AsEnumerable().Reverse().ToArray()),
            LocalFace(
                Point(0, -0.5, 0), Point(10, -0.5, 0),
                Point(10, 0.5, 0), Point(0, 0.5, 0)),
            CrossSection(10),
            LocalFace(
                Point(10, -0.5, 5), Point(10, 0.5, 5),
                Point(4.2, 0.5, 5), Point(4.2, -0.5, 5)),
            LocalFace(
                Point(4.2, -0.5, 5), Point(4.2, 0.5, 5),
                Point(0, 0.5, 5), Point(0, -0.5, 5)),
            CrossSection(0),
        };
        var rebuilt = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, rebuiltFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };

        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                rebuilt, wall.Location, 1, wall.BoundingBox!,
                out var rebuiltPlan, out _, out _, out string rebuiltReason),
            rebuiltReason);
        Assert.Equal("exact-boundary-owned-redundant-faces", rebuiltReason);
        Assert.Equal(4, rebuiltPlan.Count);
        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            sourceFaces, Enumerable.Range(0, 6).ToList(), out _));
        Assert.True(IfcExporter
            .TryGetExactSourceOwnedFullHeightVerticalGap(
                wall, wall.BoundingBox!, rebuilt,
                hasAnyEmittedWallOpening: false,
                out var gross, out var openings));
        Assert.Equal(6, gross.Faces.Count);
        var opening = Assert.Single(openings);
        Assert.Equal(0.2, opening.WidthFt, 12);
        Assert.Equal(0, opening.BaseZFt, 12);
        Assert.Equal(5, opening.HeightFt, 12);
        Assert.Equal(-0.5, opening.NormalMinimumFt, 12);
        Assert.Equal(0.5, opening.NormalMaximumFt, 12);

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuiltFromSource));
        Assert.True(IfcExporter
            .TryGetExactSourceOwnedFullHeightVerticalGap(
                wall, wall.BoundingBox!, rebuiltFromSource,
                hasAnyEmittedWallOpening: false,
                out _, out _));

        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-full-height-vertical-gap-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
            Assert.Contains("=IFCCARTESIANPOINT((-1447.8,0.));", ifc);
            Assert.Contains("=IFCCARTESIANPOINT((1600.2,0.));", ifc);
            string openingLine = ifc.Split('\n').Single(line =>
                line.Contains("=IFCOPENINGELEMENT("));
            Assert.EndsWith(",'476474');", openingLine.Trim());
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        wall.CuttingElementIds = [9001];
        Assert.False(IfcExporter
            .TryGetExactSourceOwnedFullHeightVerticalGap(
                wall, wall.BoundingBox!, rebuilt,
                hasAnyEmittedWallOpening: false,
                out _, out _));
        wall.CuttingElementIds = [];
        source.Faces[4].OuterVertices![0][0] = 4.1;
        Assert.False(IfcExporter
            .TryGetExactSourceOwnedFullHeightVerticalGap(
                wall, wall.BoundingBox!, rebuilt,
                hasAnyEmittedWallOpening: false,
                out _, out _));
        source.Faces[4].OuterVertices![0][0] = 4;
        source.Faces[6].OuterVertices![0][0] = 0.05;
        Assert.False(IfcExporter
            .TryGetExactSourceOwnedFullHeightVerticalGap(
                wall, wall.BoundingBox!, rebuilt,
                hasAnyEmittedWallOpening: false,
                out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactStandaloneBrepOpening()
    {
        const int phaseId = 99;
        var (wall, _, boundary) = ExactWallWithOneThroughOpening();
        wall.CuttingElementIds = [];
        var opening = new Element
        {
            Id = 1301,
            TypeId = -1,
            IsDiscovered = true,
            CategoryId = -2000997,
            Category = "OST_SWallRectOpening",
            HostId = wall.Id,
            SerializedHostId = wall.Id,
            References = [wall.Id, phaseId],
            Parameters =
            [
                new Parameter
                {
                    Id = -1012100,
                    StorageType = StorageType.ElementId,
                    Value = phaseId,
                },
                new Parameter
                {
                    Id = -1013201,
                    StorageType = StorageType.Integer,
                    Value = -4,
                },
            ],
            BoundingBox = [1, -0.75, 1, 2, 0.75, 2],
            Geometry = BoxGeometry(1, -0.75, 1, 2, 0.75, 2),
        };
        var standaloneIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [opening.Id],
        };
        var directBoundaries = new Dictionary<int,
            List<(int OpeningId, GeometryData Boundary)>>
        {
            [wall.Id] = [(opening.Id, opening.Geometry)],
        };

        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndStandaloneOpening(
            wall, wall.BoundingBox!, boundary, null, standaloneIds,
            directBoundaries, out var gross, out int openingId));
        Assert.Equal(opening.Id, openingId);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        // The inverse cut edge is also present in real SWallRectOpening records. The
        // standalone IFCOPENINGELEMENT already owns its void relation and must not enter
        // the later synthetic hosted-cutter pipeline a second time.
        wall.CuttingElementIds = [opening.Id];
        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, opening]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-standalone-opening-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(1, Count(ifc, "=IFCFACETEDBREP("));
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesCompleteStandaloneBrepOpeningBijection()
    {
        const int phaseId = 99;
        var (wall, _, _, boundary) = ExactWallWithTwoThroughOpenings();
        wall.CuttingElementIds = [];
        Element Opening(int id, double minimumAlong) => new()
        {
            Id = id,
            TypeId = -1,
            IsDiscovered = true,
            CategoryId = -2000997,
            Category = "OST_SWallRectOpening",
            HostId = wall.Id,
            SerializedHostId = wall.Id,
            References = [wall.Id, phaseId],
            Parameters =
            [
                new Parameter
                {
                    Id = -1012100,
                    StorageType = StorageType.ElementId,
                    Value = phaseId,
                },
                new Parameter
                {
                    Id = -1013201,
                    StorageType = StorageType.Integer,
                    Value = -4,
                },
            ],
            BoundingBox =
                [minimumAlong, -0.75, 1, minimumAlong + 1, 0.75, 2],
            Geometry = BoxGeometry(
                minimumAlong, -0.75, 1, minimumAlong + 1, 0.75, 2),
        };
        var firstOpening = Opening(1701, 1);
        var secondOpening = Opening(1702, 3);
        var standaloneIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [secondOpening.Id, firstOpening.Id],
        };
        var directBoundaries = new Dictionary<int,
            List<(int OpeningId, GeometryData Boundary)>>
        {
            [wall.Id] =
            [
                (secondOpening.Id, secondOpening.Geometry!),
                (firstOpening.Id, firstOpening.Geometry!),
            ],
        };

        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndStandaloneOpenings(
            wall, wall.BoundingBox!, boundary, null, standaloneIds,
            directBoundaries, out var gross, out var openingIds));
        Assert.Equal([firstOpening.Id, secondOpening.Id], openingIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        directBoundaries[wall.Id][0] =
            (secondOpening.Id, BoxGeometry(3.25, -0.75, 1, 4.25, 0.75, 2));
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndStandaloneOpenings(
            wall, wall.BoundingBox!, boundary, null, standaloneIds,
            directBoundaries, out _, out _));
        directBoundaries[wall.Id][0] =
            (secondOpening.Id, secondOpening.Geometry!);

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, firstOpening, secondOpening]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-standalone-openings-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "=IFCFACETEDBREP("));
            Assert.Equal(2, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(2, Count(ifc, "=IFCRELVOIDSELEMENT("));
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

