    [Fact]
    public void RectangularWallMultiHoleValidation_SeparatesTwoExactThroughOpenings()
    {
        var (wall, _, _, boundary) = ExactWallWithTwoThroughOpenings();

        Assert.True(IfcExporter.TryGetExactRectangularWallGrossBoundaryAndOpenings(
            boundary, wall.Location!, 1, wall.BoundingBox!,
            out var gross, out var openings, out string rejectionReason),
            rejectionReason);
        Assert.Equal(6, gross.Faces.Count);
        Assert.All(gross.Faces, face => Assert.Null(face.InnerVertices));
        Assert.Equal(2, openings.Count);
        Assert.Equal(1.5, openings[0].CentreXFt, 12);
        Assert.Equal(3.5, openings[1].CentreXFt, 12);
        Assert.All(openings, opening =>
        {
            Assert.Equal(1, opening.WidthFt, 12);
            Assert.Equal(1, opening.BaseZFt, 12);
            Assert.Equal(1, opening.HeightFt, 12);
        });
        Assert.False(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            boundary, wall.Location!, 1, wall.BoundingBox!, out _, out _));
    }

    [Fact]
    public void JoinedWallOpeningValidation_PreservesExactMiteredGrossPlan()
    {
        var (wall, cutter, boundary) = ExactWallWithOneThroughOpening();
        wall.Location!.StartPoint = [-1, 0, 0];
        foreach (GeoFace face in boundary.Faces!)
        {
            foreach (double[] point in (face.OuterVertices ?? [])
                         .Concat((face.InnerVertices ?? [])
                             .SelectMany(ring => ring)))
            {
                bool openingVertex = point[2] is > 0 and < 3
                    && point[0] is 1 or 2;
                if (openingVertex)
                    point[0] += 0.5;
                else if (point[1] == 0.5 && point[0] == 0)
                    point[0] = 1;
            }
        }
        cutter.BoundingBox = [1.5, -0.5, 1, 2.5, 0.5, 2];
        cutter.Transform!.Origin = [2, 0, 1];

        Assert.False(IfcExporter.TryGetExactRectangularWallGrossBoundaryAndOpenings(
            boundary, wall.Location, 1, wall.BoundingBox!,
            out _, out _, out string rectangularRejectionReason));
        Assert.StartsWith("outer-side-profile-", rectangularRejectionReason);
        Assert.True(IfcExporter.TryGetExactStraightWallGrossBoundaryAndOpenings(
            boundary, wall.Location, 1, wall.BoundingBox!,
            out var confirmedGross, out var openings, out string rejectionReason),
            rejectionReason);
        Assert.Single(openings);
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            confirmedGross, wall.Location, 1, wall.BoundingBox!,
            out var plan, out _, out _));
        Assert.Equal(4, plan.Count);
        Assert.Contains(plan, point => point[0] == 0 && point[1] == -0.5);
        Assert.Contains(plan, point => point[0] == 1 && point[1] == 0.5);

        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
        };
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, boundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            out var verifiedGross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, verifiedGross));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, verifiedGross,
            allowBoundaryOwnedVerticalDefinition: true));

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, cutter]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-joined-wall-opening-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCARBITRARYCLOSEDPROFILEDEF(", ifc);
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        foreach (GeoFace face in boundary.Faces!)
            foreach (double[] point in (face.OuterVertices ?? [])
                         .Concat((face.InnerVertices ?? [])
                             .SelectMany(ring => ring)))
                if (point[1] == 0.5 && point[0] == 4)
                    point[0] = 3.75;
        Assert.False(IfcExporter.TryGetExactStraightWallGrossBoundaryAndOpenings(
            boundary, wall.Location, 1, wall.BoundingBox!,
            out _, out _, out string asymmetricJoinRejectionReason));
        Assert.Equal("outer-side-profile-asymmetric-two-end-join",
            asymmetricJoinRejectionReason);
    }

    [Fact]
    public void HorizontalCapSlotValidation_ReconstructsOnlyExactUProfile()
    {
        var wall = new Element
        {
            Id = 1791,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        foreach (bool maximumZ in new[] { false, true })
        {
            var slotted = HorizontalCapSlottedWallGeometry(
                0, -0.5, 0, 6, 0.5, 3,
                slotMinimumAlong: 2, slotMaximumAlong: 4,
                slotBoundaryZ: maximumZ ? 2 : 1,
                slotTouchesMaximumZ: maximumZ);

            Assert.True(
                IfcExporter
                    .TryGetExactRectangularWallGrossBoundaryFromHorizontalCapSlot(
                        slotted, wall.Location!, 1, wall.BoundingBox!,
                        out var gross, out var opening,
                        out string rejectionReason),
                rejectionReason);
            Assert.Equal(6, gross.Faces.Count);
            Assert.True(IfcExporter.IsExactVerticalExtrusionBoundary(gross));
            Assert.Equal(3, opening.CentreXFt, 12);
            Assert.Equal(2, opening.WidthFt, 12);
            Assert.Equal(maximumZ ? 2 : 0, opening.BaseZFt, 12);
            Assert.Equal(1, opening.HeightFt, 12);

            slotted.Faces![2].OuterVertices![0][0] += 0.125;
            Assert.False(
                IfcExporter
                    .TryGetExactRectangularWallGrossBoundaryFromHorizontalCapSlot(
                        slotted, wall.Location!, 1, wall.BoundingBox!,
                        out _, out _, out _));
        }
    }

    [Fact]
    public void SingleBoundarySlotValidation_RecoversEndAndSubdividedCornerProfiles()
    {
        var wall = new Element
        {
            Id = 17911,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var endSlot = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 3), (0, 3),
            (0, 2), (2, 2), (2, 1), (0, 1),
        ], -0.5, 0.5);
        var subdividedCornerSlot = ExtrudedSideProfileWallGeometry(
        [
            (2, 0), (6, 0), (6, 1.5), (6, 3),
            (3, 3), (0, 3), (0, 1), (2, 1),
        ], -0.5, 0.5);
        var multiplySubdividedEndSlot = ExtrudedSideProfileWallGeometry(
        [
            (6, 1), (4.5, 1), (3, 1), (0.25, 1),
            (0.25, 2.75), (6, 2.75), (6, 3),
            (0, 3), (0, 0), (6, 0),
        ], -0.5, 0.5);
        var cornerSlot = ExtrudedSideProfileWallGeometry(
        [
            (2, 0), (6, 0), (6, 3),
            (0, 3), (0, 1), (2, 1),
        ], -0.5, 0.5);

        foreach (var slotted in new[]
                 {
                     endSlot, subdividedCornerSlot,
                     multiplySubdividedEndSlot, cornerSlot,
                 })
        {
            Assert.True(
                IfcExporter
                    .TryGetExactRectangularWallGrossBoundaryFromSingleBoundarySlot(
                        slotted, wall.Location!, 1, wall.BoundingBox!,
                        out var gross, out string rejectionReason),
                rejectionReason);
            Assert.Equal(6, gross.Faces.Count);
            Assert.True(IfcExporter.IsExactVerticalExtrusionBoundary(gross));
            Assert.True(
                IfcExporter
                    .TryGetExactStraightWallGrossBoundaryFromSingleBoundarySlot(
                        slotted, wall.Location!, 1, wall.BoundingBox!,
                        out _, out var opening, out rejectionReason),
                rejectionReason);
            Assert.True(opening.WidthFt > 0);
            Assert.True(opening.HeightFt > 0);
        }
        Assert.Equal(12, multiplySubdividedEndSlot.Faces!.Count);
        multiplySubdividedEndSlot.Faces[2].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetExactStraightWallGrossBoundaryFromSingleBoundarySlot(
                    multiplySubdividedEndSlot, wall.Location!, 1,
                    wall.BoundingBox!, out _, out _, out _));

        subdividedCornerSlot.Faces![1].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetExactRectangularWallGrossBoundaryFromSingleBoundarySlot(
                    subdividedCornerSlot, wall.Location!, 1,
                    wall.BoundingBox!, out _, out _));

        var joinedCapSlot = PairedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (2, 1), (4, 1),
            (4, 0), (6, 0), (6, 3), (0, 3),
        ],
        [
            (1, 0), (2, 0), (2, 1), (4, 1),
            (4, 0), (6, 0), (6, 3), (1, 3),
        ], -0.5, 0.5);
        Assert.False(
            IfcExporter
                .TryGetExactRectangularWallGrossBoundaryFromSingleBoundarySlot(
                    joinedCapSlot, wall.Location!, 1, wall.BoundingBox!,
                    out _, out _));
        Assert.True(
            IfcExporter
                .TryGetExactStraightWallGrossBoundaryFromSingleBoundarySlot(
                    joinedCapSlot, wall.Location!, 1, wall.BoundingBox!,
                    out var joinedGross, out var joinedOpening,
                    out string joinedRejectionReason),
            joinedRejectionReason);
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            joinedGross, wall.Location!, 1, wall.BoundingBox!,
            out _, out _, out _));
        Assert.Equal(3, joinedOpening.CentreXFt, 12);
        Assert.Equal(2, joinedOpening.WidthFt, 12);
        Assert.Equal(0, joinedOpening.BaseZFt, 12);
        Assert.Equal(1, joinedOpening.HeightFt, 12);

        foreach (double[] point in joinedCapSlot.Faces![1].OuterVertices!
                     .Where(point => point[0] == 2))
            point[0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetExactStraightWallGrossBoundaryFromSingleBoundarySlot(
                    joinedCapSlot, wall.Location!, 1, wall.BoundingBox!,
                    out _, out _, out _));
    }

    [Fact]
    public void CollinearlySubdividedSideProfileValidation_RecoversJoinedGrossWithoutSlot()
    {
        var wall = new Element
        {
            Id = 17913,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 7, 0.5, 3],
        };
        var subdivided = PairedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (6, 0), (6, 3),
            (4, 3), (0, 3), (0, 2), (0, 1),
        ],
        [
            (1, 0), (2, 0), (7, 0), (7, 3),
            (4, 3), (1, 3), (1, 2), (1, 1),
        ], -0.5, 0.5);

        Assert.False(IfcExporter
            .TryGetExactStraightWallGrossBoundaryFromSingleBoundarySlot(
                subdivided, wall.Location!, 1, wall.BoundingBox!,
                out _, out _, out _));
        Assert.True(IfcExporter
            .TryGetExactStraightWallGrossBoundaryFromCollinearlySubdividedSideProfiles(
                subdivided, wall.Location!, 1, wall.BoundingBox!,
                out var gross, out string rejectionReason),
            rejectionReason);
        Assert.Equal("exact-collinearly-subdivided-side-profiles",
            rejectionReason);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            gross, wall.Location!, 1, wall.BoundingBox!,
            out var plan, out _, out _));
        Assert.Equal(4, plan.Count);

        double diagonal = Math.Sqrt(0.5);
        const double OffsetX = -20.123456789;
        const double OffsetY = 20.987654321;
        const double OffsetZ = 48.392388451443551;
        double[] Rotate(double[] point) =>
        [
            OffsetX + (point[0] - point[1]) * diagonal,
            OffsetY + (point[0] + point[1]) * diagonal,
            OffsetZ + point[2],
        ];
        var diagonalGross = new GeometryData
        {
            Faces = gross.Faces.Select(face => new GeoFace
            {
                OuterVertices = face.OuterVertices!
                    .Select(Rotate).ToList(),
            }).ToList(),
        };
        var sourceAlternatives = new List<GeoFace>
        {
            new()
            {
                AlternativeOuterVertices =
                [
                    Rotate([0, -0.5, 0]), Rotate([2, -0.5, 0]),
                    Rotate([6, -0.5, 0]), Rotate([6, -0.5, 3]),
                    Rotate([0, -0.5, 3]), Rotate([0, -0.5, 1]),
                ],
            },
            new()
            {
                AlternativeOuterVertices =
                [
                    Rotate([1, 0.5, 0]), Rotate([7, 0.5, 0]),
                    Rotate([7, 0.5, 3]), Rotate([4, 0.5, 3]),
                    Rotate([1, 0.5, 3]), Rotate([1, 0.5, 2]),
                ],
            },
        };
        var diagonalLocation = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = Rotate([0, 0, 0]),
            EndPoint = Rotate([6, 0, 0]),
        };
        Assert.True(
            IfcExporter.ExactCollinearlySubdividedSideProfilesMatchGross(
                sourceAlternatives, diagonalGross, diagonalLocation));
        sourceAlternatives[1].AlternativeOuterVertices![3][0] += 0.125;
        Assert.False(
            IfcExporter.ExactCollinearlySubdividedSideProfilesMatchGross(
                sourceAlternatives, diagonalGross, diagonalLocation));

        subdivided.Faces![1].OuterVertices![1][0] += 0.125;
        Assert.False(IfcExporter
            .TryGetExactStraightWallGrossBoundaryFromCollinearlySubdividedSideProfiles(
                subdivided, wall.Location!, 1, wall.BoundingBox!,
                out _, out _));
    }

    [Fact]
    public void ReferencedPeerWallMinimumCapValidation_PreservesEveryExactIntersection()
    {
        var wall = new Element
        {
            Id = 17914,
            CategoryId = -2000011,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 7, 0.5, 3],
        };
        var joinedGross = PairedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 3), (0, 3),
        ],
        [
            (1, 0), (7, 0), (7, 3), (1, 3),
        ], -0.5, 0.5);
        var peer = new Element
        {
            Id = 17915,
            CategoryId = -2000011,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [6, -2, 0],
                EndPoint = [6, 2, 0],
            },
            BoundingBox = [5.5, -2, 0, 6.5, 2, 3],
            Geometry = BoxGeometry(5.5, -2, 0, 6.5, 2, 3),
        };
        wall.References = [peer.Id];
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [peer.Id] = peer,
        };

        Assert.False(IfcExporter.TryGetUniquePathWallMinimumCapSubdivision(
            wall, elements, joinedGross, out _,
            out string uniqueRejectionReason));
        Assert.StartsWith("path-intersections-", uniqueRejectionReason);
        Assert.True(
            IfcExporter.TryGetExactReferencedPeerWallMinimumCapSubdivisions(
                wall, elements, joinedGross, out var subdivided,
                out string rejectionReason),
            rejectionReason);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                subdivided, wall.Location, 1, subdivided.BoundingBox!,
                out var plan, out _, out _, out string extrusionReason),
            extrusionReason);
        Assert.Equal("exact-collinear-boundary-subdivision",
            extrusionReason);
        Assert.True(plan.Count > 5);

        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                joinedGross, wall.Location, 1, joinedGross.BoundingBox!,
                out var unsubdividedPlan, out _, out _,
                out string unsubdividedReason),
            unsubdividedReason);
        var pathOnlyPoints = plan.Where(point =>
                !unsubdividedPlan.Any(corner =>
                    Math.Abs(corner[0] - point[0]) < 1e-10
                    && Math.Abs(corner[1] - point[1]) < 1e-10))
            .ToList();
        Assert.True(pathOnlyPoints.Count > 1);
        peer.Parameters = [WallWidthParameter(0.5)];
        Assert.False(
            IfcExporter.TryGetExactReferencedPeerWallMinimumCapSubdivisions(
                wall, elements, joinedGross, out _, out _));

        peer.Parameters = [WallWidthParameter(1)];
        const double OffsetX = -20.123456789;
        const double OffsetY = 20.987654321;
        double diagonal = Math.Sqrt(0.5);
        double[] Rotate(double[] point) =>
        [
            OffsetX + (point[0] - point[1]) * diagonal,
            OffsetY + (point[0] + point[1]) * diagonal,
            point[2],
        ];
        static void TransformGeometry(
            GeometryData geometry, Func<double[], double[]> transform)
        {
            foreach (GeoFace face in geometry.Faces ?? [])
            {
                face.OuterVertices = face.OuterVertices?
                    .Select(transform).ToList();
                face.AlternativeOuterVertices =
                    face.AlternativeOuterVertices?
                        .Select(transform).ToList();
                face.InnerVertices = face.InnerVertices?
                    .Select(ring => ring.Select(transform).ToList())
                    .ToList();
            }
            var points = (geometry.Faces ?? [])
                .SelectMany(face => face.OuterVertices ?? []).ToList();
            geometry.BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ];
        }
        TransformGeometry(joinedGross, Rotate);
        TransformGeometry(peer.Geometry!, Rotate);
        wall.Location.StartPoint = Rotate(wall.Location.StartPoint);
        wall.Location.EndPoint = Rotate(wall.Location.EndPoint);
        peer.Location!.StartPoint = Rotate(peer.Location.StartPoint);
        peer.Location.EndPoint = Rotate(peer.Location.EndPoint);
        wall.BoundingBox = joinedGross.BoundingBox;
        peer.BoundingBox = peer.Geometry.BoundingBox;

        Assert.True(
            IfcExporter.TryGetExactReferencedPeerWallMinimumCapSubdivisions(
                wall, elements, joinedGross, out var diagonalSubdivision,
                out string diagonalRejectionReason),
            diagonalRejectionReason);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                diagonalSubdivision, wall.Location, 1,
                diagonalSubdivision.BoundingBox!,
                out var diagonalPlan, out _, out _,
                out string diagonalExtrusionReason),
            diagonalExtrusionReason);
        Assert.Equal("exact-collinear-boundary-subdivision",
            diagonalExtrusionReason);
        Assert.True(diagonalPlan.Count > 5);
    }

    [Fact]
    public void ReciprocalEndConnectorMinimumCapValidation_PreservesOnlyAuthoredSubdivision()
    {
        double diagonal = Math.Sqrt(0.5);
        double lowStartAlong = -0.5 - diagonal;
        double highStartAlong = lowStartAlong + 2;
        double subdivisionAlong = lowStartAlong + 2 * diagonal;
        double[] Rotate(double[] point) =>
        [
            -(point[0] + point[1]) * diagonal,
            (point[0] - point[1]) * diagonal,
            point[2],
        ];
        static void TransformGeometry(
            GeometryData geometry, Func<double[], double[]> transform)
        {
            foreach (GeoFace face in geometry.Faces ?? [])
                face.OuterVertices = face.OuterVertices?
                    .Select(transform).ToList();
            var points = geometry.Faces!
                .SelectMany(face => face.OuterVertices!).ToList();
            geometry.BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ];
        }

        var exactBoundary = PairedSideProfileWallGeometry(
        [
            (lowStartAlong, 0), (4, 0), (4, 3),
            (lowStartAlong, 3),
        ],
        [
            (highStartAlong, 0), (4, 0), (4, 3),
            (highStartAlong, 3),
        ], -0.5, 0.5);
        TransformGeometry(exactBoundary, Rotate);
        double[] corner = Rotate([lowStartAlong, -0.5, 0]);
        double[] subdivision =
            Rotate([subdivisionAlong, -0.5, 0]);

        var wall = new Element
        {
            Id = 17918,
            CategoryId = -2000011,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = Rotate([4, 0, 0]),
            },
            BoundingBox = exactBoundary.BoundingBox,
        };
        var neighbour = new Element
        {
            Id = 17919,
            CategoryId = -2000011,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Geometry = PairedSideProfileWallGeometry(
            [
                (corner[0], 0), (4, 0), (4, 3), (corner[0], 3),
            ],
            [
                (subdivision[0], 0), (4, 0), (4, 3),
                (subdivision[0], 3),
            ], corner[1], subdivision[1]),
            References = [wall.Id],
        };
        wall.References = [neighbour.Id];
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [neighbour.Id] = neighbour,
        };

        Assert.True(
            IfcExporter
                .TryGetUniqueReciprocalEndConnectorMinimumCapSubdivision(
                    wall, elements, exactBoundary, out var subdivided,
                    out string rejectionReason),
            rejectionReason);
        Assert.Equal(
            "exact-reciprocal-end-connector-minimum-cap-subdivision",
            rejectionReason);
        Assert.Equal(7, subdivided.Faces.Count);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                subdivided, wall.Location, 1, subdivided.BoundingBox!,
                out var plan, out _, out _, out string extrusionReason),
            extrusionReason);
        Assert.Equal("exact-collinear-boundary-subdivision",
            extrusionReason);
        Assert.Equal(5, plan.Count);
        Assert.Contains(plan, point =>
            Math.Abs(point[0] - subdivision[0]) < 1e-10
            && Math.Abs(point[1] - subdivision[1]) < 1e-10);

        double[] openingCentre = Rotate([2, 0, 0]);
        var exactInteriorThroughCut =
            new IfcExporter.HostedOpeningGeometry(
                openingCentre[0], openingCentre[1],
                -diagonal, diagonal, 0.5, 2, 0.5, 1.5,
                ExactDepth: true,
                IsExactSerializedDefinition: true);
        Assert.True(
            IfcExporter
                .HostedOpeningWriterOperandIsRobustInteriorThroughCutOfExactWall(
                    wall, exactBoundary.BoundingBox!, exactBoundary,
                    exactInteriorThroughCut));
        Assert.False(
            IfcExporter
                .HostedOpeningWriterOperandIsRobustInteriorThroughCutOfExactWall(
                    wall, subdivided.BoundingBox!, subdivided,
                    exactInteriorThroughCut));

        double[] recessCentre = Rotate([2, -0.3, 0]);
        var exactSingleSideRecess = exactInteriorThroughCut with
        {
            CentreXFt = recessCentre[0],
            CentreYFt = recessCentre[1],
            DepthFt = 0.4,
        };
        Assert.True(
            IfcExporter
                .HostedOpeningWriterOperandIsWriterPrecisionSingleSidePlaneCoincidentInteriorCutOfExactWall(
                    wall, exactBoundary.BoundingBox!, exactBoundary,
                    exactSingleSideRecess));
        Assert.False(
            IfcExporter
                .HostedOpeningWriterOperandIsWriterPrecisionSingleSidePlaneCoincidentInteriorCutOfExactWall(
                    wall, exactBoundary.BoundingBox!, exactBoundary,
                    exactSingleSideRecess with { DepthFt = 0.39 }));
        double[] shiftedRecessCentre = Rotate([2, -0.29, 0]);
        Assert.False(
            IfcExporter
                .HostedOpeningWriterOperandIsWriterPrecisionSingleSidePlaneCoincidentInteriorCutOfExactWall(
                    wall, exactBoundary.BoundingBox!, exactBoundary,
                    exactSingleSideRecess with
                    {
                        CentreXFt = shiftedRecessCentre[0],
                        CentreYFt = shiftedRecessCentre[1],
                    }));

        neighbour.References = [];
        Assert.False(
            IfcExporter
                .TryGetUniqueReciprocalEndConnectorMinimumCapSubdivision(
                    wall, elements, exactBoundary, out _,
                    out string missingReciprocalReason));
        Assert.Equal("reciprocal-end-connector-subdivisions-0",
            missingReciprocalReason);

        neighbour.References = [wall.Id];
        neighbour.Location.StartPoint = [0.01, 0, 0];
        Assert.False(
            IfcExporter
                .TryGetUniqueReciprocalEndConnectorMinimumCapSubdivision(
                    wall, elements, exactBoundary, out _,
                    out string disconnectedPathReason));
        Assert.Equal("reciprocal-end-connector-subdivisions-0",
            disconnectedPathReason);
    }

    [Fact]
    public void SingleBoundarySlotWriterGate_RequiresOneExactProvenanceOperand()
    {
        var wall = new Element
        {
            Id = 17912,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var slotted = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 3), (0, 3),
            (0, 2), (2, 2), (2, 1), (0, 1),
        ], -0.5, 0.5);
        var unsubdividedCornerSlot = ExtrudedSideProfileWallGeometry(
        [
            (2, 0), (6, 0), (6, 3),
            (0, 3), (0, 1), (2, 1),
        ], -0.5, 0.5);
        const int CutterId = 17913;
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [CutterId],
        };
        var standalone = new Dictionary<int, List<int>>();
        var serializedOperand = new IfcExporter.HostedOpeningGeometry(
            2, 0, 0, 1, 1, 2, 1, 1,
            ExactDepth: true,
            IsExactSerializedDefinition: true);
        var operands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(CutterId, serializedOperand)],
        };

        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out var gross, out var cutterIds));
        Assert.Equal([CutterId], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, unsubdividedCornerSlot,
                    emittedCutters, operands, standalone,
                    out _, out _));

        double diagonal = Math.Sqrt(0.5);
        operands[wall.Id] =
        [
            (CutterId, serializedOperand with
            {
                AxisX = diagonal,
                AxisY = diagonal,
                WidthFt = 2,
                DepthFt = 2,
            }),
        ];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));

        operands[wall.Id] =
        [
            (CutterId, serializedOperand with { CentreXFt = 20 }),
        ];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, unsubdividedCornerSlot,
                    emittedCutters, operands, standalone,
                    out _, out _));

        operands[wall.Id] =
        [
            (CutterId, new IfcExporter.HostedOpeningGeometry(
                2, 1, 1, 0, 2, 1, 1, 1,
                ExactDepth: true,
                IsExactSerializedDefinition: true)),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));

        operands[wall.Id] =
        [
            (CutterId, serializedOperand with
            {
                IsExactSerializedDefinition = false,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));

        var familyBoundary = BoxGeometry(1, -0.5, 1, 3, 0.5, 2);
        operands[wall.Id] =
        [
            (CutterId, new IfcExporter.HostedOpeningGeometry(
                2, 0, 1, 0, 2, 1, 1, 1,
                ExactDepth: true,
                Boundary: familyBoundary,
                IsExactConcordantFamilyCut: true)),
        ];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));
        var multiplySubdividedSlot = ExtrudedSideProfileWallGeometry(
        [
            (6, 1), (4.5, 1), (3, 1), (0.25, 1),
            (0.25, 2.75), (6, 2.75), (6, 3),
            (0, 3), (0, 0), (6, 0),
        ], -0.5, 0.5);
        Assert.Equal(12, multiplySubdividedSlot.Faces!.Count);
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, multiplySubdividedSlot,
                    emittedCutters, operands, standalone,
                    out _, out _));

        var sourceSteppedOperand =
            new IfcExporter.HostedOpeningGeometry(
                1, 0, 1, 0, 2, 2, 1, 1,
                ExactDepth: true,
                IsExactSourceWallProfilesMappedBreakpoint: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            sourceSteppedOperand, innerWidthFt: 1.5,
            innerHeightFt: 0.75, breakpointNormalFt: 0,
            innerAtMinimum: false, out var sourceSteppedBoundary));
        sourceSteppedOperand = sourceSteppedOperand with
        {
            Boundary = sourceSteppedBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                1.5, 0.75, 0, false),
        };
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                sourceSteppedOperand));
        operands[wall.Id] = [(CutterId, sourceSteppedOperand)];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));

        sourceSteppedBoundary.Faces![0].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));
        sourceSteppedBoundary.Faces[0].OuterVertices![0][0] -= 0.125;
        operands[wall.Id] =
        [
            (CutterId, sourceSteppedOperand with
            {
                IsExactSerializedDefinition = true,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));

        standalone[wall.Id] = [17914];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                    wall, wall.BoundingBox!, slotted,
                    emittedCutters, operands, standalone,
                    out _, out _));
    }

    [Fact]
    public void ExactSourceStepReplacement_InheritsOnlyCompleteLegacyWriterValidation()
    {
        const int CutterId = 17915;
        var wallBoundary = BoxGeometry(0, -0.5, 0, 6, 0.5, 3);
        var wall = new Element
        {
            Id = 17916,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = wallBoundary,
        };
        var legacyOperand = new IfcExporter.HostedOpeningGeometry(
            2, 0, 1, 0, 1.2, 2, 1, 1.1,
            ExactDepth: true);
        var sourceStepOperand = legacyOperand with
        {
            IsExactSourceWallProfilesMappedBreakpoint = true,
        };
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            sourceStepOperand, innerWidthFt: 1,
            innerHeightFt: 1, breakpointNormalFt: 0,
            innerAtMinimum: false, out var sourceStepBoundary));
        sourceStepOperand = sourceStepOperand with
        {
            Boundary = sourceStepBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                1, 1, 0, false),
        };
        var emitted = new List<(
            int CutterId, IfcExporter.HostedOpeningGeometry Operand)>
        {
            (CutterId, sourceStepOperand),
        };
        var legacy = new List<(
            int CutterId, IfcExporter.HostedOpeningGeometry Operand)>
        {
            (CutterId, legacyOperand),
        };

        Assert.True(
            IfcExporter
                .ExactSourceSteppedReplacementCanInheritLegacyWriterValidation(
                    wall, wall.BoundingBox!, wallBoundary,
                    emitted, legacy));

        emitted[0] = (CutterId, sourceStepOperand with
        {
            IsExactSerializedDefinition = true,
        });
        Assert.False(
            IfcExporter
                .ExactSourceSteppedReplacementCanInheritLegacyWriterValidation(
                    wall, wall.BoundingBox!, wallBoundary,
                    emitted, legacy));
        emitted[0] = (CutterId, sourceStepOperand);
        legacy[0] = (CutterId, legacyOperand with { DepthFt = 0 });
        Assert.False(
            IfcExporter
                .ExactSourceSteppedReplacementCanInheritLegacyWriterValidation(
                    wall, wall.BoundingBox!, wallBoundary,
                    emitted, legacy));
    }

    [Fact]
    public void SourceOwnedCapSlotGate_RequiresNoOtherOpeningPath()
    {
        var wall = new Element
        {
