    }

    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsExactCapSlotCutterBijection()
    {
        var wall = new Element
        {
            Id = 1794,
            TypeId = 1796,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            CuttingElementIds = [1795],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var slotted = HorizontalCapSlottedWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            slotMinimumAlong: 2, slotMaximumAlong: 4,
            slotBoundaryZ: 1, slotTouchesMaximumZ: false);
        wall.Geometry = slotted;
        var cutter = new Element
        {
            Id = 1795,
            TypeId = 1797,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = wall.Id,
            BoundingBox = [2, -0.5, 0, 4, 0.5, 1],
            Transform = new InstanceTransform
            {
                Origin = [3, 0, 0],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
        };

        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, slotted, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        cutter.BoundingBox = [2, -0.5, 0, 4.25, 0.5, 1];
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, slotted, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsExactOppositeEndSlotBijection()
    {
        var wall = new Element
        {
            Id = 1798,
            TypeId = 1802,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            CuttingElementIds = [1800, 1799],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var slotted = OppositeEndSlottedWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            minimumSlotEnd: 1, maximumSlotStart: 5,
            slotMinimumZ: 1, slotMaximumZ: 2);
        wall.Geometry = slotted;
        Element Cutter(int id, double minimumAlong, double maximumAlong) =>
            new()
            {
                Id = id,
                TypeId = 1803,
                CategoryId = -2000023,
                Category = "OST_Doors",
                SerializedHostId = wall.Id,
                BoundingBox =
                [
                    minimumAlong, -0.5, 1,
                    maximumAlong, 0.5, 2,
                ],
                Transform = new InstanceTransform
                {
                    Origin =
                    [
                        (minimumAlong + maximumAlong) / 2, 0, 1,
                    ],
                    BasisX = [1, 0, 0],
                    BasisY = [0, 1, 0],
                    BasisZ = [0, 0, 1],
                },
            };
        var minimumCutter = Cutter(1799, 0, 1);
        var maximumCutter = Cutter(1800, 5, 6);
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [minimumCutter.Id] = minimumCutter,
            [maximumCutter.Id] = maximumCutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [minimumCutter.Id] = [wall.Id],
            [maximumCutter.Id] = [wall.Id],
        };

        Assert.True(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromOppositeEndSlots(
                slotted, wall.Location!, 1, wall.BoundingBox!,
                out var confirmedGross, out var openings,
                out string rejectionReason),
            rejectionReason);
        Assert.Equal(2, openings.Count);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, confirmedGross));
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, slotted, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            out var gross, out var cutterIds));
        Assert.Equal([minimumCutter.Id, maximumCutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        maximumCutter.BoundingBox = [4, -0.5, 1, 4.5, 0.5, 2];
        maximumCutter.Transform!.Origin = [4.25, 0, 1];
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, slotted, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsExactVerticalStepWithoutOpenings()
    {
        var wall = new Element
        {
            Id = 1891,
            TypeId = 1892,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
