        };
        var stepped = VerticalStepWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            stepAlong: 1, stepZ: 1);
        var fragmentedSource = new GeometryData
        {
            BoundingBox = stepped.BoundingBox,
            Faces = stepped.Faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, stepped.Faces!.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        wall.Geometry = fragmentedSource;
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromVerticalStep(
                stepped, wall.Location!, 1, wall.BoundingBox!,
                out var confirmedGross, out string rejectionReason),
            rejectionReason);
        Assert.Equal(6, confirmedGross.Faces.Count);
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, stepped,
                emittedCutterIds, standaloneOpeningIds, out var gross));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        wall.CuttingElementIds = [1893];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, stepped,
                emittedCutterIds, standaloneOpeningIds, out _));
        wall.CuttingElementIds = [];

        emittedCutterIds[wall.Id] = [1893];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, stepped,
                emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        wall.Geometry = new GeometryData
        {
            Faces =
            [
                new GeoFace
                {
                    AlternativeOuterVertices =
                    [
                        [0, 0, 0], [1, 0, 0], [1, 1, 0],
                    ],
                },
            ],
        };
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, stepped,
                emittedCutterIds, standaloneOpeningIds, out _));
        wall.Geometry = fragmentedSource;

        wall.Geometry = stepped;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, stepped,
                emittedCutterIds, standaloneOpeningIds, out _));
        wall.Geometry = fragmentedSource;

        var mismatchedSides = VerticalStepWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            stepAlong: 1, stepZ: 1);
        mismatchedSides.Faces![1].OuterVertices![3][0] += 0.25;
        Assert.False(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromVerticalStep(
                mismatchedSides, wall.Location!, 1, wall.BoundingBox!,
                out _, out _));

        var ambiguousBottomLeft = VerticalStepWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            stepAlong: 1, stepZ: 1);
        foreach (var point in ambiguousBottomLeft.Faces!
                     .SelectMany(face => face.OuterVertices!)
                     .Distinct<double[]>(ReferenceEqualityComparer.Instance))
        {
            point[0] = 6 - point[0];
            point[2] = 3 - point[2];
        }
        Assert.False(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromVerticalStep(
                ambiguousBottomLeft, wall.Location!, 1, wall.BoundingBox!,
                out _, out _));
        Assert.True(
            IfcExporter.TryGetExactRectangularWallTrimmedBoundaryFromInverseVerticalStep(
                ambiguousBottomLeft, wall.Location!, 1, wall.BoundingBox!,
                out var trimmed, out string trimmedReason),
            trimmedReason);
        Assert.Equal(5, trimmed.BoundingBox![0], 12);
        Assert.Equal(6, trimmed.BoundingBox[3], 12);
        Assert.True(
            IfcExporter.TryGetVerifiedTrimmedWallBoundaryFromInverseVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, ambiguousBottomLeft,
                emittedCutterIds, standaloneOpeningIds,
                out var verifiedTrimmed, out var serializedAxisPlan));
        Assert.Equal(trimmed.BoundingBox, verifiedTrimmed.BoundingBox);
        Assert.Equal(4, serializedAxisPlan.Count);
        Assert.True(IfcExporter.WallPlanMatchesSerializedBounds(
            serializedAxisPlan, wall.BoundingBox!));

        wall.Geometry = stepped;
        Assert.False(
            IfcExporter.TryGetVerifiedTrimmedWallBoundaryFromInverseVerticalStepWithoutOpenings(
                wall, wall.BoundingBox!, ambiguousBottomLeft,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

    [Fact]
    public void VerticalStepOpeningValidation_RequiresExactSourceHoleAndWriterPrism()
    {
        static (Element Wall, GeometryData Boundary,
            Dictionary<int, List<int>> EmittedIds,
            Dictionary<int, List<(int CutterId,
                IfcExporter.HostedOpeningGeometry Operand)>> EmittedOperands)
            Scenario(bool inverse)
        {
            const int cutterId = 1896;
            var (boundary, openingBoundary) =
                VerticalStepWallWithThroughOpeningGeometry(inverse);
            var source = new GeometryData
            {
                BoundingBox = boundary.BoundingBox,
                Faces = boundary.Faces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(
                            0, boundary.Faces!.Count).ToList(),
                        IsClosed = false,
                    },
                ],
            };
            var wall = new Element
            {
                Id = inverse ? 1894 : 1895,
                TypeId = 1892,
                CategoryId = -2000011,
                Category = "OST_Walls",
                Layers =
                [
                    new MaterialLayer
                    {
                        LayerIndex = 0,
                        ThicknessMm = 304.8,
                    },
                ],
                CuttingElementIds = [],
                Location = new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [0, 0, 0],
                    EndPoint = [6, 0, 0],
                },
                BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
                Geometry = source,
            };
            double openingMinimumAlong = inverse ? 5.2 : 2;
            double openingMaximumAlong = inverse ? 5.6 : 3;
            double openingBaseZ = inverse ? 1.25 : 0.25;
            var operand = new IfcExporter.HostedOpeningGeometry(
                CentreXFt:
                    (openingMinimumAlong + openingMaximumAlong) / 2,
                CentreYFt: 0,
                AxisX: 1, AxisY: 0,
                WidthFt: openingMaximumAlong - openingMinimumAlong,
                DepthFt: 1.5,
                BaseZFt: openingBaseZ, HeightFt: 0.5,
                ExactDepth: true, Boundary: openingBoundary);
            return (wall, boundary,
                new Dictionary<int, List<int>>
                {
                    [wall.Id] = [cutterId],
                },
                new Dictionary<int,
                    List<(int CutterId,
                        IfcExporter.HostedOpeningGeometry Operand)>>
                {
                    [wall.Id] = [(cutterId, operand)],
                });
        }

        foreach (bool inverse in new[] { false, true })
        {
            var scenario = Scenario(inverse);
            Assert.True(
                IfcExporter
                    .TryGetVerifiedGrossWallBoundaryFromVerticalStepAndExactRectangularOpening(
                        scenario.Wall, scenario.Wall.BoundingBox!,
                        scenario.Boundary, scenario.EmittedIds,
                        scenario.EmittedOperands, null,
                        out var gross, out var cutterIds,
                        out bool usesInverseTrimmedSpan,
                        out var serializedAxisPlan));
            Assert.Equal([1896], cutterIds);
            Assert.Equal(inverse, usesInverseTrimmedSpan);
            Assert.Equal(inverse ? 5 : 0,
                gross.BoundingBox![0], 12);
            Assert.Equal(6, gross.BoundingBox[3], 12);
            Assert.Equal(inverse ? 4 : 0, serializedAxisPlan.Count);
        }

        var brokenConnector = Scenario(inverse: true);
        brokenConnector.Boundary.Faces![8]
            .OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromVerticalStepAndExactRectangularOpening(
                    brokenConnector.Wall,
                    brokenConnector.Wall.BoundingBox!,
                    brokenConnector.Boundary,
                    brokenConnector.EmittedIds,
                    brokenConnector.EmittedOperands, null,
                    out _, out _, out _, out _));

        var brokenWriter = Scenario(inverse: false);
        brokenWriter.EmittedOperands[brokenWriter.Wall.Id][0]
            .Operand.Boundary!.Faces[0]
            .OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromVerticalStepAndExactRectangularOpening(
                    brokenWriter.Wall,
                    brokenWriter.Wall.BoundingBox!,
                    brokenWriter.Boundary,
                    brokenWriter.EmittedIds,
                    brokenWriter.EmittedOperands, null,
                    out _, out _, out _, out _));
    }

