        const int DirectHostId = 1710638;
        const int PeerOneId = 1759223;
        const int PeerTwoId = 9740896;
        const int TerminalNeighbourId = 7723721;

        static double Feet(int writerMetres) =>
            writerMetres * (1e-5 / 0.3048);
        static double[] Point(int[] key) =>
            [Feet(key[0]), Feet(key[1]), Feet(key[2])];
        static GeoFace ProjectedFace(int[][] outer, int[][]? inner = null)
        {
            var face = Face(outer.Select(Point));
            if (inner != null)
                face.InnerVertices = [inner.Select(Point).ToList()];
            return face;
        }
        static GeometryData Shell(
            List<GeoFace> faces, double[] bounds, bool isClosed) => new()
        {
            BoundingBox = (double[])bounds.Clone(),
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = isClosed,
                },
            ],
        };
        static IfcExporter.HostedOpeningGeometry Stepped(
            int centreAlong, int centreNormal,
            int width, int depth, int baseZ, int height,
            int innerWidth, int innerHeight, int breakpointNormal,
            bool innerAtMinimum, bool parameterized)
        {
            var definition = new IfcExporter.HostedOpeningGeometry(
                CentreXFt: Feet(centreAlong),
                CentreYFt: Feet(centreNormal),
                AxisX: 1, AxisY: 0,
                WidthFt: Feet(width), DepthFt: Feet(depth),
                BaseZFt: Feet(baseZ), HeightFt: Feet(height),
                ExactDepth: true,
                IsExactAuthoredMultiHostEnvelope: true,
                IsExactParameterizedReveal: parameterized);
            Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
                definition, Feet(innerWidth), Feet(innerHeight),
                Feet(breakpointNormal), innerAtMinimum,
                out var boundary));
            return definition with
            {
                Boundary = boundary,
                SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                    Feet(innerWidth), Feet(innerHeight),
                    Feet(breakpointNormal), innerAtMinimum),
            };
