                Feet(-1237974), Feet(-1098317), Feet(1435000)),
            CuttingElementIds = [],
            References = [WallId],
        };
        var primaryCutter = Cutter(PrimaryId);
        var secondaryCutter = Cutter(SecondaryId);
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [directHost.Id] = directHost,
            [peerOne.Id] = peerOne,
            [peerTwo.Id] = peerTwo,
            [terminalNeighbour.Id] = terminalNeighbour,
            [primaryCutter.Id] = primaryCutter,
            [secondaryCutter.Id] = secondaryCutter,
        };
        int[] hostIds = [DirectHostId, PeerOneId, WallId, PeerTwoId];
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [PrimaryId] = hostIds.ToList(),
            [SecondaryId] = hostIds.ToList(),
        };
        var primary = Stepped(
            centreAlong: -1398474, centreNormal: -1189317,
            width: 185000, depth: 58000,
            baseZ: 953000, height: 177000,
            innerWidth: 175000, innerHeight: 172000,
            breakpointNormal: -1198317,
            innerAtMinimum: true,
            parameterized: true);
        var secondary = Stepped(
            centreAlong: -1150000, centreNormal: -1167317,
            width: 10000, depth: 20000,
            baseZ: 1000000, height: 50000,
            innerWidth: 8000, innerHeight: 40000,
            breakpointNormal: -1164317,
            innerAtMinimum: false,
            parameterized: false);
        var emittedCutters = hostIds.ToDictionary(
            id => id, _ => new List<int> { PrimaryId, SecondaryId });
        var emittedOperands = hostIds.ToDictionary(
            id => id,
            _ => new List<(int CutterId,
                IfcExporter.HostedOpeningGeometry Operand)>
            {
                (PrimaryId, primary),
                (SecondaryId, secondary),
            });
        var standalone = new Dictionary<int, List<int>>();
        bool TryValidation() => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenEighteenFaceSteppedJoinParameterizedRevealAndDisjointOpening(
                wall, bounds, rebuilt, elements, inverseHosts,
                emittedCutters, emittedOperands, standalone,
                out _, out _);

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenEighteenFaceSteppedJoinParameterizedRevealAndDisjointOpening(
                wall, bounds, rebuilt, elements, inverseHosts,
                emittedCutters, emittedOperands, standalone,
                out var gross, out var cutterIds));
        Assert.Equal([PrimaryId, SecondaryId], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        var grossAlong = gross.Faces.SelectMany(face =>
                face.OuterVertices ?? [])
            .Select(point => point[0]).ToList();
        Assert.Equal(Feet(302000),
            grossAlong.Max() - grossAlong.Min(), 12);
        Assert.Equal(Feet(302900),
            wall.Location!.EndPoint[0] - wall.Location.StartPoint[0], 12);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, gross));

        sourceFaces[8].OuterVertices![0][0] += Feet(1);
        Assert.False(TryValidation());
        sourceFaces[8].OuterVertices![0][0] -= Feet(1);

        rebuiltFaces[9].OuterVertices![0][0] += Feet(1);
        Assert.False(TryValidation());
        rebuiltFaces[9].OuterVertices![0][0] -= Feet(1);

        terminalNeighbour.References = [];
        Assert.False(TryValidation());
        terminalNeighbour.References = [WallId];

        var targetReferences = wall.References!;
        targetReferences.Add(TerminalNeighbourId);
        Assert.False(TryValidation());
        targetReferences.RemoveAt(targetReferences.Count - 1);

        wall.CuttingElementIds = [];
        Assert.False(TryValidation());
        wall.CuttingElementIds = null;

        inverseHosts[SecondaryId].Add(DirectHostId);
        Assert.False(TryValidation());
        inverseHosts[SecondaryId].RemoveAt(
            inverseHosts[SecondaryId].Count - 1);

        emittedCutters[WallId].Add(PrimaryId);
        Assert.False(TryValidation());
        emittedCutters[WallId].RemoveAt(
            emittedCutters[WallId].Count - 1);

        emittedOperands[WallId][0] = (
            PrimaryId, primary with { IsExactParameterizedReveal = false });
        Assert.False(TryValidation());
        emittedOperands[WallId][0] = (PrimaryId, primary);

        emittedOperands[WallId][0] = (
            PrimaryId,
            primary with { IsExactAuthoredMultiHostEnvelope = false });
        Assert.False(TryValidation());
        emittedOperands[WallId][0] = (PrimaryId, primary);

        emittedOperands[WallId][1] = (
            SecondaryId,
            secondary with { IsExactSerializedDefinition = true });
        Assert.False(TryValidation());
        emittedOperands[WallId][1] = (SecondaryId, secondary);

        var overlappingSecondary = Stepped(
            centreAlong: -1400000, centreNormal: -1167317,
            width: 10000, depth: 20000,
            baseZ: 1000000, height: 50000,
            innerWidth: 8000, innerHeight: 40000,
            breakpointNormal: -1164317,
            innerAtMinimum: false,
            parameterized: false);
        emittedOperands[WallId][1] =
            (SecondaryId, overlappingSecondary);
        Assert.False(TryValidation());
        emittedOperands[WallId][1] = (SecondaryId, secondary);

        standalone[WallId] = [PrimaryId];
        Assert.False(TryValidation());
        standalone.Clear();
    }

    [Fact]
    public void OpenSteppedMinimumCapShellValidation_RequiresExactSourceCapAndNoOpenings()
    {
        var wall = new Element
        {
            Id = 1897,
            TypeId = 1898,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var stepped = PairedSideProfileWallGeometry(
        [
            (0, 3), (6, 3), (6, 1),
            (5.5, 1), (5.5, 0), (0, 0),
        ],
        [
            (0, 3), (5.5, 3), (5.5, 1),
            (5, 1), (5, 0), (0, 0),
        ], -0.5, 0.5);
        var source = PairedSideProfileWallGeometry(
        [
            (0, 3), (6, 3), (6, 1),
            (5.5, 1), (5.5, 0), (0, 0),
        ],
        [
            (0, 3), (5.5, 3), (5.5, 1),
            (5, 1), (5, 0), (0, 0),
        ], -0.5, 0.5);
        source.BrepSolids![0].IsClosed = false;
        wall.Geometry = source;
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter
                .TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
                    stepped, wall.Location, 1, wall.BoundingBox,
                    out var exact, out string rejectionReason),
            rejectionReason);
        Assert.Equal(6, exact.Faces.Count);
        Assert.Equal(5.5, exact.BoundingBox![3], 12);
        Assert.Equal(3, exact.BoundingBox[5], 12);

        var endpointStepped = PairedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 1),
            (5.5, 1), (5.5, 3), (0, 3),
        ],
        [
            (0, 0), (5.5, 0), (5.5, 1),
            (5, 1), (5, 3), (0, 3),
        ], -0.5, 0.5);
        Assert.True(
            IfcExporter
                .TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
                    endpointStepped, wall.Location, 1, wall.BoundingBox,
                    out var endpointExact, out rejectionReason),
            rejectionReason);
        var pathNeighbour = new Element
        {
            Id = 1900,
            CategoryId = -2000011,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [6, 0, 0],
                EndPoint = [6, 2, 0],
            },
            BoundingBox = [5.5, 0, 0, 6.5, 2, 3],
            Geometry = BoxGeometry(5.5, 0, 0, 6.5, 2, 3),
        };
        wall.References = [pathNeighbour.Id];
        elements[pathNeighbour.Id] = pathNeighbour;
        Assert.True(
            IfcExporter.TryGetUniquePathWallMinimumCapSubdivision(
                wall, elements, endpointExact, out var subdivided,
                out string subdivisionRejectionReason),
            subdivisionRejectionReason);
        Assert.Equal(7, subdivided.Faces.Count);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                subdivided, wall.Location, 1, subdivided.BoundingBox!,
                out var subdividedPlan, out _, out _,
                out string subdividedReason));
        Assert.Equal("exact-collinear-boundary-subdivision",
            subdividedReason);
        Assert.Equal(5, subdividedPlan.Count);
        pathNeighbour.Location.StartPoint = [6, 0.000001, 0];
        Assert.True(
            IfcExporter.TryGetUniquePathWallMinimumCapSubdivision(
                wall, elements, endpointExact, out _,
                out subdivisionRejectionReason),
            subdivisionRejectionReason);
        pathNeighbour.Location.StartPoint = [6, 0.1, 0];
        Assert.False(
            IfcExporter.TryGetUniquePathWallMinimumCapSubdivision(
                wall, elements, endpointExact, out _,
                out subdivisionRejectionReason));
        Assert.Equal("path-intersections-0",
            subdivisionRejectionReason);

        var rectangularEndpointStepped = PairedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 1),
            (5.5, 1), (5.5, 3), (0, 3),
        ],
        [
            (0, 0), (6, 0), (6, 1),
            (5.5, 1), (5.5, 3), (0, 3),
        ], -0.5, 0.5);
        Assert.True(
            IfcExporter
                .TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
                    rectangularEndpointStepped, wall.Location, 1,
                    wall.BoundingBox, out var rectangularEndpointExact,
                    out rejectionReason),
            rejectionReason);
        pathNeighbour.Location.StartPoint = [6, 0, 0];
        Assert.False(
            IfcExporter.TryGetUniquePathWallMinimumCapSubdivision(
                wall, elements, rectangularEndpointExact, out _,
                out subdivisionRejectionReason));
        Assert.Equal("exact-rectangular-minimum-cap",
            subdivisionRejectionReason);

        wall.References = null;
        elements.Remove(pathNeighbour.Id);

        Assert.True(
            IfcExporter
                .TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithoutOpenings(
                    wall, wall.BoundingBox, stepped, elements,
                    emittedCutterIds, standaloneOpeningIds,
                    out var verified));
        Assert.Equal(exact.BoundingBox, verified.BoundingBox);

        var grossFace = exact.Faces[2].OuterVertices!
            .Select(point => (double[])point.Clone()).ToList();
        grossFace.Insert(1,
        [
            (grossFace[0][0] + grossFace[1][0]) / 2,
            (grossFace[0][1] + grossFace[1][1]) / 2,
            (grossFace[0][2] + grossFace[1][2]) / 2,
        ]);
        source.Faces![0].AlternativeOuterVertices = grossFace;
        Assert.True(
            IfcExporter
                .TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithoutOpenings(
                    wall, wall.BoundingBox, stepped, elements,
                    emittedCutterIds, standaloneOpeningIds, out _));
        grossFace[1][1] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithoutOpenings(
                    wall, wall.BoundingBox, stepped, elements,
                    emittedCutterIds, standaloneOpeningIds, out _));
        source.Faces[0].AlternativeOuterVertices = null;

        emittedCutterIds[wall.Id] = [1899];
        Assert.False(
            IfcExporter
                .TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithoutOpenings(
                    wall, wall.BoundingBox, stepped, elements,
                    emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        source.BrepSolids[0].IsClosed = true;
        Assert.False(
            IfcExporter
                .TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithoutOpenings(
                    wall, wall.BoundingBox, stepped, elements,
                    emittedCutterIds, standaloneOpeningIds, out _));
        source.BrepSolids[0].IsClosed = false;

        source.Faces[6].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithoutOpenings(
                    wall, wall.BoundingBox, stepped, elements,
                    emittedCutterIds, standaloneOpeningIds, out _));
    }

    [Fact]
    public void CompleteOpenTwelveFaceMinimumPlanCap_UsesSourceOwnedAxisAndSmallerCap()
    {
        var (boundary, source) = CompleteOpenTwelveFaceMinimumPlanCapGeometry();
        var wall = new Element
        {
            Id = 19001,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0.25, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = source,
        };

        Assert.True(IfcExporter
            .HasExactCompleteOpenTwelveFaceNoAlternativeSourceAuthority(
                source));
        Assert.True(IfcExporter
            .TryGetExactVerticalWallBoundaryFromCompleteOpenTwelveFaceMinimumCapShell(
                wall, boundary, wall.BoundingBox,
                out var exact, out var exactLocation,
                out string rejectionReason), rejectionReason);
        Assert.Equal(
            "exact-complete-open-twelve-face-minimum-plan-cap-shell",
            rejectionReason);
        Assert.Equal(6, exact.Faces.Count);
        Assert.Equal(0, exact.BoundingBox![0], 12);
        Assert.Equal(5, exact.BoundingBox[3], 12);
        Assert.Equal([0.0, 5.0], new[]
        {
            exactLocation.StartPoint[0], exactLocation.EndPoint[0],
        }.Order());
        Assert.Equal(0, exactLocation.StartPoint[1], 12);
        Assert.Equal(0, exactLocation.EndPoint[1], 12);

        var touchingWriter = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5.5, CentreYFt: 0,
            AxisX: 0, AxisY: 1,
            WidthFt: 2, DepthFt: 1,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true,
            IsExactFamilyCutLoopWriterBox: true);
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
                exactLocation, 1, exact.BoundingBox, exact, touchingWriter));
        Assert.False(IfcExporter
            .HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
                wall, wall.BoundingBox, exact, touchingWriter));

        source.BrepSolids![0].IsClosed = true;
        Assert.False(IfcExporter
            .HasExactCompleteOpenTwelveFaceNoAlternativeSourceAuthority(
                source));
        Assert.False(IfcExporter
            .TryGetExactVerticalWallBoundaryFromCompleteOpenTwelveFaceMinimumCapShell(
                wall, boundary, wall.BoundingBox,
                out _, out _, out _));
        source.BrepSolids[0].IsClosed = false;

        source.Faces![0].AlternativeOuterVertices = source.Faces[0]
            .OuterVertices!.Select(point => (double[])point.Clone()).ToList();
        Assert.False(IfcExporter
            .HasExactCompleteOpenTwelveFaceNoAlternativeSourceAuthority(
                source));
        source.Faces[0].AlternativeOuterVertices = null;

        var equalCaps = PairedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 1),
            (5.9999999, 1), (5.9999999, 3), (0, 3),
        ],
        [
            (0, 0), (6, 0), (6, 1),
            (5.9999999, 1), (5.9999999, 3), (0, 3),
        ], -0.5, 0.5);
        Assert.False(IfcExporter
            .TryGetExactVerticalWallBoundaryFromCompleteOpenTwelveFaceMinimumCapShell(
                wall, equalCaps, wall.BoundingBox,
                out _, out _, out _));
    }

    [Fact]
    public void TwentyFourSolidSevenPointJoinedSpanSourceAuthority_RequiresExactTopology()
    {
        var source = TwentyFourSolidSevenPointJoinedSpanSourceGeometry();
        Assert.True(IfcExporter
            .HasExactTwentyFourSolidSevenPointJoinedSpanSourceAuthority(
                source));

        source.BrepSolids![8].IsClosed = true;
        Assert.False(IfcExporter
            .HasExactTwentyFourSolidSevenPointJoinedSpanSourceAuthority(
                source));
        source.BrepSolids[8].IsClosed = false;

        int lastFaceIndex = source.BrepSolids[23].FaceIndices[^1];
        source.BrepSolids[23].FaceIndices.RemoveAt(
            source.BrepSolids[23].FaceIndices.Count - 1);
        Assert.False(IfcExporter
            .HasExactTwentyFourSolidSevenPointJoinedSpanSourceAuthority(
                source));
        source.BrepSolids[23].FaceIndices.Add(lastFaceIndex);

        var exactAlternative = source.Faces![0].AlternativeOuterVertices!;
        source.Faces[0].AlternativeOuterVertices = exactAlternative.Take(6)
            .Select(point => (double[])point.Clone()).ToList();
        Assert.False(IfcExporter
            .HasExactTwentyFourSolidSevenPointJoinedSpanSourceAuthority(
                source));
        source.Faces[0].AlternativeOuterVertices = exactAlternative;

        source.BoundingBox![3] += 0.125;
        Assert.False(IfcExporter
            .HasExactTwentyFourSolidSevenPointJoinedSpanSourceAuthority(
                source));
    }

    [Fact]
    public void CompleteOpenNineFaceHorizontalCapProjection_RequiresExactSourceAndWriterIntersection()
    {
        const int WallId = 19011;
        const int CutterId = 19012;
        const int DirectHostId = 19013;
        var rebuilt = PairedSideProfileWallGeometry(
        [
            (0, 0), (0, 3), (6, 3),
            (6, 2), (4, 2), (4, 0),
        ],
        [
            (0, 0), (0, 3), (6, 3),
            (6, 2), (4, 2), (4, 0),
        ], -0.5, 0.5);
        var sourceFaces = rebuilt.Faces!.Select(face =>
            Face(face.OuterVertices!.Select(point =>
                (double[])point.Clone()))).ToList();
        GeoFace slotTop = Assert.Single(sourceFaces, face =>
            face.OuterVertices is { } ring
            && ring.All(point => point[2] == 2)
            && ring.Min(point => point[0]) == 4
            && ring.Max(point => point[0]) == 6);
        slotTop.AlternativeOuterVertices =
        [
            [4, -5, 2], [7, -5, 2],
            [7, 5, 2], [4, 5, 2],
        ];
        var slotBottom = Face(
        [
            [4, -0.5, 0], [6, -0.5, 0],
            [6, 0.5, 0], [4, 0.5, 0],
        ]);
        slotBottom.AlternativeOuterVertices =
        [
            [4, -5, 0], [7, -5, 0],
            [7, 5, 0], [4, 5, 0],
        ];
        sourceFaces.Add(slotBottom);
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 9).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = WallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = source,
            CuttingElementIds = [CutterId, 19014, 19015],
            References = [CutterId],
        };
        var directHost = new Element
        {
            Id = DirectHostId,
            CategoryId = -2000011,
            Category = "OST_Walls",
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = DirectHostId,
            SerializedHostId = DirectHostId,
            ExtraHostIds = [],
            ExplicitHostIds = [],
            References = [DirectHostId],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
            [directHost.Id] = directHost,
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5.5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 3, DepthFt: 10,
            BaseZFt: 0, HeightFt: 2,
            ExactDepth: true,
            IsExactFamilyCutLoopWriterBox: true,
            IsExactAuthoredRevealWriterBox: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, writer)],
        };

        Assert.True(IfcExporter
            .HasExactCompleteOpenNineFaceTwoHorizontalCapSourceAuthority(
                source));
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, null,
                out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox, gross));

        wall.Location.StartPoint = [6, 0, 0];
        wall.Location.EndPoint = [0, 0, 0];
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, null,
                out _, out _));
        wall.Location.StartPoint = [0, 0, 0];
        wall.Location.EndPoint = [6, 0, 0];

        double exactAlternativeX =
            slotTop.AlternativeOuterVertices![0][0];
        slotTop.AlternativeOuterVertices[0][0] += 0.125;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, null,
                out _, out _));
        slotTop.AlternativeOuterVertices[0][0] = exactAlternativeX;

        wall.References = [];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, null,
                out _, out _));
        wall.References = [cutter.Id];

        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with
            {
                IsExactAuthoredRevealWriterBox = false,
            }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, null,
                out _, out _));
        emittedOperands[wall.Id] = [(cutter.Id, writer)];

        source.BrepSolids![0].FaceIndices.Reverse();
        Assert.False(IfcExporter
            .HasExactCompleteOpenNineFaceTwoHorizontalCapSourceAuthority(
                source));
    }

    [Fact]
    public void CompleteOpenTwentyEightFaceDirectHostProjection_RequiresExactSourceAndConcordantWriter()
    {
        const int WallId = 5168994;
        const int CutterId = 2564811;
        static GeoFace SideFace(int vertexCount, double y)
        {
            int extraCount = vertexCount - 4;
            var vertices = new List<double[]> { new[] { 0.0, y, 0.0 } };
            for (int index = 1; index <= extraCount; index++)
                vertices.Add([10.0 * index / (extraCount + 1), y, 0]);
            vertices.AddRange(
            [
                [10, y, 0], [10, y, 3], [0, y, 3],
            ]);
            return Face(vertices);
        }

        var sourceFaces = new List<GeoFace> { SideFace(8, -0.5) };
        sourceFaces[0].AlternativeOuterVertices =
            SideFace(6, -0.5).OuterVertices;
        sourceFaces.AddRange(Enumerable.Range(0, 3)
            .Select(index => SideFace(8, index % 2 == 0 ? 0.5 : -0.5)));
        sourceFaces.Add(SideFace(6, 0.5));
        sourceFaces.AddRange(Enumerable.Range(0, 2)
            .Select(index => SideFace(5, index == 0 ? -0.5 : 0.5)));
        sourceFaces.AddRange(Enumerable.Range(0, 21)
            .Select(index => SideFace(4, index % 2 == 0 ? -0.5 : 0.5)));
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 28).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var rebuilt = PairedSideProfileWallGeometry(
        [
            (0, 0), (4, 0), (10, 0),
            (10, 1), (10, 3), (0, 3),
        ],
        [
            (0, 0), (4, 0), (10, 0),
            (10, 1), (10, 3), (0, 3),
        ], -0.5, 0.5);
        var wall = new Element
        {
            Id = WallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0.25, 0, 0],
                EndPoint = [9.75, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Geometry = source,
            CuttingElementIds = [],
            References = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = WallId,
            SerializedHostId = WallId,
            ExtraHostIds = [],
            ExplicitHostIds = [],
            References = [WallId],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var exactWriter = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 4, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 2,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true,
            Boundary: BoxGeometry(3, -1, 1, 5, 1, 2),
            IsExactConcordantFamilyCut: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, exactWriter)],
        };
        var exactPairs = new HashSet<(int WallId, int CutterId)>
        {
            (wall.Id, cutter.Id),
        };

        Assert.True(IfcExporter
            .HasExactCompleteOpenTwentyEightFaceSingleAlternativeSourceAuthority(
                source));
        Assert.True(IfcExporter
            .TryGetVerifiedBoundaryOwnedRedundantWallFromExactCompleteOpenTwentyEightFaceSourceAndSingleDirectHostOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands,
                new Dictionary<int, List<int>>(), exactPairs,
                out var gross, out var cutterIds));
        Assert.Same(rebuilt, gross);
        Assert.Equal([cutter.Id], cutterIds);

        wall.References = [];
        Assert.False(IfcExporter
            .TryGetVerifiedBoundaryOwnedRedundantWallFromExactCompleteOpenTwentyEightFaceSourceAndSingleDirectHostOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, exactPairs,
                out _, out _));
        wall.References = [cutter.Id];

        exactPairs.Clear();
        Assert.False(IfcExporter
            .TryGetVerifiedBoundaryOwnedRedundantWallFromExactCompleteOpenTwentyEightFaceSourceAndSingleDirectHostOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, exactPairs,
                out _, out _));
        exactPairs.Add((wall.Id, cutter.Id));

        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactWriter with
            {
                Boundary = BoxGeometry(3, -0.25, 1, 5, 0.25, 2),
            }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedBoundaryOwnedRedundantWallFromExactCompleteOpenTwentyEightFaceSourceAndSingleDirectHostOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, null, exactPairs,
                out _, out _));
        emittedOperands[wall.Id] = [(cutter.Id, exactWriter)];

        source.BrepSolids![0].FaceIndices.Reverse();
        Assert.False(IfcExporter
            .HasExactCompleteOpenTwentyEightFaceSingleAlternativeSourceAuthority(
                source));
    }

