                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        source.Faces[0].OuterVertices![0] = validPrimaryPoint;

        double validAlternativeCoordinate =
            source.Faces[0].AlternativeOuterVertices![0][0];
        source.Faces[0].AlternativeOuterVertices![0][0] = double.NaN;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        source.Faces[0].AlternativeOuterVertices![0][0] =
            validAlternativeCoordinate;

        double validRebuiltCoordinate = rebuilt.Faces![2].OuterVertices![0][0];
        rebuilt.Faces[2].OuterVertices![0][0] = double.MaxValue;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        rebuilt.Faces[2].OuterVertices![0][0] = validRebuiltCoordinate;

        var unsafeOpeningBoundary = BoxGeometry(
            2, -1.5, -0.5, 7, 1.5, 3.5);
        unsafeOpeningBoundary.Faces![0].OuterVertices![0][0] =
            double.MaxValue;
        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactWriter with { Boundary = unsafeOpeningBoundary }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        emittedOperands[wall.Id] = [(cutter.Id, exactWriter)];

        var sourcePrimaryRing = source.Faces[1].OuterVertices!;
        (sourcePrimaryRing[1], sourcePrimaryRing[2]) =
            (sourcePrimaryRing[2], sourcePrimaryRing[1]);
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        (sourcePrimaryRing[1], sourcePrimaryRing[2]) =
            (sourcePrimaryRing[2], sourcePrimaryRing[1]);

        var rebuiltConnectorRing = rebuilt.Faces[2].OuterVertices!;
        (rebuiltConnectorRing[1], rebuiltConnectorRing[2]) =
            (rebuiltConnectorRing[2], rebuiltConnectorRing[1]);
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        (rebuiltConnectorRing[1], rebuiltConnectorRing[2]) =
            (rebuiltConnectorRing[2], rebuiltConnectorRing[1]);

        exactPairs.Clear();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        exactPairs.Add((wall.Id, cutter.Id));

        double validAlternativeChord =
            source.Faces[0].AlternativeOuterVertices![5][0];
        source.Faces![0].AlternativeOuterVertices![5][0] = 6.5;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        source.Faces[0].AlternativeOuterVertices![5][0] =
            validAlternativeChord;

        double validConnectorChord = rebuilt.Faces![7].OuterVertices![0][0];
        rebuilt.Faces![7].OuterVertices![0][0] = 6.5;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        rebuilt.Faces[7].OuterVertices![0][0] = validConnectorChord;

        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactWriter with
            {
                Boundary = BoxGeometry(2.25, -1.5, -0.5, 7, 1.5, 3.5),
            }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactWriter with
            {
                Boundary = BoxGeometry(2, -1.5, -0.5, 7, 1.5, 2.5),
            }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        emittedOperands[wall.Id] = [(cutter.Id, exactWriter)];

        wall.References = [];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        wall.References = [cutter.Id];
        standalone[wall.Id] = [CutterId + 1];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        standalone.Clear();

        source.Faces.Add(Face([[0, -0.5, 0], [1, -0.5, 0],
            [1, -0.5, 1], [0, -0.5, 1]]));
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone, exactPairs,
                out _, out _));
        source.Faces.RemoveAt(source.Faces.Count - 1);
    }

    [Fact]
    public void CompleteOpenFifteenFaceTopSlot_RequiresExactEmbeddedReciprocalPeerAndDisjointWriter()
    {
        const int WallId = 8865712;
        const int PeerId = 9272247;
        const int CutterId = 8867617;
        const int DirectHostId = 8865713;
        const int AmbiguousPeerId = 9272248;
        double diagonal = Math.Sqrt(0.5);
        static void RotateFortyFiveDegrees(GeometryData geometry)
        {
            double diagonal = Math.Sqrt(0.5);
            foreach (GeoFace face in geometry.Faces)
                foreach (double[] point in face.OuterVertices ?? [])
                {
                    double along = point[0];
                    double normal = point[1];
                    point[0] = (along - normal) * diagonal;
                    point[1] = (along + normal) * diagonal;
                }
            var points = geometry.Faces
                .SelectMany(face => face.OuterVertices ?? []).ToList();
            geometry.BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ];
        }

        var rebuilt = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (10, 0), (10, 4), (9, 4),
            (9, 1), (1, 1), (1, 4), (0, 4),
        ], -0.5, 0.5);
        var peerBox = BoxGeometry(1, -0.7, 1, 9, -0.5, 4);
        var peerFaces = peerBox.Faces
            .Select(face => Face(face.OuterVertices!)).ToList();
        var peerSecondary = FourSideShellGeometry(
            1.5, 0.5, 1, 8.5, 0.7, 4);
        peerFaces.AddRange(peerSecondary.Faces
            .Select(face => Face(face.OuterVertices!)));
        var peerGeometry = new GeometryData
        {
            BoundingBox = [1, -0.7, 1, 9, -0.5, 4],
            Faces = peerFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 6).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(6, 4).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var sourceFaces = new List<GeoFace>
        {
            Face(rebuilt.Faces[0].OuterVertices!),
            Face([[0, -0.5, 0], [0, 0.5, 0],
                [10, 0.5, 0], [10, -0.5, 0]]),
            Face([[0, 0.5, 1], [0, 0.5, 0],
                [10, 0.5, 0], [10, 0.5, 1]]),
            Face([[0, 0.5, 4], [0, -0.5, 4],
                [10, -0.5, 4], [10, 0.5, 4]]),
            Face([[0, -0.5, 4], [0, 0.5, 4],
                [0, 0.5, 0], [0, -0.5, 0]]),
            Face([[10, 0.5, 4], [10, 0.5, 1],
                [0, 0.5, 1], [0, 0.5, 4]]),
            Face([[10, 0.5, 1], [0, 0.5, 1],
                [1, 0.7, 1], [9, 0.7, 1]]),
            Face([[1, 0.7, 4], [1, 0.7, 1],
                [9, 0.7, 1], [9, 0.7, 4]]),
        };
        sourceFaces.Add(Face(peerFaces[0].OuterVertices!)); // target 8
        sourceFaces.Add(Face(peerFaces[1].OuterVertices!)); // target 9
        sourceFaces.Add(Face(peerFaces[4].OuterVertices!)); // target 10
        sourceFaces.Add(Face(peerFaces[3].OuterVertices!)); // target 11
        sourceFaces.Add(Face(peerFaces[5].OuterVertices!)); // target 12
        sourceFaces.Add(Face(peerFaces[2].OuterVertices!)); // target 13
        sourceFaces.Add(Face([[10, -0.5, 0], [10, 0.5, 0],
            [10, 0.5, 4], [10, -0.5, 4]]));
        Assert.Equal(15, sourceFaces.Count);
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 10, 0.5, 4],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 15).ToList(),
                    IsClosed = false,
                },
            ],
        };
        RotateFortyFiveDegrees(rebuilt);
        RotateFortyFiveDegrees(peerGeometry);
        RotateFortyFiveDegrees(source);
        var wall = new Element
        {
            Id = WallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10.2 * diagonal, 10.2 * diagonal, 0],
            },
            BoundingBox = (double[])source.BoundingBox!.Clone(),
            Geometry = source,
            References = [PeerId, CutterId],
        };
        var peer = new Element
        {
            Id = PeerId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Geometry = peerGeometry,
            References = [WallId, CutterId],
        };
        var directHost = new Element
        {
            Id = DirectHostId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            References = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = DirectHostId,
            SerializedHostId = DirectHostId,
            ExtraHostIds = [PeerId, WallId],
            ExplicitHostIds = [],
            References = [DirectHostId, PeerId, WallId],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [peer.Id] = peer,
            [directHost.Id] = directHost,
            [cutter.Id] = cutter,
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 12 * diagonal, CentreYFt: 12 * diagonal,
            AxisX: -diagonal, AxisY: diagonal,
            WidthFt: 1, DepthFt: 1,
            BaseZFt: 1, HeightFt: 2,
            ExactDepth: true,
            IsFamilyCutLoop: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, writer)],
        };
        var standalone = new Dictionary<int, List<int>>();
        var exactForwardPairs = new HashSet<(int WallId, int CutterId)>
        {
            (wall.Id, cutter.Id),
        };

        bool TryValidation() => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFifteenFaceEmbeddedPeerTopSlotOpening(
                wall, wall.BoundingBox!, rebuilt, elements,
                emittedCutters, emittedOperands, standalone,
                exactForwardPairs,
                out _, out _);

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFifteenFaceEmbeddedPeerTopSlotOpening(
                wall, wall.BoundingBox, rebuilt, elements,
                emittedCutters, emittedOperands, standalone,
                exactForwardPairs,
                out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                gross, wall.Location, 1, wall.BoundingBox,
                out var grossPlan, out _, out _, out string grossReason),
            grossReason);
        Assert.Equal("exact", grossReason);
        var grossAlong = grossPlan.Select(point =>
            point[0] * diagonal + point[1] * diagonal).ToList();
        Assert.Equal(10, grossAlong.Max() - grossAlong.Min(), 12);
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, wall.BoundingBox, gross, writer));

        peerFaces[0].OuterVertices!.Reverse();
        Assert.True(TryValidation());
        peerFaces[0].OuterVertices!.Reverse();

        wall.Id = 0;
        Assert.False(TryValidation());
        wall.Id = WallId;

        double[] validSourcePoint = source.Faces[0].OuterVertices![0];
        source.Faces[0].OuterVertices![0] = [0, -0.5];
        Assert.False(TryValidation());
        source.Faces[0].OuterVertices![0] = validSourcePoint;

        double validSourceCoordinate =
            source.Faces[1].OuterVertices![0][0];
        source.Faces[1].OuterVertices![0][0] = double.NaN;
        Assert.False(TryValidation());
        source.Faces[1].OuterVertices![0][0] = validSourceCoordinate;

        double validRoleCoordinate =
            source.Faces[6].OuterVertices![2][0];
        source.Faces[6].OuterVertices![2][0] += 0.1;
        Assert.False(TryValidation());
        source.Faces[6].OuterVertices![2][0] = validRoleCoordinate;

        source.BrepSolids![0].FaceIndices.Reverse();
        Assert.False(TryValidation());
        source.BrepSolids[0].FaceIndices.Reverse();

        var sourcePrimary = source.Faces[0].OuterVertices!;
        (sourcePrimary[1], sourcePrimary[2]) =
            (sourcePrimary[2], sourcePrimary[1]);
        Assert.False(TryValidation());
        (sourcePrimary[1], sourcePrimary[2]) =
            (sourcePrimary[2], sourcePrimary[1]);

        source.Faces[1].AlternativeOuterVertices =
            source.Faces[1].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.False(TryValidation());
        source.Faces[1].AlternativeOuterVertices = null;

        var rebuiltConnector = rebuilt.Faces[2].OuterVertices!;
        (rebuiltConnector[1], rebuiltConnector[2]) =
            (rebuiltConnector[2], rebuiltConnector[1]);
        Assert.False(TryValidation());
        (rebuiltConnector[1], rebuiltConnector[2]) =
            (rebuiltConnector[2], rebuiltConnector[1]);

        var embeddedCycle = source.Faces[8].OuterVertices!;
        (embeddedCycle[1], embeddedCycle[2]) =
            (embeddedCycle[2], embeddedCycle[1]);
        Assert.False(TryValidation());
        (embeddedCycle[1], embeddedCycle[2]) =
            (embeddedCycle[2], embeddedCycle[1]);

        double validPeerCoordinate = peerFaces[0].OuterVertices![0][0];
        peerFaces[0].OuterVertices![0][0] = double.MaxValue;
        Assert.False(TryValidation());
        peerFaces[0].OuterVertices![0][0] = validPeerCoordinate;

        peerGeometry.BrepSolids![0].IsClosed = true;
        Assert.False(TryValidation());
        peerGeometry.BrepSolids[0].IsClosed = false;
        peerGeometry.BrepSolids[1].FaceIndices.Reverse();
        Assert.False(TryValidation());
        peerGeometry.BrepSolids[1].FaceIndices.Reverse();

        var peerSecondaryCycle = peerFaces[6].OuterVertices!;
        (peerSecondaryCycle[1], peerSecondaryCycle[2]) =
            (peerSecondaryCycle[2], peerSecondaryCycle[1]);
        Assert.False(TryValidation());
        (peerSecondaryCycle[1], peerSecondaryCycle[2]) =
            (peerSecondaryCycle[2], peerSecondaryCycle[1]);

        peer.IsBlockOnly = true;
        Assert.False(TryValidation());
        peer.IsBlockOnly = false;

        peer.References = [CutterId];
        Assert.False(TryValidation());
        peer.References = [WallId, CutterId];
        wall.References = [PeerId, PeerId, CutterId];
        Assert.False(TryValidation());
        wall.References = [PeerId, CutterId];

        var ambiguousPeer = new Element
        {
            Id = AmbiguousPeerId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Geometry = peerGeometry,
            References = [WallId, CutterId],
        };
        elements[ambiguousPeer.Id] = ambiguousPeer;
        wall.References.Add(ambiguousPeer.Id);
        Assert.False(TryValidation());
        wall.References.Remove(ambiguousPeer.Id);
        elements.Remove(ambiguousPeer.Id);

        cutter.ExtraHostIds = [WallId, WallId];
        Assert.False(TryValidation());
        cutter.ExtraHostIds = [PeerId, WallId];
        cutter.SuperInstanceId = CutterId + 1;
        Assert.False(TryValidation());
        cutter.SuperInstanceId = null;
        directHost.References = [];
        Assert.False(TryValidation());
        directHost.References = [CutterId];
        cutter.References = [DirectHostId, WallId];
        Assert.False(TryValidation());
        cutter.References = [DirectHostId, PeerId, WallId];

        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with
            {
                IsExactFamilyCutLoopWriterBox = true,
            }),
        ];
        Assert.False(TryValidation());
        emittedOperands[wall.Id] = [(cutter.Id, writer)];
        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with { WidthFt = double.MaxValue }),
        ];
        Assert.False(TryValidation());
        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with
            {
                AxisX = double.MaxValue,
                AxisY = 0,
            }),
        ];
        Assert.False(TryValidation());
        emittedOperands[wall.Id] = [(cutter.Id, writer)];
        exactForwardPairs.Clear();
        Assert.False(TryValidation());
        exactForwardPairs.Add((wall.Id, cutter.Id));
        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with
            {
                CentreXFt = 10.5 * diagonal,
                CentreYFt = 10.5 * diagonal,
            }),
        ];
        Assert.False(TryValidation());
        emittedOperands[wall.Id] = [(cutter.Id, writer)];
        emittedOperands[wall.Id].Add((cutter.Id, writer));
        Assert.False(TryValidation());
        emittedOperands[wall.Id] = [(cutter.Id, writer)];

        standalone[wall.Id] = [CutterId + 1];
        Assert.False(TryValidation());
        standalone.Clear();

        source.Faces.Add(Face(
            [[0, -0.5, 0], [1, -0.5, 0],
             [1, -0.5, 1], [0, -0.5, 1]]));
        Assert.False(TryValidation());
        source.Faces.RemoveAt(source.Faces.Count - 1);
    }

