        static GeometryData OrientedBox(
            double centreX, double centreY,
            double axisX, double axisY,
            double width, double depth,
            double baseZ, double height)
        {
            var geometry = BoxGeometry(
                -width / 2, -depth / 2, baseZ,
                width / 2, depth / 2, baseZ + height);
            double normalX = -axisY;
            double normalY = axisX;
            foreach (double[] point in geometry.Faces
                         .SelectMany(face => face.OuterVertices ?? []))
            {
                double along = point[0];
                double normal = point[1];
                point[0] = centreX + along * axisX + normal * normalX;
                point[1] = centreY + along * axisY + normal * normalY;
            }
            var points = geometry.Faces
                .SelectMany(face => face.OuterVertices ?? []).ToList();
            geometry.BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ];
            return geometry;
