            -46.26516139562565, 25.37227658464417,
            Diagonal, Diagonal,
            3.313648293963258, 3.6745406824115534,
            0, 6.88976377952756,
            ExactDepth: true, Boundary: primaryBoundary,
            IsExactConcordantFamilyCut: true);
        var contained = new IfcExporter.HostedOpeningGeometry(
            -46.40435564388959, 25.511470832908124,
            -Diagonal, -Diagonal,
            3.3104565141866473, 10,
            2.788713910761155, 3.280839895006709,
