            -Diagonal, -Diagonal,
            1.3779527559055111, 0.39370078740157766,
            11.040026246718835, 0.39370078740157766,
            ExactDepth: true, IsExactMappedSideShell: true);
        var mappedTwo = new IfcExporter.HostedOpeningGeometry(
            -48.65513866715366, 22.982299313113934,
            -Diagonal, -Diagonal,
            0.8202099737532862, 0.39370078740157766,
            10.82677165354297, 0.8202099737532897,
            ExactDepth: true, IsExactMappedSideShell: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [WallId] =
            [
                (PrimaryId, primary),
                (ContainedId, contained),
                (DisjointOneId, mappedOne),
                (DisjointTwoId, mappedTwo),
            ],
        };
        var standalone = new Dictionary<int, List<int>>();
        Assert.True(IfcExporter.IsExactFacetedShell(
            rebuiltFaces, Enumerable.Range(0, 12).ToList()));
        bool TryValidation() => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFifteenFaceContainedRedundantOpenings(
                wall, bounds, rebuilt, elements, inverseHosts,
                emittedCutters, emittedOperands, standalone,
                out _, out _);

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFifteenFaceContainedRedundantOpenings(
                wall, bounds, rebuilt, elements, inverseHosts,
                emittedCutters, emittedOperands, standalone,
                out var gross, out var cutterIds));
        Assert.Equal(
            [PrimaryId, ContainedId, DisjointOneId, DisjointTwoId],
            cutterIds);
        Assert.Equal(6, gross.Faces.Count);

        sourceFaces[0].AlternativeOuterVertices![1][2] = 0.1;
        Assert.False(TryValidation());
        sourceFaces[0].AlternativeOuterVertices[1][2] = 0;

        emittedOperands[WallId][1] = (
            ContainedId, contained with
            {
                IsExactFamilyCutLoopWriterBox = false,
            });
        Assert.False(TryValidation());
        emittedOperands[WallId][1] = (ContainedId, contained);

        emittedOperands[WallId][1] = (
            ContainedId, contained with
            {
                WidthFt = primary.WidthFt,
            });
        Assert.False(TryValidation());
        emittedOperands[WallId][1] = (ContainedId, contained);

        double primaryBoundaryX =
            primaryBoundary.Faces[0].OuterVertices![0][0];
        primaryBoundary.Faces[0].OuterVertices[0][0] = double.MaxValue;
        Assert.False(TryValidation());
        primaryBoundary.Faces[0].OuterVertices[0][0] = primaryBoundaryX;

        emittedOperands[WallId][2] = (
            DisjointOneId, mappedOne with
            {
                BaseZFt = 5.905511811023622,
            });
        Assert.False(TryValidation());
        emittedOperands[WallId][2] = (DisjointOneId, mappedOne);

        inverseHosts[DisjointTwoId] = [DirectHostId];
        Assert.False(TryValidation());
        inverseHosts[DisjointTwoId] = [DirectHostId, WallId];

        inverseHosts[DisjointTwoId] =
            [DirectHostId, WallId, DirectHostId];
        Assert.False(TryValidation());
        inverseHosts[DisjointTwoId] = [DirectHostId, WallId];

        disjointTwo.References = [DirectHostId, WallId];
        Assert.False(TryValidation());
        disjointTwo.References = [DirectHostId];

        disjointTwo.References = [];
        Assert.False(TryValidation());
        disjointTwo.References = [DirectHostId];

        wall.References!.Remove(DirectHostId);
        Assert.False(TryValidation());
        wall.References.Add(DirectHostId);

        const int OtherDirectHostId = 2326602;
        elements[OtherDirectHostId] = new Element
        {
            Id = OtherDirectHostId,
            CategoryId = -2000011,
            Category = "OST_Walls",
        };
        wall.References.Add(OtherDirectHostId);
        disjointTwo.HostId = OtherDirectHostId;
        disjointTwo.SerializedHostId = OtherDirectHostId;
        disjointTwo.References = [OtherDirectHostId];
        inverseHosts[DisjointTwoId] = [OtherDirectHostId, WallId];
        Assert.False(TryValidation());
        disjointTwo.HostId = DirectHostId;
        disjointTwo.SerializedHostId = DirectHostId;
        disjointTwo.References = [DirectHostId];
        inverseHosts[DisjointTwoId] = [DirectHostId, WallId];
        wall.References.Remove(OtherDirectHostId);
        elements.Remove(OtherDirectHostId);

        standalone[WallId] = [PrimaryId];
        Assert.False(TryValidation());
        standalone.Clear();
    }

    [Fact]
    public void CompleteOpenThirteenFaceDualAlternativeBottomCoincidentOpening_RequiresExactSourceAndSixHostFamilyBrepGraph()
    {
        const int WallId = 9309756;
        const int CutterId = 4299482;
