        const int PeerFourId = 9323810;

        static GeoFace EndFace(double along) => Face(
        [
            [along, -0.5, 0], [along, 0.5, 0],
            [along, 0.5, 6], [along, -0.5, 6],
        ]);
        static GeoFace SideFace(
            double minimumAlong, double maximumAlong, double normal) => Face(
        [
            [minimumAlong, normal, 0], [maximumAlong, normal, 0],
            [maximumAlong, normal, 6], [minimumAlong, normal, 6],
        ]);

        var sourceFaces = new List<GeoFace>
        {
            SideFace(6.75, 10, 0.5),
            Face([[6.75, -0.5, 0], [10, -0.5, 0],
                [10, 0.5, 0], [6.75, 0.5, 0]]),
            SideFace(6.75, 10, -0.5),
            EndFace(0.1),
            Face([[6.75, -0.5, 6], [6.75, 0.5, 6],
                [10, 0.5, 6], [10, -0.5, 6]]),
            EndFace(0.2),
            EndFace(0),
            EndFace(10),
            SideFace(2, 3, -0.5),
            EndFace(3.25),
            SideFace(1, 2, 0.5),
            EndFace(6.75),
            Face([[3.25, -0.5, 0], [6.75, -0.5, 0],
                [6.75, 0.5, 0], [3.25, 0.5, 0]]),
        };
        sourceFaces[1].AlternativeOuterVertices =
        [
            [10, 0.5, 0], [0, 0.5, 0], [0, -0.5, 0],
            [10, -0.5, 0], [3.25, -0.5, 0], [3.25, 0.5, 0],
        ];
        sourceFaces[2].AlternativeOuterVertices =
        [
            [0, -0.5, 0], [10, -0.5, 0], [3.25, -0.5, 0],
            [3.25, -0.5, 6], [6.75, -0.5, 6], [1, -0.5, 6],
            [10, -0.5, 6], [0, -0.5, 6],
        ];
        double[] bounds = [0, -0.5, 0, 10, 0.5, 6];
        var source = new GeometryData
        {
            BoundingBox = (double[])bounds.Clone(),
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 13).ToList(),
                    IsClosed = false,
                },
            ],
        };

        var lowProfile = sourceFaces[2].AlternativeOuterVertices!;
        var highProfile = lowProfile.Select(point =>
            new[] { point[0], 0.5, point[2] }).ToList();
        var rebuiltFaces = new List<GeoFace>
        {
            Face(lowProfile),
            Face(highProfile.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < lowProfile.Count; index++)
        {
            int next = (index + 1) % lowProfile.Count;
            rebuiltFaces.Add(Face(
            [
                lowProfile[index], highProfile[index],
                highProfile[next], lowProfile[next],
            ]));
        }
        var rebuilt = new GeometryData
        {
            BoundingBox = (double[])bounds.Clone(),
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 10).ToList(),
                    IsClosed = true,
                },
            ],
        };

        var wall = new Element
        {
            Id = WallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 6.0,
                },
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [1, 0, 0],
                EndPoint = [10, 0, 0],
            },
            BoundingBox = (double[])bounds.Clone(),
            Geometry = source,
            References = [CutterId],
        };
        Element Host(int id) => new()
        {
            Id = id,
            CategoryId = -2000011,
            Category = "OST_Walls",
            References = [CutterId],
        };
        var directHost = Host(DirectHostId);
        var peerOne = Host(PeerOneId);
        var peerTwo = Host(PeerTwoId);
        var peerThree = Host(PeerThreeId);
        var peerFour = Host(PeerFourId);
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = DirectHostId,
            SerializedHostId = DirectHostId,
            ExtraHostIds = [],
            ExplicitHostIds = [],
            BoundingBox = [3.25, -1, 0, 6.75, 1, 7],
            References = [DirectHostId],
        };
        int[] hostIds =
        [
            DirectHostId, PeerOneId, WallId,
            PeerTwoId, PeerThreeId, PeerFourId,
        ];
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
            [directHost.Id] = directHost,
            [peerOne.Id] = peerOne,
            [peerTwo.Id] = peerTwo,
            [peerThree.Id] = peerThree,
            [peerFour.Id] = peerFour,
        };
        var visibleWallIds = hostIds.ToHashSet();
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [CutterId] = hostIds.ToList(),
        };
        var emittedCutters = hostIds.ToDictionary(
            hostId => hostId, _ => new List<int> { CutterId });
        var openingBoundary = BoxGeometry(
            3.25, -1, 0, 6.75, 1, 7);
        var exactOperand = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 3.5, DepthFt: 2,
            BaseZFt: 0, HeightFt: 7,
            ExactDepth: true, Boundary: openingBoundary,
            IsExactConcordantFamilyCut: true);
        var emittedOperands = hostIds.ToDictionary(
            hostId => hostId,
            _ => new List<(int CutterId,
                IfcExporter.HostedOpeningGeometry Operand)>
            {
                (CutterId, exactOperand),
            });
        var standalone = new Dictionary<int, List<int>>();
        var exactPairs = hostIds
            .Select(hostId => (WallId: hostId, CutterId))
            .ToHashSet();

        bool TryValidation() => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenThirteenFaceDualAlternativeBottomCoincidentFamilyOpening(
                wall, bounds, rebuilt, elements, visibleWallIds,
                inverseHosts, emittedCutters, emittedOperands,
                standalone, exactPairs, out _, out _);

        Assert.True(IfcExporter.IsExactFacetedShell(
            rebuiltFaces, Enumerable.Range(0, 10).ToList()));
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenThirteenFaceDualAlternativeBottomCoincidentFamilyOpening(
                wall, bounds, rebuilt, elements, visibleWallIds,
                inverseHosts, emittedCutters, emittedOperands,
                standalone, exactPairs,
                out var gross, out var cutterIds));
        Assert.Equal([CutterId], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, gross));
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                gross, wall.Location, 1, bounds,
                out var grossPlan, out _, out _, out string grossReason),
            grossReason);
        Assert.Equal("exact", grossReason);
        Assert.Equal(9, wall.Location.EndPoint[0]
            - wall.Location.StartPoint[0], 12);
        Assert.Equal(10, grossPlan.Max(point => point[0])
            - grossPlan.Min(point => point[0]), 12);

        object? validWidth = wall.Parameters[0].Value;
        wall.Parameters[0].Value = double.MaxValue;
        Assert.False(TryValidation());
        wall.Parameters[0].Value = validWidth;

        double validPrimaryCoordinate =
            sourceFaces[3].OuterVertices![0][0];
        sourceFaces[3].OuterVertices![0][0] = double.NaN;
        Assert.False(TryValidation());
        sourceFaces[3].OuterVertices![0][0] = validPrimaryCoordinate;

        double validAlternativeCoordinate =
            sourceFaces[2].AlternativeOuterVertices![5][0];
        sourceFaces[2].AlternativeOuterVertices![5][0] = 1.25;
        Assert.False(TryValidation());
        sourceFaces[2].AlternativeOuterVertices![5][0] =
            validAlternativeCoordinate;

        var connector = rebuiltFaces[2].OuterVertices!;
        (connector[1], connector[2]) = (connector[2], connector[1]);
        Assert.False(TryValidation());
        (connector[1], connector[2]) = (connector[2], connector[1]);

        inverseHosts[CutterId].Remove(PeerFourId);
        Assert.False(TryValidation());
        inverseHosts[CutterId].Add(PeerFourId);

        const int SeventhHostId = 9309761;
        emittedCutters[SeventhHostId] = [CutterId];
        Assert.False(TryValidation());
        emittedCutters.Remove(SeventhHostId);

        emittedOperands[SeventhHostId] = [(CutterId, exactOperand)];
        Assert.False(TryValidation());
        emittedOperands.Remove(SeventhHostId);

        exactPairs.Add((SeventhHostId, CutterId));
        Assert.False(TryValidation());
        exactPairs.Remove((SeventhHostId, CutterId));

        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenThirteenFaceDualAlternativeBottomCoincidentFamilyOpening(
                wall, bounds, rebuilt, elements, visibleWallIds,
                inverseHosts, emittedCutters, emittedOperands,
                null, exactPairs, out _, out _));

        exactPairs.Remove((PeerThreeId, CutterId));
        Assert.False(TryValidation());
        exactPairs.Add((PeerThreeId, CutterId));

        emittedOperands[PeerOneId] =
        [
            (CutterId, exactOperand with { CentreXFt = 5.25 }),
        ];
        Assert.False(TryValidation());
        emittedOperands[PeerOneId] = [(CutterId, exactOperand)];

        emittedOperands[WallId] =
        [
            (CutterId, exactOperand with
            {
                IsExactConcordantFamilyCut = false,
            }),
        ];
        Assert.False(TryValidation());
        emittedOperands[WallId] = [(CutterId, exactOperand)];

        var unsafeOpeningBoundary = BoxGeometry(
            3.25, -1, 0, 6.75, 1, 7);
        unsafeOpeningBoundary.Faces![0].OuterVertices![0][0] =
            double.MaxValue;
        emittedOperands[WallId] =
        [
            (CutterId, exactOperand with
            {
                Boundary = unsafeOpeningBoundary,
            }),
        ];
        Assert.False(TryValidation());
        emittedOperands[WallId] = [(CutterId, exactOperand)];

        cutter.SerializedHostId = PeerOneId;
        Assert.False(TryValidation());
        cutter.SerializedHostId = DirectHostId;

        cutter.References!.Add(WallId);
        Assert.False(TryValidation());
        cutter.References.RemoveAt(cutter.References.Count - 1);

        var capCoincidentBoundary = BoxGeometry(
            3.25, -1, 0, 6.75, 1, 6);
        var capCoincidentOperand = exactOperand with
        {
            HeightFt = 6,
            Boundary = capCoincidentBoundary,
        };
        foreach (int hostId in hostIds)
            emittedOperands[hostId] =
                [(CutterId, capCoincidentOperand)];
        Assert.False(TryValidation());
        foreach (int hostId in hostIds)
            emittedOperands[hostId] = [(CutterId, exactOperand)];

        peerTwo.References!.Add(CutterId);
        Assert.False(TryValidation());
        peerTwo.References.RemoveAt(peerTwo.References.Count - 1);

        standalone[PeerFourId] = [CutterId];
        Assert.False(TryValidation());
        standalone.Clear();

        GeoFace removedSourceFace = sourceFaces[12];
        sourceFaces.RemoveAt(12);
        source.BrepSolids![0].FaceIndices.RemoveAt(12);
        Assert.False(TryValidation());
        sourceFaces.Add(removedSourceFace);
        source.BrepSolids[0].FaceIndices.Add(12);
    }

