                [11.85, MinimumNormal, WallHeight],
                [14.1, MinimumNormal, WallHeight],
                [14.1, MaximumNormal, WallHeight]),
            Quad([14.1, MaximumNormal, WallHeight],
                [14.1, MinimumNormal, WallHeight],
                [14.4, MinimumNormal, WallHeight],
                [14.4, MaximumNormal, WallHeight]),
            Quad([14.4, MaximumNormal, WallHeight],
                [14.4, MinimumNormal, WallHeight],
                [0, MinimumNormal, WallHeight],
                [0, MaximumNormal, WallHeight]),
            Quad([0, MaximumNormal, WallHeight],
                [0, MinimumNormal, WallHeight], [0, MinimumNormal, 0],
                [0, MaximumNormal, 0]),
            Quad([0, MaximumNormal, 0], [0, MinimumNormal, 0],
                [14.4, MinimumNormal, 0], [14.4, MaximumNormal, 0]),
            Quad([14.4, MaximumNormal, 0], [14.4, MinimumNormal, 0],
                [3.75, MinimumNormal, 0], [3.75, MaximumNormal, 0]),
        };
        foreach (var face in sourceFaces.Concat(rebuiltFaces))
        {
            foreach (var point in face.OuterVertices!) point[1] = -point[1];
            foreach (var point in face.AlternativeOuterVertices
                         ?? Enumerable.Empty<double[]>())
                point[1] = -point[1];
        }
        var rebuilt = new GeometryData
        {
            BoundingBox = (double[])bounds.Clone(),
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 10).ToList(),
                    IsClosed = true,
                },
            ],
