        int[] inverseHostIds = [.. forwardHostIds, .. inverseOnlyHostIds];
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = DirectHostId,
            SerializedHostId = DirectHostId,
            ExtraHostIds = [WallId, .. otherForwardHostIds],
            ExplicitHostIds = [],
