                    out _));
        Assert.True(
            IfcExporter.TryGetExactVerticalRectangularWallPlan(
                verifiedWriterPrecisionSingleSubdivision, wall.Location, 1,
                verifiedWriterPrecisionSingleSubdivision.BoundingBox!,
                out var writerPrecisionRectangle));
        Assert.Equal(4, writerPrecisionRectangle.Count);
        exactFamilyPairs.Clear();
        emittedOperands[wall.Id] = [(cutterId, operand)];

        int disjointCutterId = cutterId + 1;
        var disjointAdditionalOperand = operand with
        {
            CentreYFt = 3,
            WidthFt = 2,
            IsExactSerializedDefinition = true,
        };
        emittedCutterIds[wall.Id] = [cutterId, disjointCutterId];
        emittedOperands[wall.Id] =
        [
            (cutterId, operand),
            (disjointCutterId, disjointAdditionalOperand),
        ];
        wall.CuttingElementIds = [cutterId, disjointCutterId];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpeningWithRobustlyDisjointAdditionalOperand(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements, emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out var verifiedWithDisjoint,
                    out var verifiedWithDisjointCutterIds));
        Assert.Equal([cutterId, disjointCutterId],
            verifiedWithDisjointCutterIds);
        Assert.Equal(6, verifiedWithDisjoint.Faces.Count);

        int secondDisjointCutterId = disjointCutterId + 1;
        var secondDisjointAdditionalOperand =
            disjointAdditionalOperand with { CentreYFt = -3 };
        emittedCutterIds[wall.Id] =
            [cutterId, disjointCutterId, secondDisjointCutterId];
        emittedOperands[wall.Id] =
        [
            (cutterId, operand),
            (disjointCutterId, disjointAdditionalOperand),
            (secondDisjointCutterId, secondDisjointAdditionalOperand),
        ];
        wall.CuttingElementIds =
            [cutterId, disjointCutterId, secondDisjointCutterId];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpeningWithRobustlyDisjointAdditionalOperand(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements, emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out var verifiedWithTwoDisjoint,
                    out var verifiedWithTwoDisjointCutterIds));
        Assert.Equal(
            [cutterId, disjointCutterId, secondDisjointCutterId],
            verifiedWithTwoDisjointCutterIds);
        Assert.Equal(6, verifiedWithTwoDisjoint.Faces.Count);

        emittedOperands[wall.Id][2] = (
            secondDisjointCutterId,
            secondDisjointAdditionalOperand with { CentreYFt = 0 });
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpeningWithRobustlyDisjointAdditionalOperand(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements, emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out _, out _));

        emittedCutterIds[wall.Id] = [cutterId, disjointCutterId];
        emittedOperands[wall.Id] =
        [
            (cutterId, operand),
            (disjointCutterId, disjointAdditionalOperand),
        ];
        wall.CuttingElementIds = [cutterId, disjointCutterId];
        emittedOperands[wall.Id][1] = (
            disjointCutterId,
            disjointAdditionalOperand with { CentreYFt = 0 });
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpeningWithRobustlyDisjointAdditionalOperand(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements, emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out _, out _));
        wall.CuttingElementIds = [cutterId, disjointCutterId + 1];
        emittedOperands[wall.Id][1] =
            (disjointCutterId, disjointAdditionalOperand);
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpeningWithRobustlyDisjointAdditionalOperand(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements, emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out _, out _));

        wall.CuttingElementIds = [];
        emittedCutterIds[wall.Id] = [cutterId];
        var unconfirmedOperand = operand with
        {
            IsExactSerializedDefinition = false,
        };
        emittedOperands[wall.Id] = [(cutterId, unconfirmedOperand)];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpening(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements,
                    emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out _, out _));

        var writerPrecisionCapOperand = unconfirmedOperand with
        {
            BaseZFt = 0.5,
            HeightFt = 2.5 - 0.000002 / 0.3048,
        };
        emittedOperands[wall.Id] =
            [(cutterId, writerPrecisionCapOperand)];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpening(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements,
                    emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out _, out _));
        emittedOperands[wall.Id] =
        [
            (cutterId, writerPrecisionCapOperand with
            {
                HeightFt = 2.5 - 0.000006 / 0.3048,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpening(
                    wall, wall.BoundingBox, splitMinimumCapShell,
                    elements,
                    emittedCutterIds, emittedOperands,
                    standaloneOpeningIds, exactSourceOpenings,
                    exactFamilyPairs, out _, out _));

        var perpendicularOperand = operand with
        {
            AxisX = 0,
            AxisY = 1,
            WidthFt = 2,
            DepthFt = 4,
            BaseZFt = 0.5,
            HeightFt = 2,
