        [
            (alternativeGrossFace[0][0] + alternativeGrossFace[1][0]) / 2,
            (alternativeGrossFace[0][1] + alternativeGrossFace[1][1]) / 2,
            (alternativeGrossFace[0][2] + alternativeGrossFace[1][2]) / 2,
        ]);
        openSourceJoined.Faces![0].AlternativeOuterVertices =
            alternativeGrossFace;
        Assert.True(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, joined,
                emittedCutterIds, standaloneOpeningIds, out _));
        alternativeGrossFace[1][2] += 0.125;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, joined,
                emittedCutterIds, standaloneOpeningIds, out _));
        var primaryGrossFace = exact.Faces[0].OuterVertices!
            .Select(point => (double[])point.Clone()).ToList();
        primaryGrossFace.Insert(1,
        [
            (primaryGrossFace[0][0] + primaryGrossFace[1][0]) / 2,
            (primaryGrossFace[0][1] + primaryGrossFace[1][1]) / 2,
            (primaryGrossFace[0][2] + primaryGrossFace[1][2]) / 2,
        ]);
        var exteriorAlternative = exact.Faces[0].OuterVertices!
            .Select(point => new[] { point[0] + 10, point[1], point[2] })
            .ToList();
        openSourceJoined.Faces[0].OuterVertices = primaryGrossFace;
        openSourceJoined.Faces[0].AlternativeOuterVertices =
            exteriorAlternative;
        Assert.True(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, joined,
                emittedCutterIds, standaloneOpeningIds, out _));
        openSourceJoined.Faces[0].AlternativeOuterVertices =
        [
            [1, -0.25, 1], [2, -0.25, 1],
            [2, 0.25, 1], [1, 0.25, 1],
        ];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, joined,
                emittedCutterIds, standaloneOpeningIds, out _));
        openSourceJoined.Faces[0].AlternativeOuterVertices = null;

        var bothEndsJoined = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 3), (5.5, 3),
            (5.5, 0.25), (0.5, 0.25), (0.5, 3), (0, 3),
        ], -0.5, 0.5);
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                bothEndsJoined, wall.Location, 1, wall.BoundingBox,
                out _, out rejectionReason),
            rejectionReason);
        var shiftedInvariantJoin = ExtrudedSideProfileWallGeometry(
        [
            (0.08, 0), (6, 0), (6, 3), (0.08, 3),
            (0.08, 2.9), (0, 2.9), (0, 2.74), (0.08, 2.74),
        ], -0.5, 0.5);
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                shiftedInvariantJoin,
                new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [0.08, 0, 0],
                    EndPoint = [6, 0, 0],
                },
                1, [0.08, -0.5, 0, 6, 0.5, 3],
                out _, out rejectionReason),
            rejectionReason);

        emittedCutterIds[wall.Id] = [1896];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, joined,
                emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        openSourceJoined.BrepSolids[0].FaceIndices.RemoveAt(
            openSourceJoined.BrepSolids[0].FaceIndices.Count - 1);
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, joined,
                emittedCutterIds, standaloneOpeningIds, out _));
        openSourceJoined.BrepSolids[0].FaceIndices.Add(9);

        var interiorCapSlot = HorizontalCapSlottedWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            slotMinimumAlong: 2, slotMaximumAlong: 4,
            slotBoundaryZ: 2, slotTouchesMaximumZ: true);
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                interiorCapSlot, wall.Location, 1, wall.BoundingBox,
                out _, out rejectionReason),
            rejectionReason);
        emittedCutterIds[wall.Id] = [1896];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, interiorCapSlot,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

    [Fact]
    public void PairedFiveLevelMinimumCapJoinValidation_RequiresExactExteriorSourceAuthority()
    {
        static GeoFace CloneFace(GeoFace face) => new()
        {
            OuterVertices = face.OuterVertices!
                .Select(point => (double[])point.Clone()).ToList(),
        };
        static GeoFace ExteriorFace(int index, int count)
        {
            double start = 0.2 + index * 0.01;
            List<double[]> ring = count switch
            {
                3 =>
                [
                    [start, -1, 0.5], [start + 0.2, -1, 0.5],
                    [start + 0.1, -1, 2],
                ],
                _ =>
                [
                    [start, -1, 0.5], [start + 0.2, -1, 0.5],
                    [start + 0.2, -1, 2], [start, -1, 2],
                ],
            };
            if (index is 19 or 20)
            {
                ring =
                [
                    [start, -1, 0.5], [start + 0.2, -1, 0.5],
                    [start + 0.1, -1, 2], [start, -1, 0.5],
                ];
            }
            if (index == 7)
                foreach (double[] point in ring) point[1] = 1;
            if (index == 15)
                ring =
                [
                    [-1, -0.2, 0.5], [-1, 0.2, 0.5],
                    [-1, 0.2, 2], [-1, -0.2, 2],
                ];
            return Face(ring);
        }
        static List<GeoFace> ExteriorPrismFaces(
            IReadOnlyList<double[]> contact, double exteriorNormal,
            double openAlong)
        {
            var exterior = contact.Select(point =>
                new[] { point[0], exteriorNormal, point[2] }).ToList();
            var faces = new List<GeoFace>
            {
                Face(contact.Select(point => (double[])point.Clone()).ToList()),
                Face(exterior),
            };
            foreach (int index in Enumerable.Range(0, contact.Count))
            {
                int next = (index + 1) % contact.Count;
                if (contact[index][0] == openAlong
                    && contact[next][0] == openAlong)
                    continue;
                faces.Add(Face(
                [
                    (double[])contact[index].Clone(),
                    (double[])contact[next].Clone(),
                    (double[])exterior[next].Clone(),
                    (double[])exterior[index].Clone(),
                ]));
            }
            return faces;
        }

        var wall = new Element
        {
            Id = 18945,
            TypeId = 18946,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var rebuilt = PairedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 3), (0, 3),
            (0, 2.5), (5.5, 2.5), (5.5, 0.25), (0, 0.25),
        ],
        [
            (0, 0), (6, 0), (6, 0.25), (0.5, 0.25),
            (0.5, 2.4), (6, 2.4), (6, 3), (0, 3),
        ], -0.5, 0.5);
        Assert.False(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                rebuilt, wall.Location, 1, wall.BoundingBox,
                out _, out _));
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                rebuilt, wall.Location, 1, wall.BoundingBox,
                out var exact, out string exactReason,
                requireExactPairedFiveLevelSideProfiles: true), exactReason);

        var minimumCap = exact.Faces.Single(face =>
            face.OuterVertices!.All(point => point[2] == 0));
        var maximumCap = exact.Faces.Single(face =>
            face.OuterVertices!.All(point => point[2] == 3));
        var maximumEnd = exact.Faces.Single(face =>
            face.OuterVertices!.All(point => point[0] == 6));
        var minimumEnd = exact.Faces.Single(face =>
            face.OuterVertices!.All(point => point[0] == 0));
        var sourceFaces = Enumerable.Range(0, 23)
            .Select(index => ExteriorFace(index, index is 16 or 17 ? 3 : 4))
            .ToList();
        sourceFaces[0] = CloneFace(rebuilt.Faces[0]);
        sourceFaces[1] = CloneFace(minimumCap);
        sourceFaces[2] = CloneFace(rebuilt.Faces[1]);
        sourceFaces[3] = CloneFace(maximumEnd);
        sourceFaces[4] = CloneFace(maximumCap);
        sourceFaces[5].AlternativeOuterVertices = minimumEnd.OuterVertices!
            .Select(point => (double[])point.Clone()).ToList();
        List<double[]> firstContact =
        [
            [0, -0.5, 2.5], [5.5, -0.5, 2.5],
            [5.5, -0.5, 0.25], [0, -0.5, 0.25],
        ];
        List<double[]> secondContact =
        [
            [6, 0.5, 0.25], [0.5, 0.5, 0.25],
            [0.5, 0.5, 2.4], [6, 0.5, 2.4],
        ];
        var firstExteriorPrism = ExteriorPrismFaces(firstContact, -1, 0);
        var secondExteriorPrism = ExteriorPrismFaces(secondContact, 1, 6);
        foreach (int index in Enumerable.Range(0, 5))
            sourceFaces[6 + index] = firstExteriorPrism[index];
        foreach (int index in Enumerable.Range(0, 4))
            sourceFaces[11 + index] = secondExteriorPrism[index];
        sourceFaces[22] = secondExteriorPrism[4];
        wall.Geometry = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 23).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out var verified));
        Assert.Equal(6, verified.Faces.Count);

        double[] originalExteriorPoint =
            (double[])sourceFaces[6].OuterVertices![0].Clone();
        sourceFaces[6].OuterVertices[0] = [3, 0, 1];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[6].OuterVertices[0] = originalExteriorPoint;

        sourceFaces[1].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[1].OuterVertices[0][0] -= 0.125;

        sourceFaces[5].AlternativeOuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[5].AlternativeOuterVertices[0][0] -= 0.125;

        emittedCutterIds[wall.Id] = [wall.Id + 1];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        wall.Geometry.BrepSolids![0].FaceIndices[22] = 21;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

    [Fact]
    public void ClosedMinimumCapJoinShellValidation_RecoversExactJoinedTrapezoidWithExteriorPrism()
    {
        var wall = new Element
        {
            Id = 18946,
            TypeId = 18947,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [2, 0.5, 0],
                EndPoint = [10, 0.5, 0],
            },
            BoundingBox = [0, 0, 0, 10, 1, 3],
        };
        var rebuilt = PairedSideProfileWallGeometry(
        [
            (10, 0), (1, 0), (1, 3), (4, 3),
            (4, 1), (9, 1), (9, 3), (10, 3),
        ],
        [
            (10, 0), (0, 0), (0, 3), (4, 3),
            (4, 1), (9, 1), (9, 3), (10, 3),
        ], 0, 1);
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                rebuilt, wall.Location, 1, wall.BoundingBox,
                out _, out string rebuiltReason), rebuiltReason);

        var sourceFaces = new List<GeoFace>
        {
            Face([[1, 0, 0], [1, 0, 3], [10, 0, 3], [10, 0, 0]]),
            Face([[1, 0, 0], [0, 1, 0], [10, 1, 0], [10, 0, 0]]),
            Face(
            [
                [10, 1, 0], [0, 1, 0], [0, 1, 3], [4, 1, 3],
                [4, 1, 1], [9, 1, 1], [9, 1, 3], [10, 1, 3],
            ]),
            Face([[10, 0, 0], [10, 1, 0], [10, 1, 3], [10, 0, 3]]),
            Face([[10, 0, 3], [10, 1, 3], [0, 1, 3], [1, 0, 3]]),
            Face([[2, 0, 3], [2, 1, 3], [2, 1, 0], [2, 0, 0]]),
            Face([[1, 0, 0], [1, 0, 3], [0, 1, 3], [0, 1, 0]]),
            Face([[4, 1, 1], [4, 1, 3], [9, 1, 3], [9, 1, 1]]),
            Face([[4, 1, 1], [3.5, 2, 1], [9, 2, 1], [9, 1, 1]]),
            Face([[9, 1, 1], [9, 2, 1], [9, 2, 3], [9, 1, 3]]),
            Face([[9, 1, 3], [9, 2, 3], [3.5, 2, 3], [4, 1, 3]]),
            Face([[4, 1, 3], [3.5, 2, 3], [3.5, 2, 1], [4, 1, 1]]),
            Face([[3.5, 2, 1], [3.5, 2, 3], [9, 2, 3], [9, 2, 1]]),
        };
        wall.Geometry = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 13).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds,
                out var verified));
        Assert.Equal(7, verified.Faces.Count);
        Assert.True(
            IfcExporter.TryGetExactBoundaryOwnedArbitraryVerticalExtrusionDefinition(
                verified, wall.Location, 1, wall.BoundingBox,
                out var plan, out double baseZ, out double height));
        Assert.Equal(5, plan.Count);
        Assert.Contains(plan, point => point.SequenceEqual([3.0, 1.0]));
        Assert.Equal(0, baseZ);
        Assert.Equal(3, height);

        emittedCutterIds[wall.Id] = [wall.Id + 1];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        sourceFaces[5].OuterVertices![0][0] = 2.25;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[5].OuterVertices[0][0] = 2;

        sourceFaces[12].OuterVertices![0][1] = 0.75;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[12].OuterVertices[0][1] = 2;

        sourceFaces[1].OuterVertices![0][0] = 1.25;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[1].OuterVertices[0][0] = 1;

        wall.Geometry.BrepSolids![0].FaceIndices[0] = 1;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

