            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0.5, 0],
                EndPoint = [10, 0.5, 0],
            },
            BoundingBox = [0, 0, 0, 10, 1, 3],
        };
        List<double[]> firstSide =
        [
            [0, 0, 1], [2, 0, 1], [4, 0, 1], [6, 0, 1],
            [8, 0, 1], [8, 0, 3], [10, 0, 3],
            [10, 0, 0], [0, 0, 0],
        ];
        var secondSide = firstSide.Select(point =>
            new[] { point[0], 1.0, point[2] }).ToList();
        var rebuiltFaces = new List<GeoFace>
        {
            Face(firstSide),
            Face(secondSide.AsEnumerable().Reverse().ToList()),
        };
        for (int index = 0; index < firstSide.Count; index++)
        {
            int next = (index + 1) % firstSide.Count;
            rebuiltFaces.Add(Face(
            [
                firstSide[next], firstSide[index],
                secondSide[index], secondSide[next],
            ]));
        }
        var rebuilt = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 11).ToList(),
                    IsClosed = true,
                },
            ],
        };
        Assert.False(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                rebuilt, wall.Location, 1, wall.BoundingBox,
                out _, out _));
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                rebuilt, wall.Location, 1, wall.BoundingBox,
                out _, out string rebuiltReason,
                requireExactNinePointSideProfiles: true), rebuiltReason);

        var sourceFaces = new List<GeoFace>
        {
            Face([[2, 1, 1], [2, 1, 3], [4, 1, 3], [4, 1, 1]]),
            Face([[0, 0, 0], [10, 0, 0], [10, 1, 0], [0, 1, 0]]),
            Face(
            [
                [0, 0, 0], [10, 0, 0], [10, 0, 3],
                [9, 0, 3], [9, 0, 1], [7, 0, 1],
                [5, 0, 1], [3, 0, 1], [0, 0, 1],
            ]),
            Face([[0, 1, 3], [10, 1, 3], [10, 0, 3], [0, 0, 3]]),
            Face([[10, 0, 0], [10, 0, 1], [10, 1, 1], [10, 1, 0]]),
            Face([[0, 0, 0], [0, 1, 0], [0, 1, 3], [0, 0, 3]]),
        };
        for (int index = 6; index < 34; index++)
        {
            double firstX = 1 + (index - 6) * 0.2;
            double secondX = firstX + 0.1;
            sourceFaces.Add(Face(
            [
                [firstX, 2, 1], [secondX, 2, 1],
                [secondX, 2, 3], [firstX, 2, 3],
            ]));
        }
        wall.Geometry = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 34).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds,
                out var verified));
        Assert.Equal(6, verified.Faces.Count);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                verified, wall.Location, 1, verified.BoundingBox!,
                out var plan, out double baseZ, out double height,
                out string reason), reason);
        Assert.Equal("exact", reason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(0, baseZ);
        Assert.Equal(3, height);

        emittedCutterIds[wall.Id] = [wall.Id + 1];
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        sourceFaces[2].OuterVertices![4][1] = 0.25;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[2].OuterVertices[4][1] = 0;

        foreach (double[] point in sourceFaces[6].OuterVertices!)
            point[1] = 0.5;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        foreach (double[] point in sourceFaces[6].OuterVertices!)
            point[1] = 2;

        sourceFaces[1].OuterVertices![0][0] = 0.25;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[1].OuterVertices[0][0] = 0;

        wall.Geometry.BrepSolids![0].FaceIndices[0] = 1;
        Assert.False(
            IfcExporter.TryGetVerifiedWallBoundaryFromClosedMinimumCapJoinShellWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

