    [Fact]
    public void DualExteriorJoinPrismValidation_RequiresTwoExactOppositeExteriorContacts()
    {
        static GeoFace CloneFace(GeoFace face) => new()
        {
            OuterVertices = face.OuterVertices?
                .Select(point => (double[])point.Clone()).ToList(),
            InnerVertices = face.InnerVertices?.Select(ring =>
                ring.Select(point => (double[])point.Clone()).ToList()).ToList(),
            AlternativeOuterVertices = face.AlternativeOuterVertices?
                .Select(point => (double[])point.Clone()).ToList(),
        };

        var wall = new Element
        {
            Id = 1897,
            TypeId = 1898,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var nominal = BoxGeometry(0, -0.5, 0, 6, 0.5, 3);
        var minimumExterior = BoxGeometry(1, -0.6, 0.25, 5, -0.5, 2.75);
        var maximumExterior = BoxGeometry(2, 0.5, 0.25, 5.5, 0.6, 2.75);
        var sourceFaces = new[] { 2, 0, 4, 3, 1, 5 }
            .Select(index => CloneFace(nominal.Faces[index])).ToList();
        sourceFaces[0].InnerVertices =
        [
            minimumExterior.Faces[4].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList(),
        ];
        sourceFaces[2].InnerVertices =
        [
            maximumExterior.Faces[2].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList(),
        ];
        sourceFaces.AddRange(minimumExterior.Faces.Select(CloneFace));
        sourceFaces.AddRange(maximumExterior.Faces.Select(CloneFace));
        wall.Geometry = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, sourceFaces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var rebuiltFaces = sourceFaces.Take(6).Select(CloneFace).ToList();
        rebuiltFaces.AddRange(sourceFaces.Skip(6).Take(4).Select(CloneFace));
        var rebuilt = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, rebuiltFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out var gross));
        Assert.Equal(6, gross.Faces.Count);
        Assert.Equal(wall.BoundingBox, gross.BoundingBox);

        var threeFaceJoinFragment = new List<GeoFace>
        {
            Face(
            [
                [6, -0.4, 0.5], [6.25, -0.4, 0.5],
                [6.25, 0.4, 0.5], [6, 0.4, 0.5],
            ]),
            Face(
            [
                [6, -0.4, 2.5], [6, 0.4, 2.5],
                [6.25, 0.4, 2.5], [6.25, -0.4, 2.5],
            ]),
            Face(
            [
                [6.25, -0.4, 0.5], [6.25, -0.4, 2.5],
                [6.25, 0.4, 2.5], [6.25, 0.4, 0.5],
            ]),
        };
        sourceFaces.InsertRange(12, threeFaceJoinFragment);
        wall.Geometry.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, sourceFaces.Count).ToList();
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out var extendedGross));
        Assert.Equal(gross.BoundingBox, extendedGross.BoundingBox);

        foreach (var face in threeFaceJoinFragment)
            foreach (var point in face.OuterVertices!)
                if (point[0] == 6.25) point[0] = 5.75;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        foreach (var face in threeFaceJoinFragment)
            foreach (var point in face.OuterVertices!)
                if (point[0] == 5.75) point[0] = 6.25;

        wall.Geometry.BrepSolids[0].FaceIndices[^1]--;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        wall.Geometry.BrepSolids[0].FaceIndices[^1]++;
        sourceFaces.RemoveRange(12, threeFaceJoinFragment.Count);
        wall.Geometry.BrepSolids[0].FaceIndices =
            Enumerable.Range(0, sourceFaces.Count).ToList();

        foreach (var face in sourceFaces.Skip(6).Take(6))
            foreach (var point in face.OuterVertices!)
                if (point[1] == -0.6) point[1] = -0.4;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        foreach (var face in sourceFaces.Skip(6).Take(6))
            foreach (var point in face.OuterVertices!)
                if (point[1] == -0.4) point[1] = -0.6;

        emittedCutterIds[wall.Id] = [1899];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        emittedCutterIds.Clear();

        wall.Geometry.BrepSolids![0].IsClosed = true;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        wall.Geometry.BrepSolids[0].IsClosed = false;

        rebuilt.Faces[0].InnerVertices![0][0][0] += 0.25;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

    [Fact]
    public void ExteriorJoinNetworkValidation_RequiresExactExternalSourceAuthority()
    {
        static GeoFace CloneFace(GeoFace face) => new()
        {
            OuterVertices = face.OuterVertices?
                .Select(point => (double[])point.Clone()).ToList(),
            InnerVertices = face.InnerVertices?.Select(ring =>
                ring.Select(point => (double[])point.Clone()).ToList()).ToList(),
            AlternativeOuterVertices = face.AlternativeOuterVertices?
                .Select(point => (double[])point.Clone()).ToList(),
        };

        var wall = new Element
        {
            Id = 1899,
            TypeId = 1900,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var nominal = BoxGeometry(0, -0.5, 0, 6, 0.5, 3);
        var minimumExterior = BoxGeometry(1, -0.75, 0.25, 5, -0.5, 2.75);
        var maximumExterior = BoxGeometry(1, 0.5, 0.25, 5, 0.75, 2.75);
        var grossFaces = new[] { 2, 0, 4, 3, 1, 5 }
            .Select(index => CloneFace(nominal.Faces[index])).ToList();
        grossFaces[0].InnerVertices =
        [
            minimumExterior.Faces[4].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList(),
        ];
        grossFaces[2].InnerVertices =
        [
            maximumExterior.Faces[2].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList(),
        ];
        var sourceFaces = grossFaces.Take(3).Select(CloneFace).ToList();
        sourceFaces.Add(Face(
        [
            [3, -0.5, 0], [3, 0.5, 0],
            [3, 0.5, 3], [3, -0.5, 3],
        ]));
        sourceFaces.AddRange(grossFaces.Skip(3).Select(CloneFace));
        sourceFaces.AddRange(Enumerable.Range(0, 10).Select(index =>
            CloneFace(minimumExterior.Faces[index % 6])));
        sourceFaces.AddRange(minimumExterior.Faces.Take(5).Select(CloneFace));
        sourceFaces.AddRange(maximumExterior.Faces.Take(5).Select(CloneFace));
        sourceFaces.AddRange(maximumExterior.Faces.Select(CloneFace));
        sourceFaces.AddRange(maximumExterior.Faces.Take(5).Select(CloneFace));
        sourceFaces.Add(CloneFace(minimumExterior.Faces[5]));
        sourceFaces.Add(CloneFace(maximumExterior.Faces[5]));
        sourceFaces.Add(Face(
        [
            [6, 0.5, 0.5], [6, 0.5, 2.5],
            [6, 0.5, 2.5], [6, 0.5, 0.5],
        ]));
        Assert.Equal(41, sourceFaces.Count);
        wall.Geometry = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices =
                    [
                        .. Enumerable.Range(0, 17),
                        .. Enumerable.Range(22, 5),
                        38, 39,
                    ],
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(17, 5).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(27, 6).ToList(),
                    IsClosed = true,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(33, 5).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var rebuiltFaces = new[] { 0, 1, 2, 4, 5, 6 }
            .Select(index => CloneFace(sourceFaces[index])).ToList();
        rebuiltFaces.AddRange(sourceFaces.Skip(7).Take(4).Select(CloneFace));
        var rebuilt = new GeometryData
        {
            BoundingBox = wall.BoundingBox,
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, rebuiltFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>();
        var standaloneOpeningIds = new Dictionary<int, List<int>>();

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out var gross));
        Assert.Equal(6, gross.Faces.Count);

        double originalNormal = sourceFaces[7].OuterVertices![0][1];
        sourceFaces[7].OuterVertices[0][1] = 0;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        sourceFaces[7].OuterVertices[0][1] = originalNormal;

        wall.Geometry.BrepSolids![0].FaceIndices[^1] = 38;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
        wall.Geometry.BrepSolids[0].FaceIndices[^1] = 39;

        emittedCutterIds[wall.Id] = [wall.Id + 1];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromDualExteriorJoinPrismsWithoutOpenings(
                wall, wall.BoundingBox, rebuilt,
                emittedCutterIds, standaloneOpeningIds, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsExactFoldedCapSpanCutter()
    {
        var wall = new Element
        {
            Id = 1901,
            TypeId = 1903,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            CuttingElementIds = [1902],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
        };
        var folded = FoldedCapSpanWallGeometry(
            0, -0.5, 0, 6, 0.5, 3, foldAlong: 2);
        wall.Geometry = folded;
        var cutter = new Element
        {
            Id = 1902,
            TypeId = 1904,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = wall.Id,
            BoundingBox = [2, -1, -0.5, 4, 1, 3],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        IfcExporter.HostedOpeningGeometry exactOperand = new(
            CentreXFt: 3, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 2,
            BaseZFt: -0.5, HeightFt: 3.5,
            ExactDepth: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, exactOperand)],
        };

        Assert.True(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromFoldedCapSpan(
                folded, wall.Location!, 1, wall.BoundingBox!,
                out var confirmedGross, out _, out string rejectionReason),
            rejectionReason);
        Assert.Equal(6, confirmedGross.Faces.Count);
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryFromFoldedCapSpanAndSingleCutter(
            wall, wall.BoundingBox!, folded, elements,
            new HashSet<int> { wall.Id }, inverseHosts,
            emittedCutterIds, emittedOperands, null,
            out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactOperand with { HeightFt = 3.5 - 2e-12 }),
        ];
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryFromFoldedCapSpanAndSingleCutter(
            wall, wall.BoundingBox!, folded, elements,
            new HashSet<int> { wall.Id }, inverseHosts,
            emittedCutterIds, emittedOperands, null,
            out _, out _));

        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactOperand with { HeightFt = 3.4999 }),
        ];
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryFromFoldedCapSpanAndSingleCutter(
            wall, wall.BoundingBox!, folded, elements,
            new HashSet<int> { wall.Id }, inverseHosts,
            emittedCutterIds, emittedOperands, null,
            out _, out _));

        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactOperand with { CentreXFt = 3.25 }),
        ];
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryFromFoldedCapSpanAndSingleCutter(
            wall, wall.BoundingBox!, folded, elements,
            new HashSet<int> { wall.Id }, inverseHosts,
            emittedCutterIds, emittedOperands, null,
            out _, out _));

        var damaged = FoldedCapSpanWallGeometry(
            0, -0.5, 0, 6, 0.5, 3, foldAlong: 2);
        damaged.Faces![3].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromFoldedCapSpan(
                damaged, wall.Location!, 1, wall.BoundingBox!,
                out _, out _, out _));
    }

    [Fact]
    public void EndCapNotchValidation_ReconstructsOnlyExactBrepCutCorner()
    {
        var wall = new Element
        {
            Id = 1801,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
        };
        var notched = EndCapNotchedWallGeometry(
            0, -0.5, 0, 4, 0.5, 3,
            notchAlong: 3, notchZ: 2);
        var exactCutter = BoxGeometry(3, -0.75, 0, 4.25, 0.75, 2);

        Assert.True(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromEndCapNotch(
                notched, wall.Location!, 1, wall.BoundingBox!, exactCutter,
                out var gross, out string rejectionReason),
            rejectionReason);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter.IsExactVerticalExtrusionBoundary(gross));
        Assert.True(IfcExporter.TryGetExactVerticalRectangularWallPlan(
            gross, wall.Location!, 1, wall.BoundingBox!, out _));

        var sideCoincidentCutter =
            BoxGeometry(3, -0.75, 0, 4.25, 0.5, 2);
        Assert.False(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromEndCapNotch(
                notched, wall.Location!, 1, wall.BoundingBox!,
                sideCoincidentCutter, out _, out rejectionReason));
        Assert.Equal("cutter-normal-coverage", rejectionReason);
        Assert.True(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromEndCapNotch(
                notched, wall.Location!, 1, wall.BoundingBox!,
                sideCoincidentCutter, out _, out rejectionReason,
                allowExactSingleWallSidePlaneCoincidence: true),
            rejectionReason);

        var overcut = BoxGeometry(2.9, -0.75, 0, 4.25, 0.75, 2);
        Assert.False(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromEndCapNotch(
                notched, wall.Location!, 1, wall.BoundingBox!, overcut,
                out _, out rejectionReason));
        Assert.Equal("cutter-notch-intersection", rejectionReason);

        notched.Faces![2].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter.TryGetExactRectangularWallGrossBoundaryFromEndCapNotch(
                notched, wall.Location!, 1, wall.BoundingBox!, exactCutter,
                out _, out _));
    }

    [Fact]
    public void EndCapNotchGate_RequiresCompleteWriterOperandCoverage()
    {
        var wall = new Element
        {
            Id = 1811,
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
        };
        var notched = EndCapNotchedWallGeometry(
            0, -0.5, 0, 4, 0.5, 3,
            notchAlong: 3, notchZ: 2);
        var exactCutter = BoxGeometry(3, -0.75, 0, 4.25, 0.75, 2);
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [1812, 1813],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (1812, new IfcExporter.HostedOpeningGeometry(
                    0, 0, 1, 0, 0, 0, 0, 0,
                    ExactDepth: true, Boundary: exactCutter)),
                (1813, new IfcExporter.HostedOpeningGeometry(
                    10, 0, 1, 0, 1, 2, 1, 1,
                    ExactDepth: true)),
            ],
        };

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromExactEndCapNotchAndCutters(
