    [Fact]
    public void CompleteOpenTenFaceSideCoincidentEndCapNotchGate_UsesExactSourceAndReturnsOnlyPrimaryBrepOperand()
    {
        const int wallId = 1821;
        const int primaryCutterId = 1822;
        const int disjointCutterId = 1823;
        var (rebuilt, source, bounds, location) =
            CompleteOpenTenFaceSideCoincidentEndCapNotchGeometry();
        var primaryBoundary = DiagonalWallFrameBoxGeometry(
            3, -2, 0, 11, 0.5, 6);
        var disjointBoundary = DiagonalWallFrameBoxGeometry(
            -8, -0.5, 1, -6, 0.5, 2);
        var primaryCentre = DiagonalWallFramePoint(7, -0.75, 0);
        var disjointCentre = DiagonalWallFramePoint(-7, 0, 0);
        double diagonal = Math.Sqrt(0.5);
        var primaryOperand = new IfcExporter.HostedOpeningGeometry(
            primaryCentre[0], primaryCentre[1], diagonal, diagonal,
            WidthFt: 8, DepthFt: 2.5,
            BaseZFt: 0, HeightFt: 6,
            ExactDepth: true, Boundary: primaryBoundary);
        var disjointOperand = new IfcExporter.HostedOpeningGeometry(
            disjointCentre[0], disjointCentre[1], diagonal, diagonal,
            WidthFt: 2, DepthFt: 1,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true, Boundary: disjointBoundary);
        var wall = new Element
        {
            Id = wallId,
            CategoryId = -2000011,
            Location = location,
            BoundingBox = (double[])bounds.Clone(),
            Geometry = source,
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 8.0,
                },
            ],
            CuttingElementIds = [primaryCutterId, disjointCutterId],
            References = [primaryCutterId, disjointCutterId],
        };
        var primaryCutter = new Element
        {
            Id = primaryCutterId,
            CategoryId = -2000023,
            BoundingBox = (double[])primaryBoundary.BoundingBox!.Clone(),
            References = [wallId],
        };
        var disjointCutter = new Element
        {
            Id = disjointCutterId,
            CategoryId = -2000023,
            BoundingBox = (double[])disjointBoundary.BoundingBox!.Clone(),
            References = [wallId],
        };
        var elements = new Dictionary<int, Element>
        {
            [wallId] = wall,
            [primaryCutterId] = primaryCutter,
            [disjointCutterId] = disjointCutter,
        };
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wallId] = [primaryCutterId, disjointCutterId],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wallId] =
            [
                (primaryCutterId, primaryOperand),
                (disjointCutterId, disjointOperand),
            ],
        };
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenTenFaceSideCoincidentEndCapNotchAndDisjointOpening(
                wall, bounds, rebuilt, elements,
                emittedCutterIds, emittedOperands, null,
                out var gross, out var cutterIds,
                out int exactSweptCutterId,
                out var exactSweptWriterOperand));
        Assert.Equal([primaryCutterId, disjointCutterId], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.Equal(primaryCutterId, exactSweptCutterId);
        Assert.Equal(primaryOperand, exactSweptWriterOperand);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, gross,
            allowBoundaryOwnedVerticalDefinition: true));
    }

    [Fact]
    public void CompleteOpenTenFaceSideCoincidentEndCapNotchGate_FailsClosedOnSourceGraphAndDisjointMutations()
    {
        const int wallId = 1831;
        const int primaryCutterId = 1832;
        const int disjointCutterId = 1833;
        var (rebuilt, source, bounds, location) =
            CompleteOpenTenFaceSideCoincidentEndCapNotchGeometry();
        var primaryBoundary = DiagonalWallFrameBoxGeometry(
            3, -2, 0, 11, 0.5, 6);
        var disjointBoundary = DiagonalWallFrameBoxGeometry(
            -8, -0.5, 1, -6, 0.5, 2);
        var primaryCentre = DiagonalWallFramePoint(7, -0.75, 0);
        var disjointCentre = DiagonalWallFramePoint(-7, 0, 0);
        double diagonal = Math.Sqrt(0.5);
        var primaryOperand = new IfcExporter.HostedOpeningGeometry(
            primaryCentre[0], primaryCentre[1], diagonal, diagonal,
            WidthFt: 8, DepthFt: 2.5,
            BaseZFt: 0, HeightFt: 6,
            ExactDepth: true, Boundary: primaryBoundary);
        var disjointOperand = new IfcExporter.HostedOpeningGeometry(
            disjointCentre[0], disjointCentre[1], diagonal, diagonal,
            WidthFt: 2, DepthFt: 1,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true, Boundary: disjointBoundary);
        var wall = new Element
        {
            Id = wallId,
            CategoryId = -2000011,
            Location = location,
            BoundingBox = (double[])bounds.Clone(),
            Geometry = source,
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 8.0,
                },
            ],
            CuttingElementIds = [primaryCutterId, disjointCutterId],
            References = [primaryCutterId, disjointCutterId],
        };
        var elements = new Dictionary<int, Element>
        {
            [wallId] = wall,
            [primaryCutterId] = new Element
            {
                Id = primaryCutterId,
                CategoryId = -2000023,
                BoundingBox = (double[])primaryBoundary.BoundingBox!.Clone(),
            },
            [disjointCutterId] = new Element
            {
                Id = disjointCutterId,
                CategoryId = -2000023,
                BoundingBox = (double[])disjointBoundary.BoundingBox!.Clone(),
            },
        };
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wallId] = [primaryCutterId, disjointCutterId],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wallId] =
            [
                (primaryCutterId, primaryOperand),
                (disjointCutterId, disjointOperand),
            ],
        };
        bool Gate(GeometryData candidateRebuilt, out int exactCutterId) =>
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromCompleteOpenTenFaceSideCoincidentEndCapNotchAndDisjointOpening(
                    wall, bounds, candidateRebuilt, elements,
                    emittedCutterIds, emittedOperands, null,
                    out _, out _, out exactCutterId, out _);

        var detachedBowTie = CloneGeometryData(source);
        (detachedBowTie.Faces![9].OuterVertices![1],
            detachedBowTie.Faces[9].OuterVertices![2]) =
            (detachedBowTie.Faces[9].OuterVertices![2],
                detachedBowTie.Faces[9].OuterVertices![1]);
        wall.Geometry = detachedBowTie;
        Assert.False(Gate(rebuilt, out int exactCutterId));
        Assert.Equal(0, exactCutterId);

        var redundantCapBowTie = CloneGeometryData(source);
        (redundantCapBowTie.Faces![7].OuterVertices![1],
            redundantCapBowTie.Faces[7].OuterVertices![2]) =
            (redundantCapBowTie.Faces[7].OuterVertices![2],
                redundantCapBowTie.Faces[7].OuterVertices![1]);
        wall.Geometry = redundantCapBowTie;
        Assert.False(Gate(rebuilt, out exactCutterId));
        Assert.Equal(0, exactCutterId);

        wall.Geometry = source;
        wall.CuttingElementIds = [primaryCutterId, 999999];
        Assert.False(Gate(rebuilt, out exactCutterId));
        Assert.Equal(0, exactCutterId);

        wall.CuttingElementIds = [primaryCutterId, disjointCutterId];
        Element primaryCutter = elements[primaryCutterId];
        elements[primaryCutterId] = new Element
        {
            Id = primaryCutterId + 100,
            CategoryId = primaryCutter.CategoryId,
            BoundingBox = primaryCutter.BoundingBox,
        };
        Assert.False(Gate(rebuilt, out exactCutterId));
        Assert.Equal(0, exactCutterId);
        elements[primaryCutterId] = primaryCutter;

        var mismatchedRebuiltBounds = CloneGeometryData(rebuilt);
        mismatchedRebuiltBounds.BoundingBox![3] += 1;
        Assert.False(Gate(mismatchedRebuiltBounds, out exactCutterId));
        Assert.Equal(0, exactCutterId);

        var intersectingBoundary = DiagonalWallFrameBoxGeometry(
            1, -0.5, 1, 2, 0.5, 2);
        var intersectingCentre = DiagonalWallFramePoint(1.5, 0, 0);
        emittedOperands[wallId][1] =
        (
            disjointCutterId,
            new IfcExporter.HostedOpeningGeometry(
                intersectingCentre[0], intersectingCentre[1],
                diagonal, diagonal,
                WidthFt: 1, DepthFt: 1,
                BaseZFt: 1, HeightFt: 1,
                ExactDepth: true, Boundary: intersectingBoundary)
        );
        Assert.False(Gate(rebuilt, out exactCutterId));
        Assert.Equal(0, exactCutterId);
    }

    [Fact]
    public void CompleteOpenTenFaceSideCoincidentEndCapNotchExporter_DefersAndPreservesExactPrimaryOperand()
    {
        const int wallId = 1861;
        const int primaryCutterId = 1862;
        const int disjointCutterId = 1863;
        const int primaryTypeId = 1864;
        const int disjointTypeId = 1865;
        const int phaseId = 1899;
        var (_, source, bounds, location) =
            CompleteOpenTenFaceSideCoincidentEndCapNotchGeometry();
        var primaryBoundary = DiagonalWallFrameBoxGeometry(
            3, -2, 0, 11, 0.5, 6);
        var disjointBoundary = DiagonalWallFrameBoxGeometry(
            -8, -0.5, 1, -6, 0.5, 2);
        double diagonal = Math.Sqrt(0.5);
        var wall = new Element
        {
            Id = wallId,
            TypeId = 1860,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Complete open side-coincident end-cap notch wall",
            Location = location,
            BoundingBox = (double[])bounds.Clone(),
            Geometry = source,
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 8.0,
                },
            ],
            CuttingElementIds = [primaryCutterId, disjointCutterId],
            References = [primaryCutterId, disjointCutterId],
        };
        Element Cutter(int id, int typeId, GeometryData boundary,
            double along, double normal, double baseZ) => new()
        {
            Id = id,
            TypeId = typeId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = wallId,
            References = [wallId, phaseId],
            BoundingBox = (double[])boundary.BoundingBox!.Clone(),
            Transform = new InstanceTransform
            {
                Origin = DiagonalWallFramePoint(along, normal, baseZ),
                BasisX = [diagonal, diagonal, 0],
                BasisY = [-diagonal, diagonal, 0],
                BasisZ = [0, 0, 1],
                SymbolId = typeId,
            },
            Parameters =
            [
                new Parameter
                {
                    Id = -1012100,
                    StorageType = StorageType.ElementId,
                    Value = phaseId,
                },
                new Parameter
                {
                    Id = -1013201,
                    StorageType = StorageType.Integer,
                    Value = -4,
                },
            ],
        };
        var primaryCutter = Cutter(
            primaryCutterId, primaryTypeId, primaryBoundary,
            along: 7, normal: -0.75, baseZ: 0);
        var disjointCutter = Cutter(
            disjointCutterId, disjointTypeId, disjointBoundary,
            along: -7, normal: 0, baseZ: 1);
        var primaryType = new Element
        {
            Id = primaryTypeId,
            FamilyCutGeometry = BoxGeometry(-4, -1.25, 0, 4, 1.25, 6),
        };
        var disjointType = new Element
        {
            Id = disjointTypeId,
            FamilyCutGeometry = BoxGeometry(-1, -0.5, 0, 1, 0.5, 1),
        };
        string acceptedPath = Path.Combine(Path.GetTempPath(),
            $"revitreader-complete-open-ten-side-coincident-{Guid.NewGuid():N}.ifc");
        string rejectedPath = Path.Combine(Path.GetTempPath(),
            $"revitreader-complete-open-ten-side-coincident-rejected-{Guid.NewGuid():N}.ifc");
        try
        {
            var info = new RevitFileInfo();
            info.Elements.AddRange(
                [wall, primaryCutter, disjointCutter, primaryType, disjointType]);
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, acceptedPath);
            string acceptedIfc = File.ReadAllText(acceptedPath);

            Assert.Contains("'Axis','Curve2D'", acceptedIfc);
            Assert.Equal(2, Count(acceptedIfc, "=IFCOPENINGELEMENT("));
            Assert.Equal(2, Count(acceptedIfc, "=IFCRELVOIDSELEMENT("));
            Assert.Equal(2, Count(acceptedIfc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(1, Count(acceptedIfc, "=IFCFACETEDBREP("));
            Assert.Matches(
                @"IFCRECTANGLEPROFILEDEF\([^;\r\n]*(?:2438\.4,762\.|762\.,2438\.4)\)",
                acceptedIfc);

            var mutatedSource = CloneGeometryData(source);
            (mutatedSource.Faces![9].OuterVertices![1],
                mutatedSource.Faces[9].OuterVertices![2]) =
                (mutatedSource.Faces[9].OuterVertices![2],
                    mutatedSource.Faces[9].OuterVertices![1]);
            wall.Geometry = mutatedSource;
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, rejectedPath);
            string rejectedIfc = File.ReadAllText(rejectedPath);

            Assert.DoesNotContain("'Axis','Curve2D'", rejectedIfc);
            Assert.Equal(2, Count(rejectedIfc, "=IFCOPENINGELEMENT("));
            Assert.Equal(2, Count(rejectedIfc, "=IFCRELVOIDSELEMENT("));
            Assert.Equal(0, Count(rejectedIfc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(3, Count(rejectedIfc, "=IFCFACETEDBREP("));
        }
        finally
        {
            if (File.Exists(acceptedPath)) File.Delete(acceptedPath);
            if (File.Exists(rejectedPath)) File.Delete(rejectedPath);
        }
    }

    [Fact]
    public void CompleteOpenElevenFaceFullHeightSplitterGate_ReconstructsExactGrossAndKeepsBothOperands()
    {
        const int wallId = 1871;
        const int primaryCutterId = 1872;
        const int disjointCutterId = 1873;
        var (wall, rebuilt, elements, emittedCutterIds,
            emittedOperands, standalone) =
            CompleteOpenElevenFaceAlternativeFullHeightSplitterFixture(
                wallId, primaryCutterId, disjointCutterId);
        double[] bounds = wall.BoundingBox!;
        var location = wall.Location!;
        var primaryOperand = emittedOperands[wallId][0].Operand;
        var disjointOperand = emittedOperands[wallId][1].Operand;

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenElevenFaceAlternativeFullHeightSplitterAndDisjointOpening(
                wall, bounds, rebuilt, elements,
                emittedCutterIds, emittedOperands, standalone,
                out var gross, out var cutterIds));
        Assert.Equal([primaryCutterId, disjointCutterId], cutterIds);
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                gross, location, 1, bounds,
                out var plan, out _, out _, out string grossReason),
            grossReason);
        Assert.Equal(4, plan.Count);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, bounds, gross,
            allowBoundaryOwnedVerticalDefinition: true));
        Assert.True(IfcExporter.TryGetExactVerticalRectangularPrismSweptOpening(
            primaryOperand.Boundary, out var decodedPrimary));
        Assert.Equal(primaryOperand.WidthFt, decodedPrimary.WidthFt, 12);
        Assert.Equal(primaryOperand.DepthFt, decodedPrimary.DepthFt, 12);
        Assert.Equal(primaryOperand.HeightFt, decodedPrimary.HeightFt, 12);
        Assert.Null(disjointOperand.Boundary);
    }

