        GeometryData source = wall.Geometry!;
        var primaryOperand = emittedOperands[wallId][0].Operand;
        var disjointOperand = emittedOperands[wallId][1].Operand;
        bool Gate(GeometryData candidateRebuilt) => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenElevenFaceAlternativeFullHeightSplitterAndDisjointOpening(
                wall, wall.BoundingBox!, candidateRebuilt, elements,
                emittedCutterIds, emittedOperands, standalone,
                out _, out _);

        var reorderedSource = CloneGeometryData(source);
        reorderedSource.BrepSolids![0].FaceIndices.Reverse();
        wall.Geometry = reorderedSource;
        Assert.False(Gate(rebuilt));

        var missingDetachedComponent = CloneGeometryData(source);
        missingDetachedComponent.BrepSolids![0].FaceIndices.Remove(8);
        wall.Geometry = missingDetachedComponent;
        Assert.False(Gate(rebuilt));

        var damagedAlternative = CloneGeometryData(source);
        damagedAlternative.Faces![7].AlternativeOuterVertices!.RemoveAt(3);
        wall.Geometry = damagedAlternative;
        Assert.False(Gate(rebuilt));

        wall.Geometry = source;
        var damagedRebuilt = CloneGeometryData(rebuilt);
        damagedRebuilt.Faces![0].OuterVertices![2][0] += 0.25;
        Assert.False(Gate(damagedRebuilt));

        wall.CuttingElementIds = [primaryCutterId, primaryCutterId];
        Assert.False(Gate(rebuilt));
        wall.CuttingElementIds = [primaryCutterId, disjointCutterId];

        wall.References = [primaryCutterId];
        Assert.False(Gate(rebuilt));
        wall.References = [primaryCutterId, disjointCutterId];

        emittedCutterIds[wallId] =
            [primaryCutterId, disjointCutterId, disjointCutterId];
        Assert.False(Gate(rebuilt));
        emittedCutterIds[wallId] = [primaryCutterId, disjointCutterId];

        int peerHostId = emittedCutterIds.Keys.Single(id =>
            id != wallId && id == emittedCutterIds.Keys.Max());
        emittedCutterIds[peerHostId].Remove(primaryCutterId);
        Assert.False(Gate(rebuilt));
        emittedCutterIds[peerHostId].Insert(0, primaryCutterId);

        emittedOperands[peerHostId].RemoveAll(item =>
            item.CutterId == primaryCutterId);
        Assert.False(Gate(rebuilt));
        emittedOperands[peerHostId].Insert(0,
            (primaryCutterId, primaryOperand));

        elements[primaryCutterId].ExtraHostIds!.Add(wallId);
        Assert.False(Gate(rebuilt));
        elements[primaryCutterId].ExtraHostIds.Clear();

        int directHostId = elements[primaryCutterId].HostId!.Value;
        elements[disjointCutterId].HostId = wallId;
        Assert.False(Gate(rebuilt));
        elements[disjointCutterId].HostId = directHostId;

        elements[primaryCutterId].SerializedHostId = wallId;
        Assert.False(Gate(rebuilt));
        elements[primaryCutterId].SerializedHostId = directHostId;

        elements[directHostId].References!.Remove(disjointCutterId);
        Assert.False(Gate(rebuilt));
        elements[directHostId].References.Add(disjointCutterId);

        emittedOperands[wallId][0] =
        (
            primaryCutterId,
            primaryOperand with
            {
                Boundary = BoxGeometry(1.25, -2, 0, 11.25, 2, 4),
            }
        );
        Assert.False(Gate(rebuilt));
        emittedOperands[wallId][0] = (primaryCutterId, primaryOperand);

        emittedOperands[wallId][1] =
        (
            disjointCutterId,
            disjointOperand with { BaseZFt = 2, HeightFt = 1 }
        );
        Assert.False(Gate(rebuilt));
        emittedOperands[wallId][1] = (disjointCutterId, disjointOperand);

        standalone[wallId] = [disjointCutterId];
        Assert.False(Gate(rebuilt));
        standalone.Clear();

        Assert.True(Gate(rebuilt));
    }

    [Fact]
    public void CompleteOpenElevenFaceFullHeightSplitterExporter_PromotesOnlyWallAndKeepsOpeningWriters()
    {
        const int wallId = 1891;
        const int primaryCutterId = 1892;
        const int disjointCutterId = 1893;
        const int primaryTypeId = 1894;
        const int secondaryTypeId = 1895;
        const int phaseId = 1899;
        var (wall, _, elements, _, _, _) =
            CompleteOpenElevenFaceAlternativeFullHeightSplitterFixture(
                wallId, primaryCutterId, disjointCutterId);
        int[] hostIds = elements.Values.Where(element =>
                element.CategoryId == -2000011)
            .Select(element => element.Id).Order().ToArray();
        Element primaryCutter = elements[primaryCutterId];
        primaryCutter.TypeId = primaryTypeId;
        primaryCutter.IsDiscovered = true;
        primaryCutter.Transform = new InstanceTransform
        {
            Origin = [6, 0, 0],
            BasisX = [1, 0, 0],
            BasisY = [0, 1, 0],
            BasisZ = [0, 0, 1],
            SymbolId = primaryTypeId,
        };
        primaryCutter.References = [.. hostIds, phaseId];
        primaryCutter.Parameters =
        [
            new Parameter
            {
                Id = -1012100,
                StorageType = StorageType.ElementId,
                Value = phaseId,
            },
            new Parameter
            {
                Id = -1013201,
                StorageType = StorageType.Integer,
                Value = -4,
            },
        ];
        var primaryType = new Element
        {
            Id = primaryTypeId,
            FamilyCutGeometry = BoxGeometry(-5, -2, 0, 5, 2, 4),
        };

        Element disjointCutter = elements[disjointCutterId];
        disjointCutter.TypeId = secondaryTypeId;
        disjointCutter.IsDiscovered = true;
        disjointCutter.BoundingBox = [4, -0.5, 0, 12, 0.5, 3];
        disjointCutter.Geometry = BoxGeometry(4, -0.5, 6, 12, 0.5, 7);
        disjointCutter.Transform = new InstanceTransform
        {
            Origin = [0, 0, 0],
            BasisX = [1, 0, 0],
            BasisY = [0, 1, 0],
            BasisZ = [0, 0, 1],
            SymbolId = secondaryTypeId,
        };
        disjointCutter.References = [.. hostIds, phaseId];
        disjointCutter.Parameters =
        [
            new Parameter
            {
                Id = 1,
                Guid = Guid.Parse("cef807ab-6704-4013-8d86-96c5a31b2d1e"),
                StorageType = StorageType.Double,
                Value = 8.0,
            },
            new Parameter
            {
                Id = 2,
                Guid = Guid.Parse("e31864ac-8135-4bea-a7d3-f2a96b81a6ea"),
                StorageType = StorageType.Double,
                Value = 1.0,
            },
            new Parameter
            {
                Id = 3,
                Guid = Guid.Parse("e140a591-7a59-4036-b7e4-074fbd8222ff"),
                StorageType = StorageType.Double,
                Value = 1.0,
            },
            new Parameter
            {
                Id = -1012100,
                StorageType = StorageType.ElementId,
                Value = phaseId,
            },
            new Parameter
            {
                Id = -1013201,
                StorageType = StorageType.Integer,
                Value = -4,
            },
        ];
        var secondaryType = new Element { Id = secondaryTypeId };
        var info = new RevitFileInfo();
        info.Elements.AddRange(elements.Values);
        info.Elements.AddRange([primaryType, secondaryType]);
        string acceptedPath = Path.Combine(Path.GetTempPath(),
            $"revitreader-complete-open-eleven-splitter-{Guid.NewGuid():N}.ifc");
        string rejectedPath = Path.Combine(Path.GetTempPath(),
            $"revitreader-complete-open-eleven-splitter-rejected-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, acceptedPath);
            string acceptedIfc = File.ReadAllText(acceptedPath);

            var mutatedSource = CloneGeometryData(wall.Geometry!);
            mutatedSource.BrepSolids![0].FaceIndices.Remove(8);
            mutatedSource.BrepSolids[0].IsClosed = true;
            wall.Geometry = mutatedSource;
            wall.Parameters!.Single(parameter =>
                parameter.Id == -1001105).Value = 3.25;
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, rejectedPath);
            string rejectedIfc = File.ReadAllText(rejectedPath);

            int acceptedOpenings = Count(
                acceptedIfc, "=IFCOPENINGELEMENT(");
            int rejectedOpenings = Count(
                rejectedIfc, "=IFCOPENINGELEMENT(");
            Assert.True(acceptedOpenings > 0);
            Assert.Equal(acceptedOpenings, rejectedOpenings);
            Assert.Equal(
                Count(acceptedIfc, "=IFCRELVOIDSELEMENT("),
                Count(rejectedIfc, "=IFCRELVOIDSELEMENT("));
            Assert.Equal(
                Count(rejectedIfc, "'Axis','Curve2D'") + 1,
                Count(acceptedIfc, "'Axis','Curve2D'"));
            Assert.Equal(
                Count(rejectedIfc, "=IFCEXTRUDEDAREASOLID(") + 1,
                Count(acceptedIfc, "=IFCEXTRUDEDAREASOLID("));
            Assert.Equal(
                Count(acceptedIfc, "=IFCFACETEDBREP(") + 1,
                Count(rejectedIfc, "=IFCFACETEDBREP("));
            Assert.Equal(
                CanonicalOpeningRepresentationPayloads(
                    acceptedIfc, primaryCutterId),
                CanonicalOpeningRepresentationPayloads(
                    rejectedIfc, primaryCutterId));
            Assert.Equal(
                CanonicalOpeningRepresentationPayloads(
                    acceptedIfc, disjointCutterId),
                CanonicalOpeningRepresentationPayloads(
                    rejectedIfc, disjointCutterId));
        }
        finally
        {
            if (File.Exists(acceptedPath)) File.Delete(acceptedPath);
            if (File.Exists(rejectedPath)) File.Delete(rejectedPath);
        }
    }

