    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsExactPairedCutProfileWithComplexWriterOperand()
    {
        var sourceProfile = new (double Along, double Z)[]
        {
            (0, 0), (10, 0), (10, 1), (7, 1), (7, 1.2),
            (3, 1.2), (3, 1), (1, 1), (1, 4), (0, 4),
        };
        var boundary = ExtrudedSideProfileWallGeometry(
            sourceProfile, -0.5, 0.5);
        var wall = new Element
        {
            Id = 601,
            Category = "OST_Walls",
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
                Direction = [1, 0, 0],
                Length = 10,
            },
            BoundingBox = [0, -0.5, 0, 10, 0.5, 4],
            Geometry = boundary,
            Parameters =
            [
                new Parameter
                {
                    Id = -1001000,
                    Value = 1.0,
                },
            ],
            CuttingElementIds = [602],
        };
        Assert.True(
            IfcExporter.TryGetExactPairedSideProfileExtrusionGrossBoundary(
                boundary, wall.Location, 1, wall.BoundingBox,
                out var recoveredGross, out string grossReason),
            grossReason);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox, recoveredGross));

        var twelveEdgeSourceProfile = new (double Along, double Z)[]
        {
            (0, 0), (10, 0), (10, 4), (8, 4),
            (8, 1.2), (6, 1.2), (6, 1), (4, 1),
            (4, 1.2), (1, 1.2), (1, 4), (0, 4),
        };
        var twelveEdgeBoundary = ExtrudedSideProfileWallGeometry(
            twelveEdgeSourceProfile, -0.5, 0.5);
        Assert.True(
            IfcExporter.TryGetExactPairedSideProfileExtrusionGrossBoundary(
                twelveEdgeBoundary, wall.Location, 1, wall.BoundingBox,
                out var recoveredTwelveEdgeGross,
                out string twelveEdgeGrossReason),
            twelveEdgeGrossReason);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox, recoveredTwelveEdgeGross));
        twelveEdgeBoundary.Faces![2].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter.TryGetExactPairedSideProfileExtrusionGrossBoundary(
                twelveEdgeBoundary, wall.Location, 1, wall.BoundingBox,
                out _, out _));

        var openingBoundary = ExtrudedSideProfileWallGeometry(
            new (double Along, double Z)[]
            {
                (2, 0.5), (8, 0.5), (8, 1), (7, 1),
                (7, 3), (3, 3), (3, 1), (2, 1),
            },
            -1, 1);
        var operand = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 6, DepthFt: 2,
            BaseZFt: 0.5, HeightFt: 2.5,
            ExactDepth: true, Boundary: openingBoundary);
        var emittedIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [602],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(602, operand)],
        };
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromExactProfileExtrusionAndSingleComplexWriterOperand(
                    wall, wall.BoundingBox, boundary,
                    emittedIds, emittedOperands, null,
                    out var gross, out var cutterIds));
        Assert.Equal([602], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox, gross));

        var steppedOuter = operand with { Boundary = null };
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            steppedOuter, innerWidthFt: 5, innerHeightFt: 2,
            breakpointNormalFt: 0, innerAtMinimum: false,
            out var steppedBoundary));
        var steppedOperand = steppedOuter with
        {
            Boundary = steppedBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                InnerWidthFt: 5, InnerHeightFt: 2,
                BreakpointNormalFt: 0, InnerAtMinimum: false),
            IsExactParameterizedReveal = true,
        };
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromExactProfileExtrusionAndSingleComplexWriterOperand(
                    wall, wall.BoundingBox, boundary,
                    emittedIds,
                    new Dictionary<int,
                        List<(int CutterId,
                            IfcExporter.HostedOpeningGeometry Operand)>>
                    {
                        [wall.Id] = [(602, steppedOperand)],
                    },
                    null, out _, out _));
        steppedBoundary.Faces[0].OuterVertices![0][0] += 0.125;
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromExactProfileExtrusionAndSingleComplexWriterOperand(
                    wall, wall.BoundingBox, boundary,
                    emittedIds,
                    new Dictionary<int,
                        List<(int CutterId,
                            IfcExporter.HostedOpeningGeometry Operand)>>
                    {
                        [wall.Id] = [(602, steppedOperand)],
                    },
                    null, out _, out _));

        emittedOperands[wall.Id][0] = (
            602, operand with { ExactDepth = false });
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromExactProfileExtrusionAndSingleComplexWriterOperand(
                    wall, wall.BoundingBox, boundary,
                    emittedIds, emittedOperands, null, out _, out _));

        emittedOperands[wall.Id][0] = (602, operand);
        wall.CuttingElementIds = [603];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromExactProfileExtrusionAndSingleComplexWriterOperand(
                    wall, wall.BoundingBox, boundary,
                    emittedIds, emittedOperands, null, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactSteppedBrepProfileOverOneWallThickness()
    {
        const int primaryCutterId = 702;
        const int disjointCutterId = 703;
        var wall = new Element
        {
            Id = 701,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
                Direction = [1, 0, 0],
                Length = 10,
            },
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Parameters = [WallWidthParameter(1)],
            CuttingElementIds = [primaryCutterId, disjointCutterId],
        };
        var splitCapShell = PairedSideProfileWallGeometry(
        [
            (0, 0), (3, 0), (10, 0), (10, 3), (0, 3),
        ],
        [
            (0, 0), (3, 0), (10, 0), (10, 3), (0, 3),
        ], -0.5, 0.5);
        var outer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 4, DepthFt: 4,
            BaseZFt: -0.2, HeightFt: 2.5,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outer, innerWidthFt: 3, innerHeightFt: 2,
            breakpointNormalFt: -1, innerAtMinimum: true,
            out var steppedBoundary));
        var steppedBrepOperand = outer with
        {
            Boundary = steppedBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                InnerWidthFt: 3, InnerHeightFt: 2,
                BreakpointNormalFt: -1, InnerAtMinimum: true),
            IsExactParameterizedReveal = true,
        };

        Assert.True(IfcExporter.TryGetExactSteppedOpeningSweptBoxForWall(
            steppedBoundary, wall.Location, 1, out var wallProfileBox));
        Assert.Equal(5, wallProfileBox.CentreXFt, 12);
        Assert.Equal(4, wallProfileBox.WidthFt, 12);
        Assert.Equal(4, wallProfileBox.DepthFt, 12);
        Assert.Equal(-0.2, wallProfileBox.BaseZFt, 12);
        Assert.Equal(2.5, wallProfileBox.HeightFt, 12);
        Assert.True(
            IfcExporter.TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
                splitCapShell, wall.Location, 1, wall.BoundingBox,
                steppedBrepOperand, out var retainedBoundary,
                out string retainedReason), retainedReason);
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            retainedBoundary, wall.Location, 1, wall.BoundingBox,
            out var retainedPlan, out _, out _, out retainedReason),
            retainedReason);
        Assert.Equal(5, retainedPlan.Count);

        var disjointOuter = outer with { CentreXFt = -5 };
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            disjointOuter, innerWidthFt: 3, innerHeightFt: 2,
            breakpointNormalFt: -1, innerAtMinimum: true,
            out var disjointBoundary));
        var emittedIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [primaryCutterId, disjointCutterId],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (primaryCutterId, steppedBrepOperand),
                (disjointCutterId, disjointOuter with
                {
                    Boundary = disjointBoundary,
                }),
            ],
        };
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpeningWithRobustlyDisjointAdditionalOperand(
                wall, wall.BoundingBox, splitCapShell,
                new Dictionary<int, Element> { [wall.Id] = wall },
                emittedIds, emittedOperands,
                new Dictionary<int, List<int>>(),
                new Dictionary<(int WallId, int CutterId),
                    IfcExporter.HostedOpeningGeometry>(),
                new HashSet<(int WallId, int CutterId)>(),
                out var verified, out var cutterIds));
        Assert.Equal([primaryCutterId, disjointCutterId], cutterIds);
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            verified, wall.Location, 1, wall.BoundingBox,
            out var verifiedPlan, out _, out _, out var verifiedReason),
            verifiedReason);
        Assert.Equal("exact", verifiedReason);
        Assert.Equal(4, verifiedPlan.Count);

        var crossingLocation = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, -1, 0],
            EndPoint = [10, -1, 0],
            Direction = [1, 0, 0],
            Length = 10,
        };
        Assert.False(IfcExporter.TryGetExactSteppedOpeningSweptBoxForWall(
            steppedBoundary, crossingLocation, 1, out _));
        steppedBoundary.Faces![0].OuterVertices![0][0] += 0.125;
        Assert.False(IfcExporter.TryGetExactSteppedOpeningSweptBoxForWall(
            steppedBoundary, wall.Location, 1, out _));
    }

    [Fact]
    public void RectangularWallValidation_NormalizesProfilesEqualOnIfcWriterLattice()
    {
        var (wall, _, boundary) = ExactWallWithOneThroughOpening();
        const double SourceDeltaFeet = 1.0e-8;
        foreach (double[] point in boundary.Faces![1].OuterVertices!)
            point[0] += SourceDeltaFeet;
        foreach (double[] point in boundary.Faces[1].InnerVertices![0])
            point[0] += SourceDeltaFeet;

        Assert.True(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            boundary, wall.Location!, 1, wall.BoundingBox!,
            out var gross, out var opening, out string rejectionReason),
            rejectionReason);
        Assert.True(IfcExporter.IsExactVerticalExtrusionBoundary(gross));
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(1, opening.WidthFt, 12);
    }

    [Fact]
    public void RectangularWallValidation_NormalizesSourceRoundoffProfileBeforePlanValidation()
    {
