    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsUniqueTwoOpeningBijection()
    {
        var (wall, firstCutter, secondCutter, boundary) =
            ExactWallWithTwoThroughOpenings();
        wall.CuttingElementIds = [secondCutter.Id, firstCutter.Id];
        var elements = new Dictionary<int, Element>
        {
