            out var gross, out var cutterIds));
        Assert.Equal([firstCutter.Id, secondCutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactMixedHostedAndSourceOwnedOpenings()
    {
        const int phaseId = 99;
        var (wall, firstCutter, _, boundary) =
            ExactWallWithTwoThroughOpenings();
        wall.IsDiscovered = true;
        wall.Name = "Mixed source-owned opening wall";
        wall.CuttingElementIds = null;
        firstCutter.IsDiscovered = true;
        firstCutter.HostId = wall.Id;
        firstCutter.References = [wall.Id, phaseId];
        firstCutter.Parameters =
        [
            new Parameter
            {
                Id = -1012100,
                StorageType = StorageType.ElementId,
                Value = phaseId,
            },
            new Parameter
            {
                Id = -1013201,
                StorageType = StorageType.Integer,
                Value = -4,
            },
        ];
        firstCutter.Geometry = BoxGeometry(1, -0.5, 1, 2, 0.5, 2);
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [firstCutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (firstCutter.Id, new IfcExporter.HostedOpeningGeometry(
                    1.5, 0, 1, 0, 1, 1, 1, 1, ExactDepth: true)),
            ],
        };

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out var gross, out var hostedCutterIds,
                out var sourceOwnedOpenings));
        Assert.Equal([firstCutter.Id], hostedCutterIds);
        var sourceOwnedOpening = Assert.Single(sourceOwnedOpenings);
        Assert.Equal(3.5, sourceOwnedOpening.CentreXFt, 12);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        emittedOperands[wall.Id][0] =
            (firstCutter.Id, new IfcExporter.HostedOpeningGeometry(
                2.5, 0, 1, 0, 1, 1, 1, 1, ExactDepth: true));
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out _, out _, out _));
        emittedOperands[wall.Id][0] =
            (firstCutter.Id, new IfcExporter.HostedOpeningGeometry(
                1.5, 0, 1, 0, 1, 1, 1, 1, ExactDepth: true));

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, firstCutter]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-mixed-source-owned-opening-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);
            var openingLines = File.ReadLines(path)
                .Where(line => line.Contains("=IFCOPENINGELEMENT("))
                .ToList();

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, openingLines.Count);
            Assert.Equal(2, Count(ifc, "=IFCRELVOIDSELEMENT("));
            Assert.Single(openingLines, line =>
                line.EndsWith($",'{wall.Id}');",
                    StringComparison.Ordinal));
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

