    [Fact]
    public void StandardCaseSweptSolidGate_RemovesSourceHoleCoveredByCompleteHostedCutterSet()
    {
        var (wall, firstCutter, boundary) =
            ExactWallWithOneThroughOpening();
        var secondCutter = new Element { Id = firstCutter.Id + 1 };
        var thirdCutter = new Element { Id = firstCutter.Id + 2 };
        wall.CuttingElementIds =
            [firstCutter.Id, secondCutter.Id, thirdCutter.Id];
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] =
                [firstCutter.Id, secondCutter.Id, thirdCutter.Id],
        };
        var coveringOpening = new IfcExporter.HostedOpeningGeometry(
            1.5, 0, 1, 0, 2, 3, 0.5, 2,
            ExactDepth: true,
            IsFamilyCutLoop: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (firstCutter.Id, coveringOpening),
                (secondCutter.Id,
                    coveringOpening with { CentreXFt = 2 }),
                (thirdCutter.Id,
                    coveringOpening with { CentreXFt = 1 }),
            ],
        };

        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    wall, wall.BoundingBox!, boundary,
                    emittedCutterIds, emittedOperands, null,
                    out var gross, out var cutterIds));
        Assert.Equal(wall.CuttingElementIds, cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        emittedOperands[wall.Id][0] =
            (firstCutter.Id,
                coveringOpening with { CentreXFt = 3 });
        emittedOperands[wall.Id][1] =
            (secondCutter.Id,
                coveringOpening with { CentreXFt = 3 });
        emittedOperands[wall.Id][2] =
            (thirdCutter.Id,
                coveringOpening with { CentreXFt = 3 });
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    wall, wall.BoundingBox!, boundary,
                    emittedCutterIds, emittedOperands, null,
                    out _, out _));

        emittedOperands[wall.Id][0] =
            (firstCutter.Id, coveringOpening);
        emittedOperands[wall.Id].RemoveAt(2);
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    wall, wall.BoundingBox!, boundary,
                    emittedCutterIds, emittedOperands, null,
                    out _, out _));
        emittedOperands[wall.Id].Add(
            (thirdCutter.Id, coveringOpening));

        wall.CuttingElementIds =
            [firstCutter.Id, secondCutter.Id];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    wall, wall.BoundingBox!, boundary,
                    emittedCutterIds, emittedOperands, null,
                    out _, out _));
        wall.CuttingElementIds =
            [firstCutter.Id, secondCutter.Id, thirdCutter.Id];

        emittedOperands[wall.Id][0] =
            (firstCutter.Id,
                coveringOpening with
                {
                    IsFamilyCutLoop = false,
                    IsExactSerializedDefinition = false,
                });
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    wall, wall.BoundingBox!, boundary,
                    emittedCutterIds, emittedOperands, null,
                    out _, out _));

        var standalone = new Dictionary<int, List<int>>
        {
            [wall.Id] = [9999],
        };
        emittedOperands[wall.Id][0] =
            (firstCutter.Id, coveringOpening);
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    wall, wall.BoundingBox!, boundary,
                    emittedCutterIds, emittedOperands, standalone,
                    out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesSourceOwnedHoleWithExactExternalNoOpCutter()
    {
        var (wall, cutter, boundary) = ExactWallWithOneThroughOpening();
        wall.CuttingElementIds = [cutter.Id];
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                    1.5, 1, 1, 0, 1, 1, 1, 1, ExactDepth: true)),
            ],
        };

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out var gross, out var hostedCutterIds,
                out var sourceOwnedOpenings));
        Assert.Equal([cutter.Id], hostedCutterIds);
        Assert.Equal(1.5, Assert.Single(sourceOwnedOpenings).CentreXFt, 12);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        emittedOperands[wall.Id][0] =
            (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                1.5, 1.1, 1, 0, 1, 1, 1, 1, ExactDepth: true));
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out _, out _, out var disjointSourceOwnedOpenings));
        Assert.Single(disjointSourceOwnedOpenings);
        emittedOperands[wall.Id][0] =
            (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                1.5, 1, 1, 0, 1, 1, 1, 1, ExactDepth: true));

        wall.CuttingElementIds = [cutter.Id, cutter.Id + 1];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out _, out _, out _));
        wall.CuttingElementIds = [cutter.Id, cutter.Id + 1];
        emittedCutterIds[wall.Id] = [cutter.Id, cutter.Id + 1];
        emittedOperands[wall.Id].Add(
            (cutter.Id + 1, new IfcExporter.HostedOpeningGeometry(
                2.5, -1, 1, 0, 1, 1, 1, 1, ExactDepth: true)));
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out _, out _, out var multiCutterSourceOwnedOpenings));
        Assert.Single(multiCutterSourceOwnedOpenings);
        wall.CuttingElementIds = [cutter.Id];
        emittedCutterIds[wall.Id] = [cutter.Id];
        emittedOperands[wall.Id].RemoveAt(1);
        emittedOperands[wall.Id][0] =
            (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                2.5, 0.4, 1, 0, 0.5, 0.4, 1, 1, ExactDepth: true));
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out _, out _, out _));
        emittedOperands[wall.Id][0] =
            (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                1.5, 1.000025, 1, 0, 1, 1, 1, 1, ExactDepth: true));
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryWithHostedAndSourceOwnedOpenings(
                wall, wall.BoundingBox!, boundary,
                emittedCutterIds, emittedOperands, null,
                out _, out _, out _));
    }

