            [firstCutter.Id] = firstCutter,
            [secondCutter.Id] = secondCutter,
            [intersectingCutter.Id] = intersectingCutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [firstCutter.Id] = [wall.Id],
            [secondCutter.Id] = [wall.Id],
            [intersectingCutter.Id] = [wall.Id],
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] =
                [firstCutter.Id, secondCutter.Id, intersectingCutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (firstCutter.Id, new IfcExporter.HostedOpeningGeometry(
                    1.5, 0, 1, 0, 1, 1, 1, 1, ExactDepth: true)),
                (secondCutter.Id, new IfcExporter.HostedOpeningGeometry(
                    3.5, 0, 1, 0, 1, 1, 1, 1, ExactDepth: true)),
                (intersectingCutter.Id,
                    new IfcExporter.HostedOpeningGeometry(
                        2.5, 0, 1, 0, 0.6, 1, 1, 1, ExactDepth: true)),
            ],
        };

        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, boundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RejectsIntersectingAdditionalEmittedCutter()
    {
        var (wall, cutter, boundary) = ExactWallWithOneThroughOpening();
        var overlappingCutter = new Element
