                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
        };
        wall.CuttingElementIds = [cutter.Id, overlappingCutter.Id];
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
            [overlappingCutter.Id] = overlappingCutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
            [overlappingCutter.Id] = [wall.Id],
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id, overlappingCutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                    1.5, 0, 1, 0, 1, 1, 1, 1, ExactDepth: true)),
                (overlappingCutter.Id, new IfcExporter.HostedOpeningGeometry(
                    1.875, 0, 1, 0, 0.75, 0.8, 1.2, 0.6, ExactDepth: true)),
            ],
        };

        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, boundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null, out _, out _));
    }

    [Fact]
    public void RectangularOpeningBoxValidation_AcceptsOffCentreThroughCutter()
    {
        var hole = new IfcExporter.RectangularWallThroughOpening(
            1.5, 0, 1, 0, 1, 1, 1, -0.5, 0.5);
        var cutter = new IfcExporter.HostedOpeningGeometry(
            1.5, 0.25, 1, 0, 1, 2, 1, 1);

        Assert.True(IfcExporter.ExactRectangularOpeningBoxMatchesWallHole(
            cutter, hole));
    }

    [Fact]
    public void RectangularOpeningBoxValidation_DiagnosesWriterLatticeEquivalentProfile()
    {
        var hole = new IfcExporter.RectangularWallThroughOpening(
            1.5, 0, 1, 0, 1, 1, 1, -0.5, 0.5);
        var cutter = new IfcExporter.HostedOpeningGeometry(
            1.5 + 1.0e-8, 0, 1, 0, 1, 2, 1, 1);

        Assert.False(IfcExporter.ExactRectangularOpeningBoxMatchesWallHole(
            cutter, hole, out string rejectionReason));
        Assert.Equal("along-centre-writer-lattice", rejectionReason);
        Assert.True(IfcExporter.OpeningBoxProfileMatchesWallHoleAtIfcPrecision(
            cutter, hole));
    }

    [Fact]
    public void RectangularOpeningBoxValidation_RejectsOffCentreCutterThatMissesWallFace()
    {
        var hole = new IfcExporter.RectangularWallThroughOpening(
            1.5, 0, 1, 0, 1, 1, 1, -0.5, 0.5);
        var cutter = new IfcExporter.HostedOpeningGeometry(
            1.5, 0.25, 1, 0, 1, 1, 1, 1);

        Assert.False(IfcExporter.ExactRectangularOpeningBoxMatchesWallHole(
            cutter, hole));
    }

