    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactSingleLinkedSourceOpening()
    {
        var (wall, cutter, boundary) = ExactWallWithOneThroughOpening();
        wall.Geometry = new GeometryData
        {
            BoundingBox = boundary.BoundingBox,
            Faces = boundary.Faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, boundary.Faces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        cutter.BoundingBox = [0.9, -0.75, 0.9, 2.1, 0.75, 2.1];
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };

        Assert.True(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, cutter.Id, out var sourceOpening,
            out bool usesBoundarySlotSourceValidation));
        Assert.False(usesBoundarySlotSourceValidation);
        Assert.Equal(1.5, sourceOpening.CentreXFt, 12);
        Assert.Equal(0, sourceOpening.CentreYFt, 12);
        Assert.Equal(1, sourceOpening.WidthFt, 12);
        Assert.Equal(1, sourceOpening.DepthFt, 12);
        Assert.Equal(1, sourceOpening.BaseZFt, 12);
        Assert.Equal(1, sourceOpening.HeightFt, 12);
        Assert.True(sourceOpening.ExactDepth);
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, sourceOpening)],
        };
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, boundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null,
            out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, cutter]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-single-linked-source-opening-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCWALLSTANDARDCASE(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Equal(2, Count(ifc, "'Body','SweptSolid'"));
            Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
            Assert.Equal(1, Count(ifc, "=IFCOPENINGELEMENT("));
            Assert.Equal(1, Count(ifc, "=IFCRELVOIDSELEMENT("));
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        wall.Geometry.BrepSolids![0].IsClosed = true;
        Assert.False(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, cutter.Id, out _));
        wall.Geometry.BrepSolids[0].IsClosed = false;
        wall.CuttingElementIds = [cutter.Id, 1303];
        Assert.False(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, cutter.Id, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactBoundarySlotSourceOpening()
    {
        const int CutterId = 1299;
        var sourceBoundary = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (2, 1), (4, 1),
            (4, 0), (6, 0), (6, 3), (0, 3),
        ], -0.5, 0.5);
        sourceBoundary.BrepSolids![0].IsClosed = false;
        var wall = new Element
        {
            Id = 1298,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = sourceBoundary,
            CuttingElementIds = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            BoundingBox = [1.5, -0.75, -0.25, 4.5, 0.75, 1.25],
            HostId = wall.Id,
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuiltBoundary));
        Assert.True(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, CutterId, out var sourceOpening,
            out bool usesBoundarySlotSourceValidation));
        Assert.True(usesBoundarySlotSourceValidation);
        Assert.False(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, CutterId, out _));
        Assert.Equal(3, sourceOpening.CentreXFt, 12);
        Assert.Equal(0, sourceOpening.CentreYFt, 12);
        Assert.Equal(2, sourceOpening.WidthFt, 12);
        Assert.Equal(1, sourceOpening.DepthFt, 12);
        Assert.Equal(0, sourceOpening.BaseZFt, 12);
        Assert.Equal(1, sourceOpening.HeightFt, 12);

        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, sourceOpening)],
        };
        var exactSourceOpenings = new Dictionary<
            (int WallId, int CutterId),
            IfcExporter.HostedOpeningGeometry>
        {
            [(wall.Id, cutter.Id)] = sourceOpening,
        };
        sourceBoundary.Faces![0].AlternativeOuterVertices =
            sourceBoundary.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        wall.CuttingElementIds = null;
        wall.References = [cutter.Id];
        cutter.SerializedHostId = wall.Id;
        cutter.References = [wall.Id];
        exactSourceOpenings.Remove((wall.Id, cutter.Id));
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));
        cutter.References = null;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));
        wall.CuttingElementIds = [CutterId];
        wall.References = null;
        cutter.SerializedHostId = null;
        exactSourceOpenings[(wall.Id, cutter.Id)] = sourceOpening;

        var pathSlottedSource = PairedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (2, 1), (4, 1),
            (4, 0), (6, 0), (6, 3), (0, 3),
        ],
        [
            (1, 0), (2, 0), (2, 1), (4, 1),
            (4, 0), (6, 0), (6, 3), (1, 3),
        ], -0.5, 0.5);
        pathSlottedSource.BrepSolids![0].IsClosed = false;
        pathSlottedSource.Faces![0].AlternativeOuterVertices =
            pathSlottedSource.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        var pathNeighbourGeometry = PairedSideProfileWallGeometry(
        [
            (0, 0), (0.25, 0), (0.25, 3), (0, 3),
        ],
        [
            (-0.5, 0), (6, 0), (6, 3), (-0.5, 3),
        ], -0.5, 0.5);
        var pathNeighbour = new Element
        {
            Id = 1304,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [6, 0, 0],
                EndPoint = [0.25, 0, 0],
            },
            BoundingBox = pathNeighbourGeometry.BoundingBox,
            Geometry = pathNeighbourGeometry,
        };
        wall.Geometry = pathSlottedSource;
        wall.BoundingBox = pathSlottedSource.BoundingBox;
        wall.References = [pathNeighbour.Id];
        elements[pathNeighbour.Id] = pathNeighbour;
        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var pathRebuiltBoundary));
        Assert.True(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, CutterId, out var pathSourceOpening,
            out bool usesPathBoundarySlotSourceValidation));
        Assert.True(usesPathBoundarySlotSourceValidation);
        exactSourceOpenings[(wall.Id, cutter.Id)] = pathSourceOpening;
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, pathRebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out var pathGross, out _));
        Assert.Equal(7, pathGross.Faces.Count);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                pathGross, wall.Location, 1, pathGross.BoundingBox!,
                out var pathGrossPlan, out _, out _,
                out string pathGrossReason));
        Assert.Equal("exact-collinear-boundary-subdivision",
            pathGrossReason);
        Assert.Equal(5, pathGrossPlan.Count);
        wall.Geometry = sourceBoundary;
        wall.BoundingBox = [0, -0.5, 0, 6, 0.5, 3];
        wall.References = null;
        elements.Remove(pathNeighbour.Id);
        exactSourceOpenings[(wall.Id, cutter.Id)] = sourceOpening;

        var collinearlySubdividedSource = PairedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (6, 0), (6, 3),
            (4, 3), (0, 3), (0, 2), (0, 1),
        ],
        [
            (1, 0), (2, 0), (7, 0), (7, 3),
            (4, 3), (1, 3), (1, 2), (1, 1),
        ], -0.5, 0.5);
        collinearlySubdividedSource.BrepSolids![0].IsClosed = false;
        foreach (GeoFace sideFace in collinearlySubdividedSource.Faces!.Take(2))
            sideFace.AlternativeOuterVertices = sideFace.OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        wall.Geometry = collinearlySubdividedSource;
        wall.BoundingBox = collinearlySubdividedSource.BoundingBox;
        wall.CuttingElementIds = null;
        wall.References = [CutterId];
        cutter.SerializedHostId = wall.Id;
        cutter.References = [wall.Id];
        emittedOperands[wall.Id] =
        [
            (cutter.Id, new IfcExporter.HostedOpeningGeometry(
                3, 0, 1, 0, 2, 1, 0, 1,
                ExactDepth: true,
                IsExactSerializedDefinition: true)),
        ];
        exactSourceOpenings.Clear();
        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var collinearlySubdividedBoundary));
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, collinearlySubdividedBoundary,
                elements, emittedCutters, emittedOperands, null,
                exactSourceOpenings, out var collinearlySubdividedGross,
                out _));
        Assert.Equal(6, collinearlySubdividedGross.Faces.Count);
        collinearlySubdividedSource.Faces[1]
            .AlternativeOuterVertices![1][0] += 0.125;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, collinearlySubdividedBoundary,
                elements, emittedCutters, emittedOperands, null,
                exactSourceOpenings, out _, out _));

        var threeOpenRebuiltBoundary = PairedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (6, 0),
            (6, 3), (0, 3), (0, 1),
        ],
        [
            (1, 0), (2, 0), (7, 0),
            (7, 3), (1, 3), (1, 1),
        ], -0.5, 0.5);
        Assert.Equal(8, threeOpenRebuiltBoundary.Faces.Count);
        var threeOpenSourceFaces = Enumerable.Range(0, 21)
            .Select(index =>
            {
                double x = 0.5 + index % 10 * 0.05;
                double z = 1 + index / 10 * 0.1;
                return new GeoFace
                {
                    OuterVertices =
                    [
                        [x, -0.25, z],
                        [x + 0.02, -0.25, z],
                        [x, -0.20, z + 0.02],
                    ],
                };
            }).ToList();
        double[][] lowAlternative =
        [
            [0, -0.5, 0],
            [0, -0.5, 3],
            [5, -0.5, 3],
            [6, -0.5, 3],
            [6, -0.5, 0],
            [2, -0.5, 0],
        ];
        double[][] highAlternative =
        [
            [1, 0.5, 0],
            [7, 0.5, 0],
            [7, 0.5, 3],
            [1, 0.5, 3],
        ];
        threeOpenSourceFaces[0] = new GeoFace
        {
            OuterVertices =
            [
                lowAlternative[0], lowAlternative[1],
                lowAlternative[3], lowAlternative[5],
            ],
            AlternativeOuterVertices = lowAlternative.ToList(),
        };
        threeOpenSourceFaces[1] = new GeoFace
        {
            OuterVertices = highAlternative.ToList(),
            AlternativeOuterVertices = highAlternative.ToList(),
        };
        threeOpenSourceFaces[2] = new GeoFace
        {
            OuterVertices =
            [
                lowAlternative[4], lowAlternative[5], [4, -0.4, 1],
            ],
        };
        var threeOpenSource = new GeometryData
        {
            BoundingBox = (double[])threeOpenRebuiltBoundary
                .BoundingBox!.Clone(),
            Faces = threeOpenSourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 9).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(9, 8).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(17, 4).ToList(),
                    IsClosed = false,
                },
            ],
        };
        wall.Geometry = threeOpenSource;
        wall.BoundingBox = (double[])threeOpenSource.BoundingBox.Clone();
        wall.CuttingElementIds = [CutterId];
        wall.References = null;
        cutter.SerializedHostId = null;
        cutter.References = null;
        exactSourceOpenings.Clear();
        var familyCutLoopWriterBox =
            new IfcExporter.HostedOpeningGeometry(
                3, 0, 1, 0, 2, 10, 0, 1,
                ExactDepth: true);
        emittedOperands[wall.Id] =
            [(cutter.Id, familyCutLoopWriterBox)];
        var exactThreeOpenFamilyCutLoopWriterPairs =
            new HashSet<(int WallId, int CutterId)>
            {
                (wall.Id, cutter.Id),
            };
        bool TryThreeOpen(out GeometryData gross) => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, threeOpenRebuiltBoundary,
                elements, emittedCutters, emittedOperands, null,
                exactSourceOpenings, null,
                exactThreeOpenFamilyCutLoopWriterPairs,
                out gross, out _, out _);
        Assert.True(TryThreeOpen(out var threeOpenGross));
        Assert.Equal(7, threeOpenGross.Faces.Count);
        Assert.True(
            IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
                threeOpenGross, wall.Location, 1,
                threeOpenGross.BoundingBox!,
                out var threeOpenPlan, out _, out _,
                out string threeOpenReason));
        Assert.Equal("exact-collinear-boundary-subdivision",
            threeOpenReason);
        Assert.Equal(5, threeOpenPlan.Count);
        Assert.Contains(threeOpenPlan, point =>
            Math.Abs(point[0] - 5) < 1e-12
            && Math.Abs(point[1] + 0.5) < 1e-12);

        exactThreeOpenFamilyCutLoopWriterPairs.Clear();
        Assert.False(TryThreeOpen(out _));
        exactThreeOpenFamilyCutLoopWriterPairs.Add(
            (wall.Id, cutter.Id));

        threeOpenSourceFaces[0].AlternativeOuterVertices![5] =
            [3, -0.5, 0];
        Assert.False(TryThreeOpen(out _));
        threeOpenSourceFaces[0].AlternativeOuterVertices![5] =
            lowAlternative[5];

        threeOpenSource.BrepSolids![2].IsClosed = true;
        Assert.False(TryThreeOpen(out _));
        threeOpenSource.BrepSolids[2].IsClosed = false;

        emittedOperands[wall.Id] =
        [
            (cutter.Id, familyCutLoopWriterBox with
            {
                BaseZFt = -0.25,
            }),
        ];
        Assert.False(TryThreeOpen(out _));
        wall.Geometry = sourceBoundary;
        wall.BoundingBox = [0, -0.5, 0, 6, 0.5, 3];
        wall.CuttingElementIds = [CutterId];
        wall.References = null;
        cutter.SerializedHostId = null;
        cutter.References = null;
        exactSourceOpenings[(wall.Id, cutter.Id)] = sourceOpening;
        emittedOperands[wall.Id] = [(cutter.Id, sourceOpening)];

        var closedSourceFaces = sourceBoundary.Faces
            .Select(face => new GeoFace
            {
                OuterVertices = face.OuterVertices!
                    .Select(point => (double[])point.Clone()).ToList(),
            }).ToList();
        foreach (int faceIndex in new[] { 3, 2 })
        {
            GeoFace face = closedSourceFaces[faceIndex];
            var ring = face.OuterVertices!;
            closedSourceFaces.RemoveAt(faceIndex);
            closedSourceFaces.Insert(faceIndex, new GeoFace
            {
                OuterVertices =
                [
                    (double[])ring[0].Clone(),
                    (double[])ring[1].Clone(),
                    (double[])ring[2].Clone(),
                ],
                AlternativeOuterVertices =
                [
                    (double[])ring[0].Clone(),
                    (double[])ring[1].Clone(),
                    (double[])ring[2].Clone(),
                ],
            });
            closedSourceFaces.Insert(faceIndex + 1, new GeoFace
            {
                OuterVertices =
                [
                    (double[])ring[0].Clone(),
                    (double[])ring[2].Clone(),
                    (double[])ring[3].Clone(),
                ],
            });
        }
        wall.Geometry = new GeometryData
        {
            BoundingBox = sourceBoundary.BoundingBox,
            Faces = closedSourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, closedSourceFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        Assert.True(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, CutterId, out var closedSourceOpening,
            out bool usesClosedBoundarySlotSourceValidation));
        Assert.True(usesClosedBoundarySlotSourceValidation);
        exactSourceOpenings[(wall.Id, cutter.Id)] = closedSourceOpening;
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));

        var partitionedSourceFaces = Enumerable.Range(0, 34)
            .Select(index =>
            {
                double x = 0.2 + index % 10 * 0.5;
                double y = -0.4 + index / 10 * 0.2;
                return new GeoFace
                {
                    OuterVertices =
                    [
                        [x, y, 1],
                        [x + 0.1, y, 1],
                        [x, y + 0.05, 1],
                    ],
                };
            }).ToList();
        Assert.Equal(34, partitionedSourceFaces.Count);
        wall.Geometry = new GeometryData
        {
            BoundingBox = sourceBoundary.BoundingBox,
            Faces = partitionedSourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 18).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(18, 4).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(22, 4).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(26, 4).ToList(),
                    IsClosed = true,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(30, 4).ToList(),
                    IsClosed = true,
                },
            ],
        };
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));
        partitionedSourceFaces[0].OuterVertices![0][0] += 100;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));

        var completeThreeComponentFaces = Enumerable.Range(0, 30)
            .Select(index =>
            {
                double x = 0.2 + index % 10 * 0.5;
                double y = -0.4 + index / 10 * 0.2;
                return new GeoFace
                {
                    OuterVertices =
                    [
                        [x, y, 1],
                        [x + 0.1, y, 1],
                        [x, y + 0.05, 1],
                    ],
                };
            }).ToList();
        foreach (int index in new[] { 16, 24, 25 })
            completeThreeComponentFaces[index].AlternativeOuterVertices =
                completeThreeComponentFaces[index].OuterVertices!
                    .Select(point => (double[])point.Clone()).ToList();
        wall.Geometry = new GeometryData
        {
            BoundingBox = sourceBoundary.BoundingBox,
            Faces = completeThreeComponentFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 16).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(16, 8).ToList(),
                    IsClosed = true,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(24, 6).ToList(),
                    IsClosed = true,
                },
            ],
        };
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));
        completeThreeComponentFaces[0].AlternativeOuterVertices =
            completeThreeComponentFaces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));

        wall.Geometry = sourceBoundary;
        exactSourceOpenings[(wall.Id, cutter.Id)] = sourceOpening;
        sourceBoundary.Faces[0].AlternativeOuterVertices = null;
        cutter.Transform = new InstanceTransform
        {
            Origin = [3, 0, 0],
            BasisX = [1, 0, 0],
            BasisY = [0, 1, 0],
            BasisZ = [0, 0, 1],
        };
        cutter.Parameters =
        [
            new Parameter
            {
                Id = 401,
                Definition = new Definition
                {
                    Name =
                        "Толщина стены в семействах дверей, окон и прочих элементов по стене",
                },
                StorageType = StorageType.Double,
                ForgeId =
                    "autodesk.parameter.aec.revit.external.-1:"
                    + "9350e48f842b4c46a15d2e36ab1f352f-1.0.0",
                Value = 1.0,
            },
            new Parameter
            {
                Id = 402,
                Definition = new Definition
                {
                    Name = "Дополнительная Глубина наружная",
                },
                StorageType = StorageType.Double,
                ForgeId =
                    "autodesk.parameter.aec.revit.family:402-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = 1.0,
            },
        ];
        Assert.True(IfcExporter
            .TryBuildExactBoundarySlotOpeningWriterEnvelope(
                cutter, wall, sourceOpening, out var writerOpening));
        Assert.Equal(3, writerOpening.CentreXFt, 12);
        Assert.Equal(0.5, writerOpening.CentreYFt, 12);
        Assert.Equal(2, writerOpening.DepthFt, 12);
        cutter.Parameters[0].ForgeId =
            "autodesk.parameter.aec.revit.external.-1:not-a-guid-1.0.0";
        Assert.False(IfcExporter
            .TryBuildExactBoundarySlotOpeningWriterEnvelope(
                cutter, wall, sourceOpening, out _));
        cutter.Parameters[0].ForgeId =
            "autodesk.parameter.aec.revit.external.-1:"
            + "9350e48f842b4c46a15d2e36ab1f352f-1.0.0";
        cutter.Parameters[0].Value = 0.75;
        Assert.False(IfcExporter
            .TryBuildExactBoundarySlotOpeningWriterEnvelope(
                cutter, wall, sourceOpening, out _));
        cutter.Parameters[0].Value = 1.0;
        var exactWriterOpenings = new Dictionary<
            (int WallId, int CutterId),
            IfcExporter.HostedOpeningGeometry>
        {
            [(wall.Id, cutter.Id)] = writerOpening,
        };
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                exactWriterOpenings,
                out _, out _,
                out bool requiresExactBoundarySlotSourceOpening));
        Assert.True(requiresExactBoundarySlotSourceOpening);
        exactWriterOpenings.Clear();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                exactWriterOpenings, out _, out _, out _));
        exactWriterOpenings[(wall.Id, cutter.Id)] = writerOpening;
        exactSourceOpenings.Clear();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                exactWriterOpenings, out _, out _, out _));
        exactSourceOpenings[(wall.Id, cutter.Id)] = sourceOpening;
        double[] exactSourceBounds =
            (double[])sourceBoundary.BoundingBox!.Clone();
        sourceBoundary.BoundingBox[0] -= 0.125;
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                exactWriterOpenings, out _, out _, out _));
        sourceBoundary.BoundingBox = exactSourceBounds;
        sourceBoundary.Faces[0].AlternativeOuterVertices =
            sourceBoundary.Faces[0].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        emittedOperands[wall.Id] =
        [
            (cutter.Id, sourceOpening with
            {
                WidthFt = double.NaN,
            }),
        ];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));
        emittedOperands[wall.Id] = [(cutter.Id, sourceOpening)];
        exactSourceOpenings[(wall.Id, cutter.Id)] = sourceOpening with
        {
            ExactDepth = false,
        };
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null, exactSourceOpenings,
                out _, out _));

        sourceBoundary.Faces![1].OuterVertices![2][0] += 0.125;
        Assert.False(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, CutterId, out _));

        var compactBoundarySlot = ExtrudedSideProfileWallGeometry(
        [
            (2, 0), (6, 0), (6, 3),
            (0, 3), (0, 1), (2, 1),
        ], -0.5, 0.5);
        compactBoundarySlot.BrepSolids![0].IsClosed = false;
        wall.Geometry = compactBoundarySlot;
        Assert.False(IfcExporter.TryGetExactSingleLinkedSourceOpening(
            wall, CutterId, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactOpenFourProfileFamilyWriterValidation()
    {
        const int WallId = 1298;
        const int CutterId = 1299;
        var rebuiltBoundary = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (0.25, 0), (0.25, 1),
            (4, 1), (4, 3), (0, 3),
        ], -0.5, 0.5);
        var sourceFaces = Enumerable.Range(0, 12)
            .Select(index =>
            {
                double x = 0.25 + index % 4 * 0.8;
                double y = -0.4 + index / 4 * 0.3;
                double z = 0.5 + index / 8 * 0.5;
                return Face(
                [
                    [x, y, z], [x + 0.1, y, z],
                    [x + 0.1, y + 0.05, z], [x, y + 0.05, z],
                ]);
            }).ToList();
        sourceFaces[0].AlternativeOuterVertices =
        [
            [0, -0.5, 0], [0.25, -0.5, 0],
            [0.25, -0.5, 1], [4, -0.5, 1],
            [4, -0.5, 3], [0, -0.5, 3],
        ];
        sourceFaces[1].AlternativeOuterVertices =
        [
            [0, 0.5, 3], [4, 0.5, 3],
            [4, 0.5, 1], [0.25, 0.5, 1],
            [0.25, 0.5, 0], [0, 0.5, 0],
        ];
        sourceFaces[2].AlternativeOuterVertices =
        [
            [1, -2, 0], [1, 2, 0],
            [1, 2, 2], [1, -2, 2],
        ];
        sourceFaces[3].AlternativeOuterVertices =
        [
            [3, -2, 0], [3, -2, 2],
            [3, 2, 2], [3, 2, 0],
        ];
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 12).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = WallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = (double[])source.BoundingBox.Clone(),
            Geometry = source,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Parameters = [WallWidthParameter(1)],
            CuttingElementIds = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
        };
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 4,
            BaseZFt: 0, HeightFt: 2,
            ExactDepth: true,
            IsExactFamilyCutLoopWriterBox: true);
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, writer)],
        };
        var exactSourceOpenings = new Dictionary<
            (int WallId, int CutterId),
            IfcExporter.HostedOpeningGeometry>();
        bool TryValidation(out GeometryData gross) => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null,
                exactSourceOpenings, out gross, out _);

        Assert.True(IfcExporter
            .HasExactCompleteOpenFourProfileSourceAuthority(source));
        Assert.True(IfcExporter
            .ExactAlternativeWriterSideProfilesMatchOpeningBox(
                [sourceFaces[2], sourceFaces[3]], writer));
        Assert.True(TryValidation(out var gross));
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        sourceFaces[3].AlternativeOuterVertices![0][0] += 0.125;
        Assert.False(TryValidation(out _));
        sourceFaces[3].AlternativeOuterVertices![0][0] -= 0.125;

        sourceFaces[4].AlternativeOuterVertices =
            sourceFaces[4].OuterVertices!
                .Select(point => (double[])point.Clone()).ToList();
        Assert.False(TryValidation(out _));
        sourceFaces[4].AlternativeOuterVertices = null;

        source.BrepSolids![0].IsClosed = true;
        Assert.False(TryValidation(out _));
        source.BrepSolids[0].IsClosed = false;

        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with { BaseZFt = -0.25 }),
        ];
        Assert.False(TryValidation(out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactOpenFifteenFaceDisjointWriterValidation()
    {
        const int WallId = 1301;
        const int CutterId = 1302;
        var rebuiltBoundary = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (0.25, 0), (0.25, 1),
            (4, 1), (4, 3), (0, 3),
        ], -0.5, 0.5);
        var sourceFaces = Enumerable.Range(0, 15)
            .Select(index =>
            {
                double x = 0.25 + index % 5 * 0.6;
                double y = -0.35 + index / 5 * 0.3;
                double z = 0.5 + index / 10 * 0.75;
                return Face(
                [
                    [x, y, z], [x + 0.2, y, z],
                    [x + 0.2, y + 0.1, z], [x, y + 0.1, z],
                ]);
            }).ToList();
        sourceFaces[0].OuterVertices =
        [
            [0.4, -0.2, 0.5], [0.6, -0.2, 0.5],
            [0.75, -0.05, 0.5], [0.75, 0.1, 0.5],
            [0.6, 0.25, 0.5], [0.4, 0.25, 0.5],
            [0.25, 0.1, 0.5], [0.25, -0.05, 0.5],
        ];
        sourceFaces[2].OuterVertices =
        [
            [1, -0.2, 1], [1.2, -0.2, 1],
            [1.3, -0.1, 1], [1.2, 0, 1],
            [1, 0, 1], [0.9, -0.1, 1],
        ];
        sourceFaces[0].AlternativeOuterVertices =
        [
            [0, -0.5, 0], [2, -0.5, 0], [4, -0.5, 0],
            [4, -0.5, 1], [4, -0.5, 3],
            [0, -0.5, 3], [0, -0.5, 1],
        ];
        sourceFaces[1].AlternativeOuterVertices =
        [
            [0, -0.5, 0], [0, 0, 0], [0, 0.5, 0],
            [0, 0.5, 3], [0, -0.5, 3],
        ];
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 15).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = WallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = (double[])source.BoundingBox.Clone(),
            Geometry = source,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Parameters = [WallWidthParameter(1)],
            References = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            ExtraHostIds = [WallId],
            References = [WallId],
        };
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 0.5, DepthFt: 0.5,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true,
            IsExactSerializedDefinition: true);
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, writer)],
        };
        var exactSourceOpenings = new Dictionary<
            (int WallId, int CutterId),
            IfcExporter.HostedOpeningGeometry>();
        bool TryValidation(out GeometryData gross) => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactSourceValidation(
                wall, wall.BoundingBox!, rebuiltBoundary, elements,
                emittedCutters, emittedOperands, null,
                exactSourceOpenings, out gross, out _);

        Assert.True(IfcExporter
            .HasExactCompleteOpenFifteenFaceTwoProfileSourceAuthority(source));
        Assert.True(TryValidation(out var gross));
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter
            .ExactAlternativeProfilesMatchDistinctGrossFaces(
                [sourceFaces[0], sourceFaces[1]], gross));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        double diagonal = Math.Sqrt(0.5);
        double[] Rotate(double[] point) =>
        [
            -20.123456789 + (point[0] - point[1]) * diagonal,
            20.987654321 + (point[0] + point[1]) * diagonal,
            48.392388451443551 + point[2],
        ];
        var rotatedGross = new GeometryData
        {
            Faces = gross.Faces.Select(face => new GeoFace
            {
                OuterVertices = face.OuterVertices!.Select(Rotate).ToList(),
            }).ToList(),
        };
        var rotatedAlternatives = new[] { sourceFaces[0], sourceFaces[1] }
            .Select(face => new GeoFace
            {
                AlternativeOuterVertices = face.AlternativeOuterVertices!
                    .Select(Rotate).ToList(),
            }).ToList();
        Assert.True(IfcExporter
            .ExactAlternativeProfilesMatchDistinctGrossFaces(
                rotatedAlternatives, rotatedGross));
        rotatedAlternatives[0].AlternativeOuterVertices![1][0] += 0.125;
        Assert.False(IfcExporter
            .ExactAlternativeProfilesMatchDistinctGrossFaces(
                rotatedAlternatives, rotatedGross));

        sourceFaces[0].AlternativeOuterVertices![1][1] += 0.125;
        Assert.False(TryValidation(out _));
        sourceFaces[0].AlternativeOuterVertices![1][1] -= 0.125;

        sourceFaces[3].AlternativeOuterVertices = sourceFaces[3]
            .OuterVertices!.Select(point => (double[])point.Clone()).ToList();
        Assert.False(TryValidation(out _));
        sourceFaces[3].AlternativeOuterVertices = null;

        source.BrepSolids![0].IsClosed = true;
        Assert.False(TryValidation(out _));
        source.BrepSolids[0].IsClosed = false;

        emittedOperands[wall.Id] =
        [
            (cutter.Id, writer with { CentreXFt = 2 }),
        ];
        Assert.False(TryValidation(out _));
        emittedOperands[wall.Id] = [(cutter.Id, writer)];

        cutter.References = [];
        Assert.False(TryValidation(out _));
    }

    [Fact]
    public void ForwardSecondaryFamilyCut_OverridesMissedJoinedHostShell()
    {
        const int CutterId = 1299;
        var sourceBoundary = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (2, 0), (2, 1), (4, 1),
            (4, 0), (6, 0), (6, 3), (0, 3),
        ], -0.5, 0.5);
        sourceBoundary.BrepSolids![0].IsClosed = false;
        var wall = new Element
        {
            Id = 1298,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = sourceBoundary,
            CuttingElementIds = [CutterId],
            References = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = 1200,
            HostId = 1200,
            ExtraHostIds = [wall.Id, 1300],
            References = [1200, wall.Id, 1300],
        };
        var directHost = new Element
        {
            Id = 1200,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = BoxGeometry(0, -0.5, 0, 6, 0.5, 3),
            References = [CutterId],
        };
        var elements = new Dictionary<int, Element>
        {
            [directHost.Id] = directHost,
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var perpendicularWall = new Element
        {
            Id = 1300,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [3, -3, 0],
                EndPoint = [3, 3, 0],
            },
            BoundingBox = [2.5, -3, 0, 3.5, 3, 3],
            Geometry = BoxGeometry(2.5, -3, 0, 3.5, 3, 3),
            References = [CutterId],
        };
        elements[perpendicularWall.Id] = perpendicularWall;
        int[] candidateHosts =
            [directHost.Id, wall.Id, perpendicularWall.Id];
        int[] inverseHosts = [wall.Id, perpendicularWall.Id];
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 3, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 10, BaseZFt: 0, HeightFt: 1,
            ExactDepth: true, IsFamilyCutLoop: true);

        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts, inverseHosts,
                elements, writer, out var decodedParallelOpening));
        Assert.Equal(10, decodedParallelOpening.DepthFt, 12);
        Assert.True(decodedParallelOpening.IsExactFamilyCutLoopWriterBox);
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out var perpendicularOpening));
        Assert.Equal(1, perpendicularOpening.DepthFt, 12);
        perpendicularWall.CuttingElementIds = [CutterId];
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out var decodedPerpendicularOpening));
        Assert.Equal(1, decodedPerpendicularOpening.DepthFt, 12);
        perpendicularWall.CuttingElementIds = [];

        perpendicularWall.Location.EndPoint = [5, 3, 0];
        perpendicularWall.CuttingElementIds = [CutterId];
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out var decodedObliqueOpening));
        Assert.Equal(1, decodedObliqueOpening.DepthFt, 12);
        perpendicularWall.CuttingElementIds = [];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out _));
        perpendicularWall.Location.EndPoint = [3, 3, 0];

        perpendicularWall.Parameters = [WallWidthParameter(0.5)];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out _));
        perpendicularWall.CuttingElementIds = [CutterId];
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out var decodedDifferentWidthOpening));
        Assert.Equal(1, decodedDifferentWidthOpening.DepthFt, 12);
        perpendicularWall.CuttingElementIds = [];
        perpendicularWall.Parameters = [WallWidthParameter(1)];

        cutter.ExtraHostIds = [wall.Id];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out _));
        cutter.ExtraHostIds = [];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts, inverseHosts,
                elements, writer, out _));
        cutter.ExtraHostIds = [wall.Id, perpendicularWall.Id];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts,
                [wall.Id, wall.Id],
                elements, writer, out _));
        perpendicularWall.References = [];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, perpendicularWall, candidateHosts, inverseHosts,
                elements, writer, out _));
    }

    [Fact]
    public void ForwardSecondaryFamilyCut_UsesCompleteOpenTwelveFaceMinimumPlanTouch()
    {
        const int CutterId = 1310;
        var (boundary, source) = CompleteOpenTwelveFaceMinimumPlanCapGeometry();
        var wall = new Element
        {
            Id = 1311,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0.25, 0, 0],
                EndPoint = [5.75, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = source,
            CuttingElementIds = [CutterId],
            References = [CutterId],
        };
        var directHost = new Element
        {
            Id = 1312,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [5.5, -3, 0],
                EndPoint = [5.5, 3, 0],
            },
            BoundingBox = [5, -3, 0, 6, 3, 3],
            Geometry = BoxGeometry(5, -3, 0, 6, 3, 3),
            References = [CutterId],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = directHost.Id,
            HostId = directHost.Id,
            ExtraHostIds = [wall.Id],
            References = [directHost.Id, wall.Id],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [directHost.Id] = directHost,
            [cutter.Id] = cutter,
        };
        int[] candidateHosts = [directHost.Id, wall.Id];
        int[] inverseHosts = [wall.Id];
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 5.5, CentreYFt: 0,
            AxisX: 0, AxisY: 1,
            WidthFt: 2, DepthFt: 10,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true, IsFamilyCutLoop: true);

        Assert.True(IfcExporter.TryTargetCommonHostedOpeningToHost(
            writer, directHost, out var directHostOpening));
        Assert.Equal(1, directHostOpening.DepthFt, 12);
        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var exactSourceBoundary));
        Assert.True(IfcExporter
            .TryGetExactVerticalWallBoundaryFromCompleteOpenTwelveFaceMinimumCapShell(
                wall, exactSourceBoundary, wall.BoundingBox,
                out var exactMinimumPlanBoundary,
                out var exactMinimumPlanLocation,
                out string minimumPlanReason), minimumPlanReason);
        Assert.True(IfcExporter
            .HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
                exactMinimumPlanLocation, 1,
                exactMinimumPlanBoundary.BoundingBox!,
                exactMinimumPlanBoundary,
                directHostOpening with
                {
                    IsFamilyCutLoop = false,
                    IsExactFamilyCutLoopWriterBox = true,
                }));
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts, inverseHosts,
                elements, writer, out var opening,
                out bool usesMinimumPlanTouch));
        Assert.True(usesMinimumPlanTouch);
        Assert.Equal(1, opening.DepthFt, 12);
        Assert.True(opening.IsExactFamilyCutLoopWriterBox);
        Assert.False(opening.IsFamilyCutLoop);

        source.BrepSolids![0].IsClosed = true;
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts, inverseHosts,
                elements, writer, out _, out bool closedSourceUsesTouch));
        Assert.False(closedSourceUsesTouch);
        source.BrepSolids[0].IsClosed = false;

        directHost.Location.StartPoint = [5.49, -3, 0];
        directHost.Location.EndPoint = [5.49, 3, 0];
        directHost.BoundingBox = [4.99, -3, 0, 5.99, 3, 3];
        directHost.Geometry = BoxGeometry(4.99, -3, 0, 5.99, 3, 3);
        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts, inverseHosts,
                elements, writer,
                out _, out bool overlappingWriterUsesTouch));
        Assert.False(overlappingWriterUsesTouch);
        directHost.Location.StartPoint = [5.5, -3, 0];
        directHost.Location.EndPoint = [5.5, 3, 0];
        directHost.BoundingBox = [5, -3, 0, 6, 3, 3];
        directHost.Geometry = BoxGeometry(5, -3, 0, 6, 3, 3);
        cutter.References = [directHost.Id];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, wall, candidateHosts, inverseHosts,
                elements, writer, out _, out _));

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuilt));
        Assert.Equal(boundary.BoundingBox, rebuilt.BoundingBox);
    }

    [Fact]
    public void ForwardSecondaryFamilyCut_UsesSoleDecodedInverseTopology()
    {
        const int CutterId = 1320;
        var directHost = new Element
        {
            Id = 1321,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = BoxGeometry(0, -0.5, 0, 6, 0.5, 3),
            References = [CutterId],
        };
        var inverseOnlyHost = new Element
        {
            Id = 1322,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [2.5, 2, 0],
                EndPoint = [5, 2, 0],
            },
            BoundingBox = [2.5, 1.5, 0, 5, 2.5, 3],
            Geometry = BoxGeometry(2.5, 1.5, 0, 5, 2.5, 3),
            CuttingElementIds = [CutterId],
            References = [CutterId],
        };
        var touchingForwardHost = new Element
        {
            Id = 1323,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 2, 0],
                EndPoint = [6, 2, 0],
            },
            BoundingBox = [0, 1.5, 0, 6, 2.5, 3],
            Geometry = BoxGeometry(4, 1.5, 0, 6, 2.5, 3),
            CuttingElementIds = [CutterId],
            References = [CutterId],
        };
        touchingForwardHost.Geometry.Faces.AddRange(
            BoxGeometry(2.5, 1.5, 0, 3.5, 2.5, 3).Faces);
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = directHost.Id,
            HostId = directHost.Id,
            ExtraHostIds = [touchingForwardHost.Id],
            References =
                [directHost.Id, inverseOnlyHost.Id, touchingForwardHost.Id],
        };
        var elements = new Dictionary<int, Element>
        {
            [directHost.Id] = directHost,
            [inverseOnlyHost.Id] = inverseOnlyHost,
            [touchingForwardHost.Id] = touchingForwardHost,
            [cutter.Id] = cutter,
        };
        int[] candidateHosts =
            [directHost.Id, inverseOnlyHost.Id, touchingForwardHost.Id];
        int[] inverseHosts =
            [inverseOnlyHost.Id, touchingForwardHost.Id];
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 3, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 10,
            BaseZFt: 0.5, HeightFt: 2,
            ExactDepth: true, IsFamilyCutLoop: true);

        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, inverseOnlyHost, candidateHosts, inverseHosts,
                elements, writer, out var opening,
                out bool usesMinimumPlanTouch));
        Assert.False(usesMinimumPlanTouch);
        Assert.Equal(10, opening.DepthFt, 12);
        Assert.False(opening.IsFamilyCutLoop);
        Assert.True(opening.IsExactFamilyCutLoopWriterBox);

        Assert.True(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, touchingForwardHost, candidateHosts, inverseHosts,
                elements, writer, out var forwardOpening,
                out bool forwardUsesMinimumPlanTouch));
        Assert.False(forwardUsesMinimumPlanTouch);
        Assert.Equal(10, forwardOpening.DepthFt, 12);

        touchingForwardHost.CuttingElementIds = [];
        Assert.False(IfcExporter
            .TryGetExactForwardSecondaryFamilyCutOpening(
                cutter, touchingForwardHost, candidateHosts, inverseHosts,
                elements, writer, out _));
    }

    [Fact]
    public void JoinedFaceSubsetFamilyCut_UsesForwardClippedOperand()
    {
        const int CutterId = 1330;
        const int CompanionCutterId = 1331;
        var directHost = new Element
        {
            Id = 1332,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(2)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [-5, 5, 0],
                EndPoint = [5, 5, 0],
            },
            BoundingBox = [-5, 4, 0, 5, 6, 10],
            Geometry = BoxGeometry(-5, 4, 0, 5, 6, 10),
            References = [CutterId],
        };
        var subsetSource = BoxGeometry(-0.2, 2, 0, 0.2, 8, 2);
        var forwardSource = BoxGeometry(-1, 0, 0, 1, 10, 10);
        forwardSource.BrepSolids![0].IsClosed = false;
        forwardSource.Faces[2].InnerVertices =
        [
            [
                [-0.5, 0, 2], [0.5, 0, 2],
                [0.5, 0, 8], [-0.5, 0, 8],
            ],
        ];
        forwardSource.Faces.AddRange(subsetSource.Faces.Select(face =>
            Face(face.OuterVertices!)));
        forwardSource.Faces.AddRange(
        [
            Face([[-0.8, 1, 3], [0.8, 1, 3], [0.8, 2, 3], [-0.8, 2, 3]]),
            Face([[-0.8, 3, 4], [0.8, 3, 4], [0.8, 4, 4], [-0.8, 4, 4]]),
            Face([[-0.8, 5, 5], [0.8, 5, 5], [0.8, 6, 5], [-0.8, 6, 5]]),
            Face([[-0.8, 7, 6], [0.8, 7, 6], [0.8, 8, 6], [-0.8, 8, 6]]),
            Face([[-0.8, 2, 7], [-0.8, 3, 7], [-0.8, 3, 8], [-0.8, 2, 8]]),
            Face([[0.8, 4, 7], [0.8, 5, 7], [0.8, 5, 8], [0.8, 4, 8]]),
            Face([[-0.6, 6, 9], [0.6, 6, 9], [0.6, 7, 9], [-0.6, 7, 9]]),
            Face([[-0.4, 1, 1], [0.4, 1, 1], [0, 1.5, 1]]),
            Face([[-0.4, 8.5, 9], [0.4, 8.5, 9], [0, 9, 9]]),
        ]);
        forwardSource.BrepSolids[0].FaceIndices =
            Enumerable.Range(0, forwardSource.Faces.Count).ToList();
        Assert.Equal(21, forwardSource.Faces.Count);

        var forwardHost = new Element
        {
            Id = 1333,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(2)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [0, 10, 0],
            },
            BoundingBox = [-1, 0, 0, 1, 10, 10],
            Geometry = forwardSource,
            CuttingElementIds = [CutterId, CompanionCutterId],
            References = [CutterId, CompanionCutterId, 1334],
        };
        var subsetHost = new Element
        {
            Id = 1334,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(0.4)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 8, 0],
                EndPoint = [0, 2, 0],
            },
            BoundingBox = [-0.2, 2, 0, 0.2, 8, 2],
            Geometry = subsetSource,
            CuttingElementIds = [CutterId, CompanionCutterId],
            References = [CutterId, CompanionCutterId, forwardHost.Id],
        };
        var companionCutter = new Element
        {
            Id = CompanionCutterId,
            CategoryId = -2000014,
            Category = "OST_Windows",
            SerializedHostId = forwardHost.Id,
            HostId = forwardHost.Id,
            BoundingBox = [-0.5, 2, 2, 0.5, 8, 8],
            References = [forwardHost.Id],
        };
        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = directHost.Id,
            HostId = directHost.Id,
            ExtraHostIds = [forwardHost.Id],
            BoundingBox = [-2, 0, 0, 2, 10, 8],
            References = [directHost.Id, forwardHost.Id],
        };
        var elements = new Dictionary<int, Element>
        {
            [directHost.Id] = directHost,
            [forwardHost.Id] = forwardHost,
            [subsetHost.Id] = subsetHost,
            [companionCutter.Id] = companionCutter,
            [cutter.Id] = cutter,
        };
        int[] candidateHosts = [directHost.Id, forwardHost.Id, subsetHost.Id];
        int[] inverseHosts = [forwardHost.Id, subsetHost.Id];
        var writer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 0, CentreYFt: 5,
            AxisX: 1, AxisY: 0,
            WidthFt: 4, DepthFt: 10,
            BaseZFt: 0, HeightFt: 8,
            ExactDepth: true, IsFamilyCutLoop: true);

        Assert.True(IfcExporter.TryTargetCommonHostedOpeningToHost(
            writer, forwardHost, out var genericForwardOpening));
        Assert.Equal(10, genericForwardOpening.DepthFt, 12);
        Assert.True(IfcExporter
            .TryGetExactJoinedFaceSubsetFamilyCutOpening(
                cutter, forwardHost, candidateHosts, inverseHosts,
                elements, writer, out var forwardOpening));
        Assert.Equal(2, forwardOpening.DepthFt, 12);
        Assert.True(IfcExporter
            .TryGetExactJoinedFaceSubsetFamilyCutOpening(
                cutter, subsetHost, candidateHosts, inverseHosts,
                elements, writer, out var subsetOpening));
        Assert.Equal(forwardOpening, subsetOpening);

        subsetSource.Faces[0].OuterVertices![0][0] += 0.1;
        Assert.False(IfcExporter
            .TryGetExactJoinedFaceSubsetFamilyCutOpening(
                cutter, subsetHost, candidateHosts, inverseHosts,
                elements, writer, out _));
        subsetSource.Faces[0].OuterVertices![0][0] -= 0.1;

        companionCutter.BoundingBox![2] = 2.1;
        Assert.False(IfcExporter
            .TryGetExactJoinedFaceSubsetFamilyCutOpening(
                cutter, forwardHost, candidateHosts, inverseHosts,
                elements, writer, out _));
        companionCutter.BoundingBox[2] = 2;

        forwardSource.BrepSolids![0].IsClosed = true;
        Assert.False(IfcExporter
            .TryGetExactJoinedFaceSubsetFamilyCutOpening(
                cutter, forwardHost, candidateHosts, inverseHosts,
                elements, writer, out _));
    }

    [Fact]
    public void EmbeddedSingleFamilyCutBrepAuthority_RequiresExactIncompleteTopology()
    {
        const int CutterId = 1340;
        var source = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (4, 0), (4, 3),
            (3, 3), (2, 3), (0, 3),
        ], -0.5, 0.5);
        source.Faces[0].AlternativeOuterVertices = source.Faces[0]
            .OuterVertices!.Select(point => (double[])point.Clone()).ToList();
        source.Faces.Add(Face(source.Faces[2].OuterVertices!));
        source.Faces.Add(Face(source.Faces[3].OuterVertices!));
        source.BrepSolids![0].FaceIndices.Add(8);
        source.BrepSolids[0].IsClosed = false;
        var wall = new Element
        {
            Id = 1341,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Geometry = source,
            CuttingElementIds = [CutterId],
            References = [CutterId],
        };

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var rebuilt));
        Assert.Equal(8, rebuilt.Faces.Count);
        Assert.True(IfcExporter
            .HasExactEmbeddedSingleFamilyCutBrepAuthority(wall, CutterId));
        Assert.True(IfcExporter.TryGetExactEmbeddedSingleFamilyCutBrepAxis(
            wall, CutterId, out var axis, out var localBoundary, out _));
        Assert.Equal(0, axis.OriginXFt, 12);
        Assert.Equal(0, axis.OriginYFt, 12);
        Assert.Equal(0, axis.BaseZFt, 12);
        Assert.Equal(1, axis.DirectionX, 12);
        Assert.Equal(0, axis.DirectionY, 12);
        Assert.Equal(4, axis.LengthFt, 12);
        Assert.Equal(8, localBoundary.Faces.Count);
        Assert.Equal([0, -0.5, 0, 4, 0.5, 3],
            localBoundary.BoundingBox!);

        var cutter = new Element
        {
            Id = CutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = wall.Id,
            SerializedHostId = wall.Id,
            References = [wall.Id],
            BoundingBox = [1, -0.6, 1, 2, 0.6, 2],
        };
        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, cutter]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-embedded-brep-axis-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);
            Assert.Contains("=IFCWALL(", ifc);
            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCFACETEDBREP(", ifc);
            Assert.DoesNotContain("=IFCRELVOIDSELEMENT(", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        source.BrepSolids[0].IsClosed = true;
        Assert.False(IfcExporter
            .HasExactEmbeddedSingleFamilyCutBrepAuthority(wall, CutterId));
        source.BrepSolids[0].IsClosed = false;

        source.Faces[0].AlternativeOuterVertices = null;
        Assert.False(IfcExporter
            .HasExactEmbeddedSingleFamilyCutBrepAuthority(wall, CutterId));
    }

