                [ThroughStart, NormalMaximum, 0],
                [ThroughStart, NormalMaximum, ThroughTop],
                [ThroughStart, NormalMinimum, ThroughTop]]),
            Face([[CutLeft, NormalMinimum, ShallowBottom],
                [Marker, NormalMinimum, ShallowBottom],
                [Marker, InsetNormal, ShallowBottom],
                [CutLeft, InsetNormal, ShallowBottom]]),
            Face([[0, NormalMinimum, 0], [0, NormalMaximum, 0],
                [0, NormalMaximum, Top], [0, NormalMinimum, Top]]),
            Face([[Length, NormalMinimum, ThroughTop],
                [Length, NormalMaximum, ThroughTop],
                [Length, NormalMaximum, Top], [Length, NormalMinimum, Top]]),
            Face([[0, NormalMinimum, 0], [ThroughStart, NormalMinimum, 0],
                [ThroughStart, NormalMaximum, 0], [0, NormalMaximum, 0]]),
        };
        faces[0].AlternativeOuterVertices =
        [
            [0, NormalMinimum, 0], [Length, NormalMinimum, 0],
            [Length, NormalMinimum, Top], [CutRight, NormalMinimum, Top],
            [Marker, NormalMinimum, Top], [0, NormalMinimum, Top],
        ];
        var source = new GeometryData
        {
            BoundingBox = [0, NormalMinimum, 0, Length, NormalMaximum, Top],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 9).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = 1353,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [Length, 0, 0],
            },
            BoundingBox = [0, NormalMinimum, 0, Length, NormalMaximum, Top],
            Geometry = source,
            CuttingElementIds = [CutterId],
            References = [CutterId, LowerJoinId, UpperJoinId],
        };
        var lowerJoin = new Element
        {
            Id = LowerJoinId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Geometry = BoxGeometry(0, -0.25, 0, 2, 0.25, JoinedSplit),
        };
        var upperJoin = new Element
        {
            Id = UpperJoinId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Geometry = BoxGeometry(0, -0.25, JoinedSplit, 2, 0.25, 4),
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [lowerJoin.Id] = lowerJoin,
            [upperJoin.Id] = upperJoin,
        };

        Assert.True(IfcExporter.TryGetExactEmbeddedSingleFamilyCutBrepAxis(
            wall, CutterId, out var axis, out var completed,
            out bool hasCompletedSourceBrep, elements));
        Assert.True(hasCompletedSourceBrep);
        Assert.Equal(Length, axis.LengthFt, 12);
        Assert.Equal(12, completed.Faces.Count);
        Assert.Equal(23, completed.Faces
            .SelectMany(face => face.OuterVertices!)
            .Select(point => (point[0], point[1], point[2]))
            .Distinct().Count());
        Assert.True(IfcExporter.IsExactFacetedShell(
            completed.Faces, completed.BrepSolids!.Single().FaceIndices));
        Assert.Contains(completed.Faces, face => face.OuterVertices!.Any(point =>
            point[0] == 0 && point[1] == NormalMinimum
                && point[2] == JoinedSplit));

        upperJoin.Geometry = BoxGeometry(
            0, -0.25, JoinedSplit + 0.1, 2, 0.25, 4);
        Assert.True(IfcExporter.TryGetExactEmbeddedSingleFamilyCutBrepAxis(
            wall, CutterId, out _, out var incomplete,
            out bool rejectedCompletedSourceBrep, elements));
        Assert.False(rejectedCompletedSourceBrep);
        Assert.Equal(8, incomplete.Faces.Count);
    }

    [Fact]
    public void HostedOpeningGate_UsesExactParameterizedRevealConcordance()
    {
        var (wall, cutter, _) = ExactWallWithOneThroughOpening();
        cutter.Transform = new InstanceTransform
        {
            Origin = [1.5, 0, 1],
            BasisX = [1, 0, 0],
            BasisY = [0, -1, 0],
            BasisZ = [0, 0, 1],
        };
        cutter.Parameters =
        [
            FamilyLengthParameter(300,
                "Регулировка выступа выреза проёма вовнутрь", 2),
            FamilyLengthParameter(301,
                "Регулировка выступа выреза проёма наружу", 1.5),
            FamilyLengthParameter(302,
                "Регулировка глубины вставки окна", 0.6),
            FamilyLengthParameter(303, "стена_толщина", 1),
            FamilyLengthParameter(304, "Четверть сверху", 0.1),
            FamilyLengthParameter(305, "Четверть слева", 0.1),
            FamilyLengthParameter(306, "Четверть справа", 0.15),
            FamilyLengthParameter(307, "створка_слева_ширина", 0.5),
            FamilyLengthParameter(308, "створка_справа_ширина", 0.6),
            FamilyLengthParameter(309, "импост_ширина", 0.1),
            FamilyLengthParameter(310, "каркас_ширина", 0.1),
            FamilyLengthParameter(311, "Монтажные зазоры", 0.1),
            FamilyLengthParameter(312, "створка_высота", 1.4),
        ];
        var primitiveOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1.7, DepthFt: 0.4, BaseZFt: 1,
            HeightFt: 1.8, ExactDepth: true);

        Assert.True(IfcExporter.TryBuildExactParameterizedRevealOpening(
            cutter, [wall], primitiveOpening, out var opening));
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(-0.25, opening.CentreYFt, 12);
        Assert.Equal(1.6, opening.WidthFt, 12);
        Assert.Equal(4.5, opening.DepthFt, 12);
        Assert.Equal(1.8, opening.HeightFt, 12);
        Assert.NotNull(opening.Boundary);
        Assert.Equal(10, opening.Boundary.Faces.Count);
        Assert.NotNull(opening.SteppedProfile);
        Assert.Equal(1.35,
            opening.SteppedProfile.Value.InnerWidthFt, 12);
        Assert.Equal(1.7,
            opening.SteppedProfile.Value.InnerHeightFt, 12);
        Assert.Equal(0.1,
            opening.SteppedProfile.Value.BreakpointNormalFt, 12);
        Assert.True(opening.SteppedProfile.Value.InnerAtMinimum);

        cutter.Parameters.RemoveAt(12);
        Assert.False(IfcExporter.TryBuildExactParameterizedRevealOpening(
            cutter, [wall], primitiveOpening, out _));
        cutter.Parameters.Add(
            FamilyLengthParameter(312, "створка_высота", 1.4));
        Assert.False(IfcExporter.TryBuildExactParameterizedRevealOpening(
            cutter, [wall],
            primitiveOpening with { WidthFt = 1.65 }, out _));
        Assert.False(IfcExporter.TryBuildExactParameterizedRevealOpening(
            cutter, [wall],
            primitiveOpening with { Boundary = BoxGeometry(
                0.65, -0.2, 1, 2.35, 0.2, 2.8) }, out _));

        static Parameter FamilyLengthParameter(
            int id, string name, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = name },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.family:{id}-1.0.0",
            SpecType = "autodesk.spec.aec:length-2.0.0",
            Value = value,
        };
    }

    [Fact]
    public void HostedOpeningGate_UsesExactSymmetricAdditionalDepthRectangularContract()
    {
        var (wall, cutter, _) = ExactWallWithOneThroughOpening();
        cutter.Parameters =
        [
            ExternalLengthParameter(
                300, "da753fe3ecfa465b9a2c02f55d0c2ff1", 1),
            ExternalLengthParameter(
                301, "8f2e4f9394724941a65d0ac468fd6a5d", 1),
            FamilyLengthParameter(302, "Вырез_Снаружи", 0.25),
            FamilyLengthParameter(303, "Вырез_Внутри", 0.25),
            new Parameter
            {
                Id = -1001361,
                StorageType = StorageType.Double,
                Value = 0.0,
            },
        ];
        var primitive = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 1.5,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true,
            Boundary: BoxGeometry(
                1, -0.75, 1, 2, 0.75, 2));

        Assert.True(IfcExporter
            .TryBuildExactSymmetricAdditionalDepthRectangularOpening(
                cutter, wall, [wall], primitive, out var opening));
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(0, opening.CentreYFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(1, opening.WidthFt, 12);
        Assert.Equal(1.5, opening.DepthFt, 12);
        Assert.Equal(1, opening.HeightFt, 12);
        Assert.Same(primitive.Boundary, opening.Boundary);
        Assert.True(opening.IsExactParameterizedRectangularCut);
        Assert.True(IfcExporter
            .ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                opening));
        Assert.False(IfcExporter
            .ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                opening with
                {
                    Boundary = BoxGeometry(
                        1.01, -0.75, 1,
                        2.01, 0.75, 2),
                }));

        cutter.Parameters.Single(parameter =>
                parameter.Definition?.Name == "Вырез_Внутри")
            .Value = 0.2;
        Assert.False(IfcExporter
            .TryBuildExactSymmetricAdditionalDepthRectangularOpening(
                cutter, wall, [wall], primitive, out _));
        cutter.Parameters.Single(parameter =>
                parameter.Definition?.Name == "Вырез_Внутри")
            .Value = 0.25;
        cutter.Transform!.Origin[0] += 0.001;
        Assert.False(IfcExporter
            .TryBuildExactSymmetricAdditionalDepthRectangularOpening(
                cutter, wall, [wall], primitive, out _));
        cutter.Transform.Origin[0] -= 0.001;
        cutter.Parameters.Add(ExternalLengthParameter(
            304, "8f2e4f9394724941a65d0ac468fd6a5d", 1));
        Assert.False(IfcExporter
            .TryBuildExactSymmetricAdditionalDepthRectangularOpening(
                cutter, wall, [wall], primitive, out _));

        static Parameter ExternalLengthParameter(
            int id, string guid, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = $"external-{id}" },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.external.-1:{guid}-1.0.0",
            Value = value,
        };
        static Parameter FamilyLengthParameter(
            int id, string name, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = name },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.family:{id}-1.0.0",
            SpecType = "autodesk.spec.aec:length-2.0.0",
            Value = value,
        };
    }

    [Fact]
    public void HostedOpeningGate_ExpandsExactContractedParameterizedRectangle()
    {
        var (wall, cutter, _) = ExactWallWithOneThroughOpening();
        cutter.CategoryId = -2000014;
        cutter.Category = "OST_Windows";
        cutter.Parameters =
        [
            ExternalLengthParameter(
                300, "da753fe3ecfa465b9a2c02f55d0c2ff1", 1),
            ExternalLengthParameter(
                301, "8f2e4f9394724941a65d0ac468fd6a5d", 1.2),
            FamilyLengthParameter(
                302, "Доп Глубина Внутренняя", 0.4),
            FamilyLengthParameter(
                303, "Доп Глубина Наружная", 0.2),
            FamilyLengthParameter(
                304, "Проем_Наружный_Ширина", 1.2),
            FamilyLengthParameter(
                305, "Проем_Наружный_Высота", 1),
            FamilyLengthParameter(
                306, "Подоконник_Проем_Ширина", 1.2),
            FamilyLengthParameter(
                307, "Монтажный зазор Слева", 0.1),
            FamilyLengthParameter(
                308, "Монтажный зазор Справа", 0.1),
            new Parameter
            {
                Id = -1001361,
                StorageType = StorageType.Double,
                Value = 1.0,
            },
        ];
        var primitive = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0,
            AxisX: -1, AxisY: 0,
            WidthFt: 1, DepthFt: 10,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);

        Assert.True(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall], primitive, out var opening));
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(-0.1, opening.CentreYFt, 12);
        Assert.Equal(1.2, opening.WidthFt, 12);
        Assert.Equal(1.6, opening.DepthFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(1, opening.HeightFt, 12);
        Assert.True(opening.IsExactParameterizedRectangularCut);
        Assert.False(opening.IsExactFamilyCutLoopWriterBox);
        Assert.NotNull(opening.Boundary);
        Assert.Equal(6, opening.Boundary.Faces.Count);
        Assert.True(IfcExporter
            .ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                opening));
        Assert.True(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall],
                primitive with
                {
                    IsExactFamilyCutLoopWriterBox = true,
                },
                out var writerLoopOpening));
        Assert.True(IfcExporter
            .ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                writerLoopOpening));
        Assert.True(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall],
                primitive with
                {
                    IsExactFamilyCutLoopWriterBox = false,
                    IsExactSerializedDefinition = true,
                },
                out var serializedOpening));
        Assert.Equal(opening.CentreXFt, serializedOpening.CentreXFt);
        Assert.Equal(opening.CentreYFt, serializedOpening.CentreYFt);
        Assert.Equal(opening.WidthFt, serializedOpening.WidthFt);
        Assert.Equal(opening.DepthFt, serializedOpening.DepthFt);
        Assert.Equal(opening.BaseZFt, serializedOpening.BaseZFt);
        Assert.Equal(opening.HeightFt, serializedOpening.HeightFt);
        Assert.True(IfcExporter
            .ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                serializedOpening));
        Assert.False(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall],
                primitive with
                {
                    IsExactFamilyCutLoopWriterBox = true,
                    IsExactSerializedDefinition = true,
                },
                out _));

        cutter.Parameters.Single(parameter =>
                parameter.Definition?.Name == "Монтажный зазор Справа")
            .Value = 0.09;
        Assert.False(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall], primitive, out _));
        cutter.Parameters.Single(parameter =>
                parameter.Definition?.Name == "Монтажный зазор Справа")
            .Value = 0.1;

        cutter.Parameters.RemoveAll(parameter =>
            parameter.Definition?.Name == "Подоконник_Проем_Ширина");
        Assert.False(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall], primitive, out _));
        cutter.Parameters.Add(FamilyLengthParameter(
            306, "Подоконник_Проем_Ширина", 1.2));

        cutter.Transform!.BasisY = [0, -1, 0];
        Assert.False(IfcExporter
            .TryBuildExactContractedParameterizedRectangularOpening(
                cutter, wall, [wall], primitive, out _));

        static Parameter ExternalLengthParameter(
            int id, string guid, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = $"external-{id}" },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.external.-1:{guid}-1.0.0",
            Value = value,
        };
        static Parameter FamilyLengthParameter(
            int id, string name, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = name },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.family:{id}-1.0.0",
            SpecType = "autodesk.spec.aec:length-2.0.0",
            Value = value,
        };
    }

