    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactClosedOuterProfileFromDirectHost()
    {
        var (wall, cutter, boundary) =
            ExactWallWithOneThroughOpening();
        var (_, _, outerBoundary) =
            ExactWallWithOneThroughOpening(highHoleHeadZ: 2.1);
        foreach (double[] point in BoundaryPoints(outerBoundary))
        {
            if (point[2] == 2) point[2] = 2.1;
            if (point[0] == 1) point[0] = 0.9;
            if (point[0] == 2) point[0] = 2.1;
            point[1] = point[1] == -0.5 ? -2 : -1.9;
        }
        int firstOuterFace = boundary.Faces!.Count;
        boundary.Faces.AddRange(outerBoundary.Faces!);
        var outerSolid = new GeoBrepSolid
        {
            FaceIndices = Enumerable.Range(
                firstOuterFace, outerBoundary.Faces.Count).ToList(),
            IsClosed = true,
        };
        boundary.BrepSolids!.Add(outerSolid);
        wall.Geometry = boundary;
        wall.CuttingElementIds = [cutter.Id];
        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            boundary.Faces, outerSolid.FaceIndices, out _,
            triangulateNonPlanarFaces: false));
        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out _));
        cutter.HostId = wall.Id;
        cutter.SerializedHostId = wall.Id;
        cutter.Parameters =
        [
            FamilyLengthParameter(220, "Доп Глубина Внутренняя", 1.6),
            FamilyLengthParameter(221, "Доп Глубина Наружная", 1.1),
            FamilyLengthParameter(222, "Проем_Наружный_Ширина", 1.0),
            FamilyLengthParameter(223, "Проем_Наружный_Высота", 1.0),
            FamilyLengthParameter(224, "Подоконник_Проем_Ширина", 1.2),
            FamilyLengthParameter(225, "Четверть Сверху", 0.1),
        ];
        var inflatedCommonOpening =
            new IfcExporter.HostedOpeningGeometry(
                CentreXFt: 1.5, CentreYFt: -0.75,
                AxisX: 1, AxisY: 0,
                WidthFt: 1.2, DepthFt: 5,
                BaseZFt: 1, HeightFt: 1.1,
                ExactDepth: true);

        Assert.True(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [0.9, -2.1, 1, 2.1, 0.6, 2.1],
                    [wall], inflatedCommonOpening, out var opening));
        Assert.NotNull(opening.Boundary);
        Assert.NotNull(opening.SteppedProfile);
        Assert.Equal(2.7, opening.DepthFt, 12);
        Assert.Equal(-0.75, opening.CentreYFt, 12);
        Assert.Equal(-0.5,
            opening.SteppedProfile.Value.BreakpointNormalFt, 12);
        Assert.False(opening.SteppedProfile.Value.InnerAtMinimum);

        outerSolid.IsClosed = false;
        Assert.False(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [0.9, -2.1, 1, 2.1, 0.6, 2.1],
                    [wall], inflatedCommonOpening, out _));

        static IEnumerable<double[]> BoundaryPoints(
            GeometryData source)
        {
            var seen = new HashSet<double[]>(
                ReferenceEqualityComparer.Instance);
            foreach (var face in source.Faces ?? [])
            {
                foreach (var point in face.OuterVertices ?? [])
                    if (seen.Add(point)) yield return point;
                foreach (var ring in face.InnerVertices ?? [])
                    foreach (var point in ring)
                        if (seen.Add(point)) yield return point;
            }
        }

        static Parameter FamilyLengthParameter(
            int id, string name, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = name },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.family:{id}-1.0.0",
            SpecType = "autodesk.spec.aec:length-2.0.0",
            Value = value,
        };
    }

    [Fact]
    public void SourceWallProfilesAndMappedBreakpoint_RequireUniqueEndpointAndRepeatedSpan()
    {
        const int cutterId = 102;
        static GeometryData WallGeometry(double maximumNormal)
        {
            var geometry = BoxGeometry(
                0, -1, 0, 4, maximumNormal, 3);
            geometry.Faces[2].InnerVertices =
            [
                [
                    [0.9, -1, 1], [2.1, -1, 1],
                    [2.1, -1, 2.1], [0.9, -1, 2.1],
                ],
            ];
            geometry.Faces[4].InnerVertices =
            [
                [
                    [1, maximumNormal, 1],
                    [1, maximumNormal, 2],
                    [2, maximumNormal, 2],
                    [2, maximumNormal, 1],
                ],
            ];
            geometry.BrepSolids![0].IsClosed = false;
            return geometry;
        }

        var firstWall = new Element
        {
            Id = 201,
            CategoryId = -2000011,
            CuttingElementIds = [cutterId],
            Geometry = WallGeometry(2),
        };
        var secondWall = new Element
        {
            Id = 202,
            CategoryId = -2000011,
            CuttingElementIds = [cutterId],
            Geometry = WallGeometry(2),
        };
        var minimumMappedFace = Face(
        [
            [0, -0.2, 0], [3, -0.2, 0],
            [3, -0.2, 2], [0, -0.2, 2],
        ]);
        var maximumMappedFace = Face(
        [
            [0, 0.5, 0], [3, 0.5, 0],
            [3, 0.5, 2], [0, 0.5, 2],
        ]);
        maximumMappedFace.InnerVertices =
        [
            [
                [0.5, 0.5, 0.5], [2.5, 0.5, 0.5],
                [2.5, 0.5, 1.5], [0.5, 0.5, 1.5],
            ],
        ];
        var cutterGeometry = new GeometryData
        {
            Faces = [minimumMappedFace, maximumMappedFace],
            ExactMappedInstances =
            [
                new GeoInstance
                {
                    SymbolId = 301,
                    Transform =
                    [
                        1, 0, 0,
                        0, 1, 0,
                        0, 0, 1,
                        0, 0, 0,
                    ],
                },
            ],
        };
        var cutter = new Element
        {
            Id = cutterId,
            HostId = firstWall.Id,
            Transform = new InstanceTransform
            {
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
            Geometry = cutterGeometry,
        };

        Assert.True(
            IfcExporter
                .TryBuildExactSteppedOpeningFromSourceWallProfilesAndMappedBreakpoint(
                    cutter, [firstWall, secondWall], out var opening));
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(0.5, opening.CentreYFt, 12);
        Assert.Equal(1.2, opening.WidthFt, 12);
        Assert.Equal(3, opening.DepthFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(1.1, opening.HeightFt, 12);
        Assert.NotNull(opening.Boundary);
        Assert.Equal(10, opening.Boundary.Faces.Count);
        Assert.NotNull(opening.SteppedProfile);
        Assert.True(
            opening.IsExactSourceWallProfilesMappedBreakpoint);
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                opening));
        Assert.Equal(1, opening.SteppedProfile.Value.InnerWidthFt, 12);
        Assert.Equal(1, opening.SteppedProfile.Value.InnerHeightFt, 12);
        Assert.Equal(0.5,
            opening.SteppedProfile.Value.BreakpointNormalFt, 12);
        Assert.False(opening.SteppedProfile.Value.InnerAtMinimum);

        minimumMappedFace.InnerVertices =
        [
            [
                [0.5, -0.2, 0.5], [2.5, -0.2, 0.5],
                [2.5, -0.2, 1.5], [0.5, -0.2, 1.5],
            ],
        ];
        Assert.False(
            IfcExporter
                .TryBuildExactSteppedOpeningFromSourceWallProfilesAndMappedBreakpoint(
                    cutter, [firstWall, secondWall], out _));

        minimumMappedFace.InnerVertices = null;
        secondWall.Geometry = WallGeometry(2.2);
        Assert.False(
            IfcExporter
                .TryBuildExactSteppedOpeningFromSourceWallProfilesAndMappedBreakpoint(
                    cutter, [firstWall, secondWall], out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactSteppedMultiHostOpening()
    {
        var (wall, cutter, sourceBoundary) = ExactWallWithOneThroughOpening();
        var outerOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0.5, AxisX: 1, AxisY: 0,
            WidthFt: 1.2, DepthFt: 2, BaseZFt: 1, HeightFt: 1.1,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 1, innerHeightFt: 1,
            breakpointNormalFt: 0.5, innerAtMinimum: true,
            out var steppedBoundary));
        Assert.Equal(10, steppedBoundary.Faces.Count);
        Assert.Equal(16, steppedBoundary.Faces
            .SelectMany(face => face.OuterVertices!)
            .Select(Key).Distinct().Count());

        Assert.True(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            sourceBoundary, wall.Location!, 1, wall.BoundingBox!,
            out _, out var hole));
        Assert.True(IfcExporter.ExactSteppedOpeningBoundaryMatchesWallHole(
            steppedBoundary, hole));
        var outerHole = new IfcExporter.RectangularWallThroughOpening(
            1.5, 1, 1, 0, 1.2, 1, 1.1, 0.5, 1.5);
        Assert.True(IfcExporter.ExactSteppedOpeningBoundaryMatchesWallHole(
            steppedBoundary, outerHole));
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 1, innerHeightFt: 1,
            breakpointNormalFt: 0.5, innerAtMinimum: true,
            out var writerLatticeDriftBoundary));
        double[] driftedMinimumPoint = writerLatticeDriftBoundary.Faces
            .SelectMany(face => face.OuterVertices!)
            .Distinct<double[]>(ReferenceEqualityComparer.Instance)
            .First(point => Math.Abs(point[1] + 0.5) < 1e-12);
        driftedMinimumPoint[1] += 3e-10;
        var writerLatticeDriftOpening = outerOpening with
        {
            Boundary = writerLatticeDriftBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                1, 1, 0.5, true),
        };
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                writerLatticeDriftOpening));
        Assert.True(IfcExporter.ExactSteppedOpeningBoundaryMatchesWallHole(
            writerLatticeDriftBoundary, outerHole));
        Assert.False(IfcExporter.ExactSteppedOpeningBoundaryMatchesWallHole(
            steppedBoundary, hole with
            {
                NormalMinimumFt = -0.1,
                NormalMaximumFt = 0.9,
            }));
        Assert.False(IfcExporter.ExactSteppedOpeningBoundaryMatchesWallHole(
            steppedBoundary, hole with { WidthFt = 1.1 }));

        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [cutter.Id] = cutter,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var steppedOpening = outerOpening with { Boundary = steppedBoundary };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, steppedOpening)],
        };
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, sourceBoundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null,
            out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        static IEnumerable<double[]> BoundaryPoints(GeometryData boundary)
        {
            var seen = new HashSet<double[]>(
                ReferenceEqualityComparer.Instance);
            foreach (var face in boundary.Faces)
            {
                foreach (var point in face.OuterVertices ?? [])
                    if (seen.Add(point)) yield return point;
                foreach (var ring in face.InnerVertices ?? [])
                    foreach (var point in ring)
                        if (seen.Add(point)) yield return point;
            }
        }

        foreach (var point in BoundaryPoints(sourceBoundary))
        {
            if (Math.Abs(point[0] - 1) < 1e-12) point[0] = 1.1;
            if (Math.Abs(point[0] - 2) < 1e-12) point[0] = 1.9;
            if (Math.Abs(point[2] - 2) < 1e-12) point[2] = 1.9;
        }
        double[][] lowOtherHole =
        [
            [2.5, -0.5, 1.2], [3, -0.5, 1.2],
            [3, -0.5, 1.8], [2.5, -0.5, 1.8],
        ];
        double[][] highOtherHole =
        [
            [2.5, 0.5, 1.2], [3, 0.5, 1.2],
            [3, 0.5, 1.8], [2.5, 0.5, 1.8],
        ];
        sourceBoundary.Faces[0].InnerVertices!.Add(lowOtherHole.ToList());
        sourceBoundary.Faces[1].InnerVertices!.Add(
            highOtherHole.AsEnumerable().Reverse().ToList());
        sourceBoundary.Faces.AddRange(
        [
            Face([lowOtherHole[0], lowOtherHole[1],
                highOtherHole[1], highOtherHole[0]]),
            Face([lowOtherHole[1], lowOtherHole[2],
                highOtherHole[2], highOtherHole[1]]),
            Face([lowOtherHole[2], lowOtherHole[3],
                highOtherHole[3], highOtherHole[2]]),
            Face([lowOtherHole[3], lowOtherHole[0],
                highOtherHole[0], highOtherHole[3]]),
        ]);
        sourceBoundary.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, sourceBoundary.Faces.Count).ToList();
        wall.Geometry = sourceBoundary;
        wall.CuttingElementIds = [cutter.Id, cutter.Id + 10];

        var (outerWall, _, outerBoundary) =
            ExactWallWithOneThroughOpening();
        outerWall.Id = wall.Id + 1;
        outerWall.CuttingElementIds = [cutter.Id, cutter.Id + 20];
        foreach (var point in BoundaryPoints(outerBoundary))
            point[1] += 1;
        outerBoundary.BoundingBox![1] += 1;
        outerBoundary.BoundingBox[4] += 1;
        outerWall.BoundingBox![1] += 1;
        outerWall.BoundingBox[4] += 1;
        outerWall.Location!.StartPoint[1] += 1;
        outerWall.Location.EndPoint[1] += 1;
        foreach (var point in BoundaryPoints(outerBoundary))
            if (Math.Abs(point[1] - 1.5) < 1e-12) point[1] = 1.3;
        outerBoundary.BoundingBox[4] = 1.3;
        outerWall.BoundingBox[4] = 1.3;
        outerWall.Location.StartPoint[1] -= 0.1;
        outerWall.Location.EndPoint[1] -= 0.1;
        outerWall.Layers![0].ThicknessMm = 243.84;
        outerWall.Geometry = outerBoundary;

        cutter.Parameters =
        [
            new Parameter
            {
                Id = 99,
                StorageType = StorageType.Double,
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = 1.0,
            },
        ];
        var commonOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0.5, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        Assert.True(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                [wall, outerWall], commonOpening, out var builtOpening));
        Assert.NotNull(builtOpening.Boundary);
        Assert.NotNull(builtOpening.SteppedProfile);
        Assert.Equal(0.8,
            builtOpening.SteppedProfile.Value.InnerWidthFt, 12);
        Assert.Equal(0.9,
            builtOpening.SteppedProfile.Value.InnerHeightFt, 12);
        outerBoundary.Faces.Add(Face(
        [
            [0, -3, 0],
            [4, -3, 3],
            [4, 1.4, 0],
        ]));
        cutter.Parameters =
        [
            new Parameter
            {
                Id = 100,
                Definition = new Definition
                {
                    Name = "Доп Глубина Внутренняя",
                },
                StorageType = StorageType.Double,
                ForgeId = "autodesk.parameter.aec.revit.family:100-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = 1.2,
                IsReadOnly = true,
            },
            new Parameter
            {
                Id = 101,
                Definition = new Definition
                {
                    Name = "Доп Глубина Наружная",
                },
                StorageType = StorageType.Double,
                ForgeId = "autodesk.parameter.aec.revit.family:101-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = 0.9,
                IsReadOnly = true,
            },
            new Parameter
            {
                Id = 102,
                Definition = new Definition
                {
                    Name = "Generic validation minimum",
                },
                StorageType = StorageType.Double,
                ForgeId = "autodesk.parameter.aec.revit.family:102-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = 1.0,
            },
            new Parameter
            {
                Id = 103,
                Definition = new Definition
                {
                    Name = "Generic validation maximum",
                },
                StorageType = StorageType.Double,
                ForgeId = "autodesk.parameter.aec.revit.family:103-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = 0.8,
            },
        ];
        var forwardOnlyHost = new Element
        {
            Id = wall.Id + 2,
            CategoryId = -2000011,
            Category = "OST_Walls",
        };
        var (disjointDecodedHost, _, disjointBoundary) =
            ExactWallWithOneThroughOpening();
        disjointDecodedHost.Id = wall.Id + 3;
        disjointDecodedHost.CuttingElementIds = [cutter.Id];
        foreach (var point in BoundaryPoints(disjointBoundary))
            point[0] += 10;
        disjointBoundary.BoundingBox![0] += 10;
        disjointBoundary.BoundingBox[3] += 10;
        disjointDecodedHost.BoundingBox![0] += 10;
        disjointDecodedHost.BoundingBox[3] += 10;
        disjointDecodedHost.Location!.StartPoint[0] += 10;
        disjointDecodedHost.Location.EndPoint[0] += 10;
        disjointDecodedHost.Geometry = disjointBoundary;
        var remoteNormalHost = new Element
        {
            Id = wall.Id + 4,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, 3.5, 0, 4, 4.5, 3],
            Geometry = BoxGeometry(0, 3.5, 0, 4, 4.5, 3),
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 4, 0],
                EndPoint = [4, 4, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [cutter.Id],
        };
        var inflatedCommonOpening = commonOpening with
        {
            CentreYFt = 2,
            DepthFt = 5,
        };
        Assert.True(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                    [wall, outerWall], inflatedCommonOpening,
                    out var fullHostValidationOpening));
        Assert.NotNull(fullHostValidationOpening.SteppedProfile);
        Assert.Equal(2.1, fullHostValidationOpening.DepthFt, 12);
        var directedFamilyCutLoop = inflatedCommonOpening with
        {
            DepthFt = 10,
            IsFamilyCutLoop = true,
        };
        Assert.True(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                    [wall, outerWall], directedFamilyCutLoop,
                    out var finiteFamilyCutLoopOpening));
        Assert.False(finiteFamilyCutLoopOpening.IsFamilyCutLoop);
        Assert.NotNull(finiteFamilyCutLoopOpening.Boundary);
        Assert.NotNull(finiteFamilyCutLoopOpening.SteppedProfile);
        Assert.Equal(fullHostValidationOpening.CentreXFt,
            finiteFamilyCutLoopOpening.CentreXFt, 12);
        Assert.Equal(fullHostValidationOpening.CentreYFt,
            finiteFamilyCutLoopOpening.CentreYFt, 12);
        Assert.Equal(fullHostValidationOpening.WidthFt,
            finiteFamilyCutLoopOpening.WidthFt, 12);
        Assert.Equal(fullHostValidationOpening.DepthFt,
            finiteFamilyCutLoopOpening.DepthFt, 12);
        Assert.Equal(fullHostValidationOpening.HeightFt,
            finiteFamilyCutLoopOpening.HeightFt, 12);
        var perpendicularHost = new Element
        {
            Id = wall.Id + 5,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [1, -2, 0, 2, 3, 3],
            Geometry = BoxGeometry(1, -2, 0, 2, 3, 3),
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [1.5, -2, 0],
                EndPoint = [1.5, 3, 0],
            },
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [cutter.Id],
        };
        Assert.False(IfcExporter.TryBuildCommonHostedOpeningGeometry(
            cutter, [1, -0.5, 1, 2, 1.5, 2],
            [wall, outerWall, perpendicularHost], out _));
        Assert.True(IfcExporter
            .TryBuildUniqueExactSteppedMultiHostOpeningFromAuthoredHostProfiles(
                cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                [wall, outerWall, perpendicularHost],
                out var subsetOpening));
        Assert.Equal(fullHostValidationOpening.CentreXFt,
            subsetOpening.CentreXFt, 12);
        Assert.Equal(fullHostValidationOpening.CentreYFt,
            subsetOpening.CentreYFt, 12);
        Assert.Equal(fullHostValidationOpening.WidthFt,
            subsetOpening.WidthFt, 12);
        Assert.Equal(fullHostValidationOpening.DepthFt,
            subsetOpening.DepthFt, 12);
        Assert.Equal(fullHostValidationOpening.HeightFt,
            subsetOpening.HeightFt, 12);
        Assert.True(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                    [wall, outerWall, forwardOnlyHost, disjointDecodedHost,
                        remoteNormalHost],
                    inflatedCommonOpening,
                    out var filteredOpening));
        Assert.NotNull(filteredOpening.SteppedProfile);
        Assert.Equal(2.1, filteredOpening.DepthFt, 12);

        cutter.Parameters = cutter.Parameters.Skip(2).ToList();
        Assert.False(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                    [wall, outerWall, forwardOnlyHost, disjointDecodedHost,
                        remoteNormalHost],
                    inflatedCommonOpening,
                    out _));

        foreach (var point in lowOtherHole.Concat(highOtherHole))
        {
            point[0] = point[0] < 2.75 ? 1.2 : 1.8;
            point[2] = point[2] < 1.5 ? 1 : 1.8;
        }
        Assert.False(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                [wall, outerWall], commonOpening, out _));
        wall.CuttingElementIds = [cutter.Id + 10];
        Assert.False(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [1, -0.5, 1, 2, 1.5, 2],
                [wall, outerWall], commonOpening, out _));
    }

    [Fact]
    public void ExactSteppedMultiHostOpening_ExpandsSerializedInnerProfileAndCoversSourceHole()
    {
        static Parameter Length(int id, string name, double value) =>
            new()
            {
                Id = id,
                Definition = new Definition { Name = name },
                StorageType = StorageType.Double,
                ForgeId =
                    $"autodesk.parameter.aec.revit.family:{id}-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = value,
            };
        static IEnumerable<double[]> BoundaryPoints(
            GeometryData boundary)
        {
            var seen = new HashSet<double[]>(
                ReferenceEqualityComparer.Instance);
            foreach (var face in boundary.Faces)
            {
                foreach (double[] point in face.OuterVertices ?? [])
                    if (seen.Add(point)) yield return point;
                foreach (var ring in face.InnerVertices ?? [])
                    foreach (double[] point in ring)
                        if (seen.Add(point)) yield return point;
            }
        }

        var (innerWall, cutter, innerBoundary) =
            ExactWallWithOneThroughOpening();
        var (outerWall, _, outerBoundary) =
            ExactWallWithOneThroughOpening();
        outerWall.Id = innerWall.Id + 1;
        innerWall.CuttingElementIds = [cutter.Id];
        outerWall.CuttingElementIds = [cutter.Id];
        foreach (double[] point in BoundaryPoints(outerBoundary))
        {
            point[1] += 1.2;
            if (Math.Abs(point[0] - 1) < 1e-12)
                point[0] = 0.9;
            else if (Math.Abs(point[0] - 2) < 1e-12)
                point[0] = 2.1;
            if (Math.Abs(point[2] - 2) < 1e-12)
                point[2] = 2.1;
        }
        outerBoundary.BoundingBox![1] += 1.2;
        outerBoundary.BoundingBox[4] += 1.2;
        outerWall.BoundingBox![1] += 1.2;
        outerWall.BoundingBox[4] += 1.2;
        outerWall.Location!.StartPoint[1] += 1.2;
        outerWall.Location.EndPoint[1] += 1.2;
        outerWall.Geometry = outerBoundary;
        cutter.Parameters =
        [
            Length(1, "First exact segment", 1),
            Length(2, "Second exact segment", 1.2),
        ];
        var innerPrimitive = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0.6,
            AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2.2,
            BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);

        Assert.True(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [innerWall, outerWall], innerPrimitive,
                out var stepped));
        Assert.False(stepped.IsExactParameterizedReveal);
        Assert.Equal(1.2, stepped.WidthFt, 12);
        Assert.Equal(1.1, stepped.HeightFt, 12);
        Assert.Equal(1,
            stepped.SteppedProfile!.Value.InnerWidthFt, 12);
        Assert.Equal(1,
            stepped.SteppedProfile.Value.InnerHeightFt, 12);
        Assert.Equal(0.5,
            stepped.SteppedProfile.Value.BreakpointNormalFt, 12);
        Assert.True(stepped.SteppedProfile.Value.InnerAtMinimum);
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                stepped));
        Assert.True(
            IfcExporter.TryGetExactRectangularWallGrossBoundary(
                outerBoundary, outerWall.Location!, 1,
                outerWall.BoundingBox!, out _, out var outerHole));
        Assert.True(IfcExporter.ExactSteppedOpeningBoundaryMatchesWallHole(
            stepped.Boundary!, outerHole));

        List<Parameter> genericDepthParameters = cutter.Parameters;
        cutter.Parameters = [];
        var exactSerializedInnerPrimitive = innerPrimitive with
        {
            IsExactSerializedDefinition = true,
        };
        Assert.True(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [innerWall, outerWall], exactSerializedInnerPrimitive,
                out var serializedDepthStepped));
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                serializedDepthStepped));
        Assert.True(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [innerWall, outerWall], innerPrimitive with
                {
                    IsExactAuthoredMultiHostEnvelope = true,
                },
                out var authoredDepthStepped));
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                authoredDepthStepped));

        static void SetWallNormalSpan(
            Element targetWall, GeometryData targetBoundary,
            double minimumNormal, double maximumNormal)
        {
            foreach (double[] point in BoundaryPoints(targetBoundary))
                point[1] = point[1] < 0
                    ? minimumNormal : maximumNormal;
            targetBoundary.BoundingBox![1] = minimumNormal;
            targetBoundary.BoundingBox[4] = maximumNormal;
            targetWall.BoundingBox![1] = minimumNormal;
            targetWall.BoundingBox[4] = maximumNormal;
            double centreNormal =
                (minimumNormal + maximumNormal) / 2;
            targetWall.Location!.StartPoint[1] = centreNormal;
            targetWall.Location.EndPoint[1] = centreNormal;
            targetWall.Layers![0].ThicknessMm =
                (maximumNormal - minimumNormal) * 304.8;
        }

        var (thinInnerWall, thinCutter, thinInnerBoundary) =
            ExactWallWithOneThroughOpening();
        var (thinOuterWall, _, thinOuterBoundary) =
            ExactWallWithOneThroughOpening();
        SetWallNormalSpan(
            thinInnerWall, thinInnerBoundary, 0.3, 0.5);
        SetWallNormalSpan(
            thinOuterWall, thinOuterBoundary, 0.6, 0.8);
        thinOuterWall.Id = thinInnerWall.Id + 1;
        thinInnerWall.CuttingElementIds = [thinCutter.Id];
        thinOuterWall.CuttingElementIds = [thinCutter.Id];
        foreach (double[] point in BoundaryPoints(thinOuterBoundary))
        {
            if (Math.Abs(point[0] - 1) < 1e-12)
                point[0] = 0.9;
            else if (Math.Abs(point[0] - 2) < 1e-12)
                point[0] = 2.1;
            if (Math.Abs(point[2] - 2) < 1e-12)
                point[2] = 2.1;
        }
        thinCutter.Parameters =
        [
            Length(10, "Доп Глубина Внутренняя", 0.4),
            Length(11, "Доп Глубина Наружная", 0.2),
            Length(12, "Проем_Наружный_Ширина", 1),
            Length(13, "Проем_Наружный_Высота", 1),
            Length(14, "Подоконник_Проем_Ширина", 1.2),
            Length(15, "Четверть Сверху", 0.1),
            Length(16, "Вставка окна", 0.2),
            Length(17, "Вставка_Расчет", 0.45),
        ];
        var sourceVerifiedEnvelope = innerPrimitive with
        {
            IsExactAuthoredMultiHostEnvelope = true,
        };
        Assert.True(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                thinCutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [thinInnerWall, thinOuterWall], sourceVerifiedEnvelope,
                out var contractedDirectedStepped));
        Assert.True(
            contractedDirectedStepped.IsExactParameterizedReveal);
        Assert.Equal(0.6, contractedDirectedStepped.DepthFt, 12);
        Assert.Equal(0.6, contractedDirectedStepped.CentreYFt, 12);
        Assert.Equal(0.5,
            contractedDirectedStepped.SteppedProfile!
                .Value.BreakpointNormalFt, 12);
        Assert.True(
            contractedDirectedStepped.SteppedProfile.Value.InnerAtMinimum);
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                contractedDirectedStepped));
        thinCutter.Parameters.Add(
            Length(18, "Проем_Наружный_Ширина", 1));
        Assert.True(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                thinCutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [thinInnerWall, thinOuterWall], sourceVerifiedEnvelope,
                out var ambiguousProfileFallback));
        Assert.False(
            ambiguousProfileFallback.IsExactParameterizedReveal);
        Assert.Equal(2.2, ambiguousProfileFallback.DepthFt, 12);

        innerWall.CuttingElementIds = [];
        cutter.SerializedHostId = innerWall.Id;
        Assert.True(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                    [innerWall, outerWall],
                    exactSerializedInnerPrimitive,
                    out var serializedPrimaryValidation));
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(
                serializedPrimaryValidation));
        cutter.SerializedHostId = innerWall.Id + 1000;
        Assert.False(
            IfcExporter
                .TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                    [innerWall, outerWall],
                    exactSerializedInnerPrimitive, out _));
        cutter.SerializedHostId = null;
        innerWall.CuttingElementIds = [cutter.Id];
        double[] outerWallBounds = outerWall.BoundingBox!;
        outerWall.BoundingBox = null;
        Assert.False(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [innerWall, outerWall], exactSerializedInnerPrimitive,
                out _));
        outerWall.BoundingBox = outerWallBounds;
        cutter.Parameters =
        [
            Length(3, "Доп Глубина Внутренняя", 1.2),
        ];
        Assert.False(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [innerWall, outerWall], exactSerializedInnerPrimitive,
                out _));
        cutter.Parameters = genericDepthParameters;

        var secondCutterId = cutter.Id + 1;
        outerWall.CuttingElementIds = [cutter.Id, secondCutterId];
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [outerWall.Id] = [cutter.Id, secondCutterId],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId,
                IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [outerWall.Id] =
            [
                (cutter.Id, stepped),
                (secondCutterId, stepped),
            ],
        };
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    outerWall, outerWall.BoundingBox!, outerBoundary,
                    emittedCutterIds, emittedOperands, null,
                    out var gross, out var cutterIds));
        Assert.Equal(outerWall.CuttingElementIds, cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            outerWall, outerWall.BoundingBox!, gross));

        emittedOperands[outerWall.Id][0] =
            (cutter.Id, stepped with
            {
                Boundary = null,
            });
        emittedOperands[outerWall.Id][1] =
            (secondCutterId, stepped with
            {
                Boundary = null,
            });
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                    outerWall, outerWall.BoundingBox!, outerBoundary,
                    emittedCutterIds, emittedOperands, null,
                    out _, out _));

        cutter.Parameters = [];
        Assert.False(
            IfcExporter.TryBuildExactSteppedMultiHostOpeningGeometry(
                cutter, null, [0.9, -0.5, 1, 2.1, 1.7, 2.1],
                [innerWall, outerWall], innerPrimitive, out _));
    }

    [Fact]
    public void ExactQuarteredAdditionalDepthReveal_UsesReadonlyCalculatedFamilyLengths()
    {
        static Parameter Length(int id, string name, double value) =>
            new()
            {
                Id = id,
                Definition = new Definition { Name = name },
                StorageType = StorageType.Double,
                ForgeId =
                    $"autodesk.parameter.aec.revit.family:{id}-1.0.0",
                SpecType = "autodesk.spec.aec:length-2.0.0",
                Value = value,
                IsReadOnly = true,
            };

        var wall = new Element
        {
            Id = 1500,
            Parameters = [WallWidthParameter(0.2)],
            CuttingElementIds = [1501],
        };
        var cutter = new Element
        {
            Id = 1501,
            SerializedHostId = wall.Id,
            Transform = new InstanceTransform
            {
                Origin = [1.5, 0.5, 1],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
            Parameters =
            [
                Length(1, "Доп Глубина Внутренняя", 0.4),
                Length(2, "Доп Глубина Наружная", 0.6),
                Length(3, "Проем_Наружный_Ширина", 1),
                Length(4, "Проем_Наружный_Высота", 1),
                Length(5, "Подоконник_Проем_Ширина", 1.2),
                Length(6, "Четверть Сверху", 0.1),
                Length(7, "Вставка окна", 0.2),
                Length(8, "Вставка_Расчет", 0.7),
            ],
        };
        var outerPrimitive = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0.25,
            AxisX: 1, AxisY: 0,
            WidthFt: 1.2, DepthFt: 0.3,
            BaseZFt: 1, HeightFt: 1.1,
            ExactDepth: true);

        Assert.True(
            IfcExporter.TryBuildExactQuarteredAdditionalDepthRevealOpening(
                cutter, wall, [wall],
                outerPrimitive, out var outerOpening));
        Assert.Equal(1.5, outerOpening.CentreXFt, 12);
        Assert.Equal(0.6, outerOpening.CentreYFt, 12);
        Assert.Equal(1.2, outerOpening.WidthFt, 12);
        Assert.Equal(1, outerOpening.DepthFt, 12);
        Assert.Equal(1.1, outerOpening.HeightFt, 12);
        Assert.Equal(10, outerOpening.Boundary!.Faces.Count);
        Assert.Equal(1, outerOpening.SteppedProfile!.Value.InnerWidthFt, 12);
        Assert.Equal(1, outerOpening.SteppedProfile.Value.InnerHeightFt, 12);
        Assert.Equal(0.5,
            outerOpening.SteppedProfile.Value.BreakpointNormalFt, 12);
        Assert.False(outerOpening.SteppedProfile.Value.InnerAtMinimum);

        var innerPrimitive = outerPrimitive with
        {
            CentreYFt = 0.9,
            WidthFt = 1,
            DepthFt = 0.4,
            HeightFt = 1,
        };
        Assert.True(
            IfcExporter.TryBuildExactQuarteredAdditionalDepthRevealOpening(
                cutter, wall, [wall],
                innerPrimitive, out var innerOpening));
        Assert.Equal(outerOpening.CentreXFt, innerOpening.CentreXFt, 12);
        Assert.Equal(outerOpening.CentreYFt, innerOpening.CentreYFt, 12);
        Assert.Equal(outerOpening.DepthFt, innerOpening.DepthFt, 12);
        Assert.Equal(
            outerOpening.SteppedProfile.Value.BreakpointNormalFt,
            innerOpening.SteppedProfile!.Value.BreakpointNormalFt, 12);

        var (validationWall, _, _) = ExactWallWithOneThroughOpening();
        validationWall.Id = wall.Id;
        validationWall.CuttingElementIds = [cutter.Id];
        validationWall.BoundingBox = [0, 0.2, 0, 4, 0.4, 3];
        validationWall.Geometry!.BoundingBox = (double[])validationWall.BoundingBox.Clone();
        validationWall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0.3, 0],
            EndPoint = [4, 0.3, 0],
        };
        validationWall.Layers =
        [
            new MaterialLayer
            {
                LayerIndex = 0,
                ThicknessMm = 0.2 * 304.8,
            },
        ];
        foreach (double[] point in validationWall.Geometry!.Faces
                     .SelectMany(face => (face.OuterVertices ?? [])
                         .Concat((face.InnerVertices ?? [])
                             .SelectMany(ring => ring))))
        {
            point[1] = point[1] < 0 ? 0.2 : 0.4;
            if (point[0] == 1) point[0] = 0.9;
            else if (point[0] == 2) point[0] = 2.1;
            if (point[2] == 2) point[2] = 2.1;
        }
        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            validationWall, out var validationBoundary));
        Assert.True(
            IfcExporter.TryGetExactStraightWallGrossBoundaryAndOpenings(
                validationBoundary, validationWall.Location!, 0.2,
                validationWall.BoundingBox!, out _, out var validationHoles, out _));
        var validationHole = Assert.Single(validationHoles);
        Assert.True(
            IfcExporter.ExactParameterizedRevealOpeningProfileMatchesWallHole(
                innerOpening, validationHole));
        Assert.True(
            IfcExporter.ExactParameterizedRevealOpeningProfileMatchesWallSide(
                innerOpening, validationHole));
        var secondaryWall = new Element { Id = wall.Id + 10 };
        Assert.True(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [secondaryWall, validationWall], innerPrimitive,
                out var routedOpening));
        Assert.Equal(innerOpening.CentreXFt, routedOpening.CentreXFt, 12);
        Assert.Equal(innerOpening.CentreYFt, routedOpening.CentreYFt, 12);
        Assert.Equal(innerOpening.DepthFt, routedOpening.DepthFt, 12);
        Parameter calculatedInsertion = cutter.Parameters.Single(parameter =>
            parameter.Definition?.Name == "Вставка_Расчет");
        calculatedInsertion.Value = 0.65;
        Assert.False(
            IfcExporter.TryBuildExactQuarteredAdditionalDepthRevealOpening(
                cutter, wall, [wall], innerPrimitive, out _));
        Assert.False(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [secondaryWall, validationWall], innerPrimitive,
                out _));

        var (alignmentValidationWall, _, _) = ExactWallWithOneThroughOpening();
        alignmentValidationWall.Id = wall.Id + 11;
        alignmentValidationWall.CuttingElementIds = [cutter.Id];
        alignmentValidationWall.BoundingBox = [0, 0.2, 0, 4, 0.4, 3];
        alignmentValidationWall.Geometry!.BoundingBox =
            (double[])alignmentValidationWall.BoundingBox.Clone();
        alignmentValidationWall.Location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0.3, 0],
            EndPoint = [4, 0.3, 0],
        };
        alignmentValidationWall.Layers =
        [
            new MaterialLayer
            {
                LayerIndex = 0,
                ThicknessMm = 0.2 * 304.8,
            },
        ];
        foreach (double[] point in alignmentValidationWall.Geometry.Faces
                     .SelectMany(face => (face.OuterVertices ?? [])
                         .Concat((face.InnerVertices ?? [])
                             .SelectMany(ring => ring))))
        {
            point[1] = point[1] < 0 ? 0.2 : 0.4;
            if (point[0] == 1) point[0] = 0.9;
            else if (point[0] == 2) point[0] = 2.1;
            if (point[2] == 2) point[2] = 2.1;
        }
        validationWall.BoundingBox![1] = 0.1;
        validationWall.BoundingBox[4] = 0.3;
        validationWall.Geometry!.BoundingBox =
            (double[])validationWall.BoundingBox.Clone();
        validationWall.Location!.StartPoint[1] = 0.2;
        validationWall.Location.EndPoint[1] = 0.2;
        foreach (double[] point in validationWall.Geometry.Faces
                     .SelectMany(face => (face.OuterVertices ?? [])
                         .Concat((face.InnerVertices ?? [])
                             .SelectMany(ring => ring))))
            point[1] -= 0.1;
        Assert.True(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter,
                [secondaryWall, validationWall, alignmentValidationWall],
                innerPrimitive, out var mismatchRoutedOpening));
        Assert.Equal(innerOpening.CentreXFt,
            mismatchRoutedOpening.CentreXFt, 12);
        Assert.Equal(0.4, mismatchRoutedOpening.CentreYFt, 12);
        Assert.Equal(0.3,
            mismatchRoutedOpening.SteppedProfile!.Value
                .BreakpointNormalFt, 12);
        Assert.False(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [secondaryWall, wall], innerPrimitive, out _));
        calculatedInsertion.Value = 0.7;
        Assert.False(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [secondaryWall, wall], innerPrimitive, out _));
        Assert.False(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [validationWall, validationWall], innerPrimitive, out _));

        static Element ExactIntersectingWall(
            int id, IReadOnlyList<int> cutterIds,
            double minimumX, double maximumX,
            double minimumY, double maximumY)
        {
            double centreY = (minimumY + maximumY) / 2;
            double width = maximumY - minimumY;
            return new Element
            {
                Id = id,
                BoundingBox =
                    [minimumX, minimumY, 1.2,
                        maximumX, maximumY, 1.8],
                Geometry = BoxGeometry(
                    minimumX, minimumY, 1.2,
                    maximumX, maximumY, 1.8),
                Location = new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [minimumX, centreY, 0],
                    EndPoint = [maximumX, centreY, 0],
                },
                Parameters = [WallWidthParameter(width)],
                Layers =
                [
                    new MaterialLayer
                    {
                        LayerIndex = 0,
                        ThicknessMm = width * 304.8,
                    },
                ],
                CuttingElementIds = cutterIds.ToList(),
            };
        }
        var intersectingWall = ExactIntersectingWall(
            wall.Id + 20, [cutter.Id],
            1.3, 1.7, 0.25, 0.35);
        Assert.True(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [wall, intersectingWall], innerPrimitive,
                out var intersectionRoutedOpening));
        Assert.Equal(innerOpening.CentreYFt,
            intersectionRoutedOpening.CentreYFt, 12);
        var remoteWall = ExactIntersectingWall(
            wall.Id + 21, [cutter.Id],
            1.3, 1.7, 2.25, 2.35);
        Assert.False(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [wall, remoteWall], innerPrimitive, out _));

        static Parameter SharedLength(
            int id, string guid, double value) =>
            new()
            {
                Id = id,
                Guid = Guid.Parse(guid),
                StorageType = StorageType.Double,
                Value = value,
            };
        var peer = new Element
        {
            Id = cutter.Id + 1,
            CategoryId = -2000014,
            SerializedHostId = wall.Id,
            BoundingBox = [2.4, 0.1, 1, 3.6, 0.4, 2.1],
            Geometry = BoxGeometry(2.4, 0.1, 1, 3.6, 0.4, 2.1),
            Transform = new InstanceTransform
            {
                Origin = [3, 0.5, 1],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
            Parameters = cutter.Parameters.Concat(
            [
                SharedLength(20,
                    "cef807ab-6704-4013-8d86-96c5a31b2d1e", 1.2),
                SharedLength(21,
                    "e31864ac-8135-4bea-a7d3-f2a96b81a6ea", 1.1),
                SharedLength(22,
                    "e140a591-7a59-4036-b7e4-074fbd8222ff", 0.3),
            ]).ToList(),
        };
        var peerPrimaryWall = new Element
        {
            Id = wall.Id,
            Parameters = [WallWidthParameter(0.2)],
            CuttingElementIds = [cutter.Id, peer.Id],
        };
        var peerValidationWall = ExactIntersectingWall(
            wall.Id + 22, [cutter.Id, peer.Id],
            2.8, 3.2, 0.25, 0.35);
        var peerElements = new Dictionary<int, Element>
        {
            [cutter.Id] = cutter,
            [peer.Id] = peer,
        };
        var sharedInverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [peerPrimaryWall.Id, peerValidationWall.Id],
            [peer.Id] = [peerPrimaryWall.Id, peerValidationWall.Id],
        };
        Assert.True(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [peerPrimaryWall, peerValidationWall],
                innerPrimitive, out var peerRoutedOpening,
                peerElements, sharedInverseHosts));
        Assert.Equal(innerOpening.CentreXFt,
            peerRoutedOpening.CentreXFt, 12);
        Assert.False(IfcExporter
            .TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                cutter, [peerPrimaryWall, peerValidationWall],
                innerPrimitive, out _, peerElements,
                new Dictionary<int, List<int>>
                {
                    [cutter.Id] =
                        [peerPrimaryWall.Id, peerValidationWall.Id],
                    [peer.Id] = [peerPrimaryWall.Id],
                }));

        cutter.Parameters.Add(
            Length(9, "Доп Глубина Внутренняя", 0.4));
        Assert.False(
            IfcExporter.TryBuildExactQuarteredAdditionalDepthRevealOpening(
                cutter, wall, [wall], outerPrimitive, out _));
        cutter.Parameters.RemoveAt(cutter.Parameters.Count - 1);
        Assert.False(
            IfcExporter.TryBuildExactQuarteredAdditionalDepthRevealOpening(
                cutter, wall, [wall],
                outerPrimitive with { WidthFt = 1.1 }, out _));
        cutter.Transform!.Origin[0] += 0.1;
        Assert.False(
            IfcExporter.TryBuildExactQuarteredAdditionalDepthRevealOpening(
                cutter, wall, [wall], outerPrimitive, out _));
    }

    [Fact]
    public void CompleteOpenTwentyFiveFaceOpposedSidePocketGate_ReconstructsGrossAndCorrectsOnlyPocketWriters()
    {
        const int wallId = 870321;
        const int firstPocketCutterId = 550007;
        const int secondPocketCutterId = 660019;
        const int doorCutterId = 440113;
        var fixture = CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
            wallId, firstPocketCutterId, secondPocketCutterId,
            doorCutterId);
        var doorBeforeGate = Assert.Single(
            fixture.EmittedOperands[wallId],
            item => item.CutterId == doorCutterId).Operand;
        Assert.NotNull(doorBeforeGate.Boundary);
        Assert.Equal(6, doorBeforeGate.Boundary.Faces.Count);
        Assert.True(IfcExporter
            .TryGetExactVerticalRectangularPrismSweptOpeningAlignedToDefinition(
                doorBeforeGate.Boundary, doorBeforeGate, out var alignedDoor));
        Assert.Equal(2, alignedDoor.WidthFt, 12);
        Assert.Equal(4, alignedDoor.DepthFt, 12);

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenTwentyFiveFaceOpposedSidePocketsAndThroughOpening(
                fixture.Wall, fixture.Wall.BoundingBox!, fixture.Rebuilt,
                fixture.Elements, fixture.InverseHosts,
                fixture.EmittedIds, fixture.EmittedOperands,
                fixture.StandaloneIds,
                out var gross, out var cutterIds,
                out var correctedPocketOperands));

        Assert.Equal(
            [firstPocketCutterId, secondPocketCutterId, doorCutterId],
            cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                gross, fixture.Wall.Location!, 1,
                fixture.Wall.BoundingBox!, out var plan,
                out double baseZ, out double height,
                out string grossReason), grossReason);
        Assert.Equal(4, plan.Count);
        Assert.Equal(0, baseZ, 12);
        Assert.Equal(3, height, 12);

        Assert.Equal(2, correctedPocketOperands.Count);
        var first = Assert.Single(correctedPocketOperands, item =>
            item.CutterId == firstPocketCutterId).Operand;
        var second = Assert.Single(correctedPocketOperands, item =>
            item.CutterId == secondPocketCutterId).Operand;
        Assert.DoesNotContain(correctedPocketOperands,
            item => item.CutterId == doorCutterId);
        Assert.Equal(3.5, first.CentreXFt, 12);
        Assert.Equal(-0.2, first.CentreYFt, 12);
        Assert.Equal(5.5, second.CentreXFt, 12);
        Assert.Equal(0.2, second.CentreYFt, 12);
        foreach (var operand in new[] { first, second })
        {
            Assert.True(operand.ExactDepth);
            Assert.True(operand.IsExactSerializedDefinition);
            Assert.Equal(1, operand.AxisX, 12);
            Assert.Equal(0, operand.AxisY, 12);
            Assert.Equal(1, operand.WidthFt, 12);
            Assert.Equal(0.6, operand.DepthFt, 12);
            Assert.Equal(1, operand.BaseZFt, 12);
            Assert.Equal(1, operand.HeightFt, 12);
            Assert.NotNull(operand.Boundary);
            Assert.True(IfcExporter
                .TryGetExactVerticalRectangularPrismSweptOpening(
                    operand.Boundary, out var recovered));
            Assert.Equal(operand.CentreXFt, recovered.CentreXFt, 12);
            Assert.Equal(operand.CentreYFt, recovered.CentreYFt, 12);
            Assert.Equal(operand.WidthFt, recovered.WidthFt, 12);
            Assert.Equal(operand.DepthFt, recovered.DepthFt, 12);
            Assert.Equal(operand.BaseZFt, recovered.BaseZFt, 12);
            Assert.Equal(operand.HeightFt, recovered.HeightFt, 12);
        }

        var emitted = fixture.EmittedOperands[wallId];
        Assert.Equal(0, Assert.Single(emitted, item =>
            item.CutterId == firstPocketCutterId).Operand.CentreYFt, 12);
        Assert.Equal(0, Assert.Single(emitted, item =>
            item.CutterId == secondPocketCutterId).Operand.CentreYFt, 12);
        var doorAfterGate = Assert.Single(emitted, item =>
            item.CutterId == doorCutterId).Operand;
        Assert.Equal(fixture.DoorOperand, doorAfterGate);
        Assert.Equal(doorBeforeGate, doorAfterGate);
        Assert.Same(doorBeforeGate.Boundary, doorAfterGate.Boundary);

        double diagonal = Math.Sqrt(0.5);
        var diagonalPocketBoundary = DiagonalWallFrameBoxGeometry(
            3, -0.5, 1, 4, 0.1, 2);
        var diagonalPocketDefinition =
            new IfcExporter.HostedOpeningGeometry(
                CentreXFt: 3.7 * diagonal,
                CentreYFt: 3.3 * diagonal,
                AxisX: diagonal, AxisY: diagonal,
                WidthFt: 1, DepthFt: 0.6,
                BaseZFt: 1, HeightFt: 1,
                ExactDepth: true,
                Boundary: diagonalPocketBoundary,
                IsExactSerializedDefinition: true);
        Assert.True(IfcExporter
            .TryGetExactVerticalRectangularPrismSweptOpening(
                diagonalPocketBoundary, out var ordinaryDecoded));
        Assert.Equal(0.6, ordinaryDecoded.WidthFt, 12);
        Assert.Equal(1, ordinaryDecoded.DepthFt, 12);
        Assert.True(IfcExporter
            .TryGetExactVerticalRectangularPrismSweptOpeningAlignedToDefinition(
                diagonalPocketBoundary, diagonalPocketDefinition,
                out var alignedDecoded));
        Assert.Equal(diagonal, alignedDecoded.AxisX, 12);
        Assert.Equal(diagonal, alignedDecoded.AxisY, 12);
        Assert.Equal(1, alignedDecoded.WidthFt, 12);
        Assert.Equal(0.6, alignedDecoded.DepthFt, 12);
        Assert.Null(alignedDecoded.Boundary);
    }

    [Fact]
    public void CompleteOpenTwentyFiveFaceOpposedSidePocketGate_FailsClosedOnExactContractMutations()
    {
        const int wallId = 870421;
        const int firstPocketCutterId = 550107;
        const int secondPocketCutterId = 660119;
        const int doorCutterId = 440213;

        bool Gate(CompleteOpenTwentyFiveFaceOpposedSidePocketData fixture,
            GeometryData? rebuilt = null) => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenTwentyFiveFaceOpposedSidePocketsAndThroughOpening(
                fixture.Wall, fixture.Wall.BoundingBox!,
                rebuilt ?? fixture.Rebuilt,
                fixture.Elements, fixture.InverseHosts,
                fixture.EmittedIds, fixture.EmittedOperands,
                fixture.StandaloneIds,
                out _, out _, out _);

        var damagedTopology =
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId);
        damagedTopology.Wall.Geometry!.Faces[6]
            .OuterVertices![0][0] += 0.125;
        Assert.False(Gate(damagedTopology));

        var damagedAlternative =
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId);
        damagedAlternative.Wall.Geometry!.Faces[19]
            .AlternativeOuterVertices![3][1] = 0;
        Assert.False(Gate(damagedAlternative));

        var damagedRebuilt =
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId);
        var mismatchedRebuilt = CloneGeometryData(damagedRebuilt.Rebuilt);
        mismatchedRebuilt.Faces[0].OuterVertices![0][0] += 0.125;
        Assert.False(Gate(damagedRebuilt, mismatchedRebuilt));

        var ambiguousBijection =
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId, ambiguousLegacyBijection: true);
        Assert.False(Gate(ambiguousBijection));

        var nonCoplanarInnerProfile =
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId);
        nonCoplanarInnerProfile.Wall.Geometry!.Faces[2]
            .InnerVertices![1][0][1] = -0.4;
        Assert.False(Gate(nonCoplanarInnerProfile));

        var throughOppositeSides =
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId);
        foreach (GeoFace face in throughOppositeSides.Wall.Geometry!.Faces
                     .Skip(6).Take(6))
            foreach (double[] point in face.OuterVertices!)
                if (point[1] == 0.1) point[1] = 0.5;
        foreach (GeoFace face in throughOppositeSides.Wall.Geometry.Faces
                     .Skip(12).Take(6))
            foreach (double[] point in face.OuterVertices!)
                if (point[1] == -0.1) point[1] = -0.5;
        for (int index = 0; index < 2; index++)
        {
            int cutterId = index == 0
                ? firstPocketCutterId : secondPocketCutterId;
            Element cutter = throughOppositeSides.Elements[cutterId];
            cutter.Parameters.Single(parameter => parameter.Guid ==
                Guid.Parse("e140a591-7a59-4036-b7e4-074fbd8222ff"))
                .Value = 1.0;
            Assert.True(IfcExporter.TryBuildSerializedHostedOpeningGeometry(
                cutter, throughOppositeSides.Elements[991001],
                out var widenedLegacy));
            throughOppositeSides.EmittedOperands[wallId][index] =
                (cutterId, widenedLegacy);
        }
        Assert.False(Gate(throughOppositeSides));

        Assert.True(Gate(
            CompleteOpenTwentyFiveFaceOpposedSidePocketFixture(
                wallId, firstPocketCutterId, secondPocketCutterId,
                doorCutterId)));
    }

    [Fact]
    public void CompleteOpenTenFaceQuarteredReveal_ReconstructsExactWriterAndPromotesWall()
    {
        var fixture = CompleteOpenTenFaceQuarteredRevealFixture();

        Assert.True(
            IfcExporter
                .TryBuildExactQuarteredRevealOpeningFromCompleteOpenTenFaceHoleWithDetachedPatch(
                    fixture.Window, fixture.Hosts, fixture.Elements,
                    fixture.InverseHosts, out var opening));
        Assert.True(opening.ExactDepth);
        Assert.True(opening.IsExactParameterizedReveal);
        Assert.False(opening.IsFamilyCutLoop);
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(0.1, opening.CentreYFt, 12);
        Assert.Equal(1, opening.WidthFt, 12);
        Assert.Equal(3.2, opening.DepthFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(1, opening.HeightFt, 12);
        Assert.Equal(0.8, opening.SteppedProfile!.Value.InnerWidthFt, 12);
        Assert.Equal(0.8, opening.SteppedProfile.Value.InnerHeightFt, 12);
        Assert.Equal(0.7,
            opening.SteppedProfile.Value.BreakpointNormalFt, 12);
        Assert.False(opening.SteppedProfile.Value.InnerAtMinimum);
        Assert.Equal(10, opening.Boundary!.Faces.Count);
        Assert.Equal(16, opening.Boundary.Faces
            .SelectMany(face => face.OuterVertices!)
            .Select(point => string.Join(',', point.Select(value =>
                Math.Round(value, 12))))
            .Distinct().Count());
        Assert.Equal(28, opening.Boundary.Faces.Sum(face =>
            face.OuterVertices!.Count - 2));
        Assert.True(
            IfcExporter.ExactSteppedOpeningBoundaryMatchesDefinition(opening));

        var cutterIds = fixture.Cutters.Select(cutter => cutter.Id).ToList();
        var emittedIds = new Dictionary<int, List<int>>
        {
            [fixture.TargetWall.Id] = cutterIds,
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId,
                IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [fixture.TargetWall.Id] =
            [
                (fixture.Window.Id, opening),
                (fixture.Cutters[1].Id,
                    DisjointOpening(5.2)),
                (fixture.Cutters[2].Id,
                    DisjointOpening(5.8)),
                (fixture.Cutters[3].Id,
                    DisjointOpening(6.4)),
            ],
        };
        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            fixture.TargetWall, fixture.TargetWall.BoundingBox!,
            fixture.Rebuilt, fixture.Elements,
            fixture.Hosts.Select(host => host.Id).ToHashSet(),
            fixture.InverseHosts, null,
            emittedIds, emittedOperands, null,
            out var gross, out var promotedCutterIds));
        Assert.Equal(cutterIds, promotedCutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            fixture.TargetWall, fixture.TargetWall.BoundingBox!, gross));

        static IfcExporter.HostedOpeningGeometry DisjointOpening(
            double centreX) => new(
            CentreXFt: centreX, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 0.2, DepthFt: 2,
            BaseZFt: 0.4, HeightFt: 0.4,
            ExactDepth: true);
    }

    [Fact]
    public void CompleteOpenTenFaceQuarteredReveal_FailsClosedWhenAuthorityChanges()
    {
        static bool Builds(CompleteOpenTenFaceQuarteredRevealData fixture) =>
            IfcExporter
                .TryBuildExactQuarteredRevealOpeningFromCompleteOpenTenFaceHoleWithDetachedPatch(
                    fixture.Window, fixture.Hosts, fixture.Elements,
                    fixture.InverseHosts, out _);

        var closed = CompleteOpenTenFaceQuarteredRevealFixture();
        closed.TargetWall.Geometry!.BrepSolids![0].IsClosed = true;
        Assert.False(Builds(closed));

        var ownedPatch = CompleteOpenTenFaceQuarteredRevealFixture();
        ownedPatch.TargetWall.Geometry!.BrepSolids![0].FaceIndices.Add(10);
        Assert.False(Builds(ownedPatch));

        var movedRedundantPoint = CompleteOpenTenFaceQuarteredRevealFixture();
        movedRedundantPoint.TargetWall.Geometry!.Faces[7]
            .AlternativeOuterVertices![2][1] = -0.4;
        Assert.False(Builds(movedRedundantPoint));

        var incompleteInverse = CompleteOpenTenFaceQuarteredRevealFixture();
        incompleteInverse.InverseHosts[incompleteInverse.Window.Id]
            .RemoveAt(incompleteInverse.Hosts.Count - 1);
        Assert.False(Builds(incompleteInverse));

        var duplicatePrimaryReference =
            CompleteOpenTenFaceQuarteredRevealFixture();
        Element primary = duplicatePrimaryReference.Hosts.Single(host =>
            host.Id == duplicatePrimaryReference.Window.SerializedHostId);
        primary.References!.Add(duplicatePrimaryReference.Window.Id);
        Assert.False(Builds(duplicatePrimaryReference));

        var mismatchedHost = CompleteOpenTenFaceQuarteredRevealFixture();
        mismatchedHost.Window.HostId = mismatchedHost.Hosts[^1].Id;
        Assert.False(Builds(mismatchedHost));

        var duplicateParameter = CompleteOpenTenFaceQuarteredRevealFixture();
        duplicateParameter.Window.Parameters.Add(
            duplicateParameter.Window.Parameters[1]);
        Assert.False(Builds(duplicateParameter));

        var conflictingFamilyType = CompleteOpenTenFaceQuarteredRevealFixture();
        const int conflictingFamilyTypeId = 97922;
        conflictingFamilyType.Elements.Add(conflictingFamilyTypeId, new Element
        {
            Id = conflictingFamilyTypeId,
            TypeId = conflictingFamilyTypeId,
            FamilyCutGeometry = BoxGeometry(0, 0, 0, 1, 1, 1),
        });
        conflictingFamilyType.Window.Parameters.Add(new Parameter
        {
            Id = -1002050,
            Definition = new Definition { Name = "ELEM_TYPE_PARAM" },
            StorageType = StorageType.ElementId,
            Value = conflictingFamilyTypeId,
        });
        Assert.False(Builds(conflictingFamilyType));

        var selfFamilyType = CompleteOpenTenFaceQuarteredRevealFixture();
        selfFamilyType.Window.Parameters[0].Value = selfFamilyType.Window.Id;
        Assert.False(Builds(selfFamilyType));

        var familyCutAuthority = CompleteOpenTenFaceQuarteredRevealFixture();
        familyCutAuthority.MappedSymbol.FamilyCutGeometry =
            BoxGeometry(0, 0, 0, 1, 1, 1);
        Assert.False(Builds(familyCutAuthority));
    }

    [Fact]
    public void GrossWallFromAuthoredPlan_AcceptsSingleExactParameterizedSteppedOpening()
    {
        var (wall, cutter, _) = ExactWallWithOneThroughOpening();
        wall.Parameters.Add(new Parameter
        {
            Id = -1001111,
            StorageType = StorageType.Double,
            Value = 0.0,
        });
        wall.CuttingElementIds = [];
        var outerOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 1.2, DepthFt: 2,
            BaseZFt: 1, HeightFt: 1.1,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening,
            innerWidthFt: 1,
            innerHeightFt: 1,
            breakpointNormalFt: 0,
            innerAtMinimum: true,
            out var openingBoundary));
        var opening = outerOpening with
        {
            Boundary = openingBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                1, 1, 0, true),
            IsExactParameterizedReveal = true,
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, opening)],
        };

        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out var grossBoundary, out var cutterIds));
        Assert.Equal(6, grossBoundary.Faces.Count);
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                grossBoundary, wall.Location!, 1, wall.BoundingBox!,
                out _, out _, out _, out string definitionReason));
        Assert.Equal("exact", definitionReason);

        wall.Parameters.RemoveAll(parameter => parameter.Id == -1001111);
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));

        emittedOperands[wall.Id] =
        [
            (cutter.Id, opening with
            {
                IsExactParameterizedReveal = false,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));
        var rectangularOpening = outerOpening with
        {
            Boundary = BoxGeometry(
                0.9, -1, 1,
                2.1, 1, 2.1),
            IsExactParameterizedRectangularCut = true,
        };
        emittedOperands[wall.Id] = [(cutter.Id, rectangularOpening)];
        Assert.True(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));
        emittedOperands[wall.Id] =
        [
            (cutter.Id, rectangularOpening with
            {
                IsExactAuthoredRevealWriterBox = true,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));
        emittedOperands[wall.Id] =
        [
            (cutter.Id, rectangularOpening with
            {
                IsExactParameterizedRectangularCut = false,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));

        var familyCutLoopWriterBox = outerOpening with
        {
            IsExactFamilyCutLoopWriterBox = true,
            IsExactAuthoredRevealWriterBox = true,
        };
        emittedOperands[wall.Id] = [(cutter.Id, familyCutLoopWriterBox)];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));
        emittedOperands[wall.Id] =
        [
            (cutter.Id, familyCutLoopWriterBox with
            {
                IsExactAuthoredRevealWriterBox = false,
            }),
        ];
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                    out _, out _));

        emittedOperands[wall.Id] = [(cutter.Id, opening)];
        wall.Parameters.Single(parameter => parameter.Id == -1001105).Value =
            2.9;
        Assert.False(
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromAuthoredPlanAndSingleExactParameterizedSteppedOpening(
                    wall, wall.BoundingBox!,
                    emittedCutters, emittedOperands, null,
                out _, out _));
    }

    [Fact]
    public void FoldedTenVertexSideWallGrossPlan_UsesUniqueLowestSourceCap()
    {
        var foldedBoundary = ExtrudedSideProfileWallGeometry(
        [
            (0, 0), (4, 0), (4, 3), (3.5, 3), (3.5, 2),
            (3, 2), (3, 3), (1, 3), (1, 2), (0, 2),
        ], 0, 1);
        var wall = new Element
        {
            Id = 7001,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0.5, 0],
                EndPoint = [4, 0.5, 0],
            },
            Geometry = new GeometryData
            {
                Faces =
                [
                    Face([[0, 0, 0], [4, 0, 0], [4, 1, 0], [0, 1, 0]]),
                    Face([[0, 0, 3], [0, 1, 3], [4, 1, 3], [4, 0, 3]]),
                ],
            },
        };
        double[] bounds = [0, 0, 0, 4, 1, 3];

        Assert.True(
            IfcExporter
                .TryGetExactFoldedTenVertexSideWallGrossPlanFromLowestSourceCap(
                    wall, bounds, 1, foldedBoundary,
                    out var rectangularPlan, out var rectangularBounds));
        Assert.Equal(4, rectangularPlan.Count);
        Assert.Equal(bounds, rectangularBounds);

        // A five-corner joined cap retains the writer's exact collinear subdivision
        // one wall width from the gross start when the axis starts at half width.
        wall.Location.StartPoint = [0.5, 0.5, 0];
        wall.Geometry.Faces =
        [
            Face([[0, 0, 0], [4, 0, 0], [4, 0.75, 0], [3, 1, 0], [0, 1, 0]]),
            Face([[0, 0, 3], [0, 1, 3], [3, 1, 3], [4, 0.75, 3], [4, 0, 3]]),
        ];
        Assert.True(
            IfcExporter
                .TryGetExactFoldedTenVertexSideWallGrossPlanFromLowestSourceCap(
                    wall, bounds, 1, foldedBoundary,
                    out var joinedPlan, out var joinedBounds));
        Assert.Equal(6, joinedPlan.Count);
        Assert.Contains(joinedPlan, point => point[0] == 1 && point[1] == 1);
        Assert.Equal(bounds, joinedBounds);

        var low = joinedPlan.Select(point =>
            new[] { point[0], point[1], 0.0 }).ToList();
        var high = joinedPlan.Select(point =>
            new[] { point[0], point[1], 3.0 }).ToList();
        var grossFaces = new List<GeoFace>
        {
            Face(low),
            Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < joinedPlan.Count; index++)
        {
            int next = (index + 1) % joinedPlan.Count;
            grossFaces.Add(Face(
            [
                low[index], high[index], high[next], low[next],
            ]));
        }
        var arbitraryGross = new GeometryData
        {
            BoundingBox = joinedBounds,
            Faces = grossFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, grossFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        Assert.True(
            IfcExporter.TryGetExactBoundaryOwnedArbitraryVerticalExtrusionDefinition(
                arbitraryGross, wall.Location, 1, joinedBounds,
                out var recoveredPlan, out double baseZ, out double height));
        Assert.Equal(joinedPlan.Count, recoveredPlan.Count);
        Assert.Equal(0, baseZ);
        Assert.Equal(3, height);

        foldedBoundary.Faces[0].OuterVertices!.RemoveAt(0);
        Assert.False(
            IfcExporter
                .TryGetExactFoldedTenVertexSideWallGrossPlanFromLowestSourceCap(
                    wall, bounds, 1, foldedBoundary, out _, out _));
    }

    [Fact]
    public void UncutPairedSideProfileVerticalExtrusion_PreservesLongerEndSideBreakpoint()
    {
        var minimumProfile = new List<(double Along, double Z)>
        {
            (8, 0), (10, 0), (10, 1), (10, 3), (0, 3), (0, 0),
        };
        var maximumProfile = new List<(double Along, double Z)>
        {
            (8, 0), (9, 0), (9, 1), (9, 3), (0, 3), (0, 0),
        };
        var boundary = PairedSideProfileWallGeometry(
            minimumProfile, maximumProfile, 0, 1);
        var location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0.5, 0],
            EndPoint = [9, 0.5, 0],
        };
        double[] bounds = [0, 0, 0, 10, 1, 3];

        Assert.True(
            IfcExporter
                .TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                    boundary, location, 1, bounds,
                    out var plan, out double baseZ, out double height));
        Assert.Equal(5, plan.Count);
        Assert.Contains(plan, point => point.SequenceEqual([8.0, 0.0]));
        Assert.DoesNotContain(plan, point => point.SequenceEqual([8.0, 1.0]));
        Assert.Equal(0, baseZ);
        Assert.Equal(3, height);

        var maximumLongerBoundary = PairedSideProfileWallGeometry(
        [
            (8, 0), (9, 0), (9, 1), (9, 3), (0, 3), (0, 0),
        ],
        [
            (8, 0), (10, 0), (10, 1), (10, 3), (0, 3), (0, 0),
        ], 0, 1);
        Assert.True(
            IfcExporter
                .TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                    maximumLongerBoundary, location, 1, bounds,
                    out var maximumLongerPlan, out _, out _));
        Assert.Equal(5, maximumLongerPlan.Count);
        Assert.Contains(maximumLongerPlan,
            point => point.SequenceEqual([8.0, 1.0]));
        Assert.DoesNotContain(maximumLongerPlan,
            point => point.SequenceEqual([8.0, 0.0]));
        Assert.False(
            IfcExporter
                .TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                    PairedSideProfileWallGeometry(
                        minimumProfile, minimumProfile, 0, 1),
                    location, 1, bounds, out _, out _, out _));

        var wall = new Element
        {
            Id = 2722706,
            TypeId = 2722707,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Paired side profile wall",
            Location = location,
            BoundingBox = bounds,
            Geometry = boundary,
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1013201,
                    StorageType = StorageType.ElementId,
                    Value = 999,
                },
            ],
        };
        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-paired-side-profile-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCARBITRARYCLOSEDPROFILEDEF(", ifc);
            Assert.Contains("=IFCCARTESIANPOINT((1676.4,0.))", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }

        var mismatchedBreakpoint = PairedSideProfileWallGeometry(
            minimumProfile,
        [
            (7, 0), (9, 0), (9, 1), (9, 3), (0, 3), (0, 0),
        ], 0, 1);
        Assert.False(
            IfcExporter
                .TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                    mismatchedBreakpoint, location, 1, bounds,
                    out _, out _, out _));

        boundary.Faces[0].InnerVertices =
        [
            [[1, 0, 1], [2, 0, 1], [2, 0, 2], [1, 0, 2]],
        ];
        Assert.False(
            IfcExporter
                .TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                    boundary, location, 1, bounds,
                    out _, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_AcceptsExactParameterizedRevealProfileWithDisjointExtra()
    {
        var (wall, cutter, sourceBoundary) = ExactWallWithOneThroughOpening();
        int disjointCutterId = cutter.Id + 1;
        wall.CuttingElementIds = [cutter.Id, disjointCutterId];
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] = [wall.Id],
            [disjointCutterId] = [wall.Id],
        };
        var emittedCutters = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id, disjointCutterId],
        };
        var outerOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0, AxisX: 1, AxisY: 2e-15,
            WidthFt: 1, DepthFt: 2, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0, innerAtMinimum: true,
            out var firstBoundary));
        var disjointOpening = outerOpening with { CentreXFt = 7.5 };
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            disjointOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0, innerAtMinimum: true,
            out var disjointBoundary));
        var profile = new IfcExporter.ExactSteppedOpeningProfile(
            0.8, 0.9, 0, true);
        var first = outerOpening with
        {
            Boundary = firstBoundary,
            SteppedProfile = profile,
            IsExactParameterizedReveal = true,
        };
        var disjoint = disjointOpening with
        {
            Boundary = disjointBoundary,
            SteppedProfile = profile,
            IsExactParameterizedReveal = true,
        };
        Assert.True(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            sourceBoundary, wall.Location!, 1, wall.BoundingBox!,
            out _, out var hole));
        Assert.True(
            IfcExporter.ExactParameterizedRevealOpeningProfileMatchesWallHole(
                first, hole));
        Assert.False(
            IfcExporter.ExactParameterizedRevealOpeningProfileMatchesWallHole(
                disjoint, hole));
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (cutter.Id, first),
                (disjointCutterId, disjoint),
            ],
        };

        Assert.True(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, sourceBoundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null,
            out var gross, out var cutterIds));
        Assert.Equal([cutter.Id, disjointCutterId], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        emittedOperands[wall.Id][0] =
            (cutter.Id, first with { IsExactParameterizedReveal = false });
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, sourceBoundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null, out _, out _));

        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0.1, innerAtMinimum: true,
            out var nonConcordantBoundary));
        emittedOperands[wall.Id][0] =
            (cutter.Id, first with
            {
                Boundary = nonConcordantBoundary,
            });
        Assert.False(IfcExporter.TryGetVerifiedGrossWallBoundaryAndCutters(
            wall, wall.BoundingBox!, sourceBoundary, elements,
            new HashSet<int> { wall.Id }, inverseHosts, null,
            emittedCutters, emittedOperands, null, out _, out _));
    }

