    [Fact]
    public void RectangularOpeningBoundaryValidation_RejectsMismatchedOrShallowBrep()
    {
        var hole = new IfcExporter.RectangularWallThroughOpening(
            1.5, 0, 1, 0, 1, 1, 1, -0.5, 0.5);

        Assert.True(IfcExporter.ExactRectangularOpeningBoundaryMatchesWallHole(
            BoxGeometry(1, -0.75, 1, 2, 0.75, 2), hole));
        Assert.False(IfcExporter.ExactRectangularOpeningBoundaryMatchesWallHole(
            BoxGeometry(1, -0.75, 1, 2.1, 0.75, 2), hole));
        Assert.False(IfcExporter.ExactRectangularOpeningBoundaryMatchesWallHole(
            BoxGeometry(1, -0.4, 1, 2, 0.4, 2), hole));
    }

    [Fact]
    public void RectangularOpeningBoundaryValidation_UsesDirectWriterOrientationRepair()
    {
        var hole = new IfcExporter.RectangularWallThroughOpening(
            1.5, 0, 1, 0, 1, 1, 1, -0.5, 0.5);
        var boundary = BoxGeometry(1, -0.75, 1, 2, 0.75, 2);
        boundary.Faces[0].OuterVertices!.Reverse();

        Assert.False(IfcExporter.ExactRectangularOpeningBoundaryMatchesWallHole(
            boundary, hole));
        Assert.True(IfcExporter.ExactRectangularDirectFacetedBrepMatchesWallHole(
            boundary, hole, out string rejectionReason), rejectionReason);
