    [Fact]
    public void StandardCaseSweptSolidGate_UsesSoleHostedOperandForOpenSourceWall()
    {
        var (wall, cutter, rebuiltBoundary) = ExactWallWithOneThroughOpening(
            highHoleBaseZ: 1, highHoleHeadZ: 1.5);
        wall.Geometry = new GeometryData
        {
            BoundingBox = rebuiltBoundary.BoundingBox,
            Faces = rebuiltBoundary.Faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, rebuiltBoundary.Faces.Count).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = [0],
                    IsClosed = true,
                },
            ],
        };
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var exactOperand = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 1, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, exactOperand)],
        };

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null,
                out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        wall.CuttingElementIds = null;
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
        wall.CuttingElementIds = [cutter.Id + 1];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
        wall.CuttingElementIds = [cutter.Id];

        var twoSourceSolids = wall.Geometry.BrepSolids;
        wall.Geometry.BrepSolids = [twoSourceSolids![0]];
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
        wall.Geometry.BrepSolids[0].IsClosed = true;
        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
        wall.Geometry.BrepSolids[0].IsClosed = false;
        wall.Geometry.BrepSolids = twoSourceSolids;

        wall.Geometry.BrepSolids![0].IsClosed = true;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
        wall.Geometry.BrepSolids[0].IsClosed = false;
        emittedOperands[wall.Id] =
        [
            (cutter.Id, exactOperand with { WidthFt = 1.25 }),
        ];
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_UsesParameterizedRevealForTwoOpenSourceSideProfiles()
    {
        var (wall, cutter, rebuiltBoundary) =
            ExactWallWithOneThroughOpening(highHoleHeadZ: 1.9);
        foreach (double[] point in rebuiltBoundary.Faces[1].InnerVertices![0])
        {
            if (Math.Abs(point[0] - 1) < 1e-12) point[0] = 1.1;
            if (Math.Abs(point[0] - 2) < 1e-12) point[0] = 1.9;
        }
        wall.Geometry = new GeometryData
        {
            BoundingBox = rebuiltBoundary.BoundingBox,
            Faces = rebuiltBoundary.Faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, rebuiltBoundary.Faces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        int disjointCutterId = cutter.Id + 1;
        wall.CuttingElementIds = [cutter.Id, disjointCutterId];
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id, disjointCutterId],
        };
        var outerOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0, AxisX: 1, AxisY: 2e-15,
            WidthFt: 1, DepthFt: 2, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0, innerAtMinimum: false,
            out var revealBoundary));
        var revealProfile = new IfcExporter.ExactSteppedOpeningProfile(
            0.8, 0.9, 0, false);
        var reveal = outerOpening with
        {
            Boundary = revealBoundary,
            SteppedProfile = revealProfile,
            IsExactParameterizedReveal = true,
        };
        var disjointOuter = outerOpening with { CentreXFt = 7.5 };
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            disjointOuter, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0, innerAtMinimum: false,
            out var disjointBoundary));
        var disjoint = disjointOuter with
        {
            Boundary = disjointBoundary,
            SteppedProfile = revealProfile,
            IsExactParameterizedReveal = true,
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] =
            [
                (cutter.Id, reveal),
                (disjointCutterId, disjoint),
            ],
        };

        Assert.True(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null,
                out var gross, out var cutterIds));
        Assert.Equal([cutter.Id, disjointCutterId], cutterIds);
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0, innerAtMinimum: true,
            out var reversedBoundary));
        emittedOperands[wall.Id][0] =
            (cutter.Id, outerOpening with
            {
                Boundary = reversedBoundary,
                SteppedProfile = revealProfile with
                {
                    InnerAtMinimum = true,
                },
                IsExactParameterizedReveal = true,
            });
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));

        emittedOperands[wall.Id][0] =
            (cutter.Id, reveal with { IsExactParameterizedReveal = false });
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));

        emittedOperands[wall.Id][0] = (cutter.Id, reveal);
        emittedOperands[wall.Id][1] =
            (disjointCutterId, disjoint with { CentreXFt = 3.5 });
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));

        var shallowOuter = outerOpening with { DepthFt = 0.5 };
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            shallowOuter, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0, innerAtMinimum: false,
            out var shallowBoundary));
        emittedOperands[wall.Id][0] =
            (cutter.Id, shallowOuter with
            {
                Boundary = shallowBoundary,
                SteppedProfile = revealProfile,
                IsExactParameterizedReveal = true,
            });
        emittedOperands[wall.Id][1] = (disjointCutterId, disjoint);
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));

        emittedOperands[wall.Id][0] = (cutter.Id, reveal);
        foreach (GeoFace face in rebuiltBoundary.Faces!)
            foreach (double[] point in (face.OuterVertices ?? [])
                         .Concat((face.InnerVertices ?? [])
                             .SelectMany(ring => ring)))
                if (point[1] == 0.5 && point[0] == 4)
                    point[1] = 0.4;
        Assert.False(
            IfcExporter.TryGetVerifiedGrossWallBoundaryFromSingleOpenSourceHostedOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
    }

