    [Fact]
    public void StandardCaseSweptSolidGate_UsesExactSteppedWriterForClosedJoinedRevealShell()
    {
        var (wall, cutter, rebuiltBoundary) =
            ExactWallWithOneThroughOpening();
        foreach (double[] point in rebuiltBoundary.Faces[0].InnerVertices![0])
        {
            if (Math.Abs(point[0] - 1) < 1e-12) point[0] = 1.1;
            if (Math.Abs(point[0] - 2) < 1e-12) point[0] = 1.9;
            if (Math.Abs(point[2] - 2) < 1e-12) point[2] = 1.9;
        }
        foreach (GeoFace face in rebuiltBoundary.Faces!)
            foreach (double[] point in face.OuterVertices ?? [])
            {
                if (Math.Abs(point[1] + 0.5) < 1e-12
                    && point[0] > 0.5 && point[0] < 2.5
                    && point[2] > 0.5 && point[2] < 2.5)
                {
                    if (Math.Abs(point[0] - 1) < 1e-12) point[0] = 1.1;
                    if (Math.Abs(point[0] - 2) < 1e-12) point[0] = 1.9;
                    if (Math.Abs(point[2] - 2) < 1e-12) point[2] = 1.9;
                }
                if (Math.Abs(point[0] - 4) < 1e-12
                    && Math.Abs(point[1] - 0.5) < 1e-12)
                    point[0] = 3.9986;
            }
        rebuiltBoundary.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, rebuiltBoundary.Faces.Count).ToList();
        wall.Geometry = rebuiltBoundary;
        wall.CuttingElementIds = [];

        var outerOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 1.5, CentreYFt: 0, AxisX: 1, AxisY: 0,
            WidthFt: 1, DepthFt: 2, BaseZFt: 1, HeightFt: 1,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: -0.25, innerAtMinimum: true,
            out var steppedBoundary));
        var exactSteppedWriter = outerOpening with
        {
            Boundary = steppedBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                0.8, 0.9, -0.25, true),
        };
        var emittedCutterIds = new Dictionary<int, List<int>>
        {
            [wall.Id] = [cutter.Id],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wall.Id] = [(cutter.Id, exactSteppedWriter)],
        };

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleClosedSourceSteppedSideOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null,
                out var gross, out var cutterIds));
        Assert.Equal([cutter.Id], cutterIds);
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                gross, wall.Location!, 1, wall.BoundingBox!,
                out _, out _, out _, out string grossReason), grossReason);
        Assert.False(IfcExporter.TryGetExactVerticalRectangularWallPlan(
            gross, wall.Location!, 1, wall.BoundingBox!, out _, out _));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));

        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outerOpening, innerWidthFt: 0.8, innerHeightFt: 0.9,
            breakpointNormalFt: 0.25, innerAtMinimum: false,
            out var reversedBoundary));
        emittedOperands[wall.Id][0] =
            (cutter.Id, exactSteppedWriter with
            {
                Boundary = reversedBoundary,
                SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                    0.8, 0.9, 0.25, false),
            });
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleClosedSourceSteppedSideOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));

        emittedOperands[wall.Id][0] =
            (cutter.Id, exactSteppedWriter with { WidthFt = 1.1 });
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleClosedSourceSteppedSideOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));

        emittedOperands[wall.Id][0] = (cutter.Id, exactSteppedWriter);
        emittedCutterIds[wall.Id] = [cutter.Id, cutter.Id + 1];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleClosedSourceSteppedSideOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
        emittedCutterIds[wall.Id] = [cutter.Id];

        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleClosedSourceSteppedSideOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands,
                new Dictionary<int, List<int>>
                {
                    [wall.Id] = [cutter.Id + 2],
                },
                out _, out _));

        double[] originalRevealPoint =
            rebuiltBoundary.Faces[8].OuterVertices![0];
        rebuiltBoundary.Faces[8].OuterVertices![0] =
            [originalRevealPoint[0] + 0.01,
             originalRevealPoint[1], originalRevealPoint[2]];
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleClosedSourceSteppedSideOpening(
                wall, wall.BoundingBox!, rebuiltBoundary,
                emittedCutterIds, emittedOperands, null, out _, out _));
    }

    [Fact]
    public void StandardCaseSweptSolidGate_RejectsGrossProfileOutsideSerializedVerticalBounds()
    {
        var (wall, _, boundary) = ExactWallWithOneThroughOpening(outerBaseZ: -1);

        Assert.False(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            boundary, wall.Location!, 1, wall.BoundingBox!, out _, out _));
    }

    private static (Element Wall, Element Cutter, GeometryData Boundary)
        ExactWallWithOneThroughOpening(
            double highHoleBaseZ = 1, double highHoleHeadZ = 2,
            double outerBaseZ = 0)
    {
        double[][] lowOuter =
        [
            [0, -0.5, outerBaseZ], [4, -0.5, outerBaseZ],
            [4, -0.5, 3], [0, -0.5, 3],
        ];
        double[][] highOuter =
        [
            [0, 0.5, outerBaseZ], [4, 0.5, outerBaseZ],
            [4, 0.5, 3], [0, 0.5, 3],
        ];
        double[][] lowHole =
        [
            [1, -0.5, 1], [2, -0.5, 1],
            [2, -0.5, 2], [1, -0.5, 2],
        ];
        double[][] highHole =
        [
            [1, 0.5, highHoleBaseZ], [2, 0.5, highHoleBaseZ],
            [2, 0.5, highHoleHeadZ], [1, 0.5, highHoleHeadZ],
        ];
        var lowSide = Face(lowOuter);
        lowSide.InnerVertices = [lowHole.ToList()];
        var highSide = Face(highOuter.AsEnumerable().Reverse().ToArray());
        highSide.InnerVertices = [highHole.AsEnumerable().Reverse().ToList()];
        var faces = new List<GeoFace>
        {
            lowSide,
            highSide,
            Face([lowOuter[0], highOuter[0], highOuter[1], lowOuter[1]]),
            Face([lowOuter[1], highOuter[1], highOuter[2], lowOuter[2]]),
            Face([lowOuter[2], highOuter[2], highOuter[3], lowOuter[3]]),
            Face([lowOuter[3], highOuter[3], highOuter[0], lowOuter[0]]),
            Face([lowHole[0], lowHole[1], highHole[1], highHole[0]]),
            Face([lowHole[1], lowHole[2], highHole[2], highHole[1]]),
            Face([lowHole[2], lowHole[3], highHole[3], highHole[2]]),
            Face([lowHole[3], lowHole[0], highHole[0], highHole[3]]),
        };
        var boundary = new GeometryData
        {
            BoundingBox = [0, -0.5, outerBaseZ, 4, 0.5, 3],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var wall = new Element
        {
            Id = 1201,
            TypeId = 1202,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 4, 0.5, 3],
            Geometry = boundary,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [1301],
        };
        var cutter = new Element
        {
            Id = 1301,
            TypeId = 1302,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = wall.Id,
            BoundingBox = [1, -0.5, 1, 2, 0.5, 2],
            Transform = new InstanceTransform
            {
                Origin = [1.5, 0, 1],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
        };
        return (wall, cutter, boundary);
    }

    private static (Element Wall, Element FirstCutter, Element SecondCutter,
        GeometryData Boundary) ExactWallWithTwoThroughOpenings(
        double secondHoleMinimumAlong = 3,
        double? highSecondHoleMinimumAlong = null)
    {
        static double[][] Rectangle(double minimumAlong, double maximumAlong,
            double plane, double minimumZ, double maximumZ) =>
        [
            [minimumAlong, plane, minimumZ], [maximumAlong, plane, minimumZ],
            [maximumAlong, plane, maximumZ], [minimumAlong, plane, maximumZ],
        ];

        double[][] lowOuter = Rectangle(0, 6, -0.5, 0, 3);
        double[][] highOuter = Rectangle(0, 6, 0.5, 0, 3);
        double[][] lowFirstHole = Rectangle(1, 2, -0.5, 1, 2);
        double[][] highFirstHole = Rectangle(1, 2, 0.5, 1, 2);
        double[][] lowSecondHole = Rectangle(
            secondHoleMinimumAlong, secondHoleMinimumAlong + 1, -0.5, 1, 2);
        double highSecondMinimum = highSecondHoleMinimumAlong
            ?? secondHoleMinimumAlong;
        double[][] highSecondHole = Rectangle(
            highSecondMinimum, highSecondMinimum + 1, 0.5, 1, 2);

        var lowSide = Face(lowOuter);
        lowSide.InnerVertices =
        [
            lowFirstHole.ToList(),
            lowSecondHole.ToList(),
        ];
        var highSide = Face(highOuter.AsEnumerable().Reverse().ToArray());
        highSide.InnerVertices =
        [
            highSecondHole.AsEnumerable().Reverse().ToList(),
            highFirstHole.AsEnumerable().Reverse().ToList(),
        ];
        var faces = new List<GeoFace>
        {
            lowSide,
            highSide,
        };
        static void AddConnectors(List<GeoFace> target,
            IReadOnlyList<double[]> low, IReadOnlyList<double[]> high)
        {
            for (int index = 0; index < 4; index++)
            {
                int next = (index + 1) % 4;
                target.Add(Face([low[index], low[next], high[next], high[index]]));
            }
        }
        AddConnectors(faces, lowOuter, highOuter);
        AddConnectors(faces, lowFirstHole, highFirstHole);
        AddConnectors(faces, lowSecondHole, highSecondHole);

        var boundary = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        var wall = new Element
        {
            Id = 1501,
            TypeId = 1502,
            CategoryId = -2000011,
            Category = "OST_Walls",
            BoundingBox = [0, -0.5, 0, 6, 0.5, 3],
            Geometry = boundary,
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [1601, 1602],
        };
        Element Cutter(int id, double minimumAlong) => new()
        {
            Id = id,
            TypeId = id + 100,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = wall.Id,
            BoundingBox = [minimumAlong, -0.5, 1, minimumAlong + 1, 0.5, 2],
            Transform = new InstanceTransform
            {
                Origin = [minimumAlong + 0.5, 0, 1],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
        };
        return (wall, Cutter(1601, 1), Cutter(1602, secondHoleMinimumAlong), boundary);
    }

    [Fact]
    public void ShortStandardCaseWall_UsesVerifiedLocationProfileInsteadOfGeoSolidAabb()
    {
        double axis = Math.Sqrt(0.5);
        const double length = 0.005;
        const double width = 0.036;
        double[] Point(double along, double across, double z) =>
        [
            along * axis - across * axis,
            along * axis + across * axis,
            z,
        ];
        double[][] bottom =
        [
            Point(-length / 2, -width / 2, 0),
            Point(length / 2, -width / 2, 0),
            Point(length / 2, width / 2, 0),
            Point(-length / 2, width / 2, 0),
        ];
        double[][] top = bottom.Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        double extent = (length + width) * axis;
        var wall = new Element
        {
            Id = 84,
            TypeId = 85,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Short rotated wall",
            BoundingBox = [-extent / 2, -extent / 2, 0, extent / 2, extent / 2, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = Point(-length / 2, 0, 0),
                EndPoint = Point(length / 2, 0, 0),
            },
            Layers =
            [
                new MaterialLayer { LayerIndex = 0, ThicknessMm = width * 304.8 },
            ],
            Parameters =
            [
                new Parameter
                {
                    Id = -1001105, StorageType = StorageType.Double, Value = 3.0,
                },
                new Parameter
                {
                    Id = -1013201, StorageType = StorageType.ElementId, Value = 999,
                },
            ],
            Geometry = new GeometryData
            {
                BoundingBox = [-extent / 2, -extent / 2, 0, extent / 2, extent / 2, 3],
                Faces =
                [
                    Face(bottom), Face(top.AsEnumerable().Reverse().ToArray()),
                    Face([bottom[0], top[0], top[1], bottom[1]]),
                    Face([bottom[1], top[1], top[2], bottom[2]]),
                    Face([bottom[2], top[2], top[3], bottom[3]]),
                    Face([bottom[3], top[3], top[0], bottom[0]]),
                ],
                Solids =
                [
                    new GeoSolid
                    {
                        Position = [0, 0, 0],
                        RefDirection = [1, 0, 0],
                        ProfileWidth = extent,
                        ProfileDepth = extent,
                        ExtrusionHeight = 3,
                    },
                ],
            },
        };
        var info = new RevitFileInfo();
        info.Elements.Add(wall);
        info.Elements.Add(new Element
        {
            Id = 86,
            TypeId = 87,
            CategoryId = -2000170,
            Category = "OST_CurtainWallPanels",
            References = [wall.Id],
        });
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-short-wall-{Guid.NewGuid():N}.ifc");

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(wall, out var rebuilt));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, rebuilt));

        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("'Axis','Curve2D'", ifc);
            Assert.Contains("=IFCARBITRARYCLOSEDPROFILEDEF(", ifc);
            Assert.DoesNotContain("=IFCRECTANGLEPROFILEDEF(", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void StandardCasePlan_DoesNotGuessEndsWithExtraFullHeightConnectors()
    {
        var wall = new Element
        {
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
                Faces =
                [
                    Face([[4, -0.5, 0], [6, -0.5, 0], [6, -0.5, 3], [4, -0.5, 3]]),
                    Face([[4, 0.5, 0], [6, 0.5, 0], [6, 0.5, 3], [4, 0.5, 3]]),
                    Face([[0, -0.5, 0], [0, 0.5, 0], [0, 0.5, 3], [0, -0.5, 3]]),
                    Face([[10, -0.5, 0], [10, 0.5, 0], [10, 0.5, 3], [10, -0.5, 3]]),
                    Face([[4, -0.5, 0], [4, 0.5, 0], [4, 0.5, 3], [4, -0.5, 3]]),
                    Face([[6, -0.5, 0], [6, 0.5, 0], [6, 0.5, 3], [6, -0.5, 3]]),
                ],
            },
        };

        Assert.True(IfcExporter.TryGetAuthoredStraightWallPlan(wall, 1, out var plan));
        Assert.Equal(4, plan.Min(point => point[0]), 12);
        Assert.Equal(6, plan.Max(point => point[0]), 12);
    }

    [Fact]
    public void HostedElementHosts_UseTopLevelAndExactInverseCutTopology()
    {
        var firstWall = new Element { Id = 10, CategoryId = -2000011 };
        var secondWall = new Element
        {
            Id = 20,
            CategoryId = -2000011,
            References = [999],
            CuttingElementIds = [30],
        };
        var elements = new Dictionary<int, Element>
        {
            [firstWall.Id] = firstWall,
            [secondWall.Id] = secondWall,
        };
        var visibleWalls = new HashSet<int> { firstWall.Id, secondWall.Id };
        var cuttingInsert = new Element
        {
            Id = 30,
            SerializedHostId = firstWall.Id,
            ExplicitHostIds = [firstWall.Id],
            References = [999],
        };
        var nestedComponent = new Element
        {
            Id = 40,
            SerializedHostId = firstWall.Id,
            SuperInstanceId = cuttingInsert.Id,
            References = [firstWall.Id],
        };
        var inverseCutHosts = new Dictionary<int, List<int>>
        {
            [cuttingInsert.Id] = [secondWall.Id],
        };

        Assert.Equal([firstWall.Id, secondWall.Id],
            IfcExporter.ResolveHostedElementHostIds(
                cuttingInsert, elements, visibleWalls, inverseCutHosts));
        Assert.Empty(IfcExporter.ResolveHostedElementHostIds(
            nestedComponent, elements, visibleWalls, inverseCutHosts));
    }

    [Fact]
    public void ForwardHostBoundarySlotOpening_PartitionsExactIntersectingInverseHosts()
    {
        var directWall = new Element
        {
            Id = 10,
            CategoryId = -2000011,
            References = [30],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [7, 19.75, 29],
                EndPoint = [13, 19.75, 29],
            },
            Parameters = [WallWidthParameter(0.3)],
            Geometry = BoxGeometry(7, 19.6, 29, 13, 19.9, 40),
        };
        var intersectingWall = new Element
        {
            Id = 20,
            CategoryId = -2000011,
            References = [30],
            CuttingElementIds = [30],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [7, 19.75, 29],
                EndPoint = [13, 19.75, 29],
            },
            Parameters = [WallWidthParameter(0.3)],
            Geometry = BoxGeometry(7, 19.6, 29, 13, 19.9, 40),
        };
        var disjointWall = new Element
        {
            Id = 40,
            CategoryId = -2000011,
            References = [30],
            CuttingElementIds = [30],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [30, 19.75, 29],
                EndPoint = [35, 19.75, 29],
            },
            Parameters = [WallWidthParameter(0.3)],
            Geometry = BoxGeometry(30, 19.6, 29, 35, 19.9, 40),
        };
        var cutter = new Element
        {
            Id = 30,
            CategoryId = -2000023,
            SerializedHostId = directWall.Id,
            HostId = directWall.Id,
            References = [directWall.Id],
            BoundingBox = [6, 15, 30, 14, 25, 39],
        };
        var elements = new Dictionary<int, Element>
        {
            [directWall.Id] = directWall,
            [intersectingWall.Id] = intersectingWall,
            [cutter.Id] = cutter,
            [disjointWall.Id] = disjointWall,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutter.Id] =
                [directWall.Id, intersectingWall.Id, disjointWall.Id],
        };
        var sourceOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 10.25, CentreYFt: 19.75, AxisX: 1, AxisY: 0,
            WidthFt: 7.5, DepthFt: 0.3, BaseZFt: 30, HeightFt: 9,
            ExactDepth: true);
        var writerOpening = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 10, CentreYFt: 20, AxisX: 1, AxisY: 0,
            WidthFt: 8, DepthFt: 10, BaseZFt: 30, HeightFt: 9,
            ExactDepth: true);
        var verifiedPairs =
            new HashSet<(int WallId, int CutterId)>
            {
                (directWall.Id, cutter.Id),
            };
        var sourceOpenings = new Dictionary<
            (int WallId, int CutterId),
            IfcExporter.HostedOpeningGeometry>
        {
            [(directWall.Id, cutter.Id)] = sourceOpening,
        };
        var writerOpenings = new Dictionary<
            (int WallId, int CutterId),
            IfcExporter.HostedOpeningGeometry>
        {
            [(directWall.Id, cutter.Id)] = writerOpening,
        };

        Assert.True(IfcExporter.TryGetExactForwardHostOpeningPartition(
            cutter, elements, inverseHosts, verifiedPairs,
            sourceOpenings, writerOpenings, out var partition));
        Assert.Equal(directWall.Id, partition.DirectHostId);
        Assert.Equal(10, partition.DirectHostOpening.CentreXFt, 12);
        Assert.Equal(19.75, partition.DirectHostOpening.CentreYFt, 12);
        Assert.Equal(8, partition.DirectHostOpening.WidthFt, 12);
        Assert.Equal(0.3, partition.DirectHostOpening.DepthFt, 12);
        Assert.False(partition.DirectHostOpening.IsFamilyCutLoop);
        Assert.Equal(writerOpening, partition.SecondaryWriterOpening);
        Assert.Equal([intersectingWall.Id],
            partition.IntersectingSecondaryHostIds);
        Assert.True(IfcExporter.TryIntersectExactDirectedHostedOpeningWithHost(
            writerOpening, intersectingWall, out _));
        Assert.False(IfcExporter.TryIntersectExactDirectedHostedOpeningWithHost(
            writerOpening, disjointWall, out _));

        writerOpenings[(directWall.Id, cutter.Id)] =
            writerOpening with { IsFamilyCutLoop = true };
        Assert.True(IfcExporter
            .ExactDirectedOpeningHasPositiveAuthoredHostIntersection(
                writerOpenings[(directWall.Id, cutter.Id)],
                intersectingWall));
        Assert.False(IfcExporter
            .ExactDirectedOpeningHasPositiveAuthoredHostIntersection(
                writerOpenings[(directWall.Id, cutter.Id)],
                disjointWall));
        Assert.True(IfcExporter.TryGetExactForwardHostOpeningPartition(
            cutter, elements, inverseHosts, verifiedPairs,
            sourceOpenings, writerOpenings, out var loopPartition));
        Assert.Equal([intersectingWall.Id],
            loopPartition.IntersectingSecondaryHostIds);
        writerOpenings[(directWall.Id, cutter.Id)] =
            writerOpening with { WidthFt = 7 };
        Assert.False(IfcExporter.TryGetExactForwardHostOpeningPartition(
            cutter, elements, inverseHosts, verifiedPairs,
            sourceOpenings, writerOpenings, out _));
        writerOpenings[(directWall.Id, cutter.Id)] = writerOpening;
        inverseHosts[cutter.Id] =
            [directWall.Id, intersectingWall.Id, intersectingWall.Id];
        Assert.False(IfcExporter.TryGetExactForwardHostOpeningPartition(
            cutter, elements, inverseHosts, verifiedPairs,
            sourceOpenings, writerOpenings, out _));
        inverseHosts[cutter.Id] =
            [directWall.Id, intersectingWall.Id, disjointWall.Id];
        cutter.ExtraHostIds = [intersectingWall.Id];
        Assert.False(IfcExporter.TryGetExactForwardHostOpeningPartition(
            cutter, elements, inverseHosts, verifiedPairs,
            sourceOpenings, writerOpenings, out _));
    }

