    [Fact]
    public void HostedOpeningPlacement_UsesSerializedInstanceTransformInsteadOfFamilyAabbCentre()
    {
        const int phaseId = 99;
        var wall = new Element
        {
            Id = 10,
            TypeId = 11,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Host wall",
            References = [phaseId],
            Parameters =
            [
                new Parameter { Id = -1012100, StorageType = StorageType.Integer, Value = phaseId },
                WallWidthParameter(1),
            ],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [10, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
        };
        var insert = new Element
        {
            Id = 20,
            TypeId = 21,
            CategoryId = -2000023,
            Category = "OST_Doors",
            SerializedHostId = wall.Id,
            HostId = wall.Id,
            References = [wall.Id, phaseId],
            Parameters =
            [
                new Parameter { Id = -1012100, StorageType = StorageType.Integer, Value = phaseId },
            ],
            // Symbolic swing geometry makes the AABB centre 2 ft, while the exact
            // FamilyInstance insertion transform is at 8 ft.
            BoundingBox = [1, -0.5, 0, 3, 0.5, 2.5],
            Transform = new InstanceTransform
            {
                Origin = [8, 2, 0],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
        };
        var info = new RevitFileInfo();
        info.Elements.AddRange([wall, insert]);
        string path = Path.Combine(Path.GetTempPath(),
            $"revitreader-transform-opening-{Guid.NewGuid():N}.ifc");

        try
        {
            new IfcExporter() { Profile = IfcProfile.Legacy }.Export(info, path);
            string ifc = File.ReadAllText(path);

            Assert.Contains("=IFCOPENINGELEMENT(", ifc);
            Assert.Contains("=IFCCARTESIANPOINT((2438.4,609.6,0.));", ifc);
            Assert.DoesNotContain("=IFCCARTESIANPOINT((609.6,0.,0.));", ifc);
        }
        finally
        {
            if (File.Exists(path)) File.Delete(path);
        }
    }

    [Fact]
    public void HostedOpeningPlacement_UsesSingleSerializedTopLevelGInstanceTransform()
    {
