                [
                    new GeoInstance
                    {
                        SymbolId = 7550977,
                        Transform =
                        [
                            -0.7071067811865476, -0.7071067811865476, 0,
                            0.7071067811865476, -0.7071067811865476, 0,
                            0, 0, 1,
                            31.601945, -66.183217, 225.885827,
                        ],
                    },
                ],
            },
        };

        Assert.True(IfcExporter.TryGetSerializedInsertionOrigin(
            element, out double xFt, out double yFt));
        Assert.Equal(31.601945, xFt, 12);
