        element.Geometry.Instances.Add(new GeoInstance
        {
            SymbolId = 1,
            Transform = [1, 0, 0, 0, 1, 0, 0, 0, 1, 2, 3, 4],
        });
        Assert.False(IfcExporter.TryGetSerializedInsertionOrigin(element, out _, out _));
    }

