    [Fact]
    public void SlabOpeningProfile_UsesExactInnerLoopAndItsSerializedSketchLineIdentity()
    {
        var low = new List<double[]>
        {
            new[] { -18.015521404, 0.019705270, 225.032808 },
            new[] { -15.390873881, 0.019705270, 225.032808 },
            new[] { -15.390873881, -1.784757, 225.032808 },
            new[] { -18.015521404, -1.784757, 225.032808 },
        };
        var high = low.Select(point => new[] { point[0], point[1], 225.557743 }).ToList();
        var bottom = Face([[-20, -3, 225.032808], [-14, -3, 225.032808],
            [-14, 1, 225.032808], [-20, 1, 225.032808]]);
        bottom.InnerVertices = [low];
        var top = Face([[-20, -3, 225.557743], [-20, 1, 225.557743],
            [-14, 1, 225.557743], [-14, -3, 225.557743]]);
        top.InnerVertices = [high];
        var slab = new Element
        {
            Id = 2583728,
            Geometry = new GeometryData { Faces = [bottom, top] },
        };
        var firstBoundaryLine = new Element
        {
            Id = 2583855,
            CategoryId = -2000045,
            References = [slab.Id],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [-18.015521404, 0.019705270, 225.885826772],
                EndPoint = [-15.390873881, 0.019705270, 225.885826772],
            },
        };

        var profiles = IfcExporter.GetSerializedSlabOpeningProfiles(
            slab, [firstBoundaryLine]);

        var profile = Assert.Single(profiles);
        Assert.Equal(2583855, profile.TagId);
        Assert.Equal(4, profile.Ring.Count);
        Assert.Equal(225.032808, profile.LowZFt, 9);
        Assert.Equal(225.557743, profile.HighZFt, 9);
    }

