    [Theory]
    [InlineData("one-way-type")]
    [InlineData("one-way-edge")]
    [InlineData("missing-slab-owner")]
    [InlineData("non-null-type-mate")]
    [InlineData("branch")]
    public void SlabOpeningTagSelector_CurvedFallbackRequiresCompleteValidation(
        string brokenValidation)
    {
        var fixture = CurvedSlabOpeningTagFixture();
        switch (brokenValidation)
        {
            case "one-way-type":
                fixture.Mate.TypeId = -1;
                break;
            case "one-way-edge":
                fixture.Mate.References!.Remove(fixture.Seed.Id);
                break;
            case "missing-slab-owner":
                fixture.Mate.References!.Remove(fixture.Slab.Id);
                break;
            case "non-null-type-mate":
                fixture.Mate.Location = new LocationCurve
                {
                    CurveType = "Arc",
                    StartPoint = [0, 0, 7],
                    EndPoint = [2, 0, 7],
                };
                break;
            case "branch":
                var branch = new Element
                {
                    Id = 314,
                    CategoryId = -2000045,
                    References = [fixture.Slab.Id, fixture.Seed.Id],
                };
                fixture.Seed.References!.Add(branch.Id);
                fixture.Members.Add(branch);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(brokenValidation));
        }

        int tagId = IfcExporter.SelectSerializedSlabOpeningTag(
            fixture.Slab, fixture.LowRing, fixture.MatchingLines, fixture.Members);

        Assert.Equal(fixture.Seed.Id, tagId);
    }

    private static (Element Slab, List<double[]> LowRing,
        List<Element> MatchingLines, List<Element> Members,
        Element Seed, Element Mate) CurvedSlabOpeningTagFixture()
    {
        var low = new List<double[]>
        {
            new[] { 0.0, 0.0, 0.0 },
            new[] { 2.0, 0.0, 0.0 },
            new[] { 3.0, 1.0, 0.0 },
            new[] { 2.0, 2.0, 0.0 },
            new[] { 0.0, 2.0, 0.0 },
            new[] { -1.0, 1.0, 0.0 },
        };
        var high = low.Select(point => new[] { point[0], point[1], 0.5 }).ToList();
        var bottom = Face([[-2, -1, 0], [4, -1, 0], [4, 3, 0], [-2, 3, 0]]);
        bottom.InnerVertices = [low];
        var top = Face([[-2, -1, 0.5], [-2, 3, 0.5], [4, 3, 0.5], [4, -1, 0.5]]);
        top.InnerVertices = [high];
        var slab = new Element
        {
            Id = 300,
            Geometry = new GeometryData { Faces = [bottom, top] },
        };
        static Element Node(int id, int typeId, double[]? start = null,
            double[]? end = null) => new()
        {
            Id = id,
            TypeId = typeId,
            CategoryId = -2000045,
            Location = start != null && end != null
                ? new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = start,
                    EndPoint = end,
                }
                : null,
        };
        var mate = Node(308, 309);
        var seed = Node(309, 308, [0, 0, 7], [2, 0, 7]);
        var otherNull = Node(310, 309);
        var secondLine = Node(311, -1, [3, 1, 7], [2, 2, 7]);
        var thirdLine = Node(312, -1, [2, 2, 7], [0, 2, 7]);
        var fourthLine = Node(313, -1, [-1, 1, 7], [0, 0, 7]);
        mate.References = [slab.Id, otherNull.Id, seed.Id];
        seed.References = [slab.Id, mate.Id, secondLine.Id];
        secondLine.References = [slab.Id, seed.Id, thirdLine.Id];
        thirdLine.References = [slab.Id, secondLine.Id, fourthLine.Id];
        fourthLine.References = [slab.Id, thirdLine.Id, otherNull.Id];
        otherNull.References = [slab.Id, fourthLine.Id, mate.Id];

        return (slab, low, [seed, secondLine, thirdLine, fourthLine],
            [thirdLine, mate, fourthLine, seed, otherNull, secondLine], seed, mate);
    }

