    [Fact]
    public void HostedOpeningClearWidth_RequiresIndependentSerializedLengthMatch()
    {
        var hosted = new Element
        {
            Parameters =
            [
                new Parameter
                {
                    Id = 123,
                    StorageType = StorageType.Double,
                    SpecType = "autodesk.spec.aec:length-2.0.0",
                    Value = 8.0,
                },
                new Parameter
                {
                    Id = 124,
                    StorageType = StorageType.Double,
                    SpecType = "autodesk.spec.aec:area-2.0.0",
                    Value = 8.0,
                },
                new Parameter
                {
                    Id = 125,
                    StorageType = StorageType.Double,
                    Guid = Guid.Parse("8f2e4f93-9472-4941-a65d-0ac468fd6a5d"),
                    Value = 7.5,
                },
            ],
        };

        Assert.True(IfcExporter.TryResolveSerializedClearOpeningWidth(
            hosted, null, 8.5, 0.5, out double clearWidth));
        Assert.Equal(8.0, clearWidth, 12);
        Assert.True(IfcExporter.TryResolveSerializedClearOpeningWidth(
            hosted, null, 8.0, 0.5, out double adskClearWidth));
        Assert.Equal(7.5, adskClearWidth, 12);
        Assert.False(IfcExporter.TryResolveSerializedClearOpeningWidth(
            hosted, null, 9.0, 0.5, out _));
    }

