    [Fact]
    public void StraightWallBoundary_UsesExteriorJoinedProfilesAndDropsOldCap()
    {
        double[][] low =
        [
            [0, -0.5, 0], [4, -0.5, 0], [4, -0.5, 3], [0, -0.5, 2],
        ];
        double[][] high =
        [
            [4, 0.5, 3.2], [4, 0.5, 0], [0, 0.5, 0], [0, 0.5, 2.2],
        ];
        var element = new Element
        {
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 4, 0.5, 3.2],
                Faces =
                [
                    Face(low),
                    Face(high),
                    Face([low[0], high[2], high[1], low[1]]),
                    Face([low[1], high[1], high[0], low[2]]),
                    Face([low[2], high[0], high[3], low[3]]),
                    Face([low[3], high[3], high[2], low[0]]),
                    Face([[0, 0, 0], [4, 0, 0], [4, 0, 2.5], [0, 0, 2.5]]),
                    Face([[0, -0.5, 1.5], [4, -0.5, 1.5], [4, 0.5, 1.5], [0, 0.5, 1.5]]),
                ],
            },
        };

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(element, out var boundary));
        Assert.Equal(6, boundary.Faces.Count);
        var solid = Assert.Single(boundary.BrepSolids!);
        Assert.True(solid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 6), solid.FaceIndices);

        var authoredVertices = low.Concat(high).Select(Key).ToHashSet();
        var resultVertices = boundary.Faces
            .SelectMany(face => face.OuterVertices!)
            .Select(Key).ToHashSet();
        Assert.Equal(authoredVertices, resultVertices);
        Assert.DoesNotContain(resultVertices, key => key.Z == BitConverter.DoubleToInt64Bits(1.5));
    }

    [Fact]
