    [Fact]
    public void StraightWallBoundary_PreservesAuthoredThroughOpening()
    {
        double[][] lowOuter = [[0, -0.5, 0], [4, -0.5, 0], [4, -0.5, 3], [0, -0.5, 3]];
        double[][] highOuter = [[0, 0.5, 0], [4, 0.5, 0], [4, 0.5, 3], [0, 0.5, 3]];
        double[][] lowHole = [[1, -0.5, 1], [2, -0.5, 1], [2, -0.5, 2], [1, -0.5, 2]];
        double[][] highHole = [[1, 0.5, 1], [2, 0.5, 1], [2, 0.5, 2], [1, 0.5, 2]];
        var lowFace = Face(lowOuter);
        lowFace.InnerVertices =
        [
            lowHole.ToList(),
        ];
        var highFace = Face(highOuter);
        highFace.InnerVertices = [highHole.ToList()];
        var element = new Element
        {
            Parameters = [WallWidthParameter(1)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Geometry = new GeometryData
            {
                Faces =
                [
                    lowFace,
                    highFace,
                    Face([lowOuter[0], highOuter[0], highOuter[1], lowOuter[1]]),
                    Face([lowOuter[1], highOuter[1], highOuter[2], lowOuter[2]]),
                    Face([lowOuter[2], highOuter[2], highOuter[3], lowOuter[3]]),
                    Face([lowOuter[3], highOuter[3], highOuter[0], lowOuter[0]]),
                    Face([lowHole[0], lowHole[1], highHole[1], highHole[0]]),
                    Face([lowHole[1], lowHole[2], highHole[2], highHole[1]]),
                    Face([lowHole[2], lowHole[3], highHole[3], highHole[2]]),
                    Face([lowHole[3], lowHole[0], highHole[0], highHole[3]]),
                ],
            },
        };

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(element, out var boundary));
        Assert.Equal(10, boundary.Faces.Count);
        Assert.Single(boundary.Faces[0].InnerVertices!);
        Assert.Single(boundary.Faces[1].InnerVertices!);
        Assert.True(Assert.Single(boundary.BrepSolids!).IsClosed);
        Assert.True(IfcExporter.TryOrientExactFacetedShell(boundary.Faces,
            Enumerable.Range(0, boundary.Faces.Count).ToArray(), out var oriented));
        Assert.True(IfcExporter.IsExactFacetedShell(oriented,
            Enumerable.Range(0, oriented.Count).ToArray()));

        static (double X, double Y, double Z) Newell(IReadOnlyList<double[]> ring)
        {
            double x = 0, y = 0, z = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                var current = ring[index];
                var next = ring[(index + 1) % ring.Count];
                x += (current[1] - next[1]) * (current[2] + next[2]);
                y += (current[2] - next[2]) * (current[0] + next[0]);
                z += (current[0] - next[0]) * (current[1] + next[1]);
            }
            return (x, y, z);
        }
        foreach (var face in oriented.Where(face => face.InnerVertices is { Count: > 0 }))
        {
            var outerNormal = Newell(face.OuterVertices!);
            foreach (var inner in face.InnerVertices!)
            {
                var innerNormal = Newell(inner);
                Assert.True(outerNormal.X * innerNormal.X
                    + outerNormal.Y * innerNormal.Y + outerNormal.Z * innerNormal.Z < 0);
            }
        }
    }

