    [Fact]
    public void HostedOpeningBoundary_PreservesAuthoredSteppedPocketPlan()
    {
        double[][] low =
        [
            [0, 0, 1], [2, 0, 1], [2, 1, 1], [1.5, 1, 1],
            [1.5, 2, 1], [0.5, 2, 1], [0.5, 1, 1], [0, 1, 1],
        ];
        double[][] high = low.Select(point => new[] { point[0], point[1], 3.0 }).ToArray();
        var wall = new Element
        {
            Geometry = new GeometryData
            {
                Faces =
                [
                    Face(low),
                    Face(high.AsEnumerable().Reverse()),
                    Face([[0, 0, 0], [4, 0, 0], [4, 0, 4], [0, 0, 4]]),
                ],
            },
        };

        Assert.True(IfcExporter.TryBuildHostedOpeningBoundary(
            wall, [0, 0, 0, 2, 2, 4], out var boundary));
        Assert.Equal(10, boundary.Faces.Count);
        Assert.Equal(8, boundary.Faces[0].OuterVertices!.Count);
        Assert.True(Assert.Single(boundary.BrepSolids!).IsClosed);
        Assert.Equal(new double[] { 0, 0, 1, 2, 2, 3 }, boundary.BoundingBox);

        var directedEdges = boundary.Faces
            .SelectMany(face => Enumerable.Range(0, face.OuterVertices!.Count)
                .Select(index => (
                    Start: Key(face.OuterVertices[index]),
                    End: Key(face.OuterVertices[(index + 1) % face.OuterVertices.Count]))))
            .ToList();
        var edgeUses = directedEdges.GroupBy(edge =>
            Comparer<(long X, long Y, long Z)>.Default.Compare(edge.Start, edge.End) <= 0
                ? (edge.Start, edge.End)
                : (edge.End, edge.Start));
        Assert.All(edgeUses, group =>
        {
            var uses = group.ToList();
            Assert.Equal(2, uses.Count);
            Assert.Equal(uses[0].Start, uses[1].End);
            Assert.Equal(uses[0].End, uses[1].Start);
        });
    }

