    [Fact]
    public void HostedOpeningWriterBox_PromotesMatchingAuthoredReveal()
    {
        double[][] low =
        [
            [1, -0.5, 1], [2, -0.5, 1], [2, 0.5, 1], [1, 0.5, 1],
        ];
        double[][] high = low.Select(point =>
            new[] { point[0], point[1], 3.0 }).ToArray();
        var wall = new Element
        {
            Id = 1,
            BoundingBox = [0, -0.5, 0, 4, 0.5, 4],
            Parameters = [WallWidthParameter(0.5)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [4, 0, 0],
            },
            Geometry = new GeometryData
            {
                BoundingBox = [0, -0.5, 0, 4, 0.5, 4],
                Faces = [Face(low), Face(high.AsEnumerable().Reverse())],
            },
        };
        var hosted = new Element
        {
            Id = 2,
            BoundingBox = [1.1, -0.2, 1, 1.9, 0.2, 3],
        };
        var elements = new Dictionary<int, Element>
        {
            [wall.Id] = wall,
            [hosted.Id] = hosted,
        };

        Assert.True(IfcExporter.TryResolveHostedOpeningWriterOperand(
            hosted, hosted.BoundingBox!, wall, elements, default,
            out var exactWriterBox));
        Assert.True(exactWriterBox.IsExactAuthoredRevealWriterBox);
        Assert.False(exactWriterBox.IsExactParameterizedRectangularCut);
        Assert.Null(exactWriterBox.Boundary);

        hosted.BoundingBox = [1.2, -0.2, 1, 2.0, 0.2, 3];
        Assert.True(IfcExporter.TryResolveHostedOpeningWriterOperand(
            hosted, hosted.BoundingBox, wall, elements, default,
            out var shiftedWriterBox));
        Assert.False(shiftedWriterBox.IsExactAuthoredRevealWriterBox);
        Assert.False(shiftedWriterBox.IsExactParameterizedRectangularCut);
        Assert.Null(shiftedWriterBox.Boundary);
    }

