    [Fact]
    public void MultiLayerHostedOpening_UsesOneExactCommonWallCutter()
    {
        static Element LayerWall(int id, double minY, double maxY,
            double revealMinX, double revealMaxX, bool hasReveal = true)
        {
            double[][] low =
            [
                [revealMinX, minY, 1], [revealMaxX, minY, 1],
                [revealMaxX, maxY, 1], [revealMinX, maxY, 1],
            ];
            double[][] high = low.Select(point =>
                new[] { point[0], point[1], 3.0 }).ToArray();
            var faces = new List<GeoFace>
            {
                Face([[0, minY, 0], [4, minY, 0],
                    [4, minY, 4], [0, minY, 4]]),
                Face([[0, maxY, 0], [0, maxY, 4],
                    [4, maxY, 4], [4, maxY, 0]]),
            };
            if (hasReveal)
            {
                faces.Add(Face(low));
                faces.Add(Face(high.AsEnumerable().Reverse()));
            }
            return new Element
            {
                Id = id,
                Location = new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [0, 0, 0],
                    EndPoint = [4, 0, 0],
                },
                Geometry = new GeometryData
                {
                    Faces = faces,
                },
            };
        }

        var hosted = new Element { Id = 10, SerializedHostId = 1 };
        var walls = new List<Element>
        {
            LayerWall(1, -0.1, 0.1, 1.15, 2.85, hasReveal: false),
            LayerWall(2, 0.1, 0.112, 1.245, 2.755),
            LayerWall(3, -0.112, -0.1, 1.245, 2.755),
        };

        Assert.True(IfcExporter.TryBuildCommonHostedOpeningGeometry(
            hosted, [1, -1, 1, 3, 1, 3], walls, out var opening));
        Assert.Equal(2, opening.CentreXFt, 12);
        Assert.Equal(0, opening.CentreYFt, 12);
        Assert.Equal(1, opening.AxisX, 12);
        Assert.Equal(0, opening.AxisY, 12);
        Assert.Equal(1.51, opening.WidthFt, 12);
        Assert.Equal(0.224, opening.DepthFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(2, opening.HeightFt, 12);
        Assert.True(opening.ExactDepth);
