    [Fact]
    public void MultiLayerHostedOpening_ExactProfileConcordanceCorrectsOnlyNormalAnchor()
    {
        static Element LayerWall(int id, double minY, double maxY,
            bool normalFirst = false)
        {
            double[][] low = normalFirst
                ?
                [
                    [1.25, minY, 1], [1.25, maxY, 1],
                    [2.75, maxY, 1], [2.75, minY, 1],
                ]
                :
                [
                    [1.25, minY, 1], [2.75, minY, 1],
                    [2.75, maxY, 1], [1.25, maxY, 1],
                ];
            double[][] high = low.Select(point =>
                new[] { point[0], point[1], 3.0 }).ToArray();
            return new Element
            {
                Id = id,
                Location = new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [0, 0, 0],
                    EndPoint = [4, 0, 0],
                },
                Geometry = new GeometryData
                {
                    Faces =
                    [
                        Face([[0, minY, 0], [4, minY, 0],
                            [4, minY, 4], [0, minY, 4]]),
                        Face([[0, maxY, 0], [0, maxY, 4],
                            [4, maxY, 4], [4, maxY, 0]]),
                        Face(low), Face(high.AsEnumerable().Reverse()),
                    ],
                },
            };
        }

        var hosted = new Element { Id = 10, SerializedHostId = 1 };
        var walls = new List<Element>
        {
            LayerWall(1, -0.2, 0),
            LayerWall(2, 0, 0.2),
        };
        var shiftedSerialized = new IfcExporter.HostedOpeningGeometry(
            2, 0.25, 1, 0, 1.5, 0.4, 1, 2,
            ExactDepth: true, IsExactSerializedDefinition: true);

        Assert.True(
            IfcExporter.TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
                hosted, [1, -1, 1, 3, 1, 3], walls,
                shiftedSerialized, out var opening));
        Assert.Equal(2, opening.CentreXFt, 12);
        Assert.Equal(0, opening.CentreYFt, 12);
        Assert.True(opening.IsExactAuthoredMultiHostEnvelope);

        Assert.False(
            IfcExporter.TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
                hosted, [1, -1, 1, 3, 1, 3], walls,
                shiftedSerialized with { WidthFt = 1.49 }, out _));

        var identicalRevealWalls = new List<Element>
        {
            LayerWall(3, -0.2, 0, normalFirst: true),
            LayerWall(4, -0.2, 0, normalFirst: true),
        };
        Assert.True(
            IfcExporter.TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
                hosted, [1, -1, 1, 3, 1, 3], identicalRevealWalls,
                shiftedSerialized with { DepthFt = 0.2 },
                out var authoredReveal));
        Assert.Equal(2, authoredReveal.CentreXFt, 12);
        Assert.Equal(-0.1, authoredReveal.CentreYFt, 12);
        Assert.True(authoredReveal.IsExactAuthoredMultiHostEnvelope);

        identicalRevealWalls.Add(LayerWall(5, 0.4, 0.6));
        Assert.False(
            IfcExporter.TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
                hosted, [1, -1, 1, 3, 1, 3], identicalRevealWalls,
                shiftedSerialized with { DepthFt = 0.2 }, out _));
    }

    [Fact]
    public void RectangularOpeningProfileContainment_AllowsOnlyDeeperNormalEnvelope()
    {
        var reveal = new IfcExporter.HostedOpeningGeometry(
            2, 0, 1, 0, 1.5, 0.2, 1, 2, ExactDepth: true);
        var deeperFamilyCut = reveal with { DepthFt = 1.2 };

        Assert.True(IfcExporter
            .RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
                reveal, deeperFamilyCut));
        Assert.True(IfcExporter
            .RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
                reveal with
                {
                    AxisX = 0,
                    AxisY = 1,
                    WidthFt = reveal.DepthFt,
                    DepthFt = reveal.WidthFt,
                },
                deeperFamilyCut));
        Assert.False(IfcExporter
            .RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
                reveal, deeperFamilyCut with { CentreYFt = 0.7 }));
        Assert.False(IfcExporter
            .RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
                reveal, deeperFamilyCut with { CentreXFt = 2.01 }));
        Assert.False(IfcExporter
            .RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
                reveal, deeperFamilyCut with { WidthFt = 1.49 }));
    }

