    [Fact]
    public void ExactFacetedShell_OrientsNonContainedCycleAsCoplanarPatch()
    {
        const double a = 4.043635170604, b = 4.109251968504;
        const double y1 = -0.164041994751, y2 = -0.295275590551;
        const double y3 = -0.328083989501, z = 0.0656167979;
        var faces = new List<GeoFace>
        {
            Face([[a, 0, 0], [a, y1, 0], [a, y1, z], [a, 0, z]]),
            Face([[a, 0, 0], [-a, 0, 0], [-a, 0, z], [a, 0, z]]),
            Face([[a, 0, z], [-a, 0, z], [-a, y1, z], [-b, y1, z],
                [-b, y3, z], [b, y3, z], [b, y1, z], [a, y1, z]]),
            Face([[a, y1, z], [b, y1, z], [b, y1, 0], [a, y1, 0]]),
            Face([[a, y1, 0], [b, y1, 0], [b, y2, 0], [-b, y2, 0],
                [-b, y1, 0], [-a, y1, 0], [-a, 0, 0], [a, 0, 0]]),
            Face([[-a, 0, 0], [-a, 0, z], [-a, y1, z], [-a, y1, 0]]),
            Face([[-b, y1, z], [-b, y1, 0], [-b, y2, 0], [-b, y2, -z],
                [-b, y3, -z], [-b, y3, z]]),
            Face([[-b, y3, z], [-b, y3, -z], [b, y3, -z], [b, y3, z]]),
            Face([[b, y3, z], [b, y3, -z], [b, y2, -z], [b, y2, 0],
                [b, y1, 0], [b, y1, z]]),
            Face([[b, y2, 0], [b, y2, -z], [-b, y2, -z], [-b, y2, 0]]),
            Face([[b, y3, -z], [-b, y3, -z], [-b, y2, -z], [b, y2, -z]]),
        };
        faces[3].InnerVertices =
        [
            [[-a, y1, z], [-b, y1, z], [-b, y1, 0], [-a, y1, 0]],
        ];

        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            faces, Enumerable.Range(0, faces.Count).ToArray(), out var oriented));
        Assert.True(IfcExporter.IsExactFacetedShell(
            oriented, Enumerable.Range(0, oriented.Count).ToArray()));

        var coplanarFace = oriented.Single(face => face.InnerVertices is { Count: 1 });
        static double[] Newell(IReadOnlyList<double[]> ring)
        {
            double[] normal = [0, 0, 0];
            for (int index = 0; index < ring.Count; index++)
            {
                var current = ring[index]; var next = ring[(index + 1) % ring.Count];
                normal[0] += (current[1] - next[1]) * (current[2] + next[2]);
                normal[1] += (current[2] - next[2]) * (current[0] + next[0]);
                normal[2] += (current[0] - next[0]) * (current[1] + next[1]);
            }
            return normal;
        }
        var outerNormal = Newell(coplanarFace.OuterVertices!);
        var patchNormal = Newell(coplanarFace.InnerVertices![0]);
        Assert.True(outerNormal.Zip(patchNormal).Sum(pair => pair.First * pair.Second) > 0);
    }

    [Fact]
    public void StraightWallAcrossOffset_RecoversFinishFaceLocationFromSerializedBounds()
    {
        double rootHalf = Math.Sqrt(0.5);
        var location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0, 0],
            EndPoint = [4, 4, 0],
        };
        double width = 1;
        double expectedOffset = -0.5;
        double shiftX = -rootHalf * expectedOffset;
        double shiftY = rootHalf * expectedOffset;
        double halfProjection = rootHalf * width / 2;
        double[] bounds =
        [
            shiftX - halfProjection, shiftY - halfProjection, 0,
            4 + shiftX + halfProjection, 4 + shiftY + halfProjection, 3,
        ];

        Assert.True(IfcExporter.TryResolveStraightWallAcrossOffset(
            location, width, bounds, out double actualOffset));
        Assert.Equal(expectedOffset, actualOffset, 12);
        Assert.True(IfcExporter.TryResolveStraightWallPlanCentre(
            location, width, bounds, out double centreX, out double centreY));
        Assert.Equal(2 + shiftX, centreX, 12);
        Assert.Equal(2 + shiftY, centreY, 12);
    }

    [Fact]
    public void StraightWallPlanCentre_PreservesSerializedEndOffsetWhenExtentsAreExact()
    {
        var location = new LocationCurve
        {
            CurveType = "Line",
            StartPoint = [0, 0, 0],
            EndPoint = [4, 4, 0],
        };
        double projection = Math.Sqrt(0.5) / 2;
        double[] shiftedBounds =
        [
            1 - projection, 1 - projection, 0,
            5 + projection, 5 + projection, 3,
        ];

        Assert.True(IfcExporter.TryResolveStraightWallPlanCentre(
            location, 1, shiftedBounds, out double centreX, out double centreY));
        Assert.Equal(3, centreX, 12);
        Assert.Equal(3, centreY, 12);
    }

    [Fact]
    public void WallPlanBoundsValidation_DistinguishesSourceAndWriterLatticeEquality()
    {
        const double SameWriterBinFeet = 1.0e-8;
        List<double[]> plan =
        [
            [SameWriterBinFeet, 0], [4 + SameWriterBinFeet, 0],
            [4 + SameWriterBinFeet, 1], [SameWriterBinFeet, 1],
        ];
        double[] bounds = [0, 0, 0, 4, 1, 3];

        Assert.False(IfcExporter.WallPlanMatchesSerializedBounds(plan, bounds));
        Assert.True(IfcExporter.WallPlanMatchesSerializedBoundsAtIfcPrecision(
            plan, bounds));

        foreach (double[] point in plan)
            point[0] += 2.0e-5;
        Assert.False(IfcExporter.WallPlanMatchesSerializedBoundsAtIfcPrecision(
            plan, bounds));
    }

    [Fact]
    public void RectangularWallValidation_UsesWriterLatticeBoundsOnlyWhenExplicitlyAllowed()
    {
        var (wall, _, boundary) = ExactWallWithOneThroughOpening();
        const double SameWriterBinFeet = 1.0e-8;
        double[] shiftedBounds = (double[])wall.BoundingBox!.Clone();
        shiftedBounds[0] += SameWriterBinFeet;
        shiftedBounds[3] += SameWriterBinFeet;

        Assert.True(IfcExporter.TryGetExactRectangularWallGrossBoundary(
            boundary, wall.Location!, 1, shiftedBounds,
            out var gross, out _, out string rejectionReason),
            rejectionReason);
        Assert.False(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            gross, wall.Location!, 1, shiftedBounds,
            out _, out _, out _, out _));
        Assert.True(IfcExporter.TryGetExactStraightWallVerticalExtrusionDefinition(
            gross, wall.Location!, 1, shiftedBounds,
            out var snappedPlan, out _, out _, out rejectionReason,
            allowWriterLatticeBounds: true), rejectionReason);
        Assert.True(IfcExporter.WallPlanMatchesSerializedBoundsAtIfcPrecision(
            snappedPlan, shiftedBounds));
    }

