    [Fact]
    public void ExactFacetedShell_ClosesRoundoffGapBelowDeclaredIfcPrecision()
    {
        double[] a = [0, 0, 0], b = [1, 0, 0], c = [0, 1, 0], d = [0, 0, 1];
        double[] displacedB = [Math.BitIncrement(1.0), 0, 0];
        var faces = new List<GeoFace>
        {
            Face([a, c, b]),
            Face([a, displacedB, d]),
            Face([b, c, d]),
            Face([c, a, d]),
        };

        Assert.True(IfcExporter.IsExactFacetedShell(faces, [0, 1, 2, 3]));
        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            faces, [0, 1, 2, 3], out var oriented));
        Assert.True(IfcExporter.IsExactFacetedShell(oriented, [0, 1, 2, 3]));
    }

    [Fact]
    public void ExactFacetedShell_OrientsAfterRemovingPrecisionCollapsedLoopEdge()
    {
        double[] a = [0, 0, 0], nearA = [1e-6, 0, 0];
        double[] b = [1, 0, 0], c = [0, 1, 0], d = [0, 0, 1];
        var faces = new List<GeoFace>
        {
            Face([a, nearA, c, b]),
            Face([a, b, d]),
            Face([b, c, d]),
            Face([c, a, d]),
        };

        Assert.False(IfcExporter.IsExactFacetedShell(faces, [0, 1, 2, 3]));
        Assert.True(IfcExporter.TryOrientExactFacetedShell(
