        Assert.All(oriented, face => Assert.Equal(3, face.OuterVertices!.Count));
    }

    [Fact]
    public void ExactFacetedShell_ContractsUniqueSubPrecisionBoundaryWedge()
    {
        const double ifcPrecisionFeet = 1e-5 / 0.3048;
        double[] a = [0, 0, 0], b = [1, 0, 0], c = [0, 1, 0], d = [0, 0, 1];
        double[] displacedA = [0.75 * ifcPrecisionFeet, 0, 0];
        var faces = new List<GeoFace>
        {
            Face([a, c, b]),
            Face([a, b, d]),
            Face([b, c, d]),
            Face([c, displacedA, d]),
        };
        faces[0].AlternativeOuterVertices =
        [
            [10, 10, 10], [11, 10, 10], [10, 11, 10],
        ];

        Assert.False(IfcExporter.TryOrientExactFacetedShell(
            faces, [0, 1, 2, 3], out _));
        Assert.True(IfcExporter.TryOrientPrecisionContractedFacetedShell(
            faces, [0, 1, 2, 3], out var retained, out var oriented));
        Assert.Equal([0, 1, 2, 3], retained);
        Assert.True(IfcExporter.IsExactFacetedShell(oriented, [0, 1, 2, 3]));
    }

    [Fact]
    public void ExactFacetedShell_MatchesOnlyReciprocalInteriorVerticesOfParallelPaths()
    {
        (long X, long Y, long Z) start = (0, 0, 0), end = (3, 0, 30);
        (long X, long Y, long Z) first = (1, 0, 10), second = (2, 0, 20);
        (long X, long Y, long Z) parallelFirst = (1, 0, 12);
        (long X, long Y, long Z) parallelSecond = (2, 0, 22);
        const long railOffset = 50_000;
        (long X, long Y, long Z) Translate((long X, long Y, long Z) point) =>
            (point.X - railOffset, point.Y, point.Z);
        var edges = new List<((long X, long Y, long Z) A,
            (long X, long Y, long Z) B)>
        {
            (start, first), (first, second), (second, end),
            (start, parallelFirst), (parallelFirst, parallelSecond),
            (parallelSecond, end),
            (Translate(start), Translate(first)),
            (Translate(first), Translate(second)),
            (Translate(second), Translate(end)),
            (Translate(start), Translate(parallelFirst)),
            (Translate(parallelFirst), Translate(parallelSecond)),
            (Translate(parallelSecond), Translate(end)),
        };

        var pairs = IfcExporter.GetReciprocalInteriorAxisBoundaryPairs(edges);

        Assert.Equal(4, pairs.Count);
        Assert.Contains(pairs, pair => pair.First == first && pair.Second == parallelFirst);
        Assert.Contains(pairs, pair => pair.First == second && pair.Second == parallelSecond);
        Assert.DoesNotContain(pairs, pair =>
            Math.Abs(pair.First.X - pair.Second.X) == railOffset);
    }

    [Fact]
    public void ExactFacetedShell_RejectsCoordinateGapAboveDeclaredIfcPrecision()
    {
        double[] a = [0, 0, 0], b = [1, 0, 0], c = [0, 1, 0], d = [0, 0, 1];
        double[] displacedB = [1.001, 0, 0];
        var faces = new List<GeoFace>
        {
            Face([a, c, b]),
            Face([a, displacedB, d]),
            Face([b, c, d]),
            Face([c, a, d]),
        };

        Assert.False(IfcExporter.IsExactFacetedShell(faces, [0, 1, 2, 3]));
        Assert.False(IfcExporter.TryOrientPrecisionContractedFacetedShell(
