    }

    [Fact]
    public void ExactFacetedShell_RecoversConsistentOutwardOrientationFromSharedEdges()
    {
        double[] a = [0, 0, 0], b = [1, 0, 0], c = [0, 1, 0], d = [0, 0, 1];
        var faces = new List<GeoFace>
        {
            Face([a, c, b]),
            Face([d, b, a]), // deliberately reversed relative to the other three faces
            Face([b, c, d]),
            Face([c, a, d]),
        };

        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            faces, [0, 1, 2, 3], out var oriented));
        Assert.True(IfcExporter.IsExactFacetedShell(oriented, [0, 1, 2, 3]));

        double volume = 0;
        foreach (var face in oriented)
        {
            var ring = face.OuterVertices!;
            for (int index = 1; index + 1 < ring.Count; index++)
            {
                var p = ring[0]; var q = ring[index]; var r = ring[index + 1];
                volume += (p[0] * (q[1] * r[2] - q[2] * r[1])
                    - p[1] * (q[0] * r[2] - q[2] * r[0])
                    + p[2] * (q[0] * r[1] - q[1] * r[0])) / 6;
            }
        }
        Assert.True(volume > 0);
        Assert.Equal(1.0 / 6.0, volume, 12);
    }

    [Fact]
    public void PreferredMultiHostFamilyCut_RequiresExactProfileAndCompleteInverseHosts()
    {
        const int cutterId = 100;
        var preferredType = new Element
        {
            Id = 101,
            FamilyCutGeometry = BoxGeometry(-1, -2, 0, 1, 2, 2),
        };
        var genericType = new Element
        {
            Id = 102,
            FamilyCutGeometry = BoxGeometry(-1, -1, 0, 1, 1, 2),
        };
        var cutter = new Element
        {
            Id = cutterId,
            CategoryId = -2000023,
            SerializedHostId = 201,
            Transform = new InstanceTransform
            {
                Origin = [0, 0, 0],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
                SymbolId = preferredType.Id,
            },
            Parameters =
            [
                ExternalLengthParameter(
                    301, "8f2e4f9394724941a65d0ac468fd6a5d", 2),
                ExternalLengthParameter(
                    302, "da753fe3ecfa465b9a2c02f55d0c2ff1", 2),
            ],
        };
        var primaryHost = new Element
        {
            Id = 201,
            CategoryId = -2000011,
            CuttingElementIds = [cutterId],
            BoundingBox = [-3, -0.25, 0, 3, 0.25, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [-3, 0, 0],
                EndPoint = [3, 0, 0],
            },
            Parameters = [WallWidthParameter(0.5)],
            Geometry = BoxGeometry(-3, -0.25, 0, 3, 0.25, 3),
        };
        var secondaryHost = new Element
        {
            Id = 202,
            CategoryId = -2000011,
            CuttingElementIds = [cutterId],
            BoundingBox = [-3, 1.25, 0, 3, 1.75, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [-3, 1.5, 0],
                EndPoint = [3, 1.5, 0],
            },
            Parameters = [WallWidthParameter(0.5)],
            Geometry = BoxGeometry(-3, 1.25, 0, 3, 1.75, 3),
        };
        var noOpJoinedHost = new Element
        {
            Id = 203,
            CategoryId = -2000011,
            CuttingElementIds = [cutterId],
            BoundingBox = [4, -0.25, 0, 6, 0.25, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [4, 0, 0],
                EndPoint = [6, 0, 0],
            },
            Parameters = [WallWidthParameter(0.5)],
            Geometry = BoxGeometry(4, -0.25, 0, 6, 0.25, 3),
        };
        var linkedTypes = new List<Element> { preferredType, genericType };
        var hosts = new List<Element>
        {
            primaryHost,
            secondaryHost,
            noOpJoinedHost,
        };
        Assert.True(IfcExporter.TryBuildFamilyCutHostedOpeningGeometry(
            cutter, preferredType, hosts, out var preferredCandidate));
        Assert.True(IfcExporter.TryBuildFamilyCutHostedOpeningGeometry(
            cutter, genericType, hosts, out var genericCandidate));
        var candidates = new List<IfcExporter.HostedOpeningGeometry>
        {
            preferredCandidate,
            genericCandidate,
        };
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [cutterId] =
                [primaryHost.Id, secondaryHost.Id, noOpJoinedHost.Id],
        };

        Assert.True(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, hosts, inverseHosts,
                out var opening));
        Assert.Same(preferredCandidate.Boundary, opening.Boundary);
        Assert.Equal(2, opening.WidthFt, 12);
        Assert.Equal(4, opening.DepthFt, 12);
        Assert.Equal(2, opening.HeightFt, 12);
        Assert.True(opening.IsExactConcordantFamilyCut);
        Assert.True(opening.IsExactParameterizedRectangularCut);
        Assert.True(IfcExporter
            .ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                opening));

        var thirdIntersectingHost = new Element
        {
            Id = 204,
            CategoryId = -2000011,
            CuttingElementIds = [cutterId],
            BoundingBox = [-3, -0.25, 0, 3, 0.25, 3],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [-3, 0, 0],
                EndPoint = [3, 0, 0],
            },
            Parameters = [WallWidthParameter(0.5)],
            Geometry = BoxGeometry(-3, -0.25, 0, 3, 0.25, 3),
        };
        var excessIntersectingHosts = new List<Element>
        {
            primaryHost,
            secondaryHost,
            thirdIntersectingHost,
            noOpJoinedHost,
        };
        inverseHosts[cutterId] =
        [
            primaryHost.Id,
            secondaryHost.Id,
            thirdIntersectingHost.Id,
            noOpJoinedHost.Id,
        ];
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, excessIntersectingHosts,
                inverseHosts, out _));
        inverseHosts[cutterId] =
            [primaryHost.Id, secondaryHost.Id, noOpJoinedHost.Id];

        inverseHosts[cutterId] = [primaryHost.Id];
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, hosts, inverseHosts, out _));
        inverseHosts[cutterId] =
            [primaryHost.Id, secondaryHost.Id, noOpJoinedHost.Id];

        var oneIntersectionHosts = new List<Element>
        {
            primaryHost,
            noOpJoinedHost,
        };
        inverseHosts[cutterId] = [primaryHost.Id, noOpJoinedHost.Id];
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, oneIntersectionHosts,
                inverseHosts, out _));
        inverseHosts[cutterId] =
            [primaryHost.Id, secondaryHost.Id, noOpJoinedHost.Id];

        noOpJoinedHost.BoundingBox = [-3, -0.25, 0, 3, 0.25, 3];
        noOpJoinedHost.Geometry = BoxGeometry(-3, -0.25, 0, 3, 0.25, 3);
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, hosts, inverseHosts, out _));
        noOpJoinedHost.BoundingBox = [4, -0.25, 0, 6, 0.25, 3];
        noOpJoinedHost.Geometry = BoxGeometry(4, -0.25, 0, 6, 0.25, 3);

        secondaryHost.CuttingElementIds = [cutterId, cutterId];
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, hosts, inverseHosts, out _));
        secondaryHost.CuttingElementIds = [cutterId];

        candidates[1] = genericCandidate with
        {
            Boundary = BoxGeometry(-1.1, -1, 0, 1.1, 1, 2),
        };
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, hosts, inverseHosts, out _));
        candidates[1] = genericCandidate;

        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, [genericType, preferredType],
                [genericCandidate, preferredCandidate],
                hosts, inverseHosts, out _));

        cutter.Parameters[0].Value = 2.1;
        Assert.False(IfcExporter
            .TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                cutter, linkedTypes, candidates, hosts, inverseHosts, out _));

        static Parameter ExternalLengthParameter(
            int id, string guid, double value) => new()
        {
            Id = id,
            Definition = new Definition { Name = $"external-{id}" },
            StorageType = StorageType.Double,
            ForgeId =
                $"autodesk.parameter.aec.revit.external.-1:{guid}-1.0.0",
            SpecType = "autodesk.spec.aec:length-2.0.0",
            Value = value,
        };
    }

    [Fact]
    public void FamilyComplexCut_ReplacesOnlyDummyHostSlabAndPreservesProtrusions()
    {
        var type = new Element
        {
            FamilyCutGeometry = BoxGeometry(-1, -3, 0, 1, 3, 4),
            FamilyCutClosurePlaneOrigin = [0, 1, 0],
            FamilyCutClosurePlaneNormal = [0, 1, 0],
        };
        var instance = new Element
        {
            SerializedHostId = 101,
            Transform = new InstanceTransform
            {
                Origin = [10, 0, 20],
                BasisX = [1, 0, 0],
                BasisY = [0, 1, 0],
                BasisZ = [0, 0, 1],
            },
        };
        var host = new Element
        {
            Id = 101,
            Parameters = [WallWidthParameter(0.5)],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [20, 0, 0],
            },
            // Joined/corrupt face geometry must not replace the serialized wall section.
            Geometry = BoxGeometry(0, -5, 0, 20, 5, 30),
        };
        var secondaryFinishHost = new Element
        {
            Id = 202,
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [0, 0, 0], EndPoint = [20, 0, 0],
            },
            Geometry = BoxGeometry(0, -0.75, 0, 20, 0.75, 30),
        };

        Assert.True(IfcExporter.TryBuildFamilyCutHostedOpeningGeometry(
            instance, type, [host, secondaryFinishHost], out var opening));
        Assert.True(opening.ExactDepth);
