            opening.Boundary.BoundingBox!);
        Assert.Equal(2, opening.WidthFt, 12);
        Assert.Equal(4.5, opening.DepthFt, 12);
        Assert.Equal(4, opening.HeightFt, 12);
        Assert.True(opening.Boundary.BrepSolids!.Single().IsClosed);
    }

