    [Fact]
    public void FamilyComplexCut_ClosesSerializedDummyHostIntervalFromExactProfiles()
    {
        double x0 = -1, x1 = 1, closure = 1, y0 = -3, y1 = 3, z0 = 0, z1 = 4;
        var partialFaces = new List<GeoFace>
        {
            // Exterior portion stored by m_complexCutGeoms.
            Face([[x0, closure, z0], [x1, closure, z0], [x1, y1, z0], [x0, y1, z0]]),
            Face([[x0, closure, z1], [x0, y1, z1], [x1, y1, z1], [x1, closure, z1]]),
            Face([[x0, closure, z0], [x0, closure, z1], [x0, y1, z1], [x0, y1, z0]]),
            Face([[x1, closure, z0], [x1, y1, z0], [x1, y1, z1], [x1, closure, z1]]),
            Face([[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]]),
            // Opposite limit and duplicated closure faces are serialized without the
            // four side faces inside the dummy host.
            Face([[x0, y0, z0], [x0, y0, z1], [x1, y0, z1], [x1, y0, z0]]),
            Face([[x0, closure, z0], [x0, closure, z1], [x1, closure, z1], [x1, closure, z0]]),
            Face([[x0, closure, z0], [x0, closure, z1], [x1, closure, z1], [x1, closure, z0]]),
        };
        var type = new Element
        {
            FamilyCutGeometry = new GeometryData
            {
                Faces = partialFaces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(0, partialFaces.Count).ToList(),
                        IsClosed = false,
                    },
                ],
            },
            FamilyCutClosurePlaneOrigin = [0, closure, 0],
            FamilyCutClosurePlaneNormal = [0, 1, 0],
        };
        var instance = new Element
        {
            SerializedHostId = 101,
            Transform = new InstanceTransform
            {
                Origin = [0, 0, 0],
                BasisX = [1, 0, 0], BasisY = [0, 1, 0], BasisZ = [0, 0, 1],
            },
        };
        var host = new Element
        {
            Id = 101,
            Parameters = [WallWidthParameter(0.5)],
            Location = new LocationCurve
            {
                CurveType = "Line", StartPoint = [-10, 0, 0], EndPoint = [10, 0, 0],
            },
            Geometry = BoxGeometry(-10, -0.25, 0, 10, 0.25, 10),
        };

        Assert.True(IfcExporter.TryBuildFamilyCutHostedOpeningGeometry(
            instance, type, [host], out var opening));
        type.FamilyCutGeometry.BrepSolids![0].IsClosed = true;
        Assert.True(IfcExporter.TryBuildFamilyCutHostedOpeningGeometry(
            instance, type, [host], out opening));
        Assert.True(opening.IsExactRecoveredClosedFamilyCutProfile);
        Assert.NotNull(opening.Boundary);
        Assert.Equal(6, opening.Boundary!.Faces.Count);
        Assert.Equal([-1, -2.25, 0, 1, 2.25, 4], opening.Boundary.BoundingBox!);
        Assert.True(IfcExporter.IsExactFacetedShell(
            opening.Boundary.Faces, opening.Boundary.BrepSolids!.Single().FaceIndices));
    }

    [Fact]
    public void RectangularPrismSweptOpening_PreservesConfirmedFamilyInstanceFrame()
    {
        var boundary = BoxGeometry(
            -2.13254593175856, -2.0997375328084, 0,
            2.1325459317585, 2.09973753281155, 6.88976377952756);
        var definition = new IfcExporter.HostedOpeningGeometry(
            0, 0, 1, 0,
