                Origin = [0, 0, 0],
                BasisX = [1, 0, 0], BasisY = [0, 1, 0], BasisZ = [0, 0, 1],
                SymbolId = renderSymbol.Id,
            },
            Parameters =
            [
                new Parameter
                {
                    Id = -1002050,
                    StorageType = StorageType.ElementId,
                    Value = familyType.Id,
                    Definition = new Definition { Name = "ELEM_TYPE_PARAM" },
                },
            ],
        };
        var elements = new Dictionary<int, Element>
        {
            [renderSymbol.Id] = renderSymbol,
            [familyType.Id] = familyType,
            [classIdCollision.Id] = classIdCollision,
        };

        Assert.Same(renderSymbol, IfcExporter.LinkedFamilyType(instance, elements));
        Assert.Equal([familyType], IfcExporter.LinkedFamilyCutTypes(instance, elements));

        renderSymbol.FamilyCutLoops =
        [
            new FamilyCutLoopData(
                [[-1, -0.5, 0], [1, -0.5, 0], [1, -0.5, 2], [-1, -0.5, 2]],
                [0, -1, 0], 0),
        ];
        Assert.Equal([renderSymbol, familyType],
            IfcExporter.LinkedFamilyCutTypes(instance, elements));
        renderSymbol.FamilyCutLoops = null;

        renderSymbol.FamilyCutGeometry = BoxGeometry(-1, -1, 0, 1, 1, 4);
        Assert.Equal([renderSymbol, familyType],
            IfcExporter.LinkedFamilyCutTypes(instance, elements));

        var placedVariant = new Element
        {
            Id = 8538617,
            FamilyCutGeometry = BoxGeometry(-1, -0.2, 0, 1, 0.2, 4),
        };
        elements[placedVariant.Id] = placedVariant;
        instance.Geometry = new GeometryData
        {
            Instances =
            [
                new GeoInstance
                {
                    SymbolId = placedVariant.Id,
                    Transform = [1, 0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0],
                },
            ],
        };
        Assert.Equal([placedVariant, renderSymbol, familyType],
            IfcExporter.LinkedFamilyCutTypes(instance, elements));
    }

