    [Fact]
    public void CompleteOpenFourteenFaceBottomSlotValidation_RequiresExactSourceWriterAndReferenceNetwork()
    {
        const int wallId = 94101;
        const int cutterId = 94102;
        const int directHostId = 94103;
        var rebuilt = ExtrudedSideProfileWallGeometry(
        [
            (10, 3), (0, 3), (0, 2),
            (1, 2), (1, 0), (10, 0),
        ], -0.5, 0.5);
        var lowAlternative = rebuilt.Faces[0].OuterVertices!
            .Select(point => (double[])point.Clone()).ToList();
        var highAlternative = rebuilt.Faces[1].OuterVertices!
            .Select(point => (double[])point.Clone()).ToList();
        var sourceFaces = new List<GeoFace>
        {
            Face([[3, -0.5, 0], [5, -0.5, 0],
                [5, -0.5, 1], [3, -0.5, 1]]),
            Face([[1, -0.5, 0], [3, -0.5, 0],
                [3, 0.5, 0], [1, 0.5, 0]]),
            Face([[3, 0.5, 0], [3, 0.5, 1],
                [5, 0.5, 1], [5, 0.5, 0]]),
            Face([[10, -0.5, 0], [10, 0.5, 0],
                [10, 0.5, 3], [10, -0.5, 3]]),
            Face([[0, -0.5, 3], [0, 0.5, 3],
                [10, 0.5, 3], [10, -0.5, 3]]),
            Face([[0, -0.5, 2], [0, 0.5, 2],
                [0, 0.5, 3], [0, -0.5, 3]]),
            Face([[0.5, -0.5, 0], [0.5, 0.5, 0],
                [0.5, 0.5, 2], [0.5, -0.5, 2]]),
            Face([[5, -0.5, 0], [10, -0.5, 0],
                [10, 0.5, 0], [5, 0.5, 0]]),
            Face([[0, -0.5, 2], [0, 0.5, 2],
                [0.5, 0.5, 2], [0.5, -0.5, 2]]),
            Face([[1, -0.5, 0], [1, 0.5, 0],
                [1, 0.5, 2], [1, -0.5, 2]]),
            Face([[0.5, -0.5, 2], [0.5, 0.5, 2],
                [1, 0.5, 2], [1, -0.5, 2]]),
            Face([[3, -0.5, 0], [3, 0.5, 0],
                [3, 0.5, 1], [3, -0.5, 1]]),
            Face([[3, -0.5, 1], [3, 0.5, 1],
                [5, 0.5, 1], [5, -0.5, 1]]),
            Face([[5, -0.5, 0], [5, -0.5, 1],
                [5, 0.5, 1], [5, 0.5, 0]]),
        };
        sourceFaces[0].AlternativeOuterVertices = lowAlternative;
        sourceFaces[2].AlternativeOuterVertices = highAlternative;
        var source = new GeometryData
        {
            BoundingBox = [0, -0.5, 0, 10, 0.5, 3],
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, 14).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = wallId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0.5, 0, 0],
                EndPoint = [9.5, 0, 0],
            },
            BoundingBox = (double[])source.BoundingBox.Clone(),
            Parameters = [WallWidthParameter(1)],
            References = [cutterId, directHostId],
            Geometry = source,
        };
        var directedWriter = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 4, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 2, DepthFt: 10,
            BaseZFt: -2, HeightFt: 3,
            ExactDepth: true, IsFamilyCutLoop: true);
        var cutter = new Element
        {
            Id = cutterId,
            CategoryId = -2000023,
            Category = "OST_Doors",
            HostId = directHostId,
            SerializedHostId = directHostId,
            References = [directHostId],
        };
        var directHost = new Element
        {
            Id = directHostId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0.5, 0, -3],
                EndPoint = [9.5, 0, -3],
            },
            BoundingBox = [0, -0.5, -3, 10, 0.5, 3],
            Parameters = [WallWidthParameter(1)],
            References = [cutterId, wallId],
            Geometry = BoxGeometry(0, -0.5, -3, 10, 0.5, 3),
        };
        var elements = new Dictionary<int, Element>
        {
            [wallId] = wall,
            [cutterId] = cutter,
            [directHostId] = directHost,
        };

        Assert.True(IfcExporter.TryBuildStraightWallBoundary(
            wall, out var actualRebuilt));
        Assert.True(IfcExporter
            .TryGetExactCompleteOpenFourteenFaceBottomSlotFamilyCutGeometry(
                wall, wall.BoundingBox, actualRebuilt, directedWriter,
                out var gross, out var finiteWriter, out string reason), reason);
        Assert.Equal(
            "exact-complete-open-fourteen-face-bottom-slot-family-cut",
            reason);
        Assert.Equal(6, gross.Faces.Count);
        Assert.False(finiteWriter.IsFamilyCutLoop);
        Assert.True(finiteWriter.IsExactFamilyCutLoopWriterBox);
        Assert.True(IfcExporter
            .TryGetExactReferenceOnlySixPointJoinBottomSlotFamilyCutOpening(
                cutter, wall, [directHostId, wallId],
                [directHostId, wallId], elements, directedWriter,
                out finiteWriter));

        var emittedIds = new Dictionary<int, List<int>>
        {
            [wallId] = [cutterId],
        };
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>
        {
            [wallId] = [(cutterId, finiteWriter)],
        };
        var exactPairs = new HashSet<(int WallId, int CutterId)>
        {
            (wallId, cutterId),
        };
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFourteenFaceBottomSlotFamilyCutOpening(
                wall, wall.BoundingBox, actualRebuilt,
                emittedIds, emittedOperands,
                new Dictionary<int, List<int>>(), exactPairs,
                out _, out var verifiedIds));
        Assert.Equal([cutterId], verifiedIds);

        sourceFaces[12].OuterVertices![0][0] += 0.25;
        Assert.False(IfcExporter
            .TryGetExactCompleteOpenFourteenFaceBottomSlotFamilyCutGeometry(
                wall, wall.BoundingBox, actualRebuilt, directedWriter,
                out _, out _, out _));
        sourceFaces[12].OuterVertices[0][0] -= 0.25;

        directHost.References!.Remove(wallId);
        Assert.False(IfcExporter
            .TryGetExactReferenceOnlySixPointJoinBottomSlotFamilyCutOpening(
                cutter, wall, [directHostId, wallId],
                [directHostId, wallId], elements, directedWriter, out _));
        directHost.References.Add(wallId);

        exactPairs.Clear();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFourteenFaceBottomSlotFamilyCutOpening(
                wall, wall.BoundingBox, actualRebuilt,
                emittedIds, emittedOperands,
                new Dictionary<int, List<int>>(), exactPairs,
                out _, out _));
    }

    [Fact]
    public void CompleteClosedTenFaceHoleDetachedPatchSketchGate_AcceptsExactSourceAndReturnsUniqueSketchTag()
    {
        var (wall, rebuilt, elements, inverseHosts, emittedIds,
            emittedOperands, standaloneIds, _, _, innerLines) =
            CompleteClosedTenFaceHoleDetachedPatchSketchFixture();

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteClosedTenFaceHoleWithDetachedPatchAndExactSketchOpening(
                wall, wall.BoundingBox!, rebuilt, elements, inverseHosts,
                emittedIds, emittedOperands, standaloneIds,
                out var gross, out var cutterIds,
                out var sourceOpenings, out int sourceTagId));

        Assert.Equal(wall.CuttingElementIds, cutterIds);
        Assert.Equal(innerLines[0].Id, sourceTagId);
        var opening = Assert.Single(sourceOpenings);
        Assert.Equal(1.5, opening.CentreXFt, 12);
        Assert.Equal(1, opening.WidthFt, 12);
        Assert.Equal(1, opening.BaseZFt, 12);
        Assert.Equal(1, opening.HeightFt, 12);
        Assert.Equal(-0.5, opening.NormalMinimumFt, 12);
