        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            wall, wall.BoundingBox!, gross));
    }

    [Fact]
    public void CompleteClosedTenFaceHoleDetachedPatchSketchGate_FailsClosedOnGeometryWriterAndSketchMutations()
    {
        var (wall, rebuilt, elements, inverseHosts, emittedIds,
            emittedOperands, standaloneIds, owner, anchor, innerLines) =
            CompleteClosedTenFaceHoleDetachedPatchSketchFixture();
        bool Gate() => IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteClosedTenFaceHoleWithDetachedPatchAndExactSketchOpening(
                wall, wall.BoundingBox!, rebuilt, elements, inverseHosts,
                emittedIds, emittedOperands, standaloneIds,
                out _, out _, out _, out _);

        Assert.True(Gate());

        wall.Geometry!.BrepSolids![0].FaceIndices.Add(10);
        Assert.False(Gate());
        wall.Geometry.BrepSolids[0].FaceIndices.RemoveAt(10);

        wall.Geometry.Faces![10].OuterVertices![0][0] += 0.25;
        Assert.False(Gate());
        wall.Geometry.Faces[10].OuterVertices[0][0] -= 0.25;

        int touchingCutterId = wall.CuttingElementIds![2];
        var touchingOperand = emittedOperands[wall.Id][2];
        emittedOperands[wall.Id][2] =
            (touchingCutterId,
                touchingOperand.Operand with { CentreYFt = -0.99 });
        Assert.False(Gate());
        emittedOperands[wall.Id][2] = touchingOperand;

        int firstCutterId = wall.CuttingElementIds[0];
        int removedHostId = inverseHosts[firstCutterId][^1];
        inverseHosts[firstCutterId].RemoveAt(
            inverseHosts[firstCutterId].Count - 1);
        Assert.False(Gate());
        inverseHosts[firstCutterId].Add(removedHostId);

        int directHostId = elements[firstCutterId].HostId!.Value;
        int peerHostId = inverseHosts[firstCutterId].First(hostId =>
            hostId != wall.Id && hostId != directHostId);
        var peerHost = elements[peerHostId];
        peerHost.References!.Remove(firstCutterId);
        Assert.False(Gate());
        peerHost.References.Add(firstCutterId);

        peerHost.References.Add(firstCutterId);
        Assert.False(Gate());
        peerHost.References.RemoveAt(peerHost.References.Count - 1);

        elements[firstCutterId].References!.Add(peerHostId);
        Assert.False(Gate());
        elements[firstCutterId].References.Remove(peerHostId);

        standaloneIds[wall.Id].Add(99999);
        Assert.False(Gate());
        standaloneIds[wall.Id].Clear();

        owner.SketchLoops![1][0][0] += 0.25;
        Assert.False(Gate());
        owner.SketchLoops[1][0][0] -= 0.25;

        int removedOwnerReference = owner.References![3];
        owner.References.RemoveAt(3);
        Assert.False(Gate());
        owner.References.Insert(3, removedOwnerReference);

        innerLines[2].References!.Remove(owner.Id);
        Assert.False(Gate());
        innerLines[2].References.Add(owner.Id);

        anchor.References!.Remove(owner.Id);
        Assert.False(Gate());
        anchor.References.Add(owner.Id);

        var anchorFamilyTypeParameter = Assert.Single(anchor.Parameters);
        anchor.Parameters.Clear();
        Assert.True(Gate());
        anchor.Parameters.Add(anchorFamilyTypeParameter);
        anchorFamilyTypeParameter.Value = wall.Id;
        Assert.False(Gate());
        anchorFamilyTypeParameter.Value = owner.Id;

        wall.References!.Add(innerLines[0].Id);
        Assert.False(Gate());
        wall.References.Remove(innerLines[0].Id);

        innerLines[3].Location!.EndPoint[0] += 0.25;
        Assert.False(Gate());
        innerLines[3].Location.EndPoint[0] -= 0.25;

        innerLines[0].TypeId = innerLines[1].Id;
        Assert.False(Gate());
    }

    [Fact]
    public void ExactMappedSideTangentCollinearCapGate_RecoversEightPointGrossProfile()
    {
        var data = ExactMappedSideTangentCollinearCapFixture();

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactMappedSideTangentOpening(
                data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                data.Elements, data.VisibleWallIds, data.InverseHosts,
                data.EmittedIds, data.EmittedOperands, data.StandaloneIds,
                out var gross, out var cutterIds,
                out bool preserveCollinearPlan));

        Assert.Equal([data.Cutter.Id], cutterIds);
        Assert.True(preserveCollinearPlan);
        Assert.Equal(10, gross.Faces.Count);
        var solid = Assert.Single(gross.BrepSolids!);
        Assert.True(solid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 10), solid.FaceIndices);
        Assert.True(IfcExporter.IsExactFacetedShell(
            gross.Faces, solid.FaceIndices));
        Assert.True(IfcExporter
            .TryGetExactStraightWallVerticalExtrusionDefinition(
                gross, data.Wall.Location!,
                (double)data.Wall.Parameters.Single(parameter =>
                    parameter.Id == -1001000).Value!,
                data.Wall.BoundingBox!, out var plan,
                out double baseZFt, out double heightFt,
                out string reason), reason);
        Assert.Equal("exact-collinear-boundary-subdivision", reason);
        Assert.Equal(8, plan.Count);
        Assert.Equal(data.Wall.BoundingBox![2], baseZFt, 12);
        Assert.Equal(data.Wall.BoundingBox[5] - data.Wall.BoundingBox[2],
            heightFt, 12);

        var location = data.Wall.Location!;
        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double length = Math.Sqrt(dx * dx + dy * dy);
        double axisX = dx / length, axisY = dy / length;
        double normalX = -axisY, normalY = axisX;
        static long Bin(double feet) => checked((long)Math.Round(
            feet * 0.3048 / 1.0e-5, MidpointRounding.ToEven));
        var projectedPlan = plan.Select(point => (
            Along: Bin(point[0] * axisX + point[1] * axisY),
            Normal: Bin(point[0] * normalX + point[1] * normalY)))
            .ToHashSet();
        var expectedProjectedPlan = new HashSet<(long Along, long Normal)>
        {
            (796026, 365183), (796026, 384183),
            (777026, 384183), (567182, 384183),
            (548182, 365183), (645026, 365183),
            (653026, 365183), (788026, 365183),
        };
        Assert.True(expectedProjectedPlan.SetEquals(projectedPlan));
    }

    [Fact]
    public void ExactMappedSideTangentCollinearCapGate_FailsClosedOnAuthorityMutations()
    {
        static bool Gate(ExactMappedSideTangentCollinearCapData data) =>
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactMappedSideTangentOpening(
                    data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                    data.Elements, data.VisibleWallIds, data.InverseHosts,
                    data.EmittedIds, data.EmittedOperands,
                    data.StandaloneIds, out _, out _, out _);
        static void Reject(string contract,
            Action<ExactMappedSideTangentCollinearCapData> mutate)
        {
            var candidate = ExactMappedSideTangentCollinearCapFixture();
            mutate(candidate);
            Assert.False(Gate(candidate), contract);
        }

        Assert.True(Gate(ExactMappedSideTangentCollinearCapFixture()));

        Reject("source topology", data =>
        {
            var openSolid = data.Wall.Geometry!.BrepSolids!
                .Single(solid => !solid.IsClosed);
            openSolid.FaceIndices[^1] = openSolid.FaceIndices[0];
        });
        Reject("source alternative", data =>
            data.Wall.Geometry!.Faces[0]
                .AlternativeOuterVertices![0][0] += 0.05);
        Reject("duplicate exact mapped instance", data =>
        {
            var instance = Assert.Single(
                data.Cutter.Geometry!.ExactMappedInstances!);
            data.Cutter.Geometry.ExactMappedInstances!.Add(new GeoInstance
            {
                SymbolId = instance.SymbolId,
                Transform = (double[])instance.Transform.Clone(),
            });
        });
        Reject("mapped instance transform has trailing payload", data =>
        {
            var instance = Assert.Single(
                data.Cutter.Geometry!.ExactMappedInstances!);
            instance.Transform = [.. instance.Transform, 0];
        });
        Reject("mapped instance transform is missing", data =>
            Assert.Single(data.Cutter.Geometry!.ExactMappedInstances!)
                .Transform = null!);
        Reject("mapped cutter has no serialized family type", data =>
            data.Cutter.Parameters.RemoveAll(parameter =>
                parameter.Definition?.Name == "ELEM_TYPE_PARAM"));
        Reject("family type aliases mapped symbol", data =>
            data.Cutter.Parameters.Single(parameter =>
                parameter.Definition?.Name == "ELEM_TYPE_PARAM").Value =
                data.Cutter.Transform!.SymbolId);
        Reject("mapped symbol aliases cutter", data =>
        {
            data.Cutter.Transform!.SymbolId = data.Cutter.Id;
            Assert.Single(data.Cutter.Geometry!.ExactMappedInstances!)
                .SymbolId = data.Cutter.Id;
        });
        Reject("emitted operand differs from mapped source", data =>
        {
            var emitted = Assert.Single(data.EmittedOperands[data.Wall.Id]);
            data.EmittedOperands[data.Wall.Id][0] =
                (emitted.CutterId, emitted.Operand with
                {
                    WidthFt = emitted.Operand.WidthFt + 0.01,
                });
        });
        Reject("mapped box overlaps instead of touching wall side", data =>
        {
            var location = data.Wall.Location!;
            double dx = location.EndPoint[0] - location.StartPoint[0];
            double dy = location.EndPoint[1] - location.StartPoint[1];
            double length = Math.Sqrt(dx * dx + dy * dy);
            double shiftX = -dy / length * 0.05;
            double shiftY = dx / length * 0.05;
            foreach (double[] point in data.Cutter.Geometry!.Faces
                         .SelectMany(face => face.OuterVertices!))
            {
                point[0] += shiftX;
                point[1] += shiftY;
            }
            Assert.True(IfcExporter.TryBuildExactMappedHostedSideShellGeometry(
                data.Cutter, out var shiftedOperand));
            foreach (int hostId in data.HostIds)
                data.EmittedOperands[hostId][0] =
                    (data.Cutter.Id, shiftedOperand);
        });
        Reject("inverse host graph cardinality", data =>
            data.InverseHosts[data.Cutter.Id].RemoveAt(
                data.InverseHosts[data.Cutter.Id].Count - 1));
        Reject("inverse peer reciprocity", data =>
        {
            int peerId = data.HostIds.First(hostId =>
                hostId != data.Wall.Id
                && hostId != data.Cutter.HostId);
            data.Elements[peerId].CuttingElementIds = [];
        });
        Reject("target wall loses forward extra-host authority", data =>
        {
            int retainedPeerId = data.Cutter.ExtraHostIds!
                .Single(hostId => hostId != data.Wall.Id);
            int replacementPeerId = data.HostIds.First(hostId =>
                hostId != data.Wall.Id
                && hostId != data.Cutter.HostId
                && hostId != retainedPeerId);
            data.Cutter.ExtraHostIds = [retainedPeerId, replacementPeerId];
            data.Cutter.References =
                [data.Cutter.HostId!.Value, retainedPeerId, replacementPeerId];
        });
        Reject("standalone opening", data =>
            data.StandaloneIds[data.Wall.Id].Add(99999));
        Reject("source inner loop", data =>
            data.Wall.Geometry!.Faces[3].InnerVertices = null);
    }

    [Fact]
    public void CompleteOpenSixteenFaceSplitRevealGate_RecoversGrossAndEightExactWriterOverrides()
    {
        const double feetToMetres = 0.3048;
        var data = CompleteOpenSixteenFaceSplitRevealFixture();

        Assert.Equal(16, data.Wall.Geometry!.Faces.Count);
        var sourceSolid = Assert.Single(data.Wall.Geometry.BrepSolids!);
        Assert.False(sourceSolid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 16), sourceSolid.FaceIndices);
        Assert.Equal(2, data.Wall.Geometry.Faces.Count(face =>
            face.InnerVertices is [{ Count: 4 }]));
        Assert.Equal(10, data.Rebuilt.Faces.Count);
        Assert.True(Assert.Single(data.Rebuilt.BrepSolids!).IsClosed);
        Assert.Empty(data.FirstCutter.Geometry!.Faces);
        Assert.Empty(data.SecondCutter.Geometry!.Faces);
        Assert.Single(data.FirstCutter.Geometry.Instances!);
        Assert.Single(data.SecondCutter.Geometry.Instances!);
        Assert.Null(data.FirstCutter.Geometry.ExactMappedInstances);
        Assert.Null(data.SecondCutter.Geometry.ExactMappedInstances);

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters(
                data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                data.Elements, data.VisibleWallIds, data.InverseHosts,
                data.EmittedIds, data.EmittedOperands,
                data.StandaloneIds, out var gross,
                out var cutterIds, out var writerOverrides));

        Assert.Equal([data.FirstCutter.Id, data.SecondCutter.Id], cutterIds);
        Assert.Equal(6, gross.Faces.Count);
        Assert.All(gross.Faces, face =>
            Assert.False(face.InnerVertices is { Count: > 0 }));
        var solid = Assert.Single(gross.BrepSolids!);
        Assert.True(solid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 6), solid.FaceIndices);
        Assert.True(IfcExporter.IsExactFacetedShell(
            gross.Faces, solid.FaceIndices));
        Assert.True(IfcExporter.CanExportStandardCaseWallAsSweptSolid(
            data.Wall, data.Wall.BoundingBox!, gross));

        Assert.Equal(7, data.InverseHosts[data.FirstCutter.Id].Count);
        Assert.Null(data.Elements[data.ReferenceOnlyHostId]
            .CuttingElementIds);
        Assert.Equal(1, data.Elements[data.ReferenceOnlyHostId]
            .References!.Count(id => id == data.FirstCutter.Id));
        Assert.Equal(6, data.FirstHostIds.Count(hostId =>
            data.Elements[hostId].CuttingElementIds?.Count(
                id => id == data.FirstCutter.Id) == 1));
        Assert.All(data.SecondHostIds, hostId =>
            Assert.Equal(1, data.Elements[hostId].CuttingElementIds!
                .Count(id => id == data.SecondCutter.Id)));
        Assert.Equal(1, data.Elements[data.FirstHostIds[^1]]
            .CuttingElementIds!.Count(id => id == data.FirstCutter.Id));
        Assert.Equal(6, data.EmittedIds.Count(pair =>
            pair.Value.Contains(data.FirstCutter.Id)));
        Assert.Equal(2, data.InverseHosts[data.SecondCutter.Id].Count);
        Assert.Equal(2, data.EmittedIds.Count(pair =>
            pair.Value.Contains(data.SecondCutter.Id)));
        Assert.All(new[] { data.FirstCutter, data.SecondCutter }, cutter =>
        {
            Assert.Equal(2, cutter.References!.Count(
                id => id == cutter.FamilyTypeId));
            Assert.Equal(2, cutter.References.Count(
                id => id == cutter.Transform!.SymbolId));
        });
        Assert.Equal(1, data.FirstMappedSymbol.References!.Count(
            id => id == data.FirstCutter.FamilyTypeId));
        Assert.Equal(1, data.SecondMappedSymbol.References!.Count(
            id => id == data.SecondCutter.FamilyTypeId));
        var bboxThicknessOverrideHost =
            data.Elements[data.BboxThicknessOverrideHostId];
        Assert.Equal(0.2,
            (double)bboxThicknessOverrideHost.Parameters.Single(parameter =>
                parameter.Id == -1001000).Value! * feetToMetres, 12);
        double bboxThicknessFt = Math.Min(
            Math.Abs(bboxThicknessOverrideHost.BoundingBox![3]
                - bboxThicknessOverrideHost.BoundingBox[0]),
            Math.Abs(bboxThicknessOverrideHost.BoundingBox[4]
                - bboxThicknessOverrideHost.BoundingBox[1]));
        Assert.Equal(0.02, bboxThicknessFt * feetToMetres, 12);
        var bboxThicknessLegacy = Assert.Single(
            data.EmittedOperands[data.BboxThicknessOverrideHostId], item =>
                item.CutterId == data.FirstCutter.Id).Operand;
        Assert.Equal(0.0202,
            bboxThicknessLegacy.DepthFt * feetToMetres, 12);
        foreach (int hostId in data.FirstHostIds)
        {
            var host = data.Elements[hostId];
            double lineX = host.Location!.EndPoint[0]
                - host.Location.StartPoint[0];
            double lineY = host.Location.EndPoint[1]
                - host.Location.StartPoint[1];
            double lineLength = Math.Sqrt(lineX * lineX + lineY * lineY);
            double[] expectedBasis = data.SecondHostIds.Contains(hostId)
                ? data.FirstCutter.Transform!.BasisY
                : data.FirstCutter.Transform!.BasisX;
            double absoluteDot = Math.Abs(
                lineX / lineLength * expectedBasis[0]
                + lineY / lineLength * expectedBasis[1]);
            Assert.Equal(1, absoluteDot, 12);
        }
        foreach (int hostId in data.FirstHostIds.Take(6)
                     .Where(id => id != data.CorrectPeerHostId))
        {
            var host = data.Elements[hostId];
            double lineX = host.Location!.EndPoint[0]
                - host.Location.StartPoint[0];
            double lineY = host.Location.EndPoint[1]
                - host.Location.StartPoint[1];
            double lineLength = Math.Sqrt(lineX * lineX + lineY * lineY);
            var current = Assert.Single(data.EmittedOperands[hostId], item =>
                item.CutterId == data.FirstCutter.Id).Operand;
            Assert.Equal(lineX / lineLength, current.AxisX, 12);
            Assert.Equal(lineY / lineLength, current.AxisY, 12);
        }
        const double twoHostLegacyShiftFt = 0.01 / 0.3048;
        foreach (int hostId in data.SecondHostIds)
        {
            var current = Assert.Single(data.EmittedOperands[hostId], item =>
                item.CutterId == data.SecondCutter.Id).Operand;
            Assert.Equal(data.SecondCutter.Transform!.Origin[0]
                + data.SecondCutter.Transform.BasisX[1]
                    * twoHostLegacyShiftFt,
                current.CentreXFt, 12);
            Assert.Equal(data.SecondCutter.Transform.Origin[1]
                - data.SecondCutter.Transform.BasisX[0]
                    * twoHostLegacyShiftFt,
                current.CentreYFt, 12);
        }

        Assert.Equal(8, writerOverrides.Count);
        Assert.Equal(8, writerOverrides.Select(item =>
            (item.WallId, item.CutterId)).Distinct().Count());
        var expectedPairs = data.FirstHostIds
            .Where(hostId => hostId != data.CorrectPeerHostId)
            .Select(hostId => (WallId: hostId,
                CutterId: data.FirstCutter.Id))
            .Concat(data.SecondHostIds.Select(hostId =>
                (WallId: hostId, CutterId: data.SecondCutter.Id)))
            .ToHashSet();
        Assert.True(expectedPairs.SetEquals(writerOverrides.Select(item =>
            (item.WallId, item.CutterId))));
        Assert.DoesNotContain(writerOverrides, item =>
            item.WallId == data.CorrectPeerHostId
            && item.CutterId == data.FirstCutter.Id);

        const double expectedBaseMetres = 4.37;
        foreach (var item in writerOverrides)
        {
            var cutter = data.Elements[item.CutterId];
            double expectedWidthMetres = item.CutterId
                == data.FirstCutter.Id ? 2.6 : 2.92;
            Assert.Equal(cutter.Transform!.Origin[0],
                item.Operand.CentreXFt, 12);
            Assert.Equal(cutter.Transform.Origin[1],
                item.Operand.CentreYFt, 12);
            Assert.Equal(cutter.Transform.BasisX[0],
                item.Operand.AxisX, 12);
            Assert.Equal(cutter.Transform.BasisX[1],
                item.Operand.AxisY, 12);
            Assert.Equal(expectedWidthMetres,
                item.Operand.WidthFt * feetToMetres, 12);
            Assert.Equal(0.2,
                item.Operand.DepthFt * feetToMetres, 12);
            Assert.Equal(expectedBaseMetres,
                item.Operand.BaseZFt * feetToMetres, 12);
            Assert.Equal(3.52,
                item.Operand.HeightFt * feetToMetres, 12);
            Assert.True(item.Operand.ExactDepth);
            Assert.Null(item.Operand.Boundary);
            Assert.Null(item.Operand.SteppedProfile);
        }

        var correctPeer = Assert.Single(
            data.EmittedOperands[data.CorrectPeerHostId], item =>
                item.CutterId == data.FirstCutter.Id).Operand;
        Assert.Equal(data.FirstCutter.Transform!.Origin[0],
            correctPeer.CentreXFt, 12);
        Assert.Equal(data.FirstCutter.Transform.Origin[1],
            correctPeer.CentreYFt, 12);
        Assert.Equal(data.FirstCutter.Transform.BasisX[0],
            correctPeer.AxisX, 12);
        Assert.Equal(data.FirstCutter.Transform.BasisX[1],
            correctPeer.AxisY, 12);
        Assert.Equal(2.6, correctPeer.WidthFt * feetToMetres, 12);
        Assert.Equal(0.2, correctPeer.DepthFt * feetToMetres, 12);
    }

    [Fact]
    public void CompleteOpenSixteenFaceSplitRevealGate_FailsClosedOnAuthorityMutations()
    {
        static bool Gate(CompleteOpenSixteenFaceSplitRevealData data) =>
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters(
                    data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                    data.Elements, data.VisibleWallIds, data.InverseHosts,
                    data.EmittedIds, data.EmittedOperands,
                    data.StandaloneIds, out _, out _, out _);
        static void Reject(string contract,
            Action<CompleteOpenSixteenFaceSplitRevealData> mutate)
        {
            var candidate = CompleteOpenSixteenFaceSplitRevealFixture();
            mutate(candidate);
            Assert.False(Gate(candidate), contract);
        }

        Assert.True(Gate(CompleteOpenSixteenFaceSplitRevealFixture()));

        var nullStandalone = CompleteOpenSixteenFaceSplitRevealFixture();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters(
                nullStandalone.Wall, nullStandalone.Wall.BoundingBox!,
                nullStandalone.Rebuilt, nullStandalone.Elements,
                nullStandalone.VisibleWallIds, nullStandalone.InverseHosts,
                nullStandalone.EmittedIds, nullStandalone.EmittedOperands,
                null, out _, out _, out _),
            "standalone opening map is required");

        Reject("source open-solid topology", data =>
            data.Wall.Geometry!.BrepSolids![0].IsClosed = true);
        Reject("source component partition", data =>
        {
            var sourceFaces = data.Wall.Geometry!.Faces;
            sourceFaces[6].OuterVertices![0] =
                (double[])sourceFaces[10].OuterVertices![0].Clone();
            sourceFaces[6].OuterVertices[1] =
                (double[])sourceFaces[10].OuterVertices[1].Clone();
        });
        Reject("source rectangular inner ring", data =>
            data.Wall.Geometry!.Faces[0].InnerVertices![0].RemoveAt(3));
        Reject("source split reveal elevation", data =>
            data.Wall.Geometry!.Faces[8].OuterVertices![0][2] += 0.05);
        Reject("rebuilt topology", data =>
            data.Rebuilt.BrepSolids![0].FaceIndices[^1] = 0);
        Reject("wall vertical lattice", data =>
            data.Wall.Parameters.Single(parameter =>
                parameter.Id == -1001105).Value = 15.0);

        Reject("inverse host cardinality", data =>
            data.InverseHosts[data.FirstCutter.Id].RemoveAt(6));
        Reject("materialized host cardinality", data =>
        {
            int missingHostId = data.FirstHostIds[^1];
            data.EmittedIds[missingHostId] = [data.FirstCutter.Id];
            data.EmittedOperands[missingHostId] =
                [(data.FirstCutter.Id,
                    data.FirstWrongMaterializedOperand)];
        });
        Reject("emitted multiplicity", data =>
        {
            data.EmittedIds[data.Wall.Id].Add(data.FirstCutter.Id);
            data.EmittedOperands[data.Wall.Id].Add(
                (data.FirstCutter.Id,
                    data.FirstWrongMaterializedOperand));
        });
        Reject("unrelated emitted target pair", data =>
        {
            const int unrelatedCutterId = 999902;
            data.EmittedIds[data.Wall.Id].Add(unrelatedCutterId);
            data.EmittedOperands[data.Wall.Id].Add(
                (unrelatedCutterId,
                    data.FirstWrongMaterializedOperand));
        });
        Reject("missing target materialized entries", data =>
        {
            data.EmittedIds.Remove(data.Wall.Id);
            data.EmittedOperands.Remove(data.Wall.Id);
        });
        Reject("direct host", data =>
            data.FirstCutter.SerializedHostId = data.Wall.Id);
        Reject("extra host", data =>
            data.FirstCutter.ExtraHostIds!.Clear());
        Reject("forward reference multiplicity", data =>
            data.FirstCutter.References!.Add(data.Wall.Id));
        Reject("unexpected inverse-only forward reference", data =>
            data.FirstCutter.References!.Add(data.FirstHostIds[^1]));
        Reject("second reference-only seven-host candidate", data =>
            data.Elements[data.FirstHostIds[3]].CuttingElementIds = null);
        Reject("reference-only roster moved to inverse-only host", data =>
        {
            data.Elements[data.ReferenceOnlyHostId].CuttingElementIds =
                [data.FirstCutter.Id];
            data.Elements[data.FirstHostIds[^1]].CuttingElementIds = null;
        });
        Reject("reference-only host has non-null empty roster", data =>
            data.Elements[data.ReferenceOnlyHostId].CuttingElementIds = []);
        Reject("reference-only host has unrelated roster", data =>
            data.Elements[data.ReferenceOnlyHostId].CuttingElementIds =
                [999904]);
        Reject("ordinary seven-host cutter reference is missing", data =>
            data.Elements[data.FirstHostIds[3]].CuttingElementIds!
                .Remove(data.FirstCutter.Id));
        Reject("ordinary seven-host cutter reference is multiple", data =>
            data.Elements[data.FirstHostIds[3]].CuttingElementIds!
                .Add(data.FirstCutter.Id));
        Reject("seven-host emitted axis drifts from serialized host line", data =>
        {
            int hostId = data.FirstHostIds[3];
            int index = data.EmittedOperands[hostId].FindIndex(item =>
                item.CutterId == data.FirstCutter.Id);
            var existing = data.EmittedOperands[hostId][index];
            data.EmittedOperands[hostId][index] =
                (existing.CutterId, existing.Operand with
                {
                    AxisX = -existing.Operand.AxisY,
                    AxisY = existing.Operand.AxisX,
                });
        });
        Reject("seven-host serialized host line is degenerate", data =>
        {
            var location = data.Elements[data.FirstHostIds[3]].Location!;
            location.EndPoint = (double[])location.StartPoint.Clone();
        });
        Reject("seven-host serialized host line is non-finite", data =>
            data.Elements[data.FirstHostIds[3]].Location!
                .EndPoint[0] = double.PositiveInfinity);
        Reject("seven-host effective bbox thickness lattice", data =>
            data.Elements[data.BboxThicknessOverrideHostId]
                .BoundingBox![4] += 0.001 / 0.3048);
        Reject("two-host cutter reference is missing", data =>
            data.Elements[data.SecondHostIds[1]].CuttingElementIds!
                .Remove(data.SecondCutter.Id));
        Reject("two-host cutter reference is multiple", data =>
            data.Elements[data.SecondHostIds[1]].CuttingElementIds!
                .Add(data.SecondCutter.Id));
        Reject("two-host legacy shift is mirrored to left normal", data =>
        {
            int hostId = data.SecondHostIds[1];
            int index = data.EmittedOperands[hostId].FindIndex(item =>
                item.CutterId == data.SecondCutter.Id);
            var existing = data.EmittedOperands[hostId][index];
            data.EmittedOperands[hostId][index] =
                (existing.CutterId, existing.Operand with
                {
                    CentreXFt = 2 * data.SecondCutter.Transform!.Origin[0]
                        - existing.Operand.CentreXFt,
                    CentreYFt = 2 * data.SecondCutter.Transform.Origin[1]
                        - existing.Operand.CentreYFt,
                });
        });
        Reject("visible host graph", data =>
            data.VisibleWallIds.Remove(data.FirstHostIds[3]));
        Reject("seven candidate hosts instead of six", data =>
        {
            int inverseOnlyHostId = data.FirstHostIds[^1];
            data.Elements[inverseOnlyHostId].BoundingBox![2] =
                data.FirstCutter.BoundingBox![2];
        });
        Reject("target standalone opening graph", data =>
            data.StandaloneIds[data.Wall.Id].Add(999901));
        Reject("peer standalone opening graph", data =>
            data.StandaloneIds[data.FirstHostIds[2]].Add(999903));

        Reject("family root aliases mapped symbol", data =>
            data.FirstCutter.Parameters.Single(parameter =>
                parameter.Id == -1002050).Value =
                data.FirstMappedSymbol.Id);
        Reject("mapped symbols alias", data =>
        {
            data.SecondCutter.Transform!.SymbolId =
                data.FirstMappedSymbol.Id;
            Assert.Single(data.SecondCutter.Geometry!
                .Instances!).SymbolId =
                data.FirstMappedSymbol.Id;
        });
        Reject("mapped symbol family root", data =>
            data.FirstMappedSymbol.Parameters.Single(parameter =>
                parameter.Id == -1002050).Value =
                data.SecondMappedSymbol.Id);
        Reject("cutter family-root reference multiplicity one", data =>
            data.FirstCutter.References!.Remove(
                data.FirstCutter.FamilyTypeId));
        Reject("cutter family-root reference multiplicity three", data =>
            data.FirstCutter.References!.Add(
                data.FirstCutter.FamilyTypeId));
        Reject("cutter mapped-symbol reference multiplicity one", data =>
            data.SecondCutter.References!.Remove(
                data.SecondCutter.Transform!.SymbolId));
        Reject("cutter mapped-symbol reference multiplicity three", data =>
            data.SecondCutter.References!.Add(
                data.SecondCutter.Transform!.SymbolId));
        Reject("mapped instance transform", data =>
            data.FirstCutter.Geometry!.Instances![0]
                .Transform![9] += 0.05);
        Reject("instance transform basis", data =>
            data.SecondCutter.Transform!.BasisX[0] += 0.05);
        Reject("seven-host desired XY versus serialized bounding box", data =>
            data.FirstCutter.BoundingBox![0] += 0.01);
        Reject("seven-host desired Z extent versus serialized bounding box", data =>
            data.FirstCutter.BoundingBox![5] += 0.01);
        Reject("two-host desired XY versus serialized bounding box", data =>
            data.SecondCutter.BoundingBox![3] += 0.01);
        Reject("two-host desired Z extent versus serialized bounding box", data =>
            data.SecondCutter.BoundingBox![5] += 0.01);
        Reject("mapped instance geometry must be empty", data =>
            data.FirstCutter.Geometry!.Faces.Add(Face(
                [[0, 0, 0], [1, 0, 0], [0, 1, 0]])));
        Reject("multiple public mapped instances", data =>
        {
            var mapped = Assert.Single(data.SecondCutter.Geometry!
                .Instances!);
            data.SecondCutter.Geometry.Instances!.Add(
                new GeoInstance
                {
                    SymbolId = mapped.SymbolId,
                    Transform = (double[])mapped.Transform.Clone(),
                });
        });
        Reject("exact-only mapped roster is forbidden", data =>
        {
            var mapped = Assert.Single(data.FirstCutter.Geometry!
                .Instances!);
            data.FirstCutter.Geometry.Instances = null;
            data.FirstCutter.Geometry.ExactMappedInstances =
            [
                new GeoInstance
                {
                    SymbolId = mapped.SymbolId,
                    Transform = (double[])mapped.Transform.Clone(),
                },
            ];
        });
        Reject("conflicting exact and public mapped rosters", data =>
        {
            var mapped = Assert.Single(data.FirstCutter.Geometry!
                .Instances!);
            data.FirstCutter.Geometry.ExactMappedInstances =
            [
                new GeoInstance
                {
                    SymbolId = data.SecondMappedSymbol.Id,
                    Transform = (double[])mapped.Transform.Clone(),
                },
            ];
        });
        Reject("mapped symbol closure-plane authority", data =>
        {
            data.FirstMappedSymbol.FamilyCutClosurePlaneOrigin = [0, 0, 0];
            data.FirstMappedSymbol.FamilyCutClosurePlaneNormal = [0, 1, 0];
        });
        Reject("linked mapped family-cut type", data =>
            data.SecondMappedSymbol.FamilyCutGeometry =
                BoxGeometry(-1, -0.5, 0, 1, 0.5, 2));

        Reject("missing instance width GUID", data =>
            data.FirstCutter.Parameters.Remove(
                ExactExternalParameter(data.FirstCutter,
                    ExactOpeningWidthParameterGuid)));
        Reject("duplicate instance height GUID", data =>
        {
            var height = ExactExternalParameter(
                data.SecondCutter, ExactOpeningHeightParameterGuid);
            data.SecondCutter.Parameters.Add(new Parameter
            {
                Id = height.Id + 1000,
                Definition = new Definition { Name = "duplicate-height" },
                Guid = height.Guid,
                ForgeId = height.ForgeId,
                StorageType = height.StorageType,
                Value = height.Value,
                IsReadOnly = height.IsReadOnly,
                SpecType = height.SpecType,
            });
        });
        Reject("conflicting instance GUID metadata", data =>
            ExactExternalParameter(data.FirstCutter,
                ExactOpeningThicknessParameterGuid).Guid =
                Guid.Parse("11111111-2222-3333-4444-555555555555"));
        Reject("wrong instance GUID key", data =>
        {
            var width = ExactExternalParameter(
                data.FirstCutter, ExactOpeningWidthParameterGuid);
            width.Guid = null;
            width.ForgeId = "autodesk.parameter.aec.revit.external.-1:"
                + "11111111222233334444555555555555-1.0.0";
        });
        Reject("instance GUID storage type", data =>
            ExactExternalParameter(data.SecondCutter,
                ExactOpeningHeightParameterGuid).StorageType =
                StorageType.String);
        Reject("instance GUID must be read-only", data =>
            ExactExternalParameter(data.FirstCutter,
                ExactOpeningWidthParameterGuid).IsReadOnly = false);
        Reject("wrong instance width value", data =>
            ExactExternalParameter(data.SecondCutter,
                ExactOpeningWidthParameterGuid).Value = 9.0);
        Reject("finite overflow instance GUID length", data =>
            ExactExternalParameter(data.FirstCutter,
                ExactOpeningHeightParameterGuid).Value = double.MaxValue);
        Reject("symbol fallback is forbidden", data =>
        {
            data.FirstCutter.Parameters.Remove(
                ExactExternalParameter(data.FirstCutter,
                    ExactOpeningWidthParameterGuid));
            ExactExternalParameter(data.FirstMappedSymbol,
                ExactOpeningWidthParameterGuid).Value = 2.6 / 0.3048;
        });

        Reject("existing materialized operand drift", data =>
        {
            var existing = data.EmittedOperands[data.Wall.Id][0];
            data.EmittedOperands[data.Wall.Id][0] =
                (existing.CutterId, existing.Operand with
                {
                    DepthFt = existing.Operand.DepthFt + 0.01,
                });
        });
        Reject("existing secondary operand depth", data =>
        {
            int hostId = data.SecondHostIds[1];
            int index = data.EmittedOperands[hostId].FindIndex(item =>
                item.CutterId == data.SecondCutter.Id);
            var existing = data.EmittedOperands[hostId][index];
            data.EmittedOperands[hostId][index] =
                (existing.CutterId, existing.Operand with
                {
                    DepthFt = 0.2 / 0.3048,
                });
        });
        Reject("already-correct direct peer must remain exact", data =>
        {
            int index = data.EmittedOperands[data.CorrectPeerHostId]
                .FindIndex(item =>
                    item.CutterId == data.FirstCutter.Id);
            var existing = data.EmittedOperands[
                data.CorrectPeerHostId][index];
            data.EmittedOperands[data.CorrectPeerHostId][index] =
                (existing.CutterId, existing.Operand with
                {
                    CentreXFt = existing.Operand.CentreXFt + 0.01,
                });
        });
    }

    [Fact]
    public void CompleteOpenFiftyTwoFaceInsetCapsGate_RecoversExactGrossWall()
    {
        const double feetToMillimetres = 304.8;
        var data = CompleteOpenFiftyTwoFaceInsetCapsFixture();
        GeometryData source = data.Wall.Geometry!;

        Assert.Equal(52, source.Faces.Count);
        Assert.Equal(48, source.Faces.Count(face =>
            face.OuterVertices is { Count: 4 }));
        Assert.Equal([33, 34], source.Faces.Select((face, index) =>
                (face, index)).Where(item =>
                item.face.OuterVertices is { Count: 3 })
            .Select(item => item.index));
        Assert.Equal([36, 42], source.Faces.Select((face, index) =>
                (face, index)).Where(item =>
                item.face.OuterVertices is { Count: 6 })
            .Select(item => item.index));
        Assert.All(source.Faces, face =>
            Assert.False(face.InnerVertices is { Count: > 0 }));
        Assert.Equal(new[] { 0, 11, 12, 16, 20 },
            source.Faces.Select((face, index) => (face, index))
                .Where(item => item.face.AlternativeOuterVertices is { Count: > 0 })
                .Select(item => item.index));

        Assert.Equal(4, source.BrepSolids!.Count);
        Assert.False(source.BrepSolids[0].IsClosed);
        Assert.Equal(
            Enumerable.Range(0, 21).Concat(Enumerable.Range(33, 14)),
            source.BrepSolids[0].FaceIndices);
        Assert.True(source.BrepSolids[1].IsClosed);
        Assert.Equal(Enumerable.Range(21, 6),
            source.BrepSolids[1].FaceIndices);
        Assert.True(source.BrepSolids[2].IsClosed);
        Assert.Equal(Enumerable.Range(27, 6),
            source.BrepSolids[2].FaceIndices);
        Assert.False(source.BrepSolids[3].IsClosed);
        Assert.Equal(Enumerable.Range(47, 5),
            source.BrepSolids[3].FaceIndices);
        Assert.Equal((62, 88, 9), ExactTopology(
            source, source.BrepSolids[0].FaceIndices).Summary);
        Assert.Equal(new Dictionary<int, int>
        {
            [1] = 38,
            [2] = 46,
            [3] = 4,
        }, ExactTopology(source,
            source.BrepSolids[0].FaceIndices).OwnerHistogram);
        Assert.Equal([16, 6, 5, 3, 1, 1, 1, 1, 1],
            ExactTopology(source,
                source.BrepSolids[0].FaceIndices).ComponentSizes);
        foreach (int solidIndex in new[] { 1, 2 })
        {
            var topology = ExactTopology(source,
                source.BrepSolids[solidIndex].FaceIndices);
            Assert.Equal((8, 12, 1), topology.Summary);
            Assert.Equal(new Dictionary<int, int> { [2] = 12 },
                topology.OwnerHistogram);
            Assert.Equal([6], topology.ComponentSizes);
        }
        var detachedTopology = ExactTopology(source,
            source.BrepSolids[3].FaceIndices);
        Assert.Equal((8, 12, 1), detachedTopology.Summary);
        Assert.Equal(new Dictionary<int, int>
        {
            [1] = 4,
            [2] = 8,
        }, detachedTopology.OwnerHistogram);
        Assert.Equal([5], detachedTopology.ComponentSizes);

        Assert.Equal(9, data.Rebuilt.Faces.Count);
        Assert.Equal(2, data.Rebuilt.Faces.Count(face =>
            face.OuterVertices is { Count: 7 }));
        Assert.Equal(7, data.Rebuilt.Faces.Count(face =>
            face.OuterVertices is { Count: 4 }));
        var rebuiltSolid = Assert.Single(data.Rebuilt.BrepSolids!);
        Assert.True(rebuiltSolid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 9), rebuiltSolid.FaceIndices);
        var rebuiltTopology = ExactTopology(
            data.Rebuilt, rebuiltSolid.FaceIndices);
        Assert.Equal((14, 21, 1), rebuiltTopology.Summary);
        Assert.Equal(new Dictionary<int, int> { [2] = 21 },
            rebuiltTopology.OwnerHistogram);
        Assert.Equal(source.Faces[2].OuterVertices,
            data.Rebuilt.Faces[2].OuterVertices);
        Assert.Equal(source.Faces[6].OuterVertices,
            data.Rebuilt.Faces[7].OuterVertices);

        Assert.Equal(12, data.InverseHosts[data.FirstCutter.Id].Count);
        Assert.Equal(5, data.InverseHosts[data.SecondCutter.Id].Count);
        Assert.True(data.InverseHosts[data.SecondCutter.Id].ToHashSet()
            .IsProperSubsetOf(data.InverseHosts[data.FirstCutter.Id]));
        Assert.All(new[] { data.FirstCutter.Id, data.SecondCutter.Id },
            cutterId =>
            {
                foreach (int hostId in data.InverseHosts[cutterId])
                {
                    Assert.Equal(1, data.EmittedIds[hostId]
                        .Count(id => id == cutterId));
                    Assert.Equal(1, data.EmittedOperands[hostId]
                        .Count(item => item.CutterId == cutterId));
                }
            });
        Assert.All(data.StandaloneIds.Values, Assert.Empty);

        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings(
                data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                data.Elements, data.VisibleWallIds, data.InverseHosts,
                data.EmittedIds, data.EmittedOperands,
                data.StandaloneIds, out var gross,
                out var cutterElementIds));

        Assert.Equal([data.FirstCutter.Id, data.SecondCutter.Id],
            cutterElementIds);
        Assert.Equal(6, gross.Faces.Count);
        var grossSolid = Assert.Single(gross.BrepSolids!);
        Assert.True(grossSolid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 6), grossSolid.FaceIndices);
        Assert.True(IfcExporter.IsExactFacetedShell(
            gross.Faces, grossSolid.FaceIndices));
        var grossTopology = ExactTopology(gross, grossSolid.FaceIndices);
        Assert.Equal((8, 12, 1), grossTopology.Summary);
        Assert.Equal(new Dictionary<int, int> { [2] = 12 },
            grossTopology.OwnerHistogram);

        var points = gross.Faces.SelectMany(face => face.OuterVertices!)
            .GroupBy(Key).Select(group => group.First()).ToList();
        double dx = data.Wall.Location!.EndPoint[0]
            - data.Wall.Location.StartPoint[0];
        double dy = data.Wall.Location.EndPoint[1]
            - data.Wall.Location.StartPoint[1];
        double directionLength = Math.Sqrt(dx * dx + dy * dy);
        dx /= directionLength;
        dy /= directionLength;
        double Along(double[] point) => point[0] * dx + point[1] * dy;
        double Normal(double[] point) => -point[0] * dy + point[1] * dx;
        Assert.Equal(3500,
            (points.Max(Along) - points.Min(Along)) * feetToMillimetres,
            6);
        Assert.Equal(80,
            (points.Max(Normal) - points.Min(Normal)) * feetToMillimetres,
            6);
        Assert.Equal(2840,
            (points.Max(point => point[2])
                - points.Min(point => point[2])) * feetToMillimetres,
            6);
        Assert.Equal(80,
            (directionLength - (points.Max(Along) - points.Min(Along)))
                * feetToMillimetres,
            6);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void CompleteOpenFiftyTwoFaceInsetCapsGate_AcceptsExactBrepWriterOperands(
        bool perpendicularFirstEdge)
    {
        var data = CompleteOpenFiftyTwoFaceInsetCapsFixture();
        foreach (var operands in data.EmittedOperands.Values)
        {
            for (int index = 0; index < operands.Count; index++)
            {
                var (cutterId, operand) = operands[index];
                var boundary = BoxGeometry(-operand.WidthFt / 2,
                    -operand.DepthFt / 2, operand.BaseZFt,
                    operand.WidthFt / 2, operand.DepthFt / 2,
                    operand.BaseZFt + operand.HeightFt);
                foreach (var face in boundary.Faces)
                {
                    face.OuterVertices = face.OuterVertices!.Select(point =>
                        new[]
                        {
                            operand.CentreXFt + point[0] * operand.AxisX
                                - point[1] * operand.AxisY,
                            operand.CentreYFt + point[0] * operand.AxisY
                                + point[1] * operand.AxisX,
                            point[2],
                        }).ToList();
                    if (perpendicularFirstEdge)
                        face.OuterVertices = face.OuterVertices.Skip(1)
                            .Concat(face.OuterVertices.Take(1)).ToList();
                }
                var points = boundary.Faces.SelectMany(face =>
                    face.OuterVertices!).ToList();
                boundary.BoundingBox =
                [
                    points.Min(point => point[0]), points.Min(point => point[1]),
                    points.Min(point => point[2]), points.Max(point => point[0]),
                    points.Max(point => point[1]), points.Max(point => point[2]),
                ];
                operands[index] = (cutterId, operand with { Boundary = boundary });
            }
        }
        Assert.True(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings(
                data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                data.Elements, data.VisibleWallIds, data.InverseHosts,
                data.EmittedIds, data.EmittedOperands, data.StandaloneIds,
                out _, out _));
    }

    [Fact]
    public void CompleteOpenFiftyTwoFaceInsetCapsGate_FailsClosedOnAuthorityMutations()
    {
        static bool Gate(CompleteOpenFiftyTwoFaceInsetCapsData data) =>
            IfcExporter
                .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings(
                    data.Wall, data.Wall.BoundingBox!, data.Rebuilt,
                    data.Elements, data.VisibleWallIds, data.InverseHosts,
                    data.EmittedIds, data.EmittedOperands,
                    data.StandaloneIds, out _, out _);
        static void Reject(string contract,
            Action<CompleteOpenFiftyTwoFaceInsetCapsData> mutate)
        {
            var candidate = CompleteOpenFiftyTwoFaceInsetCapsFixture();
            mutate(candidate);
            Assert.False(Gate(candidate), contract);
        }
        static void RewriteOperand(
            CompleteOpenFiftyTwoFaceInsetCapsData data, int cutterId,
            Func<IfcExporter.HostedOpeningGeometry,
                IfcExporter.HostedOpeningGeometry> rewrite)
        {
            foreach (var operands in data.EmittedOperands.Values)
                for (int index = 0; index < operands.Count; index++)
                    if (operands[index].CutterId == cutterId)
                        operands[index] = (cutterId,
                            rewrite(operands[index].Operand));
        }

        Assert.True(Gate(CompleteOpenFiftyTwoFaceInsetCapsFixture()));

        var nullStandalone = CompleteOpenFiftyTwoFaceInsetCapsFixture();
        Assert.False(IfcExporter
            .TryGetVerifiedGrossWallBoundaryFromCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings(
                nullStandalone.Wall, nullStandalone.Wall.BoundingBox!,
                nullStandalone.Rebuilt, nullStandalone.Elements,
                nullStandalone.VisibleWallIds, nullStandalone.InverseHosts,
                nullStandalone.EmittedIds, nullStandalone.EmittedOperands,
                null, out _, out _),
            "standalone opening map is required");

        Reject("source lower cap", data =>
            data.Wall.Geometry!.Faces[2].OuterVertices![0][0] += 0.01);
        Reject("source triangular topology", data =>
            data.Wall.Geometry!.Faces[33].OuterVertices!.Add(
                (double[])data.Wall.Geometry.Faces[33]
                    .OuterVertices![0].Clone()));
        Reject("source six-point topology", data =>
            data.Wall.Geometry!.Faces[36].OuterVertices!.RemoveAt(5));
        Reject("source unexpected alternative", data =>
            data.Wall.Geometry!.Faces[1].AlternativeOuterVertices =
                data.Wall.Geometry.Faces[1].OuterVertices!
                    .Select(point => (double[])point.Clone()).ToList());
        Reject("source missing alternative", data =>
            data.Wall.Geometry!.Faces[16].AlternativeOuterVertices = null);
        Reject("source full-depth alternative", data =>
            data.Wall.Geometry!.Faces[16].AlternativeOuterVertices![0][0] += 0.01);
        Reject("source backtracking alternative", data =>
            data.Wall.Geometry!.Faces[20].AlternativeOuterVertices!.Reverse(1, 3));
        Reject("source solid roster", data =>
            data.Wall.Geometry!.BrepSolids!.RemoveAt(3));
        Reject("source primary solid partition", data =>
            data.Wall.Geometry!.BrepSolids![0].FaceIndices.Remove(46));
        Reject("source closed insert authority", data =>
            data.Wall.Geometry!.BrepSolids![1].IsClosed = false);

        Reject("rebuilt face topology", data =>
            data.Rebuilt.Faces[0].OuterVertices!.RemoveAt(6));
        Reject("rebuilt closed solid", data =>
            data.Rebuilt.BrepSolids![0].IsClosed = false);
        Reject("rebuilt solid partition", data =>
            data.Rebuilt.BrepSolids![0].FaceIndices[^1] = 0);
        Reject("rebuilt source-cap equality", data =>
            data.Rebuilt.Faces[7].OuterVertices![0][1] += 0.01);

        Reject("decoded cutter cardinality", data =>
            data.Wall.CuttingElementIds!.RemoveAt(1));
        Reject("decoded cutter multiplicity", data =>
            data.Wall.CuttingElementIds!.Add(data.FirstCutter.Id));
        Reject("wall cutter reference is missing", data =>
            data.Wall.References!.Remove(data.SecondCutter.Id));
        Reject("wall cutter reference is multiple", data =>
            data.Wall.References!.Add(data.FirstCutter.Id));
        Reject("door cutter category", data =>
            data.FirstCutter.CategoryId = -2000011);

        Reject("twelve-host graph cardinality", data =>
            data.InverseHosts[data.FirstCutter.Id].RemoveAt(11));
        Reject("five-host graph cardinality", data =>
            data.InverseHosts[data.SecondCutter.Id].RemoveAt(4));
        Reject("five-host graph must be a strict subset", data =>
        {
            int sharedHostId = data.SecondHostIds[^1];
            data.InverseHosts[data.FirstCutter.Id].Remove(sharedHostId);
        });
        Reject("visible inverse host", data =>
            data.VisibleWallIds.Remove(data.FirstHostIds[^1]));
        Reject("inverse host reciprocity", data =>
            data.Elements[data.FirstHostIds[^1]]
                .CuttingElementIds!.Clear());
        Reject("missing emitted inverse pair", data =>
        {
            int hostId = data.FirstHostIds[^1];
            data.EmittedIds[hostId].Clear();
            data.EmittedOperands[hostId].Clear();
        });
        Reject("duplicate emitted inverse pair", data =>
        {
            int hostId = data.Wall.Id;
            data.EmittedIds[hostId].Add(data.FirstCutter.Id);
            data.EmittedOperands[hostId].Add(
                (data.FirstCutter.Id, data.FirstOperand));
        });
        Reject("emitted id and operand bijection", data =>
            data.EmittedOperands[data.Wall.Id].RemoveAt(0));
        Reject("standalone target opening", data =>
            data.StandaloneIds[data.Wall.Id].Add(999901));
        Reject("standalone peer opening", data =>
            data.StandaloneIds[data.FirstHostIds[^1]].Add(999902));

        Reject("operand must be a simple swept rectangle", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with
                {
                    Boundary = BoxGeometry(0, 0, 0, 1, 1, 1),
                }));
        Reject("operand exact depth authority", data =>
            RewriteOperand(data, data.SecondCutter.Id, operand =>
                operand with { ExactDepth = false }));
        Reject("operand dimension lattice", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with { WidthFt = operand.WidthFt + 0.01 }));
        Reject("operand height must match source reveals", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with { HeightFt = operand.HeightFt + 0.01 }));
        Reject("operand depth must match source alternatives", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with { DepthFt = operand.DepthFt + 0.01 }));
        Reject("operand sill must match source reveals", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with { BaseZFt = operand.BaseZFt + 0.01 }));
        Reject("interior operand position must match source reveals", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with
                {
                    CentreXFt = operand.CentreXFt + operand.AxisX * 0.01,
                    CentreYFt = operand.CentreYFt + operand.AxisY * 0.01,
                }));
        Reject("end-coincident operand width must match source reveals", data =>
            RewriteOperand(data, data.SecondCutter.Id, operand =>
                operand with
                {
                    WidthFt = operand.WidthFt + 0.02,
                    CentreXFt = operand.CentreXFt - operand.AxisX * 0.01,
                    CentreYFt = operand.CentreYFt - operand.AxisY * 0.01,
                }));
        Reject("operand must pass through gross thickness", data =>
            RewriteOperand(data, data.SecondCutter.Id, operand =>
                operand with { DepthFt = 0.04 / 0.3048 }));
        Reject("operand must remain inside gross span", data =>
            RewriteOperand(data, data.FirstCutter.Id, operand =>
                operand with
                {
                    CentreXFt = operand.CentreXFt
                        + operand.AxisX * (4 / 0.3048),
                    CentreYFt = operand.CentreYFt
                        + operand.AxisY * (4 / 0.3048),
                }));
        Reject("opening operands must be disjoint", data =>
            RewriteOperand(data, data.SecondCutter.Id, operand =>
                operand with
                {
                    CentreXFt = data.FirstOperand.CentreXFt,
                    CentreYFt = data.FirstOperand.CentreYFt,
                    AxisX = data.FirstOperand.AxisX,
                    AxisY = data.FirstOperand.AxisY,
                }));
    }

    [Fact]
    public void BlockOnlyFamilySymbol_RetainsItsExactComplexCutter()
    {
        const uint symbolId = 216824;
        var state = new ParsingState();
        state.FamilyCutGreps[symbolId] = new GRepData
        {
            Faces =
            [
                new GRepFace
                {
                    Vertices = [[0, 0, 0], [1, 0, 0], [0, 1, 0]],
                    Origin = [0, 0, 0],
                    XVector = [0, 0, 1],
                },
            ],
            FamilyClosurePlaneOrigin = [0, 0.5, 0],
            FamilyClosurePlaneNormal = [0, 1, 0],
        };
        state.FamilyCutLoops[symbolId] =
        [
            new FamilyCutLoopData(
                [[-1, -0.5, 0], [1, -0.5, 0], [1, -0.5, 2], [-1, -0.5, 2]],
                [0, -1, 0], 0),
        ];
        var info = new RevitFileInfo();

        ElementBuilder.BuildBlockOnlyElement(symbolId, state, info);

        var symbol = Assert.Single(info.Elements);
        Assert.NotNull(symbol.FamilyCutGeometry);
        Assert.Single(symbol.FamilyCutGeometry!.Faces);
        Assert.NotNull(symbol.FamilyCutClosurePlaneOrigin);
        Assert.NotNull(symbol.FamilyCutClosurePlaneNormal);
        Assert.Equal([0, 0.5, 0], symbol.FamilyCutClosurePlaneOrigin!);
        Assert.Equal([0, 1, 0], symbol.FamilyCutClosurePlaneNormal!);
        Assert.Single(symbol.FamilyCutLoops!);
    }

