        Guid.Parse("9350e48f-842b-4c46-a15d-2e36ab1f352f");

    private sealed record CompleteOpenFiftyTwoFaceInsetCapsData(
        Element Wall,
        GeometryData Rebuilt,
        Element FirstCutter,
        Element SecondCutter,
        Dictionary<int, Element> Elements,
        HashSet<int> VisibleWallIds,
        Dictionary<int, List<int>> InverseHosts,
        Dictionary<int, List<int>> EmittedIds,
        Dictionary<int, List<(int CutterId,
            IfcExporter.HostedOpeningGeometry Operand)>> EmittedOperands,
        Dictionary<int, List<int>> StandaloneIds,
        List<int> FirstHostIds,
        List<int> SecondHostIds,
        IfcExporter.HostedOpeningGeometry FirstOperand);

    private static CompleteOpenFiftyTwoFaceInsetCapsData
        CompleteOpenFiftyTwoFaceInsetCapsFixture()
    {
        const int wallId = 98401;
        const int firstCutterId = 98402;
        const int secondCutterId = 98403;
        const int firstPeerHostId = 98404;
        const int wallTypeId = 98420;
        const double feetToMetres = 0.3048;
        const double wallWidthFt = 0.26246719160104987;
        const double wallBaseOffsetFt = -0.32808398950131235;
        const double wallHeightFt = 9.31758530183727;
        double[] locationStart =
        [
            24.32904509397132, -58.9103171614056,
            137.30314960629926,
        ];
        double[] locationEnd =
        [
            32.63430190711888, -67.2155739745532,
            137.30314960629926,
        ];
        const double axisX = 0.7071067811865459;
        const double axisY = -0.7071067811865491;
        const double axisLength = 11.745406824144855;

        static Parameter VerticalParameter(int id, double value) => new()
        {
            Id = id,
            StorageType = StorageType.Double,
            Value = value,
        };
        List<Parameter> WallParameters() =>
        [
            WallWidthParameter(wallWidthFt),
            VerticalParameter(-1001111, wallBaseOffsetFt),
            VerticalParameter(-1001105, wallHeightFt),
        ];
        LocationCurve WallLocation() => new()
        {
            CurveType = "Line",
            StartPoint = (double[])locationStart.Clone(),
            EndPoint = (double[])locationEnd.Clone(),
            Direction = [axisX, axisY, 0],
            Length = axisLength,
        };

        var (source, rebuilt) =
            DecodeCompleteOpenFiftyTwoFaceInsetCapsGeometry();
        var firstHostIds = new[] { wallId }
            .Concat(Enumerable.Range(firstPeerHostId, 11)).ToList();
        var secondHostIds = firstHostIds.Take(5).ToList();
        var secondHostSet = secondHostIds.ToHashSet();

        var wall = new Element
        {
            Id = wallId,
            TypeId = wallTypeId,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "FIX308 arbitrary-id target wall",
            BoundingBox = (double[])source.BoundingBox!.Clone(),
            Geometry = source,
            Location = WallLocation(),
            Parameters = WallParameters(),
            CuttingElementIds = [firstCutterId, secondCutterId],
            References = [firstCutterId, secondCutterId],
        };
        Element PeerHost(int id)
        {
            var cutterIds = new List<int> { firstCutterId };
            if (secondHostSet.Contains(id))
                cutterIds.Add(secondCutterId);
            return new Element
            {
                Id = id,
                TypeId = wallTypeId,
                CategoryId = -2000011,
                Category = "OST_Walls",
                Name = $"FIX308 arbitrary-id peer wall {id}",
                BoundingBox = (double[])source.BoundingBox!.Clone(),
                Location = WallLocation(),
                Parameters = WallParameters(),
                CuttingElementIds = cutterIds.ToList(),
                References = cutterIds.ToList(),
            };
        }
        var hosts = new List<Element> { wall };
        hosts.AddRange(firstHostIds.Skip(1).Select(PeerHost));

        double openingBaseZFt = source.BoundingBox[2]
            + 0.1 / feetToMetres;
        IfcExporter.HostedOpeningGeometry Opening(int sourceBottomIndex) => new(
            CentreXFt: source.Faces[sourceBottomIndex].OuterVertices!
                .Average(point => point[0]),
            CentreYFt: source.Faces[sourceBottomIndex].OuterVertices!
                .Average(point => point[1]),
            AxisX: axisX,
            AxisY: axisY,
            WidthFt: 0.81 / feetToMetres,
            DepthFt: 1.28 / feetToMetres,
            BaseZFt: openingBaseZFt,
            HeightFt: 2.1 / feetToMetres,
            ExactDepth: true,
            Boundary: null);
        var firstOperand = Opening(16);
        var secondOperand = Opening(10);

        static double[] OpeningBounds(
            IfcExporter.HostedOpeningGeometry operand)
        {
            double halfX = Math.Abs(operand.AxisX) * operand.WidthFt / 2
                + Math.Abs(operand.AxisY) * operand.DepthFt / 2;
            double halfY = Math.Abs(operand.AxisY) * operand.WidthFt / 2
                + Math.Abs(operand.AxisX) * operand.DepthFt / 2;
            return
            [
                operand.CentreXFt - halfX,
                operand.CentreYFt - halfY,
                operand.BaseZFt,
                operand.CentreXFt + halfX,
                operand.CentreYFt + halfY,
                operand.BaseZFt + operand.HeightFt,
            ];
        }
        Element Cutter(int id, string name,
            IfcExporter.HostedOpeningGeometry operand) => new()
        {
            Id = id,
            TypeId = 98421,
            CategoryId = -2000023,
            Category = "OST_Doors",
            Name = name,
            HostId = wallId,
            SerializedHostId = wallId,
            BoundingBox = OpeningBounds(operand),
            References = [wallId],
            Geometry = new GeometryData(),
        };
        var firstCutter = Cutter(firstCutterId,
            "FIX308 arbitrary-id broad door", firstOperand);
        var secondCutter = Cutter(secondCutterId,
            "FIX308 arbitrary-id narrow door", secondOperand);

        var elements = hosts.Concat(new[] { firstCutter, secondCutter })
            .ToDictionary(element => element.Id);
        var inverseHosts = new Dictionary<int, List<int>>
        {
            [firstCutterId] = firstHostIds.ToList(),
            [secondCutterId] = secondHostIds.ToList(),
        };
        var emittedIds = firstHostIds.ToDictionary(
            hostId => hostId,
            hostId => secondHostSet.Contains(hostId)
                ? new List<int> { firstCutterId, secondCutterId }
                : new List<int> { firstCutterId });
        var emittedOperands = firstHostIds.ToDictionary(
            hostId => hostId,
            hostId => secondHostSet.Contains(hostId)
                ? new List<(int CutterId,
                    IfcExporter.HostedOpeningGeometry Operand)>
                {
                    (firstCutterId, firstOperand),
                    (secondCutterId, secondOperand),
                }
                : new List<(int CutterId,
                    IfcExporter.HostedOpeningGeometry Operand)>
                {
                    (firstCutterId, firstOperand),
                });
        var standaloneIds = firstHostIds.ToDictionary(
            hostId => hostId, _ => new List<int>());

        return new CompleteOpenFiftyTwoFaceInsetCapsData(
            wall, rebuilt, firstCutter, secondCutter,
            elements, firstHostIds.ToHashSet(), inverseHosts,
            emittedIds, emittedOperands, standaloneIds,
            firstHostIds, secondHostIds, firstOperand);
    }

    private static (GeometryData Source, GeometryData Rebuilt)
        DecodeCompleteOpenFiftyTwoFaceInsetCapsGeometry()
    {
        const string payload = """

""";
        using var compressed = new System.IO.MemoryStream(
            Convert.FromBase64String(payload));
        using var gzip = new System.IO.Compression.GZipStream(
            compressed, System.IO.Compression.CompressionMode.Decompress);
        using var document = System.Text.Json.JsonDocument.Parse(gzip);

        static List<double[]> Ring(System.Text.Json.JsonElement element) =>
            element.EnumerateArray().Select(point => point.EnumerateArray()
                .Select(coordinate => coordinate.GetDouble()).ToArray())
                .ToList();
        var root = document.RootElement;
        var sourceFaces = root.GetProperty("f").EnumerateArray()
            .Select(faceElement => new GeoFace
            {
                OuterVertices = Ring(faceElement.GetProperty("o")),
            }).ToList();
        // Internal GRep provenance is absent from public Element JSON.
        sourceFaces[0].AlternativeOuterVertices =
        [
            [24.329045093971317, -59.09590949242569, 136.97506561679793],
            [32.448709576098786, -67.2155739745532, 136.97506561679793],
            [32.44870957609878, -67.21557397455318, 137.30314960629926],
            [32.448709576098786, -67.2155739745532, 146.27952755905517],
            [32.44870957609883, -67.21557397455324, 144.1929133858268],
            [32.448709576098786, -67.2155739745532, 146.29265091863522],
            [24.329045093971317, -59.09590949242569, 146.29265091863522],
        ];
        sourceFaces[11].AlternativeOuterVertices =
        [
            [34.0262443897696, -65.63803916088244, 137.30314960629926],
            [34.0262443897696, -65.63803916088244, 144.1929133858268],
            [31.056767093443618, -68.60751645720839, 144.19291338582684],
            [31.056767093443618, -68.60751645720839, 137.30314960629926],
            [32.448709576098814, -67.21557397455322, 137.30314960629926],
        ];
        sourceFaces[12].AlternativeOuterVertices =
        [
            [34.0262443897696, -65.63803916088244, 144.1929133858268],
            [32.14712203819119, -63.75891680930401, 144.1929133858268],
            [30.56958722452039, -65.3364516229748, 144.1929133858268],
            [29.17764474186521, -66.72839410562996, 144.1929133858268],
            [31.05676709344362, -68.60751645720839, 144.1929133858268],
        ];
        sourceFaces[16].AlternativeOuterVertices =
        [
            [27.484114721312892, -59.09590949242569, 137.30314960629926],
            [29.363237072891305, -60.97503184400412, 137.30314960629926],
            [26.393759776565325, -63.944509140330084, 137.30314960629926],
            [24.514637424986912, -62.065386788751645, 137.30314960629926],
            [25.906579907642094, -60.67344430609648, 137.30314960629926],
        ];
        sourceFaces[20].AlternativeOuterVertices =
        [
            [32.634301907118875, -67.0299816435331, 136.97506561679793],
            [32.448709576098786, -67.2155739745532, 136.97506561679793],
            [32.448709576098786, -67.2155739745532, 146.29265091863522],
            [32.448709576098786, -67.2155739745532, 144.1929133858268],
            [32.44870957609879, -67.2155739745532, 137.30314960629926],
            [32.63430190711888, -67.0299816435331, 137.30314960629926],
            [32.634301907118875, -67.0299816435331, 146.29265091863522],
        ];
        var sourceSolids = root.GetProperty("s").EnumerateArray()
            .Select(solidElement =>
            {
                var values = solidElement.EnumerateArray().ToArray();
                return new GeoBrepSolid
                {
                    IsClosed = values[0].GetBoolean(),
                    FaceIndices = values[1].EnumerateArray()
                        .Select(index => index.GetInt32()).ToList(),
                };
            }).ToList();
        var source = new GeometryData
        {
            BoundingBox = root.GetProperty("b").EnumerateArray()
                .Select(value => value.GetDouble()).ToArray(),
            Faces = sourceFaces,
            BrepSolids = sourceSolids,
        };

        const double axisX = 0.7071067811865459;
        const double axisY = -0.7071067811865491;
        double Along(double[] point) =>
            point[0] * axisX + point[1] * axisY;
        double Normal(double[] point) =>
            -point[0] * axisY + point[1] * axisX;
        var lower = source.Faces[2].OuterVertices!;
        var upper = source.Faces[6].OuterVertices!;
        var minimumAlong = lower.OrderBy(Along).Take(2).ToList();
        var maximumAlong = lower.OrderByDescending(Along).Take(2).ToList();
        double[] aMinimum = minimumAlong.MinBy(Normal)!;
        double[] aMaximum = minimumAlong.MaxBy(Normal)!;
        double[] bMinimum = maximumAlong.MinBy(Normal)!;
        double[] bMaximum = maximumAlong.MaxBy(Normal)!;
        double z0 = source.BoundingBox![2];
        const double z1 = 137.30314960629926;
        const double z2 = 146.27952755905517;
        const double z3 = 144.19291338582681;
        double z4 = source.BoundingBox[5];
        static double[] AtZ(double[] point, double z) =>
            [point[0], point[1], z];

        var rebuiltFaces = new List<GeoFace>
        {
            Face(
            [
                AtZ(aMinimum, z0), AtZ(bMinimum, z0),
                AtZ(bMinimum, z1), AtZ(bMinimum, z2),
                AtZ(bMinimum, z3), AtZ(bMinimum, z4),
                AtZ(aMinimum, z4),
            ]),
            Face(
            [
                AtZ(aMaximum, z4), AtZ(bMaximum, z4),
                AtZ(bMaximum, z3), AtZ(bMaximum, z2),
                AtZ(bMaximum, z1), AtZ(bMaximum, z0),
                AtZ(aMaximum, z0),
            ]),
            Face(lower),
            Face(
            [
                AtZ(bMinimum, z1), AtZ(bMinimum, z0),
                AtZ(bMaximum, z0), AtZ(bMaximum, z1),
            ]),
            Face(
            [
                AtZ(bMinimum, z2), AtZ(bMinimum, z1),
                AtZ(bMaximum, z1), AtZ(bMaximum, z2),
            ]),
            Face(
            [
                AtZ(bMinimum, z3), AtZ(bMinimum, z2),
                AtZ(bMaximum, z2), AtZ(bMaximum, z3),
            ]),
            Face(
            [
                AtZ(bMinimum, z4), AtZ(bMinimum, z3),
                AtZ(bMaximum, z3), AtZ(bMaximum, z4),
            ]),
            Face(upper),
            Face(
            [
                AtZ(aMinimum, z0), AtZ(aMinimum, z4),
                AtZ(aMaximum, z4), AtZ(aMaximum, z0),
            ]),
        };
        var rebuilt = new GeometryData
        {
            BoundingBox = (double[])source.BoundingBox.Clone(),
            Faces = rebuiltFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = true,
                    FaceIndices = Enumerable.Range(
                        0, rebuiltFaces.Count).ToList(),
                },
            ],
        };
        return (source, rebuilt);
    }

