        Dictionary<int, List<(int CutterId,
            IfcExporter.HostedOpeningGeometry Operand)>> EmittedOperands,
        Dictionary<int, List<int>> StandaloneIds,
        List<int> FirstHostIds,
        List<int> SecondHostIds,
        int ReferenceOnlyHostId,
        int BboxThicknessOverrideHostId,
        int CorrectPeerHostId,
        IfcExporter.HostedOpeningGeometry FirstWrongMaterializedOperand);

