    private static (Element Wall, GeometryData Rebuilt,
        Dictionary<int, Element> Elements,
        Dictionary<int, List<int>> EmittedCutterIds,
        Dictionary<int, List<(int CutterId,
            IfcExporter.HostedOpeningGeometry Operand)>> EmittedOperands,
        Dictionary<int, List<int>> Standalone)
        CompleteOpenElevenFaceAlternativeFullHeightSplitterFixture(
            int wallId, int primaryCutterId, int disjointCutterId)
    {
        var (rebuilt, source, bounds, location) =
            CompleteOpenElevenFaceAlternativeFullHeightSplitterGeometry();
        var primaryBoundary = BoxGeometry(1, -2, 0, 11, 2, 4);
        var primaryOperand = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 6, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 10, DepthFt: 4,
            BaseZFt: 0, HeightFt: 4,
            ExactDepth: true, Boundary: primaryBoundary);
        var disjointOperand = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 8, CentreYFt: 0,
            AxisX: 1, AxisY: 0,
            WidthFt: 8, DepthFt: 1,
            BaseZFt: 6, HeightFt: 1,
            ExactDepth: true);
        var wall = new Element
        {
            Id = wallId,
            TypeId = wallId + 1000,
            IsDiscovered = true,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Name = "Complete open eleven-face splitter wall",
            Location = location,
            BoundingBox = (double[])bounds.Clone(),
            Geometry = source,
            Layers =
            [
                new MaterialLayer
                {
                    LayerIndex = 0,
                    ThicknessMm = 304.8,
                },
            ],
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = 3.0,
                },
            ],
            CuttingElementIds = [primaryCutterId, disjointCutterId],
            References = [primaryCutterId, disjointCutterId],
        };
        int[] peerHostIds =
            [wallId + 10, wallId + 11, wallId + 12, wallId + 13];
        int[] completeHostIds = [wallId, .. peerHostIds];
        int directHostId = peerHostIds[0];
        var elements = new Dictionary<int, Element>
        {
            [wallId] = wall,
            [primaryCutterId] = new Element
            {
                Id = primaryCutterId,
                CategoryId = -2000023,
                Category = "OST_Doors",
                BoundingBox = (double[])primaryBoundary.BoundingBox!.Clone(),
                HostId = directHostId,
                SerializedHostId = directHostId,
                ExtraHostIds = [],
                ExplicitHostIds = [],
                References = [directHostId],
            },
            [disjointCutterId] = new Element
            {
                Id = disjointCutterId,
                CategoryId = -2000151,
                Category = "OST_GenericModel",
                BoundingBox = [4, -0.5, 6, 12, 0.5, 7],
                HostId = directHostId,
                SerializedHostId = directHostId,
                ExtraHostIds = [],
                ExplicitHostIds = [],
                References = [directHostId],
            },
        };
        foreach (int peerHostId in peerHostIds)
        {
            elements[peerHostId] = new Element
            {
                Id = peerHostId,
                TypeId = peerHostId + 1000,
                IsDiscovered = true,
                CategoryId = -2000011,
                Category = "OST_Walls",
                Name = $"Peer host {peerHostId}",
                Location = new LocationCurve
                {
                    CurveType = "Line",
                    StartPoint = [0, 0, 0],
                    EndPoint = [14, 0, 0],
                    Direction = [1, 0, 0],
                    Length = 14,
                },
                BoundingBox = (double[])bounds.Clone(),
                Geometry = BoxGeometry(0, -0.5, 0, 14, 0.5, 3),
                Layers =
                [
                    new MaterialLayer
                    {
                        LayerIndex = 0,
                        ThicknessMm = 304.8,
                    },
                ],
                Parameters =
                [
                    WallWidthParameter(1),
                    new Parameter
                    {
                        Id = -1001105,
                        StorageType = StorageType.Double,
                        Value = 3.0,
                    },
                ],
                CuttingElementIds = [primaryCutterId, disjointCutterId],
                References = [primaryCutterId, disjointCutterId],
            };
        }
        var emittedCutterIds = completeHostIds.ToDictionary(
            id => id,
            _ => new List<int> { primaryCutterId, disjointCutterId });
        var emittedOperands = new Dictionary<int,
            List<(int CutterId, IfcExporter.HostedOpeningGeometry Operand)>>();
        foreach (int hostId in completeHostIds)
            emittedOperands[hostId] =
            [
                (primaryCutterId, primaryOperand),
                (disjointCutterId, disjointOperand),
            ];
        return (wall, rebuilt, elements, emittedCutterIds,
            emittedOperands, new Dictionary<int, List<int>>());
    }

    private static GeometryData EndCapNotchedWallGeometry(
        double x0, double y0, double z0,
        double x1, double y1, double z1,
        double notchAlong, double notchZ)
    {
        var low = new List<double[]>
        {
            new[] { x0, y0, z0 },
            new[] { notchAlong, y0, z0 },
            new[] { notchAlong, y0, notchZ },
            new[] { x1, y0, notchZ },
            new[] { x1, y0, z1 },
            new[] { x0, y0, z1 },
        };
        var high = low.Select(point =>
            new[] { point[0], y1, point[2] }).ToList();
        var faces = new List<GeoFace>
        {
            Face(low),
            Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < low.Count; index++)
        {
            int next = (index + 1) % low.Count;
            faces.Add(Face(
            [
                low[index], high[index], high[next], low[next],
            ]));
        }
        return new GeometryData
        {
            BoundingBox = [x0, y0, z0, x1, y1, z1],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
    }

    private static GeometryData HorizontalCapSlottedWallGeometry(
        double x0, double y0, double z0,
        double x1, double y1, double z1,
        double slotMinimumAlong, double slotMaximumAlong,
        double slotBoundaryZ, bool slotTouchesMaximumZ)
    {
        var low = slotTouchesMaximumZ
            ? new List<double[]>
            {
                new[] { x0, y0, z0 },
                new[] { x1, y0, z0 },
                new[] { x1, y0, z1 },
                new[] { slotMaximumAlong, y0, z1 },
                new[] { slotMaximumAlong, y0, slotBoundaryZ },
                new[] { slotMinimumAlong, y0, slotBoundaryZ },
                new[] { slotMinimumAlong, y0, z1 },
                new[] { x0, y0, z1 },
            }
            : new List<double[]>
            {
                new[] { x0, y0, z0 },
                new[] { slotMinimumAlong, y0, z0 },
                new[] { slotMinimumAlong, y0, slotBoundaryZ },
                new[] { slotMaximumAlong, y0, slotBoundaryZ },
                new[] { slotMaximumAlong, y0, z0 },
                new[] { x1, y0, z0 },
                new[] { x1, y0, z1 },
                new[] { x0, y0, z1 },
            };
        var high = low.Select(point =>
            new[] { point[0], y1, point[2] }).ToList();
        var faces = new List<GeoFace>
        {
            Face(low),
            Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < low.Count; index++)
        {
            int next = (index + 1) % low.Count;
            faces.Add(Face(
            [
                low[index], high[index], high[next], low[next],
            ]));
        }
        return new GeometryData
        {
            BoundingBox = [x0, y0, z0, x1, y1, z1],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
    }

    private static GeometryData ExtrudedSideProfileWallGeometry(
        IReadOnlyList<(double Along, double Z)> profile,
        double minimumNormal, double maximumNormal)
    {
        var low = profile.Select(point =>
            new[] { point.Along, minimumNormal, point.Z }).ToList();
        var high = profile.Select(point =>
            new[] { point.Along, maximumNormal, point.Z }).ToList();
        var faces = new List<GeoFace>
        {
            Face(low),
            Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < low.Count; index++)
        {
            int next = (index + 1) % low.Count;
            faces.Add(Face(
            [
                low[index], high[index], high[next], low[next],
            ]));
        }
        return new GeometryData
        {
            BoundingBox =
            [
                low.Min(point => point[0]), minimumNormal,
                low.Min(point => point[2]), low.Max(point => point[0]),
                maximumNormal, low.Max(point => point[2]),
            ],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
    }

    private static GeometryData PairedSideProfileWallGeometry(
        IReadOnlyList<(double Along, double Z)> minimumProfile,
        IReadOnlyList<(double Along, double Z)> maximumProfile,
        double minimumNormal, double maximumNormal)
    {
        Assert.Equal(minimumProfile.Count, maximumProfile.Count);
        var low = minimumProfile.Select(point =>
            new[] { point.Along, minimumNormal, point.Z }).ToList();
        var high = maximumProfile.Select(point =>
            new[] { point.Along, maximumNormal, point.Z }).ToList();
        var faces = new List<GeoFace>
        {
            Face(low),
            Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < low.Count; index++)
        {
            int next = (index + 1) % low.Count;
            faces.Add(Face(
            [
                low[index], high[index], high[next], low[next],
            ]));
        }
        var points = low.Concat(high).ToList();
        return new GeometryData
        {
            BoundingBox =
            [
                points.Min(point => point[0]), minimumNormal,
                points.Min(point => point[2]),
                points.Max(point => point[0]), maximumNormal,
                points.Max(point => point[2]),
            ],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
    }

    private static GeometryData
        TwentyFourSolidSevenPointJoinedSpanSourceGeometry()
    {
        static GeoFace Polygon(int index, int vertexCount)
        {
            double centreX = index * 2.0;
            double centreY = index % 5;
            double z = index % 3;
            return Face(Enumerable.Range(0, vertexCount).Select(vertex =>
            {
                double angle = 2 * Math.PI * vertex / vertexCount;
                return new[]
                {
                    centreX + 0.5 * Math.Cos(angle),
                    centreY + 0.5 * Math.Sin(angle),
                    z,
                };
            }));
        }

        var faces = Enumerable.Range(0, 161).Select(index =>
            Polygon(index, index < 152 ? 4 : index < 158 ? 5 : 6))
            .ToList();
        faces[0].AlternativeOuterVertices = Enumerable.Range(0, 7)
            .Select(vertex =>
            {
                double angle = 2 * Math.PI * vertex / 7;
                return new[]
                {
                    0.75 * Math.Cos(angle),
                    0.75 * Math.Sin(angle),
                    0.0,
                };
            }).ToList();

        var solidContracts = new (int FaceCount, bool IsClosed)[]
        {
            (39, true),
            (6, true), (6, true), (6, true), (6, true),
            (6, true), (6, true), (6, true),
            (5, false),
            (6, true), (6, true), (6, true), (6, true),
            (6, true), (6, true),
            (5, false),
            (6, true), (6, true),
            (5, false),
            (6, true), (6, true), (6, true), (6, true), (6, true),
        };
        var solids = new List<GeoBrepSolid>();
        int nextUnique = 0;
        int nextShared = 0;
        foreach (var contract in solidContracts)
        {
            var indices = new List<int>();
            while (indices.Count < contract.FaceCount && nextUnique < faces.Count)
                indices.Add(nextUnique++);
            while (indices.Count < contract.FaceCount)
                indices.Add(nextShared++);
            solids.Add(new GeoBrepSolid
            {
                FaceIndices = indices,
                IsClosed = contract.IsClosed,
            });
        }
        Assert.Equal(161, nextUnique);
        Assert.Equal(13, nextShared);

        var points = faces.SelectMany(face => face.OuterVertices!
            .Concat(face.AlternativeOuterVertices ?? [])).ToList();
        return new GeometryData
        {
            BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ],
            Faces = faces,
            BrepSolids = solids,
        };
    }

    private static (GeometryData Boundary, GeometryData Source)
        CompleteOpenTwelveFaceMinimumPlanCapGeometry()
    {
        var boundary = PairedSideProfileWallGeometry(
        [
            (0, 0), (6, 0), (6, 1),
            (5, 1), (5, 3), (0, 3),
        ],
        [
            (0, 0), (6, 0), (6, 1),
            (5, 1), (5, 3), (0, 3),
        ], -0.5, 0.5);
        var sourceFaces = boundary.Faces!.Select(face =>
            Face(face.OuterVertices!)).ToList();
        sourceFaces.AddRange(
        [
            Face([[1, -0.5, 0.25], [1, 0.5, 0.25],
                [1, 0.5, 0.75], [1, -0.5, 0.75]]),
            Face([[2, -0.5, 0.25], [2, 0.5, 0.25],
                [2, 0.5, 0.75], [2, -0.5, 0.75]]),
            Face([[3, -0.5, 1.25], [3, 0.5, 1.25],
                [3, 0.5, 1.75], [3, -0.5, 1.75]]),
            Face([[4, -0.5, 2.25], [4, 0.5, 2.25],
                [4, 0.5, 2.75], [4, -0.5, 2.75]]),
        ]);
        var source = new GeometryData
        {
            BoundingBox = (double[])boundary.BoundingBox!.Clone(),
            Faces = sourceFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, sourceFaces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        return (boundary, source);
    }

    private static (Element Wall, GeometryData Rebuilt,
        IfcExporter.HostedOpeningGeometry Operand)
        ExactMixedComponentOpenSteppedMinimumCapSource(
            bool detachedAtNegativeNormal,
            bool minimumCapShort = false)
    {
        double wallHeight = minimumCapShort ? 4 : 3;
        double openingBaseZ = minimumCapShort ? 2 : 0.25;
        GeometryData rebuilt;
        if (minimumCapShort)
        {
            rebuilt = PairedSideProfileWallGeometry(
            [
                (0, 0), (5.5, 0), (5.5, 1),
                (6, 1), (6, 4), (0, 4),
            ],
            [
                (0, 0), (5.5, 0), (5.5, 1),
                (6, 1), (6, 4), (0, 4),
            ], -0.5, 0.5);
            double[][] lowHole =
            [
                [2, -0.5, openingBaseZ],
                [3, -0.5, openingBaseZ],
                [3, -0.5, openingBaseZ + 0.5],
                [2, -0.5, openingBaseZ + 0.5],
            ];
            double[][] highHole =
            [
                [2, 0.5, openingBaseZ],
                [3, 0.5, openingBaseZ],
                [3, 0.5, openingBaseZ + 0.5],
                [2, 0.5, openingBaseZ + 0.5],
            ];
            rebuilt.Faces![0].InnerVertices = [lowHole.ToList()];
            rebuilt.Faces[1].InnerVertices =
                [highHole.AsEnumerable().Reverse().ToList()];
            for (int index = 0; index < 4; index++)
            {
                int next = (index + 1) % 4;
                rebuilt.Faces.Add(Face(
                [
                    lowHole[index], lowHole[next],
                    highHole[next], highHole[index],
                ]));
            }
            rebuilt.BrepSolids![0].FaceIndices =
                Enumerable.Range(0, rebuilt.Faces.Count).ToList();
            Assert.True(IfcExporter.TryOrientExactFacetedShell(
                rebuilt.Faces, rebuilt.BrepSolids[0].FaceIndices,
                out var orientedRebuiltFaces,
                triangulateNonPlanarFaces: false));
            rebuilt.Faces = orientedRebuiltFaces;
        }
        else
        {
            (rebuilt, _) =
                VerticalStepWallWithThroughOpeningGeometry(inverse: false);
        }
        var primaryFaces = rebuilt.Faces!
            .Select(CloneFaceGeometry).ToList();

        double closedMinimumNormal = detachedAtNegativeNormal ? -1.25 : 1;
        double closedMaximumNormal = detachedAtNegativeNormal ? -1 : 1.25;
        var closedFragment = BoxGeometry(
            1, closedMinimumNormal, 0.1,
            5, closedMaximumNormal, wallHeight - 0.1);
        double[][] closedMinimumHole =
        [
            [1.75, closedMinimumNormal, openingBaseZ],
            [3.25, closedMinimumNormal, openingBaseZ],
            [3.25, closedMinimumNormal, openingBaseZ + 0.75],
            [1.75, closedMinimumNormal, openingBaseZ + 0.75],
        ];
        double[][] closedMaximumHole =
        [
            [1.75, closedMaximumNormal, openingBaseZ],
            [3.25, closedMaximumNormal, openingBaseZ],
            [3.25, closedMaximumNormal, openingBaseZ + 0.75],
            [1.75, closedMaximumNormal, openingBaseZ + 0.75],
        ];
        closedFragment.Faces![2].InnerVertices =
            [closedMinimumHole.ToList()];
        closedFragment.Faces[4].InnerVertices =
            [closedMaximumHole.AsEnumerable().Reverse().ToList()];
        for (int index = 0; index < 4; index++)
        {
            int next = (index + 1) % 4;
            closedFragment.Faces.Add(Face(
            [
                closedMinimumHole[index], closedMinimumHole[next],
                closedMaximumHole[next], closedMaximumHole[index],
            ]));
        }
        closedFragment.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, closedFragment.Faces.Count).ToList();
        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            closedFragment.Faces,
            closedFragment.BrepSolids[0].FaceIndices,
            out var orientedClosedFaces,
            triangulateNonPlanarFaces: false));
        closedFragment.Faces = orientedClosedFaces;

        double tubeMinimumNormal = detachedAtNegativeNormal ? -2.25 : 2;
        double tubeMaximumNormal = detachedAtNegativeNormal ? -2 : 2.25;
        double tubeMinimumZ = minimumCapShort ? 3 : 1;
        double tubeMaximumZ = minimumCapShort ? 3.5 : 2;
        var openTube = FourSideShellGeometry(
            2, tubeMinimumNormal, tubeMinimumZ,
            3, tubeMaximumNormal, tubeMaximumZ);

        int primaryStart = 0;
        int closedStart = primaryFaces.Count;
        int tubeStart = closedStart + closedFragment.Faces.Count;
        var sourceFaces = primaryFaces
            .Concat(closedFragment.Faces.Select(CloneFaceGeometry))
            .Concat(openTube.Faces!.Select(CloneFaceGeometry))
            .ToList();
        var source = new GeometryData
        {
            BoundingBox =
            [
                0, Math.Min(-0.5, tubeMinimumNormal), 0,
                6, Math.Max(0.5, tubeMaximumNormal), wallHeight,
            ],
            Faces = sourceFaces,
            // Deliberately keep source order different from geometric role order.
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        closedStart, closedFragment.Faces.Count).ToList(),
                    IsClosed = true,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        tubeStart, openTube.Faces.Count).ToList(),
                    IsClosed = false,
                },
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        primaryStart, primaryFaces.Count).ToList(),
                    IsClosed = false,
                },
            ],
        };
        var wall = new Element
        {
            Id = detachedAtNegativeNormal ? 1942 : 1941,
            TypeId = 1944,
            CategoryId = -2000011,
            Category = "OST_Walls",
            Parameters =
            [
                WallWidthParameter(1),
                new Parameter
                {
                    Id = -1001105,
                    StorageType = StorageType.Double,
                    Value = wallHeight,
                },
            ],
            CuttingElementIds = [],
            Location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = [0, 0, 0],
                EndPoint = [6, 0, 0],
            },
            BoundingBox = [0, -0.5, 0, 6, 0.5, wallHeight],
            Geometry = source,
        };

        double centreNormal = detachedAtNegativeNormal ? -0.75 : 0.75;
        double breakpointNormal = detachedAtNegativeNormal ? -0.5 : 0.5;
        var outer = new IfcExporter.HostedOpeningGeometry(
            CentreXFt: 2.5, CentreYFt: centreNormal,
            AxisX: 1, AxisY: 0,
            WidthFt: 1.5, DepthFt: 4,
            BaseZFt: openingBaseZ, HeightFt: 0.75,
            ExactDepth: true);
        Assert.True(IfcExporter.TryBuildExactSteppedOpeningBoundary(
            outer, innerWidthFt: 1, innerHeightFt: 0.5,
            breakpointNormalFt: breakpointNormal,
            innerAtMinimum: !detachedAtNegativeNormal,
            out var openingBoundary));
        var operand = outer with
        {
            Boundary = openingBoundary,
            SteppedProfile = new IfcExporter.ExactSteppedOpeningProfile(
                InnerWidthFt: 1, InnerHeightFt: 0.5,
                BreakpointNormalFt: breakpointNormal,
                InnerAtMinimum: !detachedAtNegativeNormal),
            IsExactSourceWallProfilesMappedBreakpoint = true,
        };
        return (wall, rebuilt, operand);
    }

    private static GeoFace CloneFaceGeometry(GeoFace source) => new()
    {
        Origin = (double[])source.Origin.Clone(),
        XVector = (double[])source.XVector.Clone(),
        YVector = (double[])source.YVector.Clone(),
        Normal = (double[])source.Normal.Clone(),
        Envelope = source.Envelope is { } envelope
            ? (double[])envelope.Clone() : null,
        Area = source.Area,
        InnerLoops = source.InnerLoops?.Select(loop =>
            (double[])loop.Clone()).ToList(),
        OuterVertices = source.OuterVertices?.Select(point =>
            (double[])point.Clone()).ToList(),
        InnerVertices = source.InnerVertices?.Select(ring =>
            ring.Select(point => (double[])point.Clone()).ToList()).ToList(),
        AlternativeOuterVertices = source.AlternativeOuterVertices?.Select(
            point => (double[])point.Clone()).ToList(),
        EdgeIndices = source.EdgeIndices?.ToList(),
    };

    private static GeometryData CloneGeometryData(GeometryData source) => new()
    {
        BoundingBox = source.BoundingBox is { } bounds
            ? (double[])bounds.Clone() : null,
        Faces = source.Faces?.Select(CloneFaceGeometry).ToList(),
        BrepSolids = source.BrepSolids?.Select(solid => new GeoBrepSolid
        {
            FaceIndices = solid.FaceIndices.ToList(),
            IsClosed = solid.IsClosed,
        }).ToList(),
    };

    private static IEnumerable<double[]> FacePointReferences(GeoFace face) =>
        (face.OuterVertices ?? []).Concat(
            (face.InnerVertices ?? []).SelectMany(ring => ring));

    private static void TranslateSolid(
        GeometryData geometry, GeoBrepSolid solid,
        double x, double y, double z)
    {
        foreach (double[] point in solid.FaceIndices
                     .Select(index => geometry.Faces![index])
                     .SelectMany(FacePointReferences)
                     .Distinct<double[]>(
                         ReferenceEqualityComparer.Instance))
        {
            point[0] += x;
            point[1] += y;
            point[2] += z;
        }
    }

    private static void ShiftPrimaryOpeningAlong(
        GeometryData geometry, IReadOnlyList<int> faceIndices,
        double shiftFt)
    {
        var faces = faceIndices.Select(index => geometry.Faces![index])
            .ToList();
        var holeCoordinates = faces
            .SelectMany(face => face.InnerVertices ?? [])
            .SelectMany(ring => ring)
            .Select(point => (point[0], point[1], point[2]))
            .ToHashSet();
        Assert.Equal(8, holeCoordinates.Count);
        var openingPoints = faces.SelectMany(FacePointReferences)
            .Distinct<double[]>(ReferenceEqualityComparer.Instance)
            .Where(point => holeCoordinates.Contains(
                (point[0], point[1], point[2])))
            .ToList();
        Assert.NotEmpty(openingPoints);
        foreach (double[] point in openingPoints)
            point[0] += shiftFt;
    }

    private static GeometryData VerticalStepWallGeometry(
        double x0, double y0, double z0,
        double x1, double y1, double z1,
        double stepAlong, double stepZ)
    {
        var low = new List<double[]>
        {
            new[] { x0, y0, z0 },
            new[] { x1, y0, z0 },
            new[] { x1, y0, stepZ },
            new[] { stepAlong, y0, stepZ },
            new[] { stepAlong, y0, z1 },
            new[] { x0, y0, z1 },
        };
        var high = low.Select(point =>
            new[] { point[0], y1, point[2] }).ToList();
        var faces = new List<GeoFace>
        {
            Face(low),
            Face(high.AsEnumerable().Reverse()),
        };
        for (int index = 0; index < low.Count; index++)
        {
            int next = (index + 1) % low.Count;
            faces.Add(Face(
            [
                low[index], high[index], high[next], low[next],
            ]));
        }
        return new GeometryData
        {
            BoundingBox = [x0, y0, z0, x1, y1, z1],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
    }

    private static (GeometryData Boundary, GeometryData OpeningBoundary)
        VerticalStepWallWithThroughOpeningGeometry(bool inverse)
    {
        var boundary = VerticalStepWallGeometry(
            0, -0.5, 0, 6, 0.5, 3,
            stepAlong: 1, stepZ: 1);
        if (inverse)
            foreach (double[] point in boundary.Faces!
                         .SelectMany(face => face.OuterVertices!)
                         .Distinct<double[]>(
                             ReferenceEqualityComparer.Instance))
            {
                point[0] = 6 - point[0];
                point[2] = 3 - point[2];
            }

        double minimumAlong = inverse ? 5.2 : 2;
        double maximumAlong = inverse ? 5.6 : 3;
        double minimumZ = inverse ? 1.25 : 0.25;
        double maximumZ = minimumZ + 0.5;
        double[][] lowHole =
        [
            [minimumAlong, -0.5, minimumZ],
            [maximumAlong, -0.5, minimumZ],
            [maximumAlong, -0.5, maximumZ],
            [minimumAlong, -0.5, maximumZ],
        ];
        double[][] highHole =
        [
            [minimumAlong, 0.5, minimumZ],
            [maximumAlong, 0.5, minimumZ],
            [maximumAlong, 0.5, maximumZ],
            [minimumAlong, 0.5, maximumZ],
        ];
        boundary.Faces![0].InnerVertices = [lowHole.ToList()];
        boundary.Faces[1].InnerVertices =
            [highHole.AsEnumerable().Reverse().ToList()];
        for (int index = 0; index < 4; index++)
        {
            int next = (index + 1) % 4;
            boundary.Faces.Add(Face(
            [
                lowHole[index], lowHole[next],
                highHole[next], highHole[index],
            ]));
        }
        boundary.BrepSolids![0].FaceIndices =
            Enumerable.Range(0, boundary.Faces.Count).ToList();
        Assert.True(IfcExporter.TryOrientExactFacetedShell(
            boundary.Faces, boundary.BrepSolids[0].FaceIndices,
            out var orientedFaces,
            triangulateNonPlanarFaces: false));
        boundary.Faces = orientedFaces;
        return (boundary, BoxGeometry(
            minimumAlong, -0.75, minimumZ,
            maximumAlong, 0.75, maximumZ));
    }

