    private static GeometryData ClippedWedgeGeometry(double sectionZ)
    {
        double[] top00 = [0, 0.075, 0];
        double[] top01 = [0, -0.075, 0];
        double[] top11 = [-0.05, -0.075, 0];
        double[] top10 = [-0.05, 0.075, 0];
        double[] low01 = [0, -0.075, -0.597505852749074];
        double[] low11 = [-0.05, -0.075, -0.597505852749074];
        double[] low10 = [-0.05, 0.075, -0.659637887105038];
        double[] low00 = [0, 0.075, -0.659637887105038];
        var faces = new List<GeoFace>
        {
            Face([top00, top01, top11, top10]),
            Face([top00, low00, low10, top10]),
            Face([
                [-0.05, 0.075, sectionZ], [-0.05, -0.075, sectionZ],
                [0, -0.075, sectionZ], [0, 0.075, sectionZ],
            ]),
            Face([top10, low10, low11, top11]),
            Face([top11, low11, low01, top01]),
            Face([top01, low01, low00, top00]),
            Face([low01, low11, low10, low00]),
        };
        return new GeometryData
        {
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
    }

    private static Parameter WallWidthParameter(double widthFeet) => new()
    {
        Id = -1001000,
