        Value = widthFeet,
    };

    private static ((int Vertices, int Edges, int Components) Summary,
        Dictionary<int, int> OwnerHistogram,
        IReadOnlyList<int> ComponentSizes) ExactTopology(
            GeometryData geometry, IReadOnlyList<int> faceIndices)
    {
        static ((long X, long Y, long Z) A,
            (long X, long Y, long Z) B) Edge(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        static (long X, long Y, long Z) PrecisionKey(double[] point) =>
        (
            checked((long)Math.Round(point[0] * 0.3048 / 1.0e-5,
                MidpointRounding.ToEven)),
            checked((long)Math.Round(point[1] * 0.3048 / 1.0e-5,
                MidpointRounding.ToEven)),
            checked((long)Math.Round(point[2] * 0.3048 / 1.0e-5,
                MidpointRounding.ToEven))
        );

        var vertices = new HashSet<(long X, long Y, long Z)>();
        var owners = new Dictionary<(
            (long X, long Y, long Z) A,
            (long X, long Y, long Z) B), HashSet<int>>();
        var adjacency = faceIndices.Distinct().ToDictionary(
            faceIndex => faceIndex, _ => new HashSet<int>());
        foreach (int faceIndex in faceIndices)
        {
            var ring = geometry.Faces[faceIndex].OuterVertices!;
            var keys = ring.Select(PrecisionKey).ToList();
            foreach (var key in keys)
                vertices.Add(key);
            for (int index = 0; index < keys.Count; index++)
            {
                var edge = Edge(keys[index], keys[(index + 1) % keys.Count]);
                if (!owners.TryGetValue(edge, out var edgeOwners))
                    owners[edge] = edgeOwners = new HashSet<int>();
                edgeOwners.Add(faceIndex);
            }
        }
        foreach (var edgeOwners in owners.Values)
        {
            foreach (int first in edgeOwners)
                foreach (int second in edgeOwners)
                    if (first != second)
                        adjacency[first].Add(second);
        }

        int componentCount = 0;
        var componentSizes = new List<int>();
        var remaining = adjacency.Keys.ToHashSet();
        while (remaining.Count > 0)
        {
            componentCount++;
            int componentSize = 0;
            int seed = remaining.Min();
            remaining.Remove(seed);
            var queue = new Queue<int>();
            queue.Enqueue(seed);
            while (queue.Count > 0)
            {
                int current = queue.Dequeue();
                componentSize++;
                foreach (int neighbour in adjacency[current])
                    if (remaining.Remove(neighbour))
                        queue.Enqueue(neighbour);
            }
            componentSizes.Add(componentSize);
        }
        componentSizes.Sort((first, second) => second.CompareTo(first));
        var ownerHistogram = owners.Values
            .GroupBy(edgeOwners => edgeOwners.Count)
            .OrderBy(group => group.Key)
            .ToDictionary(group => group.Key, group => group.Count());
        return ((vertices.Count, owners.Count, componentCount),
            ownerHistogram, componentSizes);
    }

    private static (long X, long Y, long Z) Key(double[] point) =>
        (BitConverter.DoubleToInt64Bits(point[0]), BitConverter.DoubleToInt64Bits(point[1]),
            BitConverter.DoubleToInt64Bits(point[2]));

