    private static int Count(string value, string token)
    {
        int count = 0;
        for (int index = 0; (index = value.IndexOf(token, index, StringComparison.Ordinal)) >= 0;
             index += token.Length)
            count++;
        return count;
    }

    private static IReadOnlyList<string>
        CanonicalOpeningRepresentationPayloads(string ifc, int tag)
    {
        var entityMatches = System.Text.RegularExpressions.Regex.Matches(
            ifc, @"(?m)^#(?<id>\d+)=(?<payload>.+);\r?$");
        var entities = entityMatches.ToDictionary(
            match => int.Parse(match.Groups["id"].Value),
            match => match.Groups["payload"].Value);
        string tagSuffix = $",'{tag}')";
        var openingPayloads = entities.Values.Where(payload =>
                payload.StartsWith(
                    "IFCOPENINGELEMENT(", StringComparison.Ordinal)
                && payload.EndsWith(tagSuffix, StringComparison.Ordinal))
            .ToList();
        Assert.NotEmpty(openingPayloads);

        var cache = new Dictionary<int, string>();
        var visiting = new HashSet<int>();
        string Canonical(int id)
        {
            if (cache.TryGetValue(id, out string? cached)) return cached;
            Assert.True(entities.TryGetValue(id, out string? payload),
                $"Missing STEP entity #{id}.");
            Assert.True(visiting.Add(id),
                $"Cycle in opening representation at STEP entity #{id}.");
            int referenceIndex = 0;
            string normalized = System.Text.RegularExpressions.Regex.Replace(
                payload!, @"#(?<id>\d+)", match =>
                {
                    referenceIndex++;
                    if (payload.StartsWith(
                            "IFCSHAPEREPRESENTATION(",
                            StringComparison.Ordinal)
                        && referenceIndex == 1)
                        return "#CONTEXT";
                    int childId = int.Parse(match.Groups["id"].Value);
                    return $"<{Canonical(childId)}>";
                });
            visiting.Remove(id);
            cache[id] = normalized;
            return normalized;
        }

        var result = new List<string>();
        foreach (string openingPayload in openingPayloads)
        {
            var references = System.Text.RegularExpressions.Regex.Matches(
                    openingPayload, @"#(?<id>\d+)")
                .Select(match => int.Parse(match.Groups["id"].Value))
                .ToList();
            Assert.True(references.Count >= 2,
                $"Opening tag {tag} has no representation reference.");
            result.Add(Canonical(references[^1]));
        }
        result.Sort(StringComparer.Ordinal);
        return result;
    }
}
